insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '2CH', $b$II Nau Rêh Jêng$b$, $b$["II NAU RÊH JÊNG"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','2CH',1,1,null,$b$Y-Salômon, kon bu klâu Y-Đavit ƀư nâp păng nơm tâm ƀon-bri hađăch păng; Yêhôva Brah Ndu păng gŭ ndrel păng, jêh ri ăn păng dơi jêng toyh ngăn ngên.$b$,true),
('bunong-vn','2CH',1,2,null,$b$Y-Salômôn mbơh ma lĕ rngôch phung Israel, ma phung kôranh uănh du rbăn nuyh jêh ri ma phung kôranh uănh du rhiăng nuyh, ma phung kôranh-phat-dôih, jêh ri lĕ rngôch kôranh tâm bri Israel, jêng phung kôranh noi deh ăn dơi văch tât;$b$,true),
('bunong-vn','2CH',1,3,null,$b$pô ri, Y-Salômôn jêh ri lĕ rngôch phung tâm rgum băl ndrel ma păng hăn rlet ntŭk prêh ta ƀon Gibêôn; yor lah ta nây geh ngih bok nau tâm rƀŭn Brah Ndu, ndơ Y-Môis, oh mon Yêhôva, hŏ ƀư jêh tâm ntŭk bri rdah.$b$,false),
('bunong-vn','2CH',1,4,null,$b$(Ƀiă lah Y-Đavit hŏ tung leo jêh hip Brah Ndu tă bơh ƀon Kiriat-Jêarim tât ma ntŭk Y-Đavit hŏ nkra jêh ăn ma hip; Yor lah păng hŏ ndâk jêh ăn ma hip nây du mlâm ngih bok ta ƀon Yêrusalem).$b$,true),
('bunong-vn','2CH',1,5,null,$b$Pô ri, pa năp ngih bok Yêhôva geh nơng ƀư brah ma kông Y-Besalel kon bu klâu Y-Uri, sau Y-Hur, hŏ ƀư jêh; Y-Salômôn jêh ri phung tâm rƀŭn hăn tât ta ntŭk nây da dê.$b$,true),
('bunong-vn','2CH',1,6,null,$b$Y-Salômôn hao tât ta klơ nơng kông n'gân pa năp Yêhôva, tâm ngih bok ntŭk tâm rƀŭn, jêh ri păng nhhơr du rbăn mpa nhhơr gŭch ta klơ nơng nây.$b$,false),
('bunong-vn','2CH',1,7,null,$b$Măng nây ro, Brah Ndu tâm mpơl ma Y-Salômôn jêh ri lah ma păng, “Dăn hom, moh ndơ may ŭch gâp ăn ma may.”$b$,true),
('bunong-vn','2CH',1,8,null,$b$Jêh ri Y-Salômôn lah ma Brah Ndu. “May hŏ ăn jêh nau rŏng toyh nanê̆ ngăn ma Y-Đavit mbơ̆ gâp, jêh ri njêng jêh gâp hađăch thoi ntrok păng.$b$,false),
('bunong-vn','2CH',1,9,null,$b$Ơ Yêhôva Brah Ndu, dăn may ƀư n'hêl nanê̆ nau may ton jêh ma Y-Đavit mbơ̆ gâp, hŏ tâm di jêh, yor lah may hŏ njêng jêh gâp hađăch chiă uănh phung ƀon lan âk nâm bu ndruyh neh.$b$,false),
('bunong-vn','2CH',1,10,null,$b$Pô ri, dăn Kôranh Brah ăn ma gâp nau blau mĭn jêh ri nau gĭt rbăng, gay gâp dơi luh lăp ta năp phung ƀon lan aơ; yor lah mbu nâm dơi phat nkra phung ƀon lan may dŭt âk râk ngăn?$b$,false),
('bunong-vn','2CH',1,11,null,$b$Brah Ndu nsĭt lah ma Y-Salômôn. “Gâp njêng jêh may hađăch dơi chiă uănh ƀon lan gâp; pô ri, yor lah may geh nuih n'hâm kơt aơ, may mâu ŭch dăn ôh nau ndrŏng kuăng, drăp ndơ, nau bu yơk, mâu lah nau dơi ƀư nkhĭt phung tâm rmot ma may, jêh ri mâu mâp lĕ geh dăn nau jong rêh, ƀiă lah may dăn nau blau mĭn jêh ri nau gĭt rbăng ma may nơm gay ma may dơi phat nkra phung ƀon lan gâp,$b$,false),
('bunong-vn','2CH',1,12,null,$b$pô ri gâp hŏ ăn jêh nau blau mĭn jêh ri nau gĭt rbăng ma may. Gâp mra ăn ma may nau ndrŏng, drăp ndơ, jêh ri nau bu yơk; nau gâp ăn nây lĕ phung hađăch lor pa năp may mâu dơi geh ôh tâm ban kơt nây, jêh ri pa kơi may kŏ mâu dơi geh lĕ hađăch tâm ban nâm bu kơt nây.$b$,false),
('bunong-vn','2CH',1,13,null,$b$Pô ri, Y-Salômôn tă bơh ntŭk prêh tâm ƀon Gibêôn; pa năp ngih boh ntŭk tâm rƀŭn, plơ̆ sĭt ma ƀon Yêrusalem; jêh ri păng chiă uănh phung Israel.$b$,true),
('bunong-vn','2CH',1,14,null,$b$Y-Salômôn rgum lĕ rngôch ndeh seh jêh ri phung ta han ncho seh; păng geh du rbăn puăn rhiăng ndeh seh jêh ri du rmưn bar rbăn nuyh ta han ncho seh, phung nây păng ăn gŭ tâm ƀon bu bun ndeh seh jêh ri ndrel ma hađăch tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',1,15,null,$b$Hađăch bun prăp prăk jêh ri mah tâm ƀon Yêrusalem âk nâm bu bun lŭ, jêh ri tơm si sêdar âk ngăn nâm bu tơm si sikamôr tâm neh lâng Sêphêla.$b$,true),
('bunong-vn','2CH',1,16,null,$b$Y-Salômôn rvăt âk seh bơh n'gor bri Êjipt jêh ri bri Kuê, jêh ri phung sâm tăch drăp ăn ma hađăch sŏk dơn drăp nây bơh bri Kuê tâm di du rnoh khlay.$b$,false),
('bunong-vn','2CH',1,17,null,$b$Khân păng rvăt du bôk ndeh seh bơh N'gor bri Êjipt rnoh khlay prao rhiăng sêkel prăk, jêh ri du mlâm seh du rhiăng prăm jât sêket; tâm ban rnoh nây lĕ phung hađăch mpôl Hitit jêh ri phung hađăch Siri rvăt ta phung sâm tăch drăp ăn ma hađăch tăch đưn tay ma khân păng.$b$,false),
('bunong-vn','2CH',2,1,null,$b$Pô ri, Y-Salômôn mĭn ŭch ndâk du mlâm ngih ma Amoh Yêhôva, jêh ri du mlâm ngih ma hađăch nơm.$b$,true),
('bunong-vn','2CH',2,2,null,$b$Y-Salômôn săch pơh rmưn nuyh bu klâu prăp du nchuăn ndơ jâk jêh ri pham rmưn nuyh châm rlah lŭ ta bri klơ dor lâng jêh ri pe rbăn prao rhiăng nuyh njêh blau kan.$b$,false),
('bunong-vn','2CH',2,3,null,$b$Y-Salômôn njuăl bâr ngơi ma Haram hađăch ƀon Tyr lah: “Nâm bu may hŏ ƀư jêh ma Y-Đavit, mbơ̆ gâp, jêh ri njuăl jêh ma păng tơm si sêdar ŭch ndâk ma păng nơm du mlâm ngih gŭ, tâm ban pô nây lĕ sâm ƀư ăn ma gâp đŏng.$b$,true),
('bunong-vn','2CH',2,4,null,$b$Ta aơ gâp ntơm ndâk du mlâm ngih prăp ma Amoh Yêhôva Brah Ndu gâp, prăp ăn jêng kloh nhhơr, ma Păng, gay su ndơ ƀâu kah pa năp Păng, phiơ piăng leh kloh ƀa ƀơ, nhhơr mpa nhhơr gŭch kêng ôi jêh ri kêng mhaơ, mâu lah tâm nar Saƀat, jêh ri ta nar ntơm luh khay, mâu lah ăp tơ̆ nar nhêt ƀun tâm nal năng đah Yêhôva phung hên; ntil nau nây jêng du nau ntăm jêh ma phung Israel ƀa ƀă n'ho ro.$b$,false),
('bunong-vn','2CH',2,5,null,$b$Yor lah Brah Ndu ta klơ dŭt prêh jêng toyh lơn ma lĕ rngôch brah; pô ri gâp mĭn ŭch ndâk ngih brah toyh ma nau lơp rmah.$b$,true),
('bunong-vn','2CH',2,6,null,$b$Lah pô nây mbu nâm dơi ndâk ngih ma Păng; yor lah trôk, nđâp ma trôk jêng klơ lơn mâu hôm dơi hĕ djôt prăp Păng? Mbu nâm gâp jêng, dĭng dơi ndâk du mlâm ngih brah ăn Păng? Knŏng ndâk nâm bu du ntŭk prăp gŭch mpa ƀâu kah ta năp Păng rĭ dơm.$b$,true),
('bunong-vn','2CH',2,7,null,$b$Pô ri aƀaơ, prơh hăn hom ăn ma gâp du huê bu klâu blau dơi pah kan tŏ njêng mah, prăk, kông, loih, blau tanh ma brai chăng, brai sut jêh ri rnô̆, blau nđâp cheh chiăk brai gay pah kan ndrel ma phung njêh phung blau gŭ êp kêng gâp tâm n'gor Yuđa jêh ri tâm ƀon Yêrusalem, jêng ndơ Y-Đavit, mbơ̆ gâp, hŏ ndrăp rơm jêh.$b$,true),
('bunong-vn','2CH',2,8,null,$b$Ăt njuăl đŏng ăn ma gâp tơm si Sêdar, tơm si Chiprơ tơm rte bơh bri Liban, yor lah gâp gĭt ma phung oh mon may blau kăl tơm si tâm bri Liban. Phung oh mon gâp mra gŭ ndrel ma phung oh mon may,$b$,false),
('bunong-vn','2CH',2,9,null,$b$gay nkra tơm si ăn âk râk ngăn ma gâp, yor lah ngih gâp ŭch ndâk păng jêng toyh ngăn jêh ri lơp rmah mha ngăn ngên.$b$,false),
('bunong-vn','2CH',2,10,null,$b$Gâp mra ăn ma phung oh mon may phung kăl si bar rmưn kôr ba răch lĕ peh jêh, bar rmưn kôr ba ôrgơ, bar rmưn ƀat dak-play-kriăk-ƀâu jêh ri bar rmưn dak play ôlivơ.”$b$,false),
('bunong-vn','2CH',2,11,null,$b$Pô ri, Y-Huram hađăch ƀon Tyr, nchih sămƀŭt plơng ma Y-Salômôn, lah: “Yor lah Yêhôva rŏng ma phung ƀon lah he ri dĭng Păng njêng jêh may hađăch chiă uănh khân păng.”$b$,true),
('bunong-vn','2CH',2,12,null,$b$Y-Hiram plơ̆ lah đŏng: “Mât ton ma Yêhôva Brah Ndu Israel, jêng Nơm rhăk trôk jêh ri neh ntu, yor lah Păng hŏ ăn jêh ma hađăch Đavit du huê kon bu klâu geh nau blau mĭn jêh ri gĭt rbăng, gay ndâk ngih brah ma Păng jêh ri du mlâm ngih hađăch ma păng nơm.$b$,false),
('bunong-vn','2CH',2,13,null,$b$“Aƀaơ ri gâp prơh hăn jêh du huê bu klâu njêh blau geh nau blau mĭn Y-Huramabi,$b$,true),
('bunong-vn','2CH',2,14,null,$b$kon bu klâu du huê bu ur tâm ndŭl mpôl Dan, mbơ̆ păng jêng du huê bu klâu ƀon Tyr. Păng blau ngăn tâm kan tŏ njêng mah, prăk, kông, loih, lŭ blau tanh cheh brai chăng, rnô̆, jêh ri brai sut, breh brai nhao, jêh ri brai mhay rhên, blau ăp ntil cheh hak jêh ri kach rup tĭng nâm bu đă. Păng mra pah kan ndrel ma phung njêh may phung njêh phung blau kôranh gâp, Y-Đavit mbơ̆ may.$b$,false),
('bunong-vn','2CH',2,15,null,$b$Pô ri aƀaơ, dăn may njuăl hom ba răch, ba ôrgơ, dak play ôlivơ jêh ri dak play- kriăk-ƀâu may hŏ lah jêh.$b$,true),
('bunong-vn','2CH',2,16,null,$b$Jêh ri hên mra kăl tơm si tâm bri Liban tĭng nâm may ŭch, jêh ri kât nsum jêng nâm bu rkĭt nđông klơ dak mƀŭt tât ta ƀon Jôpa, pô nây mơ may dơi du nchuăn păng tât ta ƀon Yêrusalem.”$b$,false),
('bunong-vn','2CH',2,17,null,$b$Y-Salômôn kơp lĕ rngôch phung bu năch gŭ tâm bri Israel, tĭng nâm Y-Đavit mbơ̆ păng, hŏ kơp jêh; jêh ri rnoh kơp khân păng geh du rsen prăm rmưn pe rbăn prao rhiăng nuyh.$b$,true),
('bunong-vn','2CH',2,18,null,$b$Tâm phung nây păng jao kan geh pơh rmưn nuyh tung nchuăn ndơ jâk, pham rmưn nuyh châm trah lŭ klơ yôk, jêh ri pe rbăn prao rhiăng nuyh jêng kôranh chiă uănh ntĭm phung ƀon lan pah kan.$b$,false),
('bunong-vn','2CH',3,1,null,$b$Y-Salômôn ntơm ndâk ngih Yêhôva, tâm ƀon Yêrusalem, klơ yôk Môriah, jêng ntŭk Yêhôva hŏ tâm mpơl jêh ma Y-Đavit, mbơ̆ păng tra ntŭk Y-Đavit, mbơ̆ păng ta ntŭk Y-Đavit hŏ nchŏng jêh, jêng ntŭk mprah ba Y-Ôrnan, bunuyh Jêbusit.$b$,true),
('bunong-vn','2CH',3,2,null,$b$Y-Salômôn ntơm ndâk tâm nar rơh bar khay rơh bar tâm năm rơh puăn păng chiă uănh.$b$,true),
('bunong-vn','2CH',3,3,null,$b$Aơ, nau Y-Salômôn veh ma nau ndâk ngih Brah Ndu; jong tĭng nâm hăt ơm kăl e, geh prao jât hăt, jêh ri huy rkăng bar jât hăt.$b$,true),
('bunong-vn','2CH',3,4,null,$b$Ndring pa năp nhuang ngih geh bar jât hăt njok, huy tâm ban kơt rkăng ngih; jêh ri prêh klơ du rhiăng bar jât hăt, păng mblum ntop dak mah chrêk tâm trôm ngih.$b$,false),
('bunong-vn','2CH',3,5,null,$b$Mpir ngih păng nchăng kađar si chiprơ, jêh ri mblum ma dak mah chrêk, jêh ri ƀư rup tơm play đung jêh ri rse rvăk ta klơ.$b$,true),
('bunong-vn','2CH',3,6,null,$b$Păng rhăk ngih ndop ma lŭ khlay gay ma nkrơ̆ păng; mah nây jêng mah bơh n'gor bri Parvam.$b$,true),
('bunong-vn','2CH',3,7,null,$b$Pô nây păng rhăk ngih mblum ma mah rda păng, ndring păng, mpir, jêh ri mpông; jêh ri păng tor kach rup chêrubim ta mpir.$b$,false),
('bunong-vn','2CH',3,8,null,$b$Păng nkra Ntŭk Dŭt Kloh; njok tâm ban ma rkăng ngih lĕ geh bar jât hăt; păng mblum ntŭk nây ma dak mah chrêk; mah dŏng lĕ rngôch geh prao rhiăng ta lâng.$b$,true),
('bunong-vn','2CH',3,9,null,$b$Njing jâk kađĭn mah prăm jât sêkel, păng mblum ma mah da dê lĕ jrô klơ.$b$,true),
('bunong-vn','2CH',3,10,null,$b$Tâm trôm Ntŭk Dŭt Kloh, păng ƀư bar chêrubim trah đah tơm si jêh ri mblum ma dak mah.$b$,true),
('bunong-vn','2CH',3,11,null,$b$Puăn nting năr bar chêrubim lĭ jong bar jât hăt; du đah nting năr chêrubim pa ma jong prăm hăt, rđĭl êp mpir ngih brah; bi nting nar du đah ri ăt jong prăm hăt lĕ, jêh ri tâm mâp đah nting năr chêrubim pa chiau.$b$,false),
('bunong-vn','2CH',3,12,null,$b$Du đah nting năr pa ma chêrubim rơh bar geh prăm hăt, tâm rđĭl đah mpir ngih brah; bi nting năr pa chiau đah ri ăt jong prăm hăt lĕ, tâm mâp đah nting năr pa ma chêrubim rơh nguay.$b$,false),
('bunong-vn','2CH',3,13,null,$b$Lĕ rngôch nting năr bar chêrubim lĭ da dê, lĕ nây jong bar jât hăt; bar chêrubim nây dâk rop jop rle năp mpeh Ntŭk Kloh.$b$,true),
('bunong-vn','2CH',3,14,null,$b$Păng nthăng bok brai rnô̆ , brai chăng, brai sut breh nhau nđâp ma brai mhay rhên, jêh nây ta klơ bu cheh chiăk rup chêrubim.$b$,true),
('bunong-vn','2CH',3,15,null,$b$pa năp ngih brah, păng ƀư bar mlâm meh gâng, prêh pe jât ma prăm hăt, ta klơ bôl dŭt lĕ bar meh geh prăm hăt.$b$,true),
('bunong-vn','2CH',3,16,null,$b$Păng ƀư đŏng ma rse rvăk rhên kơt nhong nâm bu rse rvăk tâm Ntŭk Dŭt Kloh, dơm ăn ta klơ chiông dŭt meh, jêh nây ƀư du rhiăng mlâm play pom gra nat jêh ri dơm ndơ nây rgŏ rse rvăk.$b$,false),
('bunong-vn','2CH',3,17,null,$b$Păng ndâk meh nây pa năp ngih brah, du n'gâng mpeh rđŭng pa dâng, du n'gâng êng mpeh dor pa lơ; meh mpeh rđŭng pa dâng bu ntơ păng Jachhin, jêh ri meh mpeh dor pa lơ bu ntơ păng Bôas Nơng Kông Drŏng Bu Tŏ$b$,false),
('bunong-vn','2CH',4,1,null,$b$Păng ƀư du mlâm nơng kông bar jât hăt jong, rkăng bar jât hăt jêh ri prêh jât hăt.$b$,true),
('bunong-vn','2CH',4,2,null,$b$Jêh ri păng mon du mlâm drŏng dư̆ ng dak; drŏng nây rvang mlâm, huy bâr drŏng nây geh jât hăt, prêh rvang mlâm nây geh prăm hăt; du mlâm rse brăt băr văr jŭm nây jong pe jât hăt.$b$,false),
('bunong-vn','2CH',4,3,null,$b$Ta jâng drŏng nây, geh rup ndrôk, tâm du hăt geh jât mlâm, ƀư bar mbor, bu mon du rơh nđâp ma drŏng.$b$,false),
('bunong-vn','2CH',4,4,null,$b$Drŏng nây bu n'gân ta klơ rup jât ma bar ndrôk nkuăng, pe mlâm rle năp mpeh pa lơ, pe mlâm, rle năp mpeh pa dâng, pe mlâm rle năp mpeh dor pa lơ jêh ri pe mlâm rle năp mpeh rđŭng pa dâng; drŏng dư̆ ng dak gŭ ta klơ khân păng; rup ndrôk săk pa kơi gŭ tâm trôm da dê.$b$,true),
('bunong-vn','2CH',4,5,null,$b$Mbâl drŏng nây du nđam; năp bâr păng nâm bu năp kachok, nâm bu kao si li li dang; păng dơi dư̆ ng dak pe rbăn ƀat.$b$,false),
('bunong-vn','2CH',4,6,null,$b$Păng ƀư đŏng jât mlâm thŭng, ăn prăm mlâm pa ma jêh ri prăm mlâm pa chiau prăp rao ta nây ro; bu rao ta nây moh mpa bu prăp nhhơr gŭch, bi ma lĕ rngôch phung kôranh-ƀư-brah ŭm rao ta drŏng dak nây.$b$,false),
('bunong-vn','2CH',4,7,null,$b$Păng ƀư jât mlâm jâng jrêng mah tĭng nâm bu hŏ ntĭnh jêh, jêh nây dơm khân păng tâm ngih brah, prăm mlâm pa ma prăm mlâm pa chiau.$b$,true),
('bunong-vn','2CH',4,8,null,$b$Păng ƀư đŏng jât mlâm sưng, dơm tâm ngih brah, prăm mlâm pa ma jêh ri prăm mlâm pa chiau. Jêh ta nây ƀư du rhiăng mlâm ngan grưng mah.$b$,false),
('bunong-vn','2CH',4,9,null,$b$Păng ăt ƀư tay rva trong ma phung kôranh-ƀư-brah, nhuang vâl huy, jêh ri mpông nhuang vâl jêh ri mblum ma kông ăp mpông nây;$b$,false),
('bunong-vn','2CH',4,10,null,$b$jêh ri păng dơm drŏng dak mpeh pa ma ngih brah meh pa lơ tâm rđŭng.$b$,false),
('bunong-vn','2CH',4,11,null,$b$Y-Huram ƀư âk yăng kĕ, gri, jêh ri ngan grưng. Pô ri Y-Huram ƀư lôch kan păng ƀư ma Hađăch Salômôn tâm ngih Brah Ndu;$b$,true),
('bunong-vn','2CH',4,12,null,$b$bar meh gâng, bar mlâm ndrŭp meh, bar blah jal băr nkŭm bar mlâm ndrŭp ta klơ bôk meh;$b$,false),
('bunong-vn','2CH',4,13,null,$b$puăn rhiăng play pom gra nat tâm bar blah jal, tâm du blah geh bar mbor play pom gra nat, gay ma drôp bar mlâm bôk meh ta klơ bôl dŭt ri.$b$,false),
('bunong-vn','2CH',4,14,null,$b$Păng ƀư đŏng jâng thŭng, jêh ri thŭng n'gân klơ jâng.$b$,false),
('bunong-vn','2CH',4,15,null,$b$Mon du mlâm drŏng jêh ri rup jât ma bar ndrôk nkuăng tâm dâng păng;$b$,true),
('bunong-vn','2CH',4,16,null,$b$mon njêng yăng, gri n'hoi srang, jêh ri lĕ rngôch ndơ dŏng ma khân păng, Y-Huram-Abi yor Y-Salômôn ƀư lĕ ndơ ma kông prăp tâm ngih Yêhôva.$b$,false),
('bunong-vn','2CH',4,17,null,$b$Hađăch đă khân păng tŏ chiăr ndơ nây tâm ntŭk bri lâng n'gŏ dak krong Yurdan, tâm neh choih, vah vang ƀon Sukôt đah ƀon Sêrêda.$b$,false),
('bunong-vn','2CH',4,18,null,$b$Y-Salômôn ƀư âk ngăn lĕ rngôch ndơ nây, pô ri bu mâu dơi njing ôh nau jâk kông nây.$b$,false),
('bunong-vn','2CH',4,19,null,$b$Pô ri, Y-Salômôn ƀư jêh lĕ rngôch ndơ tâm ngih Brah Ndu: Nơng mah, âk sưng prăp dăp piăng let nhơr ma$b$,true),
('bunong-vn','2CH',4,20,null,$b$jâng jrêng jêh ri ŭnh kađen ƀư ma mah chrêk dŏng mpoh pa năp ntŭk dŭt kloh tâm trôm, tĭng nâm bu hŏ ntĭnh jêh;$b$,false),
('bunong-vn','2CH',4,21,null,$b$khân păng ƀư đŏng kao si, ŭnh kađen, jêh ri nchraih ƀư ma mah chrêk lơn;$b$,false),
('bunong-vn','2CH',4,22,null,$b$pêih, ngan grưng, ngan rlŭ prăp ma mpa ƀâu kah, ŭnh năk ƀư ma mah chrêk; jêh ri ntŭk lăp ngih brah, lĕ rngôch mpông tâm trôm lăp tâm Ntŭk Dŭt Kloh jêh ri lĕ rngôch mpông ngih brah ƀư ma mah da dê.$b$,false),
('bunong-vn','2CH',5,1,null,$b$Nây yơh, lĕ rngôch kan pah Y-Salômôn ƀư ma ngih brah Yêhôva hŏ lôch jêh. Y-Salômôn leo nglăp ndơ Y-Đavit, mbơ̆ păng, hŏ nhhơr jêh, jêh ri prăp bun prăk, mah jêh ri lĕ rngôch khăl ngan tâm jrô prăp drăp ndơ ngih Brah Ndu.$b$,true),
('bunong-vn','2CH',5,2,null,$b$Jêh nây Y-Salômôn rgum lĕ rngôch phung bu ranh Israel, jêh ri lĕ rngôch phung kôranh tĭng noi deh tâm phung Israel gŭ tâm ƀon Yêrusalem, gay vơt hip tâm rnglăp Yêhôva tă bơh ƀon Y-Đavit, jêng ƀon Siôn.$b$,true),
('bunong-vn','2CH',5,3,null,$b$Lĕ rngôch phung Israel tâm rƀŭn ta năp hađăch tâm nau nhêt ƀun khlay rơh pơh.$b$,false),
('bunong-vn','2CH',5,4,null,$b$Lĕ kôranh phung bu ranh Israel tât da dê, jêh ri phung Lêvi tung njŭn leo hip.$b$,false),
('bunong-vn','2CH',5,5,null,$b$Đơ phung kôranh-ƀư-brah jêh ri phung Lêvi tung leo hip tâm rnglăp, ngih bok tâm rƀŭn, jêh ri lĕ rngôch khăl ngan kloh tâm ngih bok tung leo da dê.$b$,true),
('bunong-vn','2CH',5,6,null,$b$Hađăch Salômôn jêh ri lĕ rngôch phung Israel tâm rƀŭn, gŭ tâm rƀŭn ndrel păng, gŭ dâk pa năp hip da dê, nhhơr âk râk biăp jêh ri ndrôk jêng mpa ƀư brah, tât mâu hôm dăng kơp.$b$,true),
('bunong-vn','2CH',5,7,null,$b$Pô ri, phung kôranh-ƀư-brah ndjôt leo hip tâm rnglăp Yêhôva nglăp tâm ntŭk ăn hip jêng Jrô Kloh Ueh tâm ngih brah, tâm dâng nting nar chêrubim.$b$,false),
('bunong-vn','2CH',5,8,null,$b$Bar chêrubim lĭ nting nar tâm tra ntŭk hip, nkŭm lăp jêh ri mâng rnung.$b$,false),
('bunong-vn','2CH',5,9,null,$b$Mâng tung dŭt jong, chiông mâng rho dih ri hip, pa năp ntŭk kloh tâm trôm; ƀiă lah pa dih bu mâu dơi saơ ndơ nây ôh; jêh ri hip ăt hôm ta nây tât nar aơ.$b$,false),
('bunong-vn','2CH',5,10,null,$b$Tâm trôm hip mâu geh ntil ndơ ôh, knŏng bar plơp kađar nchih nau vay Y-Môis dơm ăn tâm nây dôl khân păng gŭ ta yôk Hôrep, ta nây Yêhôva hŏ ƀư jêh nau tâm rnglăp đah phung ƀon lan Israel dôl khân păng du luh bơh n'gor bri Êjipt.$b$,false),
('bunong-vn','2CH',5,11,null,$b$Tơ lah phung kôranh-ƀư-brah luh tă bơh Ntŭk-Kloh-Ueh (yor lah lĕ rngôch phung-kôranh-ƀư-brah gŭ ta nây hŏ ƀư ăn kloh ueh jêh khân păng nơm, mâu jê ôh ma mbu mpôl khân păng jêng$b$,true),
('bunong-vn','2CH',5,12,null,$b$jêh ri lĕ mpôl mprơ tâm phung Lêvi, geh Y-Asap, Y-Hêman, jêh ri Y-Yêduthun, ndrel kon bu klâu jêh ri oh nâu khân păng, nsoh ao brai mhay rhên, ndjôt ndơ ngloh bâr, gong rêng loih, jêh ri n'hôm gŭ mpeh pa lơ nơng ndrel ma du rhiăng bar jât nuyh phung kôranh- ƀư-brah jêng phung uh nŭng.$b$,false),
('bunong-vn','2CH',5,13,null,$b$Jêh ri nau blau ma phung uh nŭng nđâp ma phung mprơ ăn bu iăt khân păng tâm rnglăp tâm ban du huê, mât ton tâm rnê ma Yêhôva), jêh ri lah bu tăng bâr mprơ nđâp ma bâr nŭng jêh ri ndơ mpât mprơ êng, dôl tâm rnê mât ton ma Yêhôva, lah: “Yor lah may jêng ueh, nau Păng rŏng n'hêl nanê̆ ngăn gŭ ƀa ƀơ n'hơ ro.” Ngih brah Yêhôva geh tŭk nkâm;$b$,false),
('bunong-vn','2CH',5,14,null,$b$kŏ tât phung kôranh-ƀư-brah mâu dơi gŭ pah kan ôh ta nây yor ma tŭk nây; yor lah nau chrêk rmah Yêhôva chrat ang bêng ngih Brah-Ndu.$b$,false),
('bunong-vn','2CH',6,1,null,$b$Aƀaơ, Y-Salômôn lah: “Yêhôva lah jêh ma Păng mra gŭ tâm ntŭk ngo klĕng.$b$,true),
('bunong-vn','2CH',6,2,null,$b$Ƀiă lah gâp ndâk jêh ma May du mlâm ngih bu yơk, du ntŭk prăp ma May gŭ ƀa ƀơ n'ho ro.”$b$,false),
('bunong-vn','2CH',6,3,null,$b$Pô ri hađăch rle măt păng jêh ri mât ton ma lĕ rngôch phung Israel; dôl lĕ rngôch phung Israel tâm rƀŭn gŭ ndâk da dê.$b$,true),
('bunong-vn','2CH',6,4,null,$b$Păng lah: “Mât ton ma Yêhôva Brah Ndu phung Israel, jêng Nơm hŏ ton jêh lah ma Y-Đavit, mbơ̆ gâp, jêh ri aƀaơ aơ ma ti Păng dơi ƀư nau ton nây hŏ dơi jêng ngăn jêh; Păng lah:$b$,true),
('bunong-vn','2CH',6,5,null,$b$Ntơm bơh nar gâp njŭn leo phung ƀon lan ngluh bơh n'gor bri Êjipt, gâp ê hŏ săch ôh du rplay ƀon tâm ndŭl mpôl phung Israel gay ndâk du mlâm ngih brah, gay dơm Amoh gâp gŭ ta nây, jêh ri gâp ăt mâu hŏ săch lĕ du huê bunuyh jêng kôranh chiă uănh phung ƀon lan Israel gâp;$b$,false),
('bunong-vn','2CH',6,6,null,$b$ƀiă lah gâp hŏ săch jêh Yêrusalem, gay dơm Amoh gâp ta nây, jêh ri gâp hŏ săch jêh Y-Đavit jêng kôranh chiă uănh phung ƀon lan Israel gâp.$b$,false),
('bunong-vn','2CH',6,7,null,$b$Pô ri, Y-Đavit, mbơ̆ gâp rơm ndrăp ơm jêh tâm nuih n'hâm ŭch ndâk du rplay ngih brah gay prăp ma Amoh Yêhôva Brah Ndu$b$,false),
('bunong-vn','2CH',6,8,null,$b$Ƀiă lah Yêhôva lah ma Y-Đavit, mbơ̆ gâp, kơt aơ: ‘Yor lah may geh nau mĭn rơm ndrăp ơm jêh tâm nuih n'hâm may ŭch ndâk du rplay ngih brah ma Amoh gâp, nau nây jêng ueh ngăn yơh,$b$,false),
('bunong-vn','2CH',6,9,null,$b$nđâp lah pô nây may mâu mra ndâk ôh ngih nây; ƀiă lah kon bu klâu may deh mra ndâk ngih brah nây ăn ma Amoh gâp.’$b$,false),
('bunong-vn','2CH',6,10,null,$b$Aƀaơ ri Yêhôva hŏ ƀư tâm di jêh nau Păng ngơi, ntrôl gâp ntrok ăn Y-Đavit, mbơ̆ gâp, jêh ri gŭ klơ sưng hađăch chiă uănh phung Israel, di tĭng nâm Yêhôva hŏ ton jêh; yor ri dĭng gâp ndâk du rplay ngih brah ma Amoh Yêhôva Brah Ndu phung Israel,$b$,false),
('bunong-vn','2CH',6,11,null,$b$jêh ri ta ngih brah nây gâp hŏ dơm jêh hip, tâm hip nây geh nau tâm rnglăp Yêhôva ƀư jêh đah phung ƀon lan Israel.”$b$,false),
('bunong-vn','2CH',6,12,null,$b$Jêh ri Y-Salômôn dâk pa năp nơng ƀư brah Yêhôva, tra năp măt lĕ rngôch phung Israel gŭ rƀŭn, jêh ri păng yơr ti.$b$,true),
('bunong-vn','2CH',6,13,null,$b$(Yor lah păng hŏ jan jêh du mlâm râng ƀư ma kông, jong prăm hăt, jêh ri dĭ rkăng prăm hăt, prêh pe hăt, n'gân ta nklang trong nhuang vâl; păng dâk ta nây, chon kômâk tra năp măt phung ƀon lan Israel gŭ rƀŭn, păng yơr ti klơ trôk),$b$,false),
('bunong-vn','2CH',6,14,null,$b$păng lah: “Ơ Yêhôva Brah Ndu phung Israel! Ta klơ trôk jêh ri tâm neh ntu, mâu hôm geh brah êng ôh tâm ban nâm bu May. May ăt ndjôt prăp lĕ nau tâm rnglăp jêh ri mpơl nau May rŏng n'hêl nanê̆ ngăn ma phung oh mon May, jêng phung chuat pa năp May ma lĕ nuih n'hâm khân păng;$b$,false),
('bunong-vn','2CH',6,15,null,$b$ma đah oh mon May Y-Đavit, mbơ̆ gâp; nanê̆ ngăn May ngơi jêh ma bâr mbung May hŏ ton ma păng: Moh ntil bâr May lah, ma ti May hŏ ƀư nanê̆ jêh tât dơi jêng nâm bu nar aơ.$b$,false),
('bunong-vn','2CH',6,16,null,$b$Yor ri, Ơ Yêhôva Brah Ndu phung Israel, May hŏ ton jêh ma oh mon May Y-Đavit, mbơ̆ gâp, kơt aơ: ‘May mâu mra pah pưt ôh ta năp gâp du huê bu klâu gŭ ta klơ sưng hađăch Israel, tơ lah phung kon bu klâu may njrăng ma trong khân păng chuat, ndjôt prăp nau vay gâp ntăm tâm ban nâm bu may hŏ ƀư jêh ta năp gâp? Aƀaơ dăn hom ma Păng gay mât njrăng nau ton nây.$b$,false),
('bunong-vn','2CH',6,17,null,$b$Yor nây, Ơ Yêhôva Brah Ndu phung Israel! Ăn nau May hŏ ngơi jêh ma Y-Đavit, oh mon May dơi tâm di ngăn.$b$,false),
('bunong-vn','2CH',6,18,null,$b$Ngăn lĕ! Brah Ndu mra gŭ ndrel ma bunuyh tâm neh ntu aơ? Ri trôk, jêh ri ta klơ dŭt prêh mâm dĭng mâu dơi prăp May ôh, ang ma ngih aơ gâp hŏ ndâk jêh mâu dơi ôh prăp ma May!$b$,true),
('bunong-vn','2CH',6,19,null,$b$Nđâp tơ lah pô nây, Ơ Yêhôva Brah Ndu gâp! Dăn May rkêng tôr yô̆ klâng lĕ nau vơh vơl tâm nau mbơh sơm oh mon May dăn ta năp măt May.$b$,false),
('bunong-vn','2CH',6,20,null,$b$Dăn ma May lin măt uănh ma ngih aơ măng nâm nar, yor lah ngih aơ ntŭk May hŏ ton jêh: Mra dơm Amoh May ta nây. Tơ lah oh mon May gŭ mbơh-sơm ta ntŭk aơ, dăn May rkêng tôr iăt ma nau khân păng dăn.$b$,false),
('bunong-vn','2CH',6,21,null,$b$Moh ntil nau oh mon May jêh ri phung ƀon lan May Israel vơh vơl dôl khân păng mbơh sơm rle ma ntŭk aơ; dăn May iăt hom bơh ntŭk May gŭ tâm trôk, jêh ri tơ lah May hŏ tăng jêh, ăn May sŏk dơn, yô̆ an hom.$b$,false),
('bunong-vn','2CH',6,22,null,$b$Tơ lah mbu nâm ƀư tih đah phung chiau meng păng, jêh ri bu ăn păng ton săk, tơ lah păng tât ton săk pa năp nơng May tâm ngih aơ,$b$,true),
('bunong-vn','2CH',6,23,null,$b$rnôk nây dăn ma May bơh trôk iăt, ƀư, jêh ri phat dôih phung oh mon May, nsĭt ma phung kue tĭng nâm nau păng ƀư, ăn nau tih păng nkhŭt ta klơ bôk păng nơm, jêh ri kơp sŏng ma bunuyh geh nau sŏng, jêh ri nkhôm ma păng tĭng nâm nau sŏng păng.$b$,false),
('bunong-vn','2CH',6,24,null,$b$“Tơ lah phung ƀon lan Israel May, ƀư tih đah May, rai roh yor tâm lơh đah phung rlăng, jêh nây tơ lah khân păng plơ̆ sĭt ma May, dơn Amoh May, jêh ri mbơh sơm vơh vơl pa năp May tâm ngih aơ,$b$,true),
('bunong-vn','2CH',6,25,null,$b$rnôk nây iăt hom bơh klơ trôk jêh ri yô̆ an nau tih phung ƀon lan Israel May, jêh ri njŭn leo tay khân păng sĭt ma bri May ăn jêh ma khân păng jêh ri ma phung che khân păng.$b$,false),
('bunong-vn','2CH',6,26,null,$b$“Tơ lah trôk prăng, jêh ri mâu geh mih ôh, yor lah khân păng ƀư tih jêh đah May; tơ lah jêh May tâm rmal khân păng, khân păng ran ta ntŭk aơ gay mbơh sơm, gĭt năl ma Amoh May, cha lơi nau tih khân păng,$b$,true),
('bunong-vn','2CH',6,27,null,$b$ta rnôk ri dăn ma May tă bơh klơ trôk rkêng tôr iăt hom, jêh ri yô̆ an ma nau tih phung oh mon May jêh ri ma phung ƀon lan Israel, tơ lah May nti jêh ma khân păng trong ueh jêng di ma khân păng chuat hăn, jêh ri ăn dak mih djrah ta klơ neh May ăn jêh ma phung ƀon lan May jêng drăp ndơm chăm.$b$,false),
('bunong-vn','2CH',6,28,null,$b$“Tơ lah geh nau ât ji ngot, nau ji tưp, năm phang toyh, nau ek găm sa, ndrŭng, mâu lah krah; mâu lah phung rlăng nchueng văr jŭm ƀon khân păng gŭ; moh ntil nau ji khĭt ndal, moh ntil nau ji tât;$b$,true),
('bunong-vn','2CH',6,29,null,$b$nâm bu ntĭt geh du huê, mâu lah lĕ rngôch phung ƀon lan Israel May, ăp nơm hŏ gĭt năl jêh nau rêh ni păng, nau rngot rvê tâm păng nơm, jêh ri yơr ti rle ma ngih aơ mbơh sơm jêh ri dăn moh ntil nau ŭch,$b$,false),
('bunong-vn','2CH',6,30,null,$b$nôk nây dăn ma May tă bơh trôk jêng ntŭk May gŭ, rkêng tôr iăt hom, jêh ri yô̆ an, plơ̆ sĭt lah ma ăp nơm tĭng nâm trong kan khân păng, yor lah May hŏ gĭt năl jêh nuih n'hâm khân păng (nanê̆ ngăn knŏng êng May yơh dơi gĭt năl nuih n'hâm phung kon bunuyh);$b$,false),
('bunong-vn','2CH',6,31,null,$b$gay ma khân păng dơi klach yơk ma May jêh ri chuat tâm trong May du bông nau rêh khân păng gŭ ta klơ neh bri May hŏ ăn jêh ma phung che hên.$b$,false),
('bunong-vn','2CH',6,32,null,$b$“Tâm ban lĕ, tơ lah du huê bu năch, mâu jêng phung ƀon lan Israel May ôh, ƀiă lah yor Amoh May jêng toyh, jêh ri yor ti brah nau dơi May yơr jêh, khân păng mra văch tât tă bơh n'gor bri ngai rle năp mpeh ngih aơ mbơh sơm,$b$,true),
('bunong-vn','2CH',6,33,null,$b$iăt hom bơh ntŭk May gŭ ta klơ trôk, jêh ri ƀư hom tĭng nâm lĕ rngôch nau bu năch nây kuăl mbơh sơm ma May, gay ma lĕ rngôch phung bunuyh ƀon lan ta neh ntu dơi gĭt năl Amoh May jêh ri klach yơk ma May, nâm bu phung ƀon lan Israel May, jêh ri gay ma khân păng dơi gĭt năl ngih aơ ndâk jêh, bu ntơ ma Amoh May.$b$,false),
('bunong-vn','2CH',6,34,null,$b$“Tơ lah phung ƀon lan May du dâk hăn tâm lơh đah phung rlăng khân păng tĭng nâm trong May mra prơh khân păng hăn, tơ lah khân păng mbơh sơm ma May, rle năp mpeh ma ƀon May hŏ săch jêh aơ, jêh ri ma ngih brah aơ gâp ndâk jêh ma Amoh May,$b$,true),
('bunong-vn','2CH',6,35,null,$b$nôk nây iăt hom tă bơh klơ trôk nau khân păng mbơh sơm dăn jêh ri sâm koh dŏng khân păng.$b$,false),
('bunong-vn','2CH',6,36,null,$b$“Tơ lah phung ƀon lan Israel ƀư tih đah May (yor lah mâu geh du huê bunuyh ôh mâu geh nau tih), jêh ri May ji nuih ma khân păng, jao khân păng ăn ma phung rlăng, jêh ri phung rlăng nhŭp leo khân păng kŏ tât jêng bu nă ma bri ngai mâu lah dăch;$b$,true),
('bunong-vn','2CH',6,37,null,$b$tơ lah tâm n'gor bu njŭn khân păng jêng bu nă, khân păng nklân rvê tay, rmal nau tih, jêh ri dăn ma May, lah: ‘Hên hŏ ƀư tih jêh, ƀư âk ntil nau kue jêh ri gŭ ngao krao sach geh nau djơh mhĭk,$b$,false),
('bunong-vn','2CH',6,38,null,$b$tơ lah tâm n'gor nây phung rlăng hŏ njŭn khân păng tât ăn jêng bu nă, khân păng rmal nau tih ma lĕ rngôch nuih n'hâm lĕ nau mĭn plơ̆ sĭt ma Kôranh Brah, mbơh sơm ma Păng mpeh ma n'gor Kôranh Brah hŏ ăn jêh ma u che (chô yau) khân păng, ma ƀon Kôranh Brah hŏ săch jêh, jêh ri ma ngih brah gâp ndâk jêh ma Amoh May,$b$,false),
('bunong-vn','2CH',6,39,null,$b$dăn ma Kôranh Brah tă bơh trôk jêng ntŭk May gŭ, ăn May iăt hom nau khân păng dăn mbơh sơm, koh dŏng khân păng, jêh ri yô̆ an nau tih phung ƀon lan May hŏ ƀư tih jêh đah May.$b$,false),
('bunong-vn','2CH',6,40,null,$b$Pô ri, Ơ Brah Ndu gâp ơi! Aƀaơ ri dăn ma May rkêng tôr iăt, măt uănh ma nau mbơh sơm tâm ntŭk aơ.$b$,true),
('bunong-vn','2CH',6,41,null,$b$“Aƀaơ, Ơ Yêhôva Brah Ndu! Dâk hom, gay ma May jêh ri hip nau dơi May dơi lăp tâm ntŭk May rlu! Ơ Yêhôva Brah Ndu, ăn phung kôranh ƀư brah May nsoh nau tâm rklaih, jêh ri phung kloh ueh May răm maak ma nau ueh May.$b$,true),
('bunong-vn','2CH',6,42,null,$b$Ơ Yêhôva Brah Ndu, lơi ta mprơh ôh nơm May tŏ dak ƀâu kah! Kah gĭt hom ma nau May rŏng nanê̆ ngăn ma Y-Đavit oh mon May.$b$,true),
('bunong-vn','2CH',7,1,null,$b$Tơ lah Y-Salômôn mbơh sơm lôch jêh, ŭnh tă bơh trôk jŭr su mpa nhhơr gŭch jêh ri mpa ƀư brah, nau chrêk rmah Brah Yêhôva bêng ngih brah.$b$,true),
('bunong-vn','2CH',7,2,null,$b$Phung kôranh ƀư brah kŏ tât mâu dơi lăp tâm ngih brah ma Yêhôva, yor nau chrêk rmah Brah Yêhôva bêng ler ngih Păng.$b$,false),
('bunong-vn','2CH',7,3,null,$b$Lĕ rngôch phung Israel saơ da dê ŭnh nây jêh ri nau chrêk rmah Yêhôva jŭr klơ ngih brah, khân păng chon mon chŭn muh măt tâm neh jêh ri yơk mbah tâm rnê ma Yêhôva, lah: Yor lah Păng jêng ueh, yor nau Păng rŏng n'hêl nanê̆ gŭ ƀa ƀơ n'ho ro!$b$,false),
('bunong-vn','2CH',7,4,null,$b$Nôk nây hađăch jêh ri lĕ rngôch phung ƀon lan nhhơr mpa ƀư brah pa năp Yêhôva.$b$,true),
('bunong-vn','2CH',7,5,null,$b$Hađăch Salômôn nhhơr bar rmưn bar rbăn mlâm ndrôk jêh ri bar rsen biăp nkuăng. Pô nây lĕ hađăch jêh ri nđâp ma phung ƀon lan nhhơr da dê ngih brah ma Brah Ndu.$b$,true),
('bunong-vn','2CH',7,6,null,$b$Phung kôranh ƀư brah gŭ ƀư kan khân păng; phung Lêvi tâm ban lĕ, ndrel ma ndơ mpât mprơ khân păng ƀư nau yơk ma Yêhôva, jêng ndơ Hađăch Đavit lĕ rơm ơm jêh gay tâm rnê ma Yêhôva, yor lah nau Păng rŏng n'hêl nanê̆ gŭ ƀa ƀơ n'ho ro. Tơ lah Y-Đavit nhhơr tâm rnê ma kan khân păng; mpeh ma khân păng phung kôranh ƀư brah uh nŭng; jêh ri lĕ rngôch phung Israel gŭ ndâk.$b$,false),
('bunong-vn','2CH',7,7,null,$b$Y-Salômôn prăp êng du ntŭk kloh tâm nklang nhuang (jâng gung) pa năp ngih brah Yêhôva; yor lah ta nây, păng nhhơr mpa nhhơr gŭch jêh ri ngi ma mpa nhhơr đăp mpăn, yor lah nơng kông Y-Salômôn ƀư, mâu dơi tŏng ntŭk ăn mpa nhhơr gŭch, mpa nhhơr rnih muy (môi), jêh ri ngi.$b$,true),
('bunong-vn','2CH',7,8,null,$b$Dôl nôk nây, Y-Salômôn jêh ri lĕ rngôch phung Israel, văch tât tă bơh n'gor mpeh Hamat tât ma dak n'hor Êjipt, tâm rƀŭn jêng du phung dŭt âk râk, râng nhêt sa da dê tâm pơh nar.$b$,true),
('bunong-vn','2CH',7,9,null,$b$Ta nar rơh pham, khân păng geh nau tâm rƀŭn bêng ma nau yơk, yor lah khân păng râng nau nhhơr nơng tâm pơh nar, jêh ri răm maak nau nhêt sa tâm pơh nar lĕ.$b$,false),
('bunong-vn','2CH',7,10,null,$b$Nar bar jât ma pe khay pơh, păng ăn phung ƀon lan sĭt, nuih n'hâm bêng ma nau maak jêh ri răm rhơn, yor nau ueh Yêhôva hŏ ăn jêh ma Y-Đavit, ma Y-Salômôn, jêh ri ma Israel, jêng ƀon lan Păng.$b$,true),
('bunong-vn','2CH',7,11,null,$b$Pô ri, Y-Salômôn ƀư lôch jêh ngih brah Yêhôva jêh ri ngih hađăch; lĕ kan Y-Salômôn ŭch ƀư tâm ngih Yêhôva jêh ri tâm ngih hađăch, lĕ jêh da dê.$b$,true),
('bunong-vn','2CH',7,12,null,$b$Rnôk nây dôl bri măng Yêhôva tâm mpơl ma Y-Salômôn, pô aơ: Gâp lĕ tăng nau may mbơh sơm, jêh ri hŏ săch jêh ntŭk aơ ƀư du mlâm ngih ƀư brah.$b$,true),
('bunong-vn','2CH',7,13,null,$b$Tơ lah gâp nchăng lĕ mpông trôk, mâu ăn tŭp mih, ăn krah ƀư rai ndơ tuch tăm, jêh ri njuăl nau ji kuet tâm phung ƀon lan gâp;$b$,false),
('bunong-vn','2CH',7,14,null,$b$jêh ri gĭt yŏng mă ƀon lan gâp; jêng phung ƀon lan kuăl ma amoh gâp; dêh rhêt êng khân păng nơm, mbơh sơm tĭng joi muh măt gâp, jêh ri cha lơi trong tih khân păng, nôk nây gâp mra iăt, yô̆ an nau tih khân păng, jêh ri tâm rklaih bri khân păng bơh nau rêh ni.$b$,false),
('bunong-vn','2CH',7,15,null,$b$Aƀaơ ri măt gâp mêt uănh jêh ri tôr gâp gŭ rkêng iăt ma nau bu mbơh sơm tâm ntŭk aơ.$b$,false),
('bunong-vn','2CH',7,16,null,$b$Yor lah aƀaơ gâp săch jêh ri prăp ăn jêh ngih aơ jêng gay kloh; ma Amoh gâp dơi gŭ ta nây ƀa ƀơ n'ho ro; măt jêh ri ndrel ma nuih n'hâm gâp gŭ ta nây ƀa ƀơ tâm lĕ rngôch rô̆.$b$,false),
('bunong-vn','2CH',7,17,null,$b$Bi may, tơ lah may chuat hăn pa năp gâp nâm bu Y-Đavit, mbơ̆ may hŏ ƀư jêh, ƀư tĭng lĕ ntil nau gâp ntăm ma may, jêh ri djôt prăp nau vay gâp,$b$,false),
('bunong-vn','2CH',7,18,null,$b$pô ri gâp mra ƀư nâp sưng hađăch may nâm bu gâp ƀư jêh nau tâm rnglăp đah Y-Đavit mbơ̆ may, jêh ri lah: May mâu mra pưt ôh bunuyh chiă uănh phung Israel.$b$,false),
('bunong-vn','2CH',7,19,null,$b$Ƀiă lah tơ lah khân may teng trong êng cha lơi nau vay gâp jêh ri nau gâp ntăm hŏ n'gân jêh pa năp khân may, jêh ri nkhơng rhŏ (pah kan) ăn ma brah êng jêh ri yơk mbah ma khân păng,$b$,false),
('bunong-vn','2CH',7,20,null,$b$nôk nây gâp mra rôk lơi khân may luh du bơh bri gâp hŏ ăn jêh ma khân may; bi ma ngih aơ gâp hŏ prăp êng jêng kloh ma Amoh gâp, gâp mra mƀăr lơi păng bơh muh măt gâp, jêh ri mra ăn păng jêng du nau ngơi hôr, du nau bu gơm mưch ta nklang lĕ rngôch phung ƀon lan.$b$,false),
('bunong-vn','2CH',7,21,null,$b$Nđâp lah ngih aơ prêh dŭt n'hâm mbu nâm prot dăch păng ăt bu mra geh nau hih rhâl, jêh ri lah: ‘Mâm ir Yêhôva ƀư pô aơ ăn ma bri aơ jêh ri ngih aơ?’$b$,true),
('bunong-vn','2CH',7,22,null,$b$Jêh ri bu mra lah: ‘Yor lah khân păng cha lơi jêh Yêhôva Brah Ndu phung du che khân păng, jêng Nơm hŏ njŭn khân păng du luh bơh n'gor bri Êjipt, jêh ri yor khân păng tĭng ndô̆ brah êng, yơk mbah jêh ri rhŏ (pah kan) ma brah êng nây, yor ri Yêhôva ăn tât lĕ nau mhĭk aơ ma khân păng.$b$,false),
('bunong-vn','2CH',8,1,null,$b$Lôch bar jât năm, jêh Y-Salômôn ndâk ngih brah Yêhôva jêh ri ngih păng nơm gŭ.$b$,true),
('bunong-vn','2CH',8,2,null,$b$Y-Salômôn ndâk nkra tay lĕ ƀon hađăch Y-Huram hŏ jao ăn păng, gay ăn phung ƀon lan Israel gŭ ta nây.$b$,false),
('bunong-vn','2CH',8,3,null,$b$Y-Salômôn hăn tât lơh ƀon Hamat- Sôba jêh ri dơi păng pit in.$b$,true),
('bunong-vn','2CH',8,4,null,$b$Păng ndâk ƀon Tatmôr tâm bri rdah, jêh ri lĕ rngôch ƀon jay drăp tâm n'gor Hamat.$b$,false),
('bunong-vn','2CH',8,5,null,$b$Păng ndâk tâm ban lĕ ƀon Bet-Hôron pa lơ jêh ri ƀon Bet-Hôron pa dâng, jêng ƀon geh pôih ta han, geh mpêr, mpông sâng, jêh ri geh mâng rnăng;$b$,false),
('bunong-vn','2CH',8,6,null,$b$ndâk đŏng ƀon Balat, jêh ri lĕ rngôch ƀon ƀư jay drăp ma Y-Salômôn, jêh ri lĕ rngôch ƀon prăp ndeh seh păng, jêh ri ƀon ăn phung ta han ncho seh gŭ, jêh nây tĭng nâm Y-Salômôn ŭch ndâk tâm ƀon Yêrusalem, tâm bri Liban jêh ri tâm bri păng chiă uănh.$b$,false),
('bunong-vn','2CH',8,7,null,$b$Lĕ rngôch bunuyh hôm e klen rêh tâm phung ndŭl mpôl Hitit, Amôrit, Pêrisit, Hivit, jêh ri Jêbusit, mâu jêng phung Israel ôh,$b$,false),
('bunong-vn','2CH',8,8,null,$b$nâm bu ntĭt phung kon sau khân păng ăt hôm e tâm bri nơm, phung nây phung Israel mâu ƀư rai lĕ ôh phung aơ Y-Salômôn ăn jêng dĭk n'ho tât nar aơ.$b$,false),
('bunong-vn','2CH',8,9,null,$b$Ƀiă lah ma phung ƀon lan Israel, Y-Salômôn mâu njêng dĭk prăp ma kan păng ôh, khân păng jêng ta han, phung kôranh ta han, phung kôranh ma ndeh seh, jêh ri phung ta han ncho seh.$b$,false),
('bunong-vn','2CH',8,10,null,$b$Bi ma phung kôranh toyh ma Hađăch Salômôn dơm kan gay chiă uănh ƀon lan ƀư kan, geh bar rhiăng prăm jât nuyh.$b$,true),
('bunong-vn','2CH',8,11,null,$b$Y-Salômôn prơh bu vơt kon druh Pharaôn bơh ƀon Đavit hao tât ta ngih păng hŏ ndâk jêh ma ô băl; yor lah păng lah: “Ur gâp mâu mra gŭ tâm ngih Y-Đavit, hađăch Israel ôh, yor lah ntŭk hip Yêhôva tât jêh jêng kloh ueh.”$b$,true),
('bunong-vn','2CH',8,12,null,$b$Nôk nây Y-Salômôn nhhơr mpa nhhơr gŭch ma Yêhôva ta klơ nơng Yêhôva păng ndâk jêh pa năp ndring;$b$,true),
('bunong-vn','2CH',8,13,null,$b$tĭng nâm kan nar, nhhơr tĭng nâm nau vay Y-Môis ntăm di tâm nar Saƀat, luh nar khay mhe, jêh ri, ăp năm pe tơ̆ nhêt ƀun, nâm bu ntĭt Nhêt sa Piăng Let Mâu Geh Ndrui. Nhêt Sa Năng Ver (Nar pơh), jêh ri Nau Nhêt Sa ma Ndưp.$b$,false),
('bunong-vn','2CH',8,14,null,$b$Tĭng nâm nau mbơ̆ păng Y-Đavit ntĭnh, păng dơm mpôl phung kôranh ƀư brah prăp ma kan khân păng, jêh ri phung Lêvi prăp ma kan pah khân păng, gay tâm rnê mât ton jêh ri pah kan ta pa năp phung kôranh ƀư brah tĭng nâm kan ăp nar, jêh ri phung mât chiă mpông pêr tĭng nâm mpôl khân păng tâm ăp mpông pêr; yor lah Y-Đavit, bunuyh Brah Ndu, ntăm jêh kơt nây.$b$,true),
('bunong-vn','2CH',8,15,null,$b$Moh ntil nau hađăch ntĭm nti ma phung kôranh ƀư brah jêh ri phung Lêvi, mâu lah ma jrô prăp drăp mâu lah ma nau kan êng, khân păng mâu dơi chuêl hêng du ntil nau ôh.$b$,false),
('bunong-vn','2CH',8,16,null,$b$Pô ri, lĕ rngôch kan Y-Salômôn dŏng tâm nau ndâk ngih brah ma Yêhôva, hŏ ndrăp lor jêh ntơm bơh nar dăp mon mbon ngih kŏ tât lôch lĕ kan. Ngih brah ma Yêhôva hŏ jêh.$b$,false),
('bunong-vn','2CH',8,17,null,$b$Dôl nây Y-Salômôn hăn tât ma ƀon Êsiôn-Gêber jêh ri ƀon Êlat ta kơh dak mƀŭt tâm bri Êđôm.$b$,true),
('bunong-vn','2CH',8,18,null,$b$Y-Huram đă oh mon păng, ndơ̆ tât ma păng ma Kumpăn jêh ri phung oh mon mơng bên đah dak mƀŭt; jêh ri khân păng hăn ma bri Ôphir ndrel ma phung oh mon Y-Salômôn, sŏk ta nây puăn rhiăng prăm jât talâng mah, jêh ri rdeng sĭt ăn ma hađăch Salômôn.$b$,false),
('bunong-vn','2CH',9,1,null,$b$Tơ lah hađăch bu ur bri Sêba tăng lư n'găr amoh Y-Salômôn, păng văch tât ma ƀon Yêrusalem, sŏk nau ngơi hôr gay ôp rlong uănh păng, geh âk ngăn phung kâp kơl nsong ndrel ma păng, jêh ri âk seh samô rdeng dak si ƀâu kah jêh ri âk ngăn mah nđâp ma glo lŭ khlay. Tơ lah păng tât ma Y-Salômôn, lah đah ô băl lĕ ntil geh tâm nuih n'hâm păng.$b$,true),
('bunong-vn','2CH',9,2,null,$b$Y-Salômôn plơ̆ sĭt lah nau păng ôh; mâu geh du ntil ndơ dơi ndâp ôh ma Y-Salômôn mâu dơi rblang ma păng.$b$,false),
('bunong-vn','2CH',9,3,null,$b$Tơ lah hađăch bu ur bri Sêba saơ nau blau mĭn Y-Salômôn, ngih gŭ păng hŏ ndâk jêh,$b$,false),
('bunong-vn','2CH',9,4,null,$b$ndơ sông sa ta klơ sưng sông păng, ngih vâl ma phung oh mon, ăp nau kan ma phung kôranh, jêh ri ndơ nsoh ma khân păng, phung oh mon djôt kachok păng, jêh ri ao jâr khân păng, nđâp ma ndơ nhhơr gŭch păng nhhơr tâm ngih brah Yêhôva, păng mâu hôm blau mĭn ôh.$b$,false),
('bunong-vn','2CH',9,5,null,$b$Păng lah ma hađăch: “Nau gâp tăng bu nkoch tâm bri gâp tâm lĕ nau ngơi jêh ri nau blau mĭn may, di ngăn.$b$,true),
('bunong-vn','2CH',9,6,null,$b$Ƀiă lah ê lor ma gâp tât ta aơ jêh ri ê hŏ măt saơ lĕ nau aơ, gâp mâu iăt nau khân păng; jêh ri aƀaơ, bu mâu mbơh ôh n'gul klong nau may blau; may jêng blau rlau lơn đah nau bu nkoch gâp hŏ tăng lư.$b$,false),
('bunong-vn','2CH',9,7,null,$b$Ueh maak ngăn ma ur may! Lĕ phung oh mon may, phung gŭ pa năp may ƀa ƀơ; jêh ri tăng nau may blau mĭn!$b$,true),
('bunong-vn','2CH',9,8,null,$b$Mât ton ma Yêhôva Brah Ndu may, yor lah Păng geh nau maak đah may jêh ri ăn may gŭ ta sưng hađăch Păng dơi ƀư hađăch ăn Yêhôva Brah Ndu may! Yor lah Brah Ndu may rŏng ma phung Israel, gay ăn ma khân păng dơi nâp ƀa ƀơ n'ho ro, ri dĭng Păng hŏ njêng may ƀư hađăch chiă uănh khân păng, gay ma may ƀư tĭng nau di jêh ri nau sŏng.”$b$,true),
('bunong-vn','2CH',9,9,null,$b$Jêh ri păng nhhơr ma hađăch du rhiăng bar jât talâng mah, jêh ri dŭt âk dak si ƀâu kah, nđâp ma lŭ khlay; mâu dơi geh ôh dak si ƀâu kah ƀa ƀă tâm ban nâm bu dak si ƀâu kah hađăch bu ur bri Sêba nhhơr ma hađăch Salômôn.$b$,true),
('bunong-vn','2CH',9,10,null,$b$Phung oh mon Y-Huram jêh ri phung oh mon Y-Salômôn djôt leo mah bơh bri Ôphir, rmeh ma nây khân păng djôt leo đŏng tơm rte jêh ri glo lŭ khlay.$b$,true),
('bunong-vn','2CH',9,11,null,$b$Ma tơm rte nây yơh păng sŏk, ƀư gung ma ngih Yêhôva, jêh ri ma ngih hađăch, nđâp ma n'hôm rlet jêh ri gong rêng ma phung mprơ; ê lor tâm bri Yuđa, bu mâu mâp saơ geh tâm ban kơt nây.$b$,false),
('bunong-vn','2CH',9,12,null,$b$Hađăch Salômôn ăn ma hađăch bu ur bri Sêba lĕ ndơ păng ŭch, lĕ nau păng dăn, rmeh ma ndơ păng hŏ djôt nhhơr ma hađăch. Jêh ri păng ndrel ma oh mon păng sĭt ma bri khân păng nơm.$b$,false),
('bunong-vn','2CH',9,13,null,$b$Njing jâk glo mah tât ma Y-Salômôn tâm du năm geh prao rhiăng pơh jât talâng mah (mah),$b$,true),
('bunong-vn','2CH',9,14,null,$b$mâu kơp mah phung tăch drăp djôt tăch; nđâp ma mah jêh ri prăk phung hađăch bri Arabi jêh ri phung kôranh toyh chiă uănh bri djôt leo ăn ma Y-Salômôn.$b$,false),
('bunong-vn','2CH',9,15,null,$b$Hađăch Salômôn chiăr ƀư bar rhiăng mlâm khêl toyh ma mah; ăp khêl bu chiăr prao rhiăng sêkel mah.$b$,false),
('bunong-vn','2CH',9,16,null,$b$Jêh ri bu chiăr ƀư pe rhiăng mlâm khêl jê̆ ma mah, tâm ăp mlâm dŏng pe rhiăng Sêkel mah; jêh ri hađăch dơm ăn khêl nây tâm Ngih Bri Krŏng Liban.$b$,false),
('bunong-vn','2CH',9,17,null,$b$Hađăch ƀư du mlâm sưng hađăch toyh đah la, jêh ri mblum păng ma mah chrêk.$b$,false),
('bunong-vn','2CH',9,18,null,$b$Sưng hađăch nây geh prao rplay gung klơ, jêh ri du mlâm ndơ chrong jâng ƀư đah mah, ndơ nây tâm krêp đah sưng hađăch, jêh ri ăp ntŭk kêng meng rnơl geh ndơ rkơl ti mpeh đah aơ jêh ri đah ri êp ntŭk gŭ, êp ntŭk rkơl ti geh bar mlâm yau mŭr.$b$,false),
('bunong-vn','2CH',9,19,null,$b$Hôm geh đŏng jât ma bar rup yau mŭr dâk klơ ntŭk prao rplay gung, pa ma jêh ri pa chiau; mâu mâp geh bri êng ƀư sưng hađăch tâm ban pô nây.$b$,false),
('bunong-vn','2CH',9,20,null,$b$Lĕ rngôch ndơ nhêt dak hađăch Salômôn ƀư đah mah da dê, jêh ri lĕ rngôch khăl ngan dŏng tâm Ngih Bri Krŏng Liban tâm ban lĕ ƀư đah mah chrêk da dê; tâm nau rêh hađăch Salômôn, prăk bu mâu kơp khlay ôh.$b$,false),
('bunong-vn','2CH',9,21,null,$b$Yor lah hađăch geh Kumpăn hăn rlet bri Tarsis ndrel ma phung oh mon Y-Huram; tâm pe năm du tơ̆ mpôl Kumpăn Tarsis rdeng leo mah, prăk, la rveh, dôk jêh ri brak.$b$,false),
('bunong-vn','2CH',9,22,null,$b$Pô ri yơh, hađăch Salômôn jêng rlau lơn ma lĕ rngôch phung hađăch ta neh ntu tâm nau ndrŏng jêh ri nau blau mĭn.$b$,false),
('bunong-vn','2CH',9,23,null,$b$Jêh ri lĕ rngôch hađăch ta neh ntu ŭch joi saơ muh măt Y-Salômôn, gay iăt nau blau mĭn păng tă bơh Brah Ndu hŏ ăn tâm nuih n'hâm păng.$b$,false),
('bunong-vn','2CH',9,24,null,$b$Tâm ăp năm tĭng nau vay ntrŭnh, ăp nơm khân păng djôt leo ndơ nhhơr, ƀă ndơ ƀư ma prăk, ma mah, ƀă ao jâr dak si tăng, dak si ƀâu kah, seh jêh ri seh bri.$b$,false),
('bunong-vn','2CH',9,25,null,$b$Hađăch Salômôn geh puăn rbăn mlâm seh jêh ri ndeh, ndrel ma du rmưn bar rbăn ta han ncho seh, ăn tâm ăp ƀon bun ndeh, jêh ri êp kêng hađăch tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',9,26,null,$b$Păng chiă uănh lĕ rngôch hađăch, ntơm bơh dak krong Ơphrat tât ma n'gor bri Philistin, jêh ri n'ho tât ma n'har neh bri Êjipt.$b$,false),
('bunong-vn','2CH',9,27,null,$b$Tâm ƀon Yêrusalem, păng kơp prăk mâu khlay ôh nâm bu lŭ chreh, jêh ri tơm si Sêdar âk ngăn nâm bu tơm si sikamôr tâm neh lâng Sêphêla.$b$,false),
('bunong-vn','2CH',9,28,null,$b$Geh bunuyh djôt leo ăn Y-Salômôn phung seh rvăt bơh n'gor bri Êjipt, jêh ri tă bơh âk bri dak êng tât ta nây.$b$,false),
('bunong-vn','2CH',9,29,null,$b$Lĕ kan Y-Salômôn ƀư ntơm bơh sa ơm tât lôch nchih tâm ndrom sămƀŭt nkoch nđơn (nkoch bri) Y-Nathan, jêng nơm mbơh lor, jêh ri tâm ndrom sămƀŭt mbơh lor Y-Ahija, bunuyh ƀon Silô chih, jêh ri tâm ndrom sămƀŭt tâm-saơ Y-Idô nơm gĭt saơ chih di ma Y-Jêrôbôam, kon bu klâu Y-Nêbat.$b$,true),
('bunong-vn','2CH',9,30,null,$b$Y-Salômôn chiă uănh lĕ rngôch phung Israel tâm ƀon Yêrusalem puăn jât năm.$b$,false),
('bunong-vn','2CH',9,31,null,$b$Y-Salômôn khĭt hăn gŭ ndrel ma phung che păng, bu tâp păng tâm ƀon Y-Đavit mbơ̆ păng; jêh ri Y-Rêhôbôam kon bu klâu păng chiă uănh thoi ntrok păng.$b$,false),
('bunong-vn','2CH',10,1,null,$b$Y-Rôbôam hăn tât ma ƀon Sichem, yor lah lĕ rngôch phung Israel tât jêh ta ƀon Sichem gay njêng păng hađăch.$b$,true),
('bunong-vn','2CH',10,2,null,$b$Tơ lah Y-Jêrôbôam kon bu klâu Y-Nêbat gĭt nau nây. (Yor lah păng hôm gŭ tâm bri Êjipt, jêng ntŭk păng hŏ du ndĕ, gay tâm ƀah đah hađăch Salômôn); păng sĭt bơh bri Êjipt.$b$,true),
('bunong-vn','2CH',10,3,null,$b$Bu prơh bunuyh hăn kuăl păng, pô ri Y-Jêrôbôam jêh ri lĕ rngôch phung Israel văch mbơh ma Y-Rôbôam pô aơ:$b$,false),
('bunong-vn','2CH',10,4,null,$b$“Mbơ̆ may ndô mâng mbăk jâk ăn phung hên, pô ri aƀaơ, n'hŭch hom ăn n'gơch kan jâk mbơ̆ may nchâp jêh ri mâng mbăk jâk păng ndô jêh ma hên, jêh ri hên mra pah kan ma may.”$b$,false),
('bunong-vn','2CH',10,5,null,$b$Păng plơ̆ lah ma khân păng pô aơ: “Lôch pe nar, khân may plơ̆ mâp gâp.” Pô ri phung ƀon lan du sĭt.$b$,false),
('bunong-vn','2CH',10,6,null,$b$Hađăch Rôbôam dăn nau kơl mĭn bơh phung bu ranh mâp gŭ jêh pa năp Y-Salômôn mbơ̆ păng dôl ô băl hôm rêh, jêh ri lah: Mâm nau khân may kơl mĭn ma gâp gay plơ̆ sĭt lah ma phung ƀon lan aơ?”$b$,true),
('bunong-vn','2CH',10,7,null,$b$Khân păng plơ̆ lah ma păng: “Tơ lah may vơt ƀon lan aơ ma nau rah rơch, gŭ ngao ƀư maak nuih n'hâm khân păng, jêh ri ngơi nau ueh ma khân păng, pô ri khân păng mra jêng oh mon may mro mrăng.”$b$,true),
('bunong-vn','2CH',10,8,null,$b$Ƀiă lah Y-Rôbôam dun nau phung bu ranh kơl nkah, jêh ri păng tâm chră đah phung mom ndăm, du rơh deh ndrel păng jêh ri gŭ pa năp păng.$b$,true),
('bunong-vn','2CH',10,9,null,$b$Păng lah ma khân păng pô aơ: “Mâm nau khân may kơl mĭn nkah ma gâp gay ma he plơ̆ sĭt lah ma phung ƀon lan aơ lah jêh ma gâp, ăn n'gơch hom mâng mbăk mbơ̆ may ndop jêh ma hên?”$b$,false),
('bunong-vn','2CH',10,10,null,$b$Phung mom ndăm hao toyh rơh păng, lah ma păng: “Pô aơ ăn may ngơi ma phung ƀon lan lah jêh ma may, ‘Mbơ̆ may ndop hên mâng mbăk jâk; may ƀư hom ăn păng n'gơch; may plơ̆ lah ma khân păng pô aơ: ‘Nglau kon et gâp toyh lơn chŭr kuyh mbơ̆ gâp.$b$,true),
('bunong-vn','2CH',10,11,null,$b$Pô ri aƀaơ, mbơ̆ gâp hŏ ndop jêh mâng mbăk jâk klơ khân may, bi gâp, gâp ntop đŏng ăn jâk lơn; mbơ̆ gâp hŏ dong jêh khân may ma rse ntâu, ƀiă lah gâp mra dong nsôch khân may ma mpôch ndŭr vơng (ndŭr ving).’ ”$b$,false),
('bunong-vn','2CH',10,12,null,$b$Nar rơh pe, Y-Jêrôbôam jêh ri lĕ rngôch phung ƀon lan hăn tât ma Y-Rêhôbôam da dê tĭng nâm păng hŏ lah jêh kơt aơ: “Văch plơ̆ hom ma gâp nar rơh pe.”$b$,false),
('bunong-vn','2CH',10,13,null,$b$Hađăch Rôbôam plơ̆ sĭt lah ma phung ƀon lan ma nau ngơi dăng jêh ri dun nau phung bu ranh kơl nkah,$b$,false),
('bunong-vn','2CH',10,14,null,$b$tĭng nau chră phung mom ndăm, jêh ri plơ̆ lah ma khân păng pô aơ: “Mbơ̆ gâp ndop mâng mbăk jâk ăn ma khân may; ƀiă lah gâp mra kơi ntop nau jâk ma mâng mbăk nây; mbơ̆ gâp dong khân may ma rse ntâu, ƀiă lah gâp nsôch khân may ma mpôch ndŭr vơng (ndŭr ving).”$b$,false),
('bunong-vn','2CH',10,15,null,$b$Pô ri, hađăch Rôbôam mâu iăt ôh phung ƀon lan kơl nkah; yor lah nau nây jêng tă bơh Brah Ndu ăn nau rlơ̆ , gay ăn Yêhôva ƀư tâm di nau Păng hŏ đă Y-Ahija, bunuyh ƀon Silô, lah ma Y-Jêrôbôam, kon bu klâu Y-Nêbat.$b$,true),
('bunong-vn','2CH',10,16,null,$b$Tơ lah lĕ rngôch phung Israel saơ hađăch mâu iăt nau khân păng, phung ƀon lan plơ̆ lah ma păng pô aơ: “Moh kô̆ ntil hên geh đah Y-Đavit? Hên mâu geh drăp gay ndơn ôh tâm kon bu klâu Y-Yêsê. Ơ phung Israel! Ăp nơm plơ̆ sĭt hom ma ngih bok khân may! Aƀaơ ri uănh hom ma ngih may nơm, Ơ Y-Đavit?” Pô ri, lĕ rngôch phung Israel plơ̆ sĭt ma ngih bok khân păng.$b$,false),
('bunong-vn','2CH',10,17,null,$b$Ƀiă lah ma phung Israel gŭ tâm ƀon n'gor Yuđa Y-Rôbôam chiă uănh khân păng.$b$,false),
('bunong-vn','2CH',10,18,null,$b$Nôk nây, hađăch Rôbôam prơh hăn Y-Adôram, jêng nơm chiă uănh nau kan nchâp, tât ma phung Israel; ƀiă lah phung Israel klŭp păng ma lŭ jêh ri păng khĭt. Hađăch Rôbôam hao ndal ndeh nchuăt ma ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',10,19,null,$b$Pô ri yơh, phung Israel tâm rdâng đah ngih Y-Đavit n'ho tât nar aơ.$b$,true),
('bunong-vn','2CH',11,1,null,$b$Tơ lah Y-Rôbôam plơ̆ sĭt ma ƀon Yêrusalem, păng tâm rƀŭn ngih Yuđa jêh ri Benjamin, du rsen pham rmưn nuyh ta han ueh uĭn, gay tâm lơh đah phung Israel mplơ̆ sĭt ƀon bri hađăch ma Y-Rôbôam.$b$,true),
('bunong-vn','2CH',11,2,null,$b$Ƀiă lah geh bâr ngơi bơh Yêhôva lah ma Y-Sêmaja bunuyh$b$,false),
('bunong-vn','2CH',11,3,null,$b$“Lah hom ma Y-Rôbôam, kon bu klâu Y-Salômôn hađăch Yuđa; jêh ri ma lĕ rngôch phung Israel tâm n'gor Yuđa jêh ri n'gor Benjamin.$b$,false),
('bunong-vn','2CH',11,4,null,$b$Pô aơ Yêhôva lah. Lơi ta khân may tâm lơh đah oh nâu nơm; ăn ăp nơm plơ̆ sĭt hom ma ngih păng nơm, yor lah nau tât aơ tă luh bơh gâp nơm.’ ” Pô ri khân păng tông ma nau Yêhôva ngơi, jêh ri sĭt mâu hăn tâm lơh ôh đah Y-Jêrôbôam.$b$,true),
('bunong-vn','2CH',11,5,null,$b$Y-Rôbôam gŭ tâm ƀon Yêrusalem, jêh ri păng njêng âk ƀon pêr n'gâng (Pôih) tâm neh Yuđa.$b$,true),
('bunong-vn','2CH',11,6,null,$b$Păng ndâk njêng ƀon Ƀêtlêhem ƀon Êtam, ƀon Têkôa,$b$,false),
('bunong-vn','2CH',11,7,null,$b$ƀon Betsur, ƀon Sêko, ƀon Adulam,$b$,false),
('bunong-vn','2CH',11,8,null,$b$ƀon Gat, ƀon Marêsa, ƀon Sip,$b$,false),
('bunong-vn','2CH',11,9,null,$b$ƀon Adôraim, ƀon Lakis, ƀon Asêka,$b$,false),
('bunong-vn','2CH',11,10,null,$b$ƀon Sôra, ƀon Aijalon, jêh ri ƀon Hêbron, ƀon geh pôih ta han tâm neh Yuđa jêh ri tâm neh Benjamin.$b$,false),
('bunong-vn','2CH',11,11,null,$b$Păng ƀư pôih nây nâp ngăn, n'gân kôranh ta han gŭ ta nây, jêh ri bun prăp ndơ sông sa, dak play ôlivơ, jêh ri dak play kriăk ƀâu ta nây.$b$,false),
('bunong-vn','2CH',11,12,null,$b$Păng rơm ndrăp ăp ƀon khêl jêh ri tak, gay ăn ƀon nây dơi jêng nâp ngăn. Neh Yuđa jêh ri neh Benjamin jêng păng da dê chiă uănh.$b$,true),
('bunong-vn','2CH',11,13,null,$b$Phung kôranh ƀư brah jêh ri phung Lêvi tâm lam n'gor Israel, plơ̆ sĭt ma păng da dê bơh lĕ rngôch ntŭk khân păng gŭ.$b$,true),
('bunong-vn','2CH',11,14,null,$b$Yor lah phung Lêvi cha lơi neh ƀon jêh ri ndô ndơ văch ran tât neh phung Yuđa jêh ri ƀon Yêrusalem; yor tă Y-Jêrôbôam jêh ri phung kon bu klâu păng mprơh du khân păng mâu ăn ƀư kan jêng kôranh ƀư brah ma Yêhôva đŏng ôh.$b$,true),
('bunong-vn','2CH',11,15,null,$b$Y-Jêrôbôam njêng phung kôranh ƀư brah ăn ma ntŭk prêh klơ, ăn ma rup trah be nkuăng, jêh ri kon ndrôk păng hŏ ƀư jêh.$b$,false),
('bunong-vn','2CH',11,16,null,$b$Geh đŏng tâm ndŭl mpôl Israel, rơm nuih n'hâm tĭng joi Yêhôva Brah Ndu phung Israel tĭng ndô̆ phung kôranh ƀư brah da dê, jêh ri phung Lêvi tât ta ƀon Yêrusalem gay nhhơr mpa ƀư brah ma Yêhôva Brah Ndu che khân păng.$b$,false),
('bunong-vn','2CH',11,17,null,$b$Tâm pe năm, khân păng ƀư ăn bri Yuđa dơi nâp, gay kơl Y-Rôbôam; kon bu klâu Y-Salômôn dơi chăt jêng; yor lah tâm pa năm nây khân păng tĭng trong Y-Đavit jêh ri Y-Salômôn.$b$,false),
('bunong-vn','2CH',11,18,null,$b$Y-Rôbôam sŏk H'Mahalat, kon druh Y-Jêrimôt, sau Y-Đavit, ƀư ur; jêh ri nsông đŏng đah H'Abihêl kon bu ur Y-Êliap jêng sau Y-Yêsê;$b$,true),
('bunong-vn','2CH',11,19,null,$b$jêh ri păng deh phung kon bu klâu amoh Y-Jêsu, Y-Sêmaria, jêh ri Y-Saham.$b$,false),
('bunong-vn','2CH',11,20,null,$b$Pa kơi jêh ô băl, păng sŏk đŏng H'Maka kon druh Y-Apsalôm, ô băl deh đah păng Y-Abija, Y-Atai, Y-Sisa jêh ri Y-Sêlômit.$b$,false),
('bunong-vn','2CH',11,21,null,$b$Y-Rôbôam rŏng ma H'Maka kon druh Y-Apsalôm hâu lơn đah lĕ rngôch phung ur păng jêh ri lĕ ur yông păng, păng geh jât ma pham nuyh ur tơm jêh ri prao jât nuyh ur yông, jêh ri geh bar jât ma pham nuyh kon bu klâu jêh ri prao jât nuyh kon bu ur.$b$,true),
('bunong-vn','2CH',11,22,null,$b$Y-Rôbôam dơm Y-Abija kon bu klâu đah H'Maka jêng kôranh ma phung oh nâu păng yor lah păng săch jêh gay njêng ô băl hađăch.$b$,false),
('bunong-vn','2CH',11,23,null,$b$Păng n'hêch ma khân păng ma nau blau mĭn jêh ri tâm pă ntŭk gŭ, ƀa ƀă phung bu klâu hăn gŭ lam n'gor Yuđa jêh ri Benjamin, ntŭk ƀon toyh lĕ nâp ngăn geh pôih ta han. Păng ƀơk ăn khân păng ăp ntil ndơ sông sa, jêh ri văng nđăp âk ur ma khân păng.$b$,false),
('bunong-vn','2CH',12,1,null,$b$Tơ lah bri dak Y-Rôbôam chiă uănh jêng nâp jêh ri ktang jêh, păng nđâp ma phung Israel cha lơi lĕ nau vay Yêhôva.$b$,true),
('bunong-vn','2CH',12,2,null,$b$Yor lah khân păng ƀư tih đah Yêhôva, tâm năm rô̆ rơh prăm hađăch Rôbôam. Y-Sisăk, hađăch bri Êjipt văch tât lơh ƀon Yêrusalem;$b$,false),
('bunong-vn','2CH',12,3,null,$b$ndrel ma du rbăn bar rhiăng ndeh seh jêh ri prao rmưn ta han ncho seh. Bu mâu dơi kơp ôh phung ƀon lan văch ndrel păng bơh bri Êjipt, phung Libi, phung Sukim, jêh ri phung Êthiôpi.$b$,false),
('bunong-vn','2CH',12,4,null,$b$Y-Sisăk lăp lơh ƀon geh pôih ta han tâm bri Yuđa jêh ri tât ma ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',12,5,null,$b$Nôk nây kôranh nơm mbơh lor Y-Sêmaja hăn tât ma Y-Rôbôam jêh ri tât ma phung kôranh n'gor bri Yuđa, dôl gŭ tâm rƀŭn ta ƀon Yêrusalem yor ma Y-Sisak, jêh ri lah ma khân păng: “Pô aơ Yêhôva lah, ‘Khân may lĕ cha lơi jêh gâp, pô ri gâp hŏ jao khân may tâm ti Y-Sisăk tâm ban lĕ.”$b$,false),
('bunong-vn','2CH',12,6,null,$b$Nôk nây, phung kôranh Israel jêh ri hađăch n'hôi êng săk khân păng nơm, jêh ri lah: “Yêhôva jêng sŏng.”$b$,false),
('bunong-vn','2CH',12,7,null,$b$Tơ lah Yêhôva saơ khân păng n'hôi êng săk nơm, Yêhôva ngơi lah ma Y-Sêmaja: Khân păng lĕ n'hôi săk nơm jêh (dêh rhêt); gâp mâu mra ƀư rai khân păng ôh, ƀiă lah mra tâm rklaih ma khân păng ƀă; jêh ri gâp mâu mra nkhŭt ôh nau ji nuih ma ƀon Yêrusalem đah ti Y-Sisăk.$b$,false),
('bunong-vn','2CH',12,8,null,$b$Ƀiă lah khân păng mra jêng oh mon Y-Sisăk, gay ma khân păng gĭt ma kan gâp jêh ri kan pah bri hađăch êng mâm nau păng jêng.$b$,false),
('bunong-vn','2CH',12,9,null,$b$Pô ri, Y-Sisăk hađăch Êjipt văch tât lơh ƀon Yêrusalem; păng du nchuăn lĕ rngôch ndô ndơ tâm ngih brah Yêhôva jêh ri ngih hađăch gro nđâp ma khêl mah Y-Salômôn hŏ ƀư tâm ban lĕ.$b$,true),
('bunong-vn','2CH',12,10,null,$b$Hađăch Rôbôam ƀư tay khêl kông ntrok khêl mah nây, jêh ri ăn khêl kông nây jao tâm ti phung kôranh ta han kâp gak mpông pêr hađăch.$b$,false),
('bunong-vn','2CH',12,11,null,$b$Ăp tơ̆ hađăch lăp tâm ngih Yêhôva, nơm gak văch djôt leo khêl nây, jêh ri mplơ̆ sĭt păng ma jrô kôranh ta han gak.$b$,false),
('bunong-vn','2CH',12,12,null,$b$Tơ lah hađăch n'hôi êng săk nơm (dêh rhêt) nau Yêhôva ji nuih lĕ du ngai đah păng, pô ri mâu geh nau ƀư rai lĕ rngôch ôh; jêh ri ăt geh nau ueh lĕ tâm n'gor Yuđa.$b$,false),
('bunong-vn','2CH',12,13,null,$b$Pô ri, hađăch Rôbôam ƀư nâp păng nơm tâm ƀon Yêrusalem jêh ri chiă uănh. Tơ lah păng jêng hađăch, păng hŏ geh puăn jât ma nguay năm jêh; păng chiă uănh jât ma pơh năm tâm ƀon Yêrusalem nâm bu ntĭt Yêhôva hŏ săch jêh lĕ rngôch tâm ndŭl mpôl phung Israel, gay dơm amoh Păng ta nây; bi ma me păng amoh jêng H'Nama, (mê̆ Y-Rôbôam) jêng bu ur Ammôn.$b$,true),
('bunong-vn','2CH',12,14,null,$b$Jêh ri păng ƀư nau mhĭk, yor lah păng mâu ŭch săch ôh tâm nuih n'hâm păng ŭch tĭng joi Yêhôva.$b$,false),
('bunong-vn','2CH',12,15,null,$b$Lĕ rngôch kan Y-Rôbôam ƀư ntơm bơh sa ơm tât lôch, hŏ chih da dê jêh tâm ndrom sămƀŭt kôranh nơm mbơh lor Y-Sêmaja, tâm ndrom sămƀŭt Y-Iđô, jêng nơm tâm saơ, nkoch ma noi deh u che Y-Rêhôbôam đah Y-Jêrôbôam geh nau tâm lơh ƀa ƀơ.$b$,false),
('bunong-vn','2CH',12,16,null,$b$Y-Rôbôam khĭt gŭ ndrel ma che păng Y-Đavit, jêh ri bu tâp păng tâm ƀon Y-Đavit; jêh ri Y-Abija kon bu klâu păng chiă uănh thoi păng.$b$,false),
('bunong-vn','2CH',13,1,null,$b$Năm rơh jât ma pham hađăch Jêrôbôam, Y-Abija ntơm chiă uănh n'gor Yuđa.$b$,true),
('bunong-vn','2CH',13,2,null,$b$Păng chiă uănh pe năm tâm ƀon Yêrusalem. Amoh me păng H'Mikaja, kon bu ur Y-Uriêl bơh bri Gibêa. Geh nau tâm lơh Y-Abija đah Y-Jêrôbôam.$b$,false),
('bunong-vn','2CH',13,3,null,$b$Y-Abija dâk hăn tâm lơh ndjôt leo ndrel păng du phung ta han, puăn rsen nuyh phung ta han ngăch prăl; jêh ri Y-Jêrôbôam săch phung ta han dăng ktang, geh pham rsen nuyh, jêng phung ta han vay tâm lơh.$b$,true),
('bunong-vn','2CH',13,4,null,$b$Y-Abija gŭ dâk ta klơ yôk Sêma-raim jêh ri lah: “Hơi Y-Jêrôbôam jêh ri lĕ rngôch phung Israel iăt hom nau gâp!$b$,true),
('bunong-vn','2CH',13,5,null,$b$Yor lah tă bơh nau tâm rnglăp đah boh, Yêhôva Brah Ndu Israel hŏ ăn jêh bri Israel ma Y-Đavit jêh ri ăn ma phung kon bu klâu păng n'ho ro, mâu ƀơh khân may gĭt?$b$,false),
('bunong-vn','2CH',13,6,null,$b$Nđâp lah pô nây kđôi lĕ, Y-Jêrôbôam, kon bu klâu Y-Nêbat, oh mon Y-Salômôn, jêng kon bu klâu Y-Đavit, du dâk tâm rdâng đah Kôranh Brah păng nơm;$b$,true),
('bunong-vn','2CH',13,7,null,$b$jêh ri ƀa ƀă phung mhĭk tâm rƀŭn ndrel tĭng păng; khân păng jan lah nsan ktang, ŭch tâm lơh đah Y-Rêhôbôam, kon bu klâu Y-Salômôn; bi ma Y-Rêhôbôam dôl hôm ndăm, vĭ vĕ ê hŏ janh tâm lơh ôh đah khân păng.$b$,false),
('bunong-vn','2CH',13,8,null,$b$“Pô ri aƀaơ, khân may mĭn phung khân may mra ŭch tâm rdâng đah bri hađăch Yêhôva hŏ ăn jêh ma kon bu klâu Y-Đavit, khân may jêng du phung mpôl âk lơn, geh djôt leo du mlâm rup kon ndrôk mah hŏ trah jêh jêng brah ma khân may.$b$,false),
('bunong-vn','2CH',13,9,null,$b$Phung khân may ƀơh mprơh phung kôranh ƀư brah Yêhôva, jêng kon sau Y-Arôn jêh ri phung Lêvi; jêh ri njêng êng ma khân may nơm jêng kôranh ƀư brah tĭng kơt nau vay phung ƀon lan bri êng ƀư jêh? Mbu nơm văch tât ndjôt leo du mlâm ndrôk nkuăng gay nhhơr ƀư brah, gay jêng du huê kôranh ƀư brah ăn ma phung brah nklă dơm.$b$,false),
('bunong-vn','2CH',13,10,null,$b$Ƀiă lah ma phung hên, Yêhôva ăt jêng Brah Ndu hên jêh ri hên mâu cha lơi Păng ôh; phung kôranh ƀư brah jêng kon sau Y-Arôn, pah kan ma Yêhôva da dê, jêh ri phung Lêvi kơl kan khân păng;$b$,true),
('bunong-vn','2CH',13,11,null,$b$ăp ôi ơm (ôi rŭk) jêh ri mhaơ, khân păng nhhơr mpa nhhơr gŭch jêh ri dak si ƀâu kah ma Yêhôva; khân păng dăp piăng let nhhơr ma Brah Ndu ta klơ sưng mah kloh, jêh ri mpoh jrêng mray ăn jâng jrêng ang mro ăp măng; yor lah hên djôt prăp nau Yêhôva Brah Ndu hên ntăm jêh, bi khân may lĕ cha lơi jêh Păng.$b$,false),
('bunong-vn','2CH',13,12,null,$b$Aơ, Brah Ndu gŭ ndrel ma hên, jêng kôranh ma hên, jêh ri phung kôranh ƀư brah Păng djôt nŭng tâm lơh gay uh ntrôl nau tâm lơh đah khân may. Ơ phung Israel! Lơi ta tâm lơh ôh đah Yêhôva Brah Ndu phung che khân may, yor lah khân may mâu mra dơi ôh.”$b$,false),
('bunong-vn','2CH',13,13,null,$b$Ƀiă lah Y-Jêrôbôam prơh bunuyh hăn ndăch kâp dah pa kơi khân păng; pô ri ta han Israel gŭ pa năp ta han Yuđa, bi phung ta han kâp dah gŭ pa kơi.$b$,true),
('bunong-vn','2CH',13,14,null,$b$Tơ lah phung Yuđa n'gĭl uănh, ri, geh nau tâm lơh mpeh pa năp jêh ri pa kơi khân păng; ri mơ khân păng nter vơh vơl ma Yêhôva, jêh ri phung kôranh ƀư brah uh nŭng.$b$,false),
('bunong-vn','2CH',13,15,null,$b$Nôk nây phung ta han Yuđa nter troh; tăng bâr phung Yuđa nter troh, ta nây ro Yêhôva lơh Y-Jêrôbôam jêh ri lĕ rngôch phung Israel roh tâm lơh tra năp măt Y-Abija jêh ri phung Yuđa.$b$,false),
('bunong-vn','2CH',13,16,null,$b$Phung Israel nchuăt du đah phung Yuđa, jêh ri Brah Ndu jao khân păng tâm ti phung Yuđa.$b$,true),
('bunong-vn','2CH',13,17,null,$b$Y-Abija jêh ri phung ta han păng nkhĭt âk ngăn bunuyh, geh prăm rsen ta han ueh uĭn tâm phung Israel khĭt.$b$,false),
('bunong-vn','2CH',13,18,null,$b$Pô ri, nôk nây phung ta han Israel roh yor nau tâm lơh, jêh ri ta han phung Yuđa dơi dăng lơn, yor lah khân păng rnơm ma Yêhôva Brah Ndu$b$,false),
('bunong-vn','2CH',13,19,null,$b$Y-Abija tĭng gôk Y-Jêrôbôam, jêh ri pit in âk rplay ƀon păng, ƀon Bethel nđâp ma ƀon jê-jê̆ păng, jêh ri ƀon Jêsana nđâp ma ƀon jê-jê̆ păng, ƀon Êphron nđâp ma ƀon jê-jê̆ păng.$b$,false),
('bunong-vn','2CH',13,20,null,$b$Y-Jêrôbôam mâu hôm dơi dăng ôh dôl tâm rnôk Y-Abija; jêh ri Yêhôva lơh păng pô ri păng khĭt.$b$,false),
('bunong-vn','2CH',13,21,null,$b$Ƀiă lah Y-Abija jêng dăng lơn mro mrăng. Păng sŏk jât ma puăn nuyh ur, jêh ri geh bar jât ma bar nuyh kon bu klâu, jêh ri jât ma prao nuyh kon bu ur.$b$,false),
('bunong-vn','2CH',13,22,null,$b$Kan ƀa ƀă Y-Abija ƀư, nau păng gŭ ngao, jêh ri mbơh ngơi bu chih da dê jêh tâm ndrom, sămƀŭt kôranh nơm mbơh lor Y-Idô nkoch bri.$b$,false),
('bunong-vn','2CH',14,1,null,$b$Pô ri Y-Abija khĭt hăn gŭ ndrel phung che păng jêh ri bu tâp păng tâm ƀon Y-Đavit; jêh ri Y-Asa kon bu klâu păng, chiă uănh thoi păng. Tâm rô̆ păng, n'gor bri nây geh nau đăp mpăn tâm jât năm.$b$,true),
('bunong-vn','2CH',14,2,null,$b$Y-Asa ƀư nau ueh jêh ri di ta năp măt Yêhôva Brah Ndu păng.$b$,true),
('bunong-vn','2CH',14,3,null,$b$Yor lah păng ƀư rai lơi nơng ƀư brah phung bu năch, jêh ri ntŭk prêh klơ, mbang nchah lơi lĕ meh jrŏng (meh gâng) jêh ri kăl nchôt lơi rup trah brah Asêrim;$b$,false),
('bunong-vn','2CH',14,4,null,$b$jêh ri ntĭnh phung Yuđa djôt prăp nau vay Yêhôva Brah Ndu phung che khân păng, ƀư tĭng nau Păng ntăm.$b$,false),
('bunong-vn','2CH',14,5,null,$b$Păng cha lơi lĕ rngôch ntŭk prêh klơ jêh ri nơng ƀư brah ma măt nar tâm lĕ ƀon phung Yuđa tâm ban lĕ. Bri dak geh nay đăp mpăn dôl păng chiă uănh.$b$,true),
('bunong-vn','2CH',14,6,null,$b$Păng ndâk njêng âk rplay ƀon geh mpêr ƀon nâp ngăn tâm lam bri Yuđa, yor lah n'gor bri nây geh nau đăp mpăn, mâu geh ôh nau tâm lơh, yor tă bơh Brah Yêhôva hŏ ăn jêh ma khân păng rlu mpăn.$b$,false),
('bunong-vn','2CH',14,7,null,$b$Păng lah ma phung Yuđa pô aơ: “Ăn hĕ ndâk njêng lĕ rngôch ƀon aơ, tăm mpêr văr jŭm ƀon, ƀư tŭm, mpông pêr jêh ri geh mâng rnăn mâng kâp nđăng mpông; dôl bri dak aơ ăt hôm jêng ndơ he, yor lah he joi jêh Yêhôva Brah Ndu he; he geh joi mơ dơi geh Păng, jêh ri Păng ăn jêh ma he nau đap mpăn văr jŭm he.” Pô ri khân păng ndâk njêng ƀon lan tât dơi chăt jêng.$b$,true),
('bunong-vn','2CH',14,8,null,$b$Y-Asa geh du phung ta han pe rsen nuyh phung Yuđa, djôt khêl jêh ri tak; jêh nây bar rsen pham rmưn phung Benjamin, djôt khêl jêh ri blau ntrŏng na (sŏng pănh na); lĕ rngôch jêng bunuyh dăng ktang.$b$,true),
('bunong-vn','2CH',14,9,null,$b$Y-Sêra du huê Êthiôpi văch tâm lơh đah khân păng ndrel ma du rkeh (jât rsen) ta han jêh ri pe rhiăng ndeh seh; khân păng văch tât ta ƀon Marêsa.$b$,true),
('bunong-vn','2CH',14,10,null,$b$Y-Asa du luh hăn tâm mâp đah păng, jêh ri khân păng dăp nthăng ta han khân păng ŭch tâm bơh tâm rlŭng Sêpahtha ta ƀon Marêsa.$b$,false),
('bunong-vn','2CH',14,11,null,$b$Y-Asa nter vơl ma Yêhôva Brah Ndu păng: “Ơ Yêhôva, mâu geh nơm êng nâm bu May dơi kơl phung ra ai dơi lơh phung dăng; Ơ Yêhôva Brah Ndu hên ơi! Kơl hom hên, yor lah hên rnơm nsing ma May; jêh ri ma amoh Kôranh Brah hên tâm rđâng đah phung aơ. Ơ Yêhôva gâp ơi! May jêng Brah Ndu hên; lơi ta ăn kon bunuyh dơi đah May.”$b$,false),
('bunong-vn','2CH',14,12,null,$b$Pô ri Yêhôva ăn Y-Asa jêh ri phung Yuđa dơi tâm lơh đah phung Êthiôpi, jêh ri phung Êthiôpi nchuăt du.$b$,false),
('bunong-vn','2CH',14,13,null,$b$Y-Asa jêh ri phung ta han ndrel păng tĭng phung Êthiôpi tât ta ƀon Gêrar, phung ta han Êthiôpi khĭt âk, kŏ tât mâu hôm geh du huê bunuyh rêh; yor lah khân păng roh jêh ta năp Yêhôva jêh ri phung ta han Păng phung ta han Yuđa sŏk in âk ngăn ndô ndơ.$b$,false),
('bunong-vn','2CH',14,14,null,$b$Khân păng ăt tâm lơh đŏng đah lĕ rngôch ƀon văr jŭm ƀon Gêrar, yor lah nau klach ma Yêhôva ƀư nau rêh ni ma ƀon nây; jêh nây ta han Y-Asa sŏk in lĕ rngôch ndô ndơ tâm ăp ƀon nây, yor lah tâm ƀon nây geh âk ngăn drăp ndơ.$b$,false),
('bunong-vn','2CH',14,15,null,$b$Lơh đŏng ndrung mât rong mpô mpa, nhŭp veng dŭt âk phung biăp jêh ri samô; gay veng nsĭt rlet ma Yêrusalem.$b$,false),
('bunong-vn','2CH',15,1,null,$b$Brah Huêng Ueh Brah Ndu tât ma Y-Asaria kon bu klâu Y-Ôdet,$b$,true),
('bunong-vn','2CH',15,2,null,$b$jêh ri păng luh hăn tâm mâp đah Y-Asa jêh ri lah: “Iăt hom nau gâp, Ơ Y-Asa, nđâp ma phung Yuđa jêh ri Benjamin. Lah khân may tĭng Yêhôva ndah jŏ, Yêhôva gŭ ndrel ma khân may dah nĕ lĕ; Tơ lah khân may joi Păng, nanê̆ mra dơi mâp Păng; tơ lah khân may cha lơi Păng, pô ri Păng mra cha lơi khân may.$b$,false),
('bunong-vn','2CH',15,3,null,$b$Hŏ jŏ năm jêh, phung Israel mâu chroh ngăn ôh ma Brah Ndu, mâu geh du huê kôranh ƀư brah ntĭm nti ma khân păng, ăt mâu geh lĕ nau vay;$b$,false),
('bunong-vn','2CH',15,4,null,$b$ƀiă lah dôl khân păng geh nau rêh ni, ri mơ khân păng plơ̆ sĭt ma. Yêhôva Brah Ndu Israel, tĭng joi Păng, plơ̆ mâp tay Păng đŏng.$b$,false),
('bunong-vn','2CH',15,5,null,$b$Tâm rnôk nây, mâu geh nau đăp mpăn ôh ma nơm luh mâu lah nơm lăp, yor lah ƀon lan bri nây geh nau rŭng răng toyh ngăn ƀư knap lĕ rngôch bunuyh.$b$,false),
('bunong-vn','2CH',15,6,null,$b$Bri dak aơ tŭn jot bri dak ri, ƀon aơ tŭn jot ƀon êng; yor lah Brah Ndu ƀư rŭng răng khân păng tâm ăp ntil nau rêh ni.$b$,false),
('bunong-vn','2CH',15,7,null,$b$Ƀiă lah ăn khân may gŭ janh hom, ti khân may lơi klach, yor lah kan khân may ƀư mra geh nau nkhôm.$b$,false),
('bunong-vn','2CH',15,8,null,$b$Tơ lah Y-Asa tăng nau ngơi nây, nau mbơh lor Y-Asaria kon bu klâu Y-Ôdet, n'hao nuih păng, jêh ri păng ƀư rai lơi rup brah Yêhôva tâm rmot tâm lam n'gor Yuđa jêh ri Benjamin, nđâp ma tâm ƀon khân păng lĕ pit in jêh bri klơ dor yôk Êphraim, jêh ri păng nkra tay nơng Yêhôva mpeh pa năp ndring ngih Yêhôva.$b$,true),
('bunong-vn','2CH',15,9,null,$b$Păng rgum lĕ rngôch phung Yuđa jêh ri phung Benjamin, jêh ri phung êng bơh ndŭl mpôl Êphraim, Manasê, jêh ri Simêôn gŭ ndrel ma khân păng.$b$,false),
('bunong-vn','2CH',15,10,null,$b$Bu tâm rƀŭn khân păng tâm ƀon Yêrusalem tâm khay pe năm rơh jât ma prăm rô̆ Y-Asa chiă uănh.$b$,false),
('bunong-vn','2CH',15,11,null,$b$Khân păng ƀư brah ma Yêhôva tâm nar nây ma mpô mpa khân păng hŏ sŏk pit djôt nsĭt jêh, pơh rhiăng mlâm ndrôk nkuăng jêh ri pơh rbăn mlâm biăp.$b$,false),
('bunong-vn','2CH',15,12,null,$b$Khân păng ƀư nau tâm rnglăp ŭch joi Yêhôva Brah Ndu phung che khân păng ma lĕ nuih n'hâm jêh ri huêng khân păng;$b$,false),
('bunong-vn','2CH',15,13,null,$b$jêh ri mbu moh mâu joi Yêhôva Brah Ndu phung Israel, bu mra ƀư nkhĭt lơi, mâu săch mom mâu lah ranh, bu klâu mâu lah bu ur.$b$,false),
('bunong-vn','2CH',15,14,null,$b$Khân păng ton săk ma Yêhôva ma bâr huy, ma nau troh, jêh ri uh nŭng.$b$,false),
('bunong-vn','2CH',15,15,null,$b$Lĕ rngôch phung Yuđa hâk răm yor nau ton săk nây; yor lah khân păng ton săk jêh ma lĕ nuih n'hâm khân păng, jêh ri joi Yêhôva ma lĕ nau khân păng ŭch, jêh ri khân păng saơ Păng. Yêhôva ăn ma khân păng nau đăp mpăn văr jŭm pŭng.$b$,false),
('bunong-vn','2CH',15,16,null,$b$Pô ri, yor H'Maka me hađăch Asa, hŏ ƀư jêh du mlâm rup trah brah Asêra, Yêhôva tâm rmot, ri dĭng hađăch Asa ntrŭnh kan mâu hôm ăn păng jêng hađăch bu ur ôh, păng kăl lơi rup trah me păng nây, nchah lơi lĕ jêh ri su tâm ŭnh êp dak n'hor ta rlŭng Sêdrôn.$b$,true),
('bunong-vn','2CH',15,17,null,$b$Ƀiă lah bu mâu ƀư rai lơi ôh ntŭk prêh klơ tâm n'gor Israel. Nđâp lah pô nây kđôi nuih n'hâm Y-Asa jêng ueh, mâu geh bu dơi nduyh ôh du bông nau rêh păng.$b$,false),
('bunong-vn','2CH',15,18,null,$b$Păng djôt leo ma ngih Yêhôva ndơ kloh mbơ̆ păng nhhơr, jêh ri lĕ rngôch ndơ păng nơm ăn êng jêng ndơ hŏ kloh jêh ƀa ƀă mah, ƀă prăk, mâu lah khăl ngan.$b$,false),
('bunong-vn','2CH',15,19,null,$b$Mâu hôm geh nau tâm lơh ôh tât năm rơh pe jât ma prăm rnôk Y-Asa chiă uănh.$b$,false),
('bunong-vn','2CH',16,1,null,$b$Tâm năm rơh pe jât prao rnôk Y-Asa chiă uănh, Y-Baêsa hađăch Israel hăn hao tâm lơh đah phung Yuđa, ndâk ƀon Rama jêng pôih gay nking mâu ăn du huê ƀon lan Y-Asa, hađăch Yuđa dơi luh lăp.$b$,true),
('bunong-vn','2CH',16,2,null,$b$Dôl nây Y-Asa sŏk prăk jêh ri mah tă tâm jrô prăp drăp ndơ tâm ngih Yêhôva jêh ri ngih hađăch jêh ri njuăl ndơ nây ma Y-Ben-Hadat hađăch Syri gŭ ta Damas, jêh ri lah:$b$,false),
('bunong-vn','2CH',16,3,null,$b$“Ăn geh du nau tâm rnglăp ndrăng may ma gâp nâm bu may hŏ ƀư jêh đah mbơ̆ gâp; aơ gâp njuăl ma may prăk jêh ri mah; hăn hom ƀư rai lơi nau may tâm rnglăp đah phung Y-Baêsa hađăch Israel, gay păng du bơh gâp.”$b$,false),
('bunong-vn','2CH',16,4,null,$b$Y-Ben-Hadat iăt tĭng nau hađăch Asa, jêh ri prơh hăn phung kôranh ta han păng tâm lơh đah ƀon phung Israel, khân păng dơi sŏk pit ƀon Ijôn, ƀon Dan, ƀon Abel-Maim, jêh ri lĕ rngôch ƀon geh jay drăp ndơ n'gor Naptali.$b$,false),
('bunong-vn','2CH',16,5,null,$b$Tơ lah Y-Baêsa tăng nau nây, păng cha lơi pah kan ndâk pôih ƀon Rama.$b$,false),
('bunong-vn','2CH',16,6,null,$b$Hađăch Asa rgum lĕ rngôch phung Yuđa; khân păng du nchuăn lĕ lŭ jêh ri tơm si Y-Baêsa hŏ ndrăp dŏng prăp ndâk ƀon Rama, jêh ri ma ndơ nây yơh Y-Asa dŏng ndâk ƀon Gêba jêh ri ƀon Mispa.$b$,false),
('bunong-vn','2CH',16,7,null,$b$Rnôk nây lĕ, nơm bu tâm saơ Y-Hanani hăn tât ma Y-Asa hađăch Yusa jêh ri lah ma păng: “Yor lah may nsing rnơm ma hađăch Syri jêh ri mâu nsing ôh ma Yêhôva Brah Ndu may, phung ta han Syri lĕ klaih du jêh bơh may.$b$,true),
('bunong-vn','2CH',16,8,null,$b$Mâm phung Êthiôpi jêh ri phung Libi mâu hôm geh âk ngăn hĕ phung ta han jêh ri dŭt âk rmeh ngăn ƀơh ndeh seh jêh ri phung ta han ncho seh? Ƀiă lah yor lah may nsing ma Yêhôva, Păng jao jêh phung nây tâm ti may.$b$,false),
('bunong-vn','2CH',16,9,null,$b$Yor lah măt Yêhôva uănh treng tâm lam neh ntu gay tâm mpơl nau ktang Păng mpeh ma phung geh nuih n'hâm ueh đah Păng. Tâm nau aơ may ƀư rluk; yor lah ntơm bơh aƀaơ rlet ô klak may mra geh nau tâm lơh.”$b$,false),
('bunong-vn','2CH',16,10,null,$b$Pô ri Y-Asa ji nuih ma nơm bu tâm saơ nây, nhŭp krŭng ô băl; yor ma nau nây, hađăch ji nuih ngăn ma păng. Dôl nôk nây, Y-Asa păng rgât phung ƀon lan tâm ban lĕ.$b$,false),
('bunong-vn','2CH',16,11,null,$b$Aơ lĕ kan Y-Asa ƀư ntơm bơh sa ơm tât lôch bu chih jêh tâm ndrom sămƀŭt phung hađăch Yuđa jêh ri Israel.$b$,true),
('bunong-vn','2CH',16,12,null,$b$Năm rơh pe jât ma sĭn rnôk Y-Asa chiă uănh, Y-Asa geh nau ji jâng, jêh ri nau ji păng lơ hâu glăm ngăn. Tâm dôl păng ji, păng mâu ŭch tĭng joi ôh Yêhôva, ƀiă lah joi nau bu kơl bơh phung kôranh dak si$b$,true),
('bunong-vn','2CH',16,13,null,$b$Y-Asa khĭt gŭ ndrel phung che păng, khĭt tâm năm rơh puăn jât ma nguay rnôk păng chiă uănh.$b$,false),
('bunong-vn','2CH',16,14,null,$b$Bu tâp păng tâm môch ntŭk păng nơm kuyh jêh tâm ƀon Y-Đavit. Bu njor păng ta klơ du mlâm sưng bêng n'hôl ƀâu dak si ƀâu kah ăp ntil, bu nkra ơm jêh tĭng nau bu n'hĭ. Pô ri bu su ŭnh toyh dŭt âk ŭch yơk ma păng.$b$,false),
('bunong-vn','2CH',17,1,null,$b$Y-Jôsaphat kon bu klâu păng chiă uănh thoi ntrok păng, jêh ri păng ăn bri dak păng jêng ktang dơi tâm rdâng đah phung Israel.$b$,true),
('bunong-vn','2CH',17,2,null,$b$Păng dơm phung ta han tâm lĕ rngôch ƀon geh pôih ta han tâm n'gor Yuđa, jêh ri ƀư pôih ta han tâm n'gor Yuđa jêh ri tâm ăp ƀon Êphraim, ƀon mbơ̆ păng Y-Asa pit in jêh.$b$,false),
('bunong-vn','2CH',17,3,null,$b$Yêhôva gŭ ndrel ma Y-Jôsaphat, yor lah păng chuat hăn tĭng trong chô yau păng Y-Đavit, hăn jêh tâm rnôk ntơm sa-ơm. Păng mâu joi brah Baal ôh,$b$,false),
('bunong-vn','2CH',17,4,null,$b$ƀiă lah joi Brah Ndu phung che păng, tĭng kơt lĕ nau vay Păng ntăm, jêh ri mâu ƀư ôh kơt phung Israel.$b$,false),
('bunong-vn','2CH',17,5,null,$b$Yor ri Brah Ndu ƀư nâp ƀon bri hađăch tâm ti păng; jêh ri lĕ rngôch phung Yuđa chê̆ pi ma Y-Jôsaphat. Păng geh nau ndrŏng toyh jêh ri nau yơk ma păng.$b$,false),
('bunong-vn','2CH',17,6,null,$b$Nuih n'hâm păng geh nau nâp răp jăp tĭng trong Yêhôva; jêh ri rlau ma nây păng ƀư rai lơi ntŭk prêh klơ jêh ri rup brah Asêrim bơh bri Yuđa.$b$,true),
('bunong-vn','2CH',17,7,null,$b$Tâm năm rơh pe rnôk păng chiă uănh, păng prơh hăn phung kôranh, oh mon păng, amoh Y-Ben-Hêl, Y-Ôbadia, Y-Sakari, Y-Nêthanel, jêh ri Y-Mikaya ăn nti tâm ƀon toyh n'gor Yuđa;$b$,true),
('bunong-vn','2CH',17,8,null,$b$ndrel ma khân păng geh phung Lêvi, amoh Y-Sêmaya, Y-Nêthania, Y-Sêbadia, Y-Asabel, Y-Sêmiramôt, Y-Tôbadônija; geh đŏng Y-Êlisama jêh ri Y-Jôram, bar hê kôranh ƀư brah hăn ndrel lĕ.$b$,false),
('bunong-vn','2CH',17,9,null,$b$Khân păng djôt leo ndrom sămƀŭt Yêhôva, hăn nsong lam ƀon tâm n'gor Yuđa nti lah ma phung ƀon lan.$b$,false),
('bunong-vn','2CH',17,10,null,$b$Nau klach ma Yêhôva tât ma lĕ rngôch puăn njônh bri dak văr jŭm n'gor Yuđa, jêh ri khân păng mâu tâm lơh ôh đah Y-Jôsaphat.$b$,true),
('bunong-vn','2CH',17,11,null,$b$Ƀa ƀă phung Philistin djôt leo ndơ nhhơr ma Y-Jôsaphat jêh ri chê̆ pi ma prăk. Tâm ban lĕ phung Arabi leo ma păng pơh rbăn pơh rhiăng mlâm biăp nkuăng, jêh ri pơh rbăn pơh rhiăng mlâm be nkuăng.$b$,false),
('bunong-vn','2CH',17,12,null,$b$Y-Jôsaphat lơ nar lơ hao jêng toyh mro. Păng ndâk tâm n'gor Yuđa pôih ta han jêh ri ƀon jay ăn drăp.$b$,false),
('bunong-vn','2CH',17,13,null,$b$Păng bun prăp âk ndô ndơ tâm ƀon n'gor Yuđa. Păng geh phung ta han janh ktang tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',17,14,null,$b$Aơ jêng rnoh kơp ma khân păng tĭng nâm noi deh khân păng; bơh n'gor Yuđa, phung kôranh ta han kôranh ma du rbăn nuyh: Y-Atna jêng kôranh, tâm pe rsen nuyh ta han janh ktang,$b$,false),
('bunong-vn','2CH',17,15,null,$b$jêh ri nơm mrô bar Y-Jônathan jêng kôranh ta han, păng uănh bar rsen pham rmưn ƀiă lah janh ktang;$b$,false),
('bunong-vn','2CH',17,16,null,$b$nơm mrô pe jêng Y-Amasia kon bu klâu Y-Sikri, du huê nơm pah kan ma Yêhôva ma nau duh nđơr, păng uănh bar rsen bunuyh janh ktang.$b$,false),
('bunong-vn','2CH',17,17,null,$b$Bơh phung Benjamin: Y-Êliada jêng bunuyh janh ktang, păng uănh bar rsen ta han djôt na jêh ri khêl,$b$,false),
('bunong-vn','2CH',17,18,null,$b$jêh ri nơm rơh bar Y-Jôsaphat geh du rsen pham rmưn ta han djôt ndơ tâm lơh.$b$,false),
('bunong-vn','2CH',17,19,null,$b$Phung aơ pah kan ma hađăch, jêng phung lĕ rmeh hađăch hŏ dơm jêh tâm ăp ƀon geh pôih ta han lam n'gor Yuđa.$b$,false),
('bunong-vn','2CH',18,1,null,$b$Y-Jôsaphat geh nau ndrŏng toyh jêh ri nau bu yơk; jêh ri păng ƀư nau tâm rnglăp đah Y-Ahap tâm nau njêng rnăk ur sai.$b$,true),
('bunong-vn','2CH',18,2,null,$b$Rlau bar pe năm, păng hăn jŭr tât Y-Ahap ta Samari. Y-Ahap gŭch âk mlâm biăp jêh ri ndrôk ma păng jêh ri ma phung ƀon lan hăn ndrel ma păng, jêh ri sŭk nsôr păng hăn hao tâm lơh đah ƀon Ramôt-Galaat.$b$,false),
('bunong-vn','2CH',18,3,null,$b$Y-Ahap hađăch Israel lah ma Y-Jôsaphat hađăch Yuđa: “May mra hăn ndrel ma gâp lơh ƀon Ramôt ta Galaat lĕ?” Păng plơ̆ lah: “Gâp jêng nâm bu may, phung ƀon lan gâp jêng nâm bu ƀon lan may lĕ, gâp mra hăn ndrel ma may tâm nau tâm lơh.”$b$,false),
('bunong-vn','2CH',18,4,null,$b$Y-Jôsaphat lah ma hađăch Israel: “Lor lơn ôp hom Yêhôva.”$b$,true),
('bunong-vn','2CH',18,5,null,$b$Hađăch Israel tâm rƀŭn phung kôranh nơm mbơh lor geh puăn rhiăng nuyh, jêh ri lah ma khân păng: “Hên mra hăn tâm lơh đah ƀon Ramôt ta Galaat lĕ mâu lah mâu?” Khân ô băl lah “Hăn hom, yor lah Brah Ndu mra jao ƀon nây tâm ti hađăch.”$b$,false),
('bunong-vn','2CH',18,6,null,$b$Ƀiă lah Y-Jôsaphat lah: Ta aơ, hôm e geh lĕ kôranh nơm mbơh lor ma Yêhôva êng, gay ôp ma păng đŏng?”$b$,false),
('bunong-vn','2CH',18,7,null,$b$Hađăch Israel plơ̆ lah ma Y-Jôsaphat pô aơ: “Hôm e du huê kon bu klâu Y-Imla amoh Y-Mika, ma nơm nây dơi ôp Yêhôva; ƀiă lah gâp ji nuih ma păng yor lah păng mâu prot mbơh nau ueh lor ôh ma gâp, ƀiă lah păng mbơh nau mhĭk mro.” Y-Jôsaphat lah: “Lơi ăn hađăch ngơi pô nây ôh.”$b$,true),
('bunong-vn','2CH',18,8,null,$b$Pô ri hađăch Israel kuăl du huê kôranh ta han jêh ri lah: “Njŭn leo gơnh Y-Mika kon bu klâu Y-Imla.”$b$,false),
('bunong-vn','2CH',18,9,null,$b$Nôk nây hađăch Israel jêh ri Y-Jôsaphat, hađăch Yuđa, ăp nơm nsoh ao jâr hađăch da dê, dôl gŭ ta klơ sưng hađăch ta ntŭk mprah ba êp mpông sâng ƀon toyh Samari; bi lĕ rngôch phung kôranh nơm mbơh lor gŭ mbơh lor pa năp bar hê hađăch.$b$,true),
('bunong-vn','2CH',18,10,null,$b$Y-Sêdêkia kon bu klâu Y-Kêmana nkra ma păng nke loih jêh ri lah: “Pô aơ Yêhôva lah: ‘Ma nke aơ khân may mra tâm phung Syri kŏ tât khân păng rai lĕ.’ ”$b$,true),
('bunong-vn','2CH',18,11,null,$b$Lĕ rngôch kôranh nơm mbơh lor ăt tâm ban lĕ, jêh ri lah: “Hăn hao lơh hom ma ƀon Ramôt ta Galaat; hađăch mra dơi yơh, yor lah Yêhôva mra jao ƀon nây tâm ti hađăch.$b$,false),
('bunong-vn','2CH',18,12,null,$b$Pô ri, nơm hăn kuăl Y-Mika lah ma păng pô aơ: “Aơ lĕ phung kôranh nơm mbơh lor ngơi du ai nau jêh ri jêng nau ueh ma hađăch; pô ri gâp dăn ma may ăn nau may ngơi jêng nâm bu nau ngơi khân păng, jêh ri ngơi hom nau ueh.”$b$,true),
('bunong-vn','2CH',18,13,null,$b$Ƀiă lah Y-Mika lah: “Tĭng nâm Yêhôva gŭ rêh, moh nau Brah Ndu gâp lah, gâp mra ngơi nau nây.”$b$,false),
('bunong-vn','2CH',18,14,null,$b$Tơ lah păng lĕ tât jêh ma hađăch, hađăch ôp ma păng: “Ơ Y-Mika, hên mra hăn lơh ƀon Ramôt ta Galaat, dơi lĕ mâu lah mâu dơi hăn ôh?” Păng plơ̆ lah: “Hăn hao hom, hađăch mra dơi yơh; bu mra jao khân păng tâm ti bar hê may hađăch.”$b$,false),
('bunong-vn','2CH',18,15,null,$b$Ƀiă lah hađăch lah ma păng: “Ndah hŏ âk tơ̆ gâp ntĭnh ma may gay ma may ngơi knŏng nau ngơi ngăn tâm amoh Yêhôva ma gâp?”$b$,false),
('bunong-vn','2CH',18,16,null,$b$Y-Mika plơ̆ lah: Gâp saơ lĕ rngôch phung Israel chah rai êng êng ta klơ yôk nâm bu phung biăp du nhhơt mâu geh rmăk ôh; jêh ri Yêhôva lah pô aơ: ‘Phung aơ mâu geh kôranh ôh; ăn ăp nơm plơ̆ sĭt ma ngih păng ma nau đăp mpăn.’ ”$b$,true),
('bunong-vn','2CH',18,17,null,$b$Hađăch Israel lah ma Y-Jôsaphat pô aơ: Mâu di hĕ nau gâp lah jêh ma păng mâu mra mbơh ôh nau ueh ma gâp, ƀiă lah knŏng nau mhĭk?”$b$,false),
('bunong-vn','2CH',18,18,null,$b$Y-Mika lah: “Yor nây iăt hom nau Yêhôva ngơi: Gâp saơ jêh Yêhôva gŭ ta klơ sưng hađăch păng, jêh ri lĕ rngôch phung ta han tâm trôk gŭ dâk mpeh pa ma jêh ri, pa chiau păng;$b$,true),
('bunong-vn','2CH',18,19,null,$b$jêh ri Yêhôva lah: ‘Mbu mra ndơm Y-Ahap hađăch Israel hăn hao Ramôt ta Galaat n'ho cha lôt khĭt ta nây?’ Jêh ri du huê lah pô aơ du huê êng lah pô ri.$b$,false),
('bunong-vn','2CH',18,20,null,$b$Nôk nĕ, geh du huê brah tât dâk pa năp Yêhôva, jêh ri lah: ‘Gâp mra ndơm păng.’ Yêhôva lah ma păng: ‘Mâm ƀư may ndơm păng?’$b$,false),
('bunong-vn','2CH',18,21,null,$b$Păng plơ̆ lah: ‘Gâp mra hăn jêng du huê brah mƀruh tâm bâr mbung lĕ rngôch phung kôranh nơm mbơh lor păng.’ Yêhôva lah: ‘Ăn may hăn ndơm păng, jêh ri may mra dơi; hăn hom jêh ri ƀư kơt nĕ.’$b$,false),
('bunong-vn','2CH',18,22,null,$b$Yor nây aƀaơ ri, aơ Yêhôva hŏ dơm jêh du huê brah mƀruh tâm bâr mbung phung kôranh nơm mbơh lor may aơ; Yêhôva ngơi jêh nau mhĭk di ma may.”$b$,false),
('bunong-vn','2CH',18,23,null,$b$Y-Sêdêkia, kon bu klâu Y-Kênana, văch dăch, tap bom Y-Mika jêh ri lah: Ntŭk trong huêng brah Yêhôva luh bơh gâp hăn ngơi ma may?”$b$,true),
('bunong-vn','2CH',18,24,null,$b$Y-Mika lah: “Aơ, tâm nar may nchuăt krap ntơm jrô aơ tât jrô ri ta nây may mra gĭt nau nây.$b$,false),
('bunong-vn','2CH',18,25,null,$b$Hađăch Israel lah: “Nhŭp Y-Mika njŭn leo păng tât Y-Amôn kôranh mât chiă ƀon jêh ri Y-Jôsa kon bu klâu hađăch,$b$,false),
('bunong-vn','2CH',18,26,null,$b$jêh ri lah: Hađăch lah pô aơ: Krŭng nơm aơ, jêh ri siăm păng ma piăng let jêh ri dak djê̆ djê̆ kŏ tât gâp lŏ plơ̆ sĭt đăp mpăn.”$b$,false),
('bunong-vn','2CH',18,27,null,$b$Y-Mika lah: “Tơ lah may plơ̆ sĭt đăp mpăn, Yêhôva mâu prot ngơi ôh nau nây ma gâp.” Jêh ri Y-Mika lah: Ơ phung ƀon lan, lĕ rngôch khân may iăt hom nau nây!$b$,false),
('bunong-vn','2CH',18,28,null,$b$Pô ri, hađăch Israel jêh ri Y-Jôsaphat hađăch Yuđa, hăn hao rlet ma ƀon Ramôt ta Galaat.$b$,true),
('bunong-vn','2CH',18,29,null,$b$Hađăch Israel lah đah Y-Jôsaphat pô aơ: “Gâp rgâl săk nkrơ̆ ƀư bu êng jêh ri hăn ma nau tâm lơh, ƀiă lah may nsoh ao jâr may.” Hađăch Israel nkrơ̆ ƀư bu êng, jêh ri khân păng hăn ma nau tâm lơh.$b$,false),
('bunong-vn','2CH',18,30,null,$b$Hađăch Syri ntĭnh jêh ma phung kôranh ta han ƀĭt ndeh seh păng: “Lơi tâm lơh đah phung jê̆ mâu lah phung toyh, ƀiă lah knŏng đah hađăch Israel.”$b$,true),
('bunong-vn','2CH',18,31,null,$b$Tơ lah kôranh ta han ƀĭt ndeh seh saơ Y-Jôsaphat, khân păng lah: “Aơ yơh hađăch Israel.” Pô ri khân păng veh tâm lơh đah ô băl; jêh ri Y-Jôsaphat nter, jêh ri Yêhôva kơl păng. Brah Ndu ăn phung rlăng du bơh păng,$b$,false),
('bunong-vn','2CH',18,32,null,$b$yor lah tơ lah phung kôranh ta han ƀĭt ndeh seh saơ mâu di jêng hađăch Israel ôh, khân păng rŭch plơ̆ mâu hôm tĭng ô băl ôh.$b$,false),
('bunong-vn','2CH',18,33,null,$b$Ƀiă lah geh du huê bu klâu pănh na pănh blă blơ jêh ri geh pănh hađăch Israel ta ntŭk vah vang nđa nsiap ao loih ndơ nkŭm ntang ntơh. Y-Ahap lah đah nơm ƀĭt ndeh seh păng: “Plăch ndeh jêh ri rdeng gâp luh du bơh nau tâm lơh, yor lah gâp lĕ rmanh jêh.”$b$,true),
('bunong-vn','2CH',18,34,null,$b$Nau tâm lơh nar nây ktang ngăn ngên, jêh ri hađăch Israel ăn bu kơl rgong păng gŭ păn tâm ndeh seh păng, rle măt mpeh phung Syri tât kêng măng. Jêh ri ta nhâp nar păng khĭt.$b$,false),
('bunong-vn','2CH',19,1,null,$b$Y-Jôsaphat hađăch Yuđa plơ̆ sĭt ma nau đăp mpăn tât ma ngih păng nơm tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',19,2,null,$b$Ƀiă lah Y-Jêhu, kon bu klâu Y-Hanani, nơm bu tâm saơ, luh hăn tâm mâp ma Y-Jôsaphat, jêh ri lah: “Jêng di lĕ may lah may kơl nơm ƀai jêh ri rŏng ma phung tâm rmot ma Yêhôva? Yor nau nây, nau Yêhôva ji nuih tât ma may.$b$,false),
('bunong-vn','2CH',19,3,null,$b$Ƀiă lah ăt bu saơ lĕ nau ueh tâm may, yor lah may ƀư rai jêh rup brah Asêrim ngluh lơi bơh n'gor bri, jêh ri nuih n'hâm may săch joi Brah Ndu.”$b$,true),
('bunong-vn','2CH',19,4,null,$b$Y-Jôsaphat gŭ ta ƀon Yêrusalem; jêh ri păng hăn joi tay phung ƀon lan, ntơm bơh ƀon Bêr-Sêba tât ta bri klơ dor Êphraim, jêh ri njŭn leo khân păng plơ̆ sĭt ma Yêhôva Brah Ndu phung che khân păng.$b$,true),
('bunong-vn','2CH',19,5,null,$b$Păng dơm phung kôranh phat dôih tâm lam bri, tâm ăp ƀon toyh geh pôih ta han tâm bri Yuđa, tâm ăp rplay ƀon geh da dê.$b$,false),
('bunong-vn','2CH',19,6,null,$b$Jêh ri păng lah ma kôranh phat dôih pô aơ: “Njrăng hom moh kan khân may ƀư, yor lah khân may phat dôih mâu di ma bunuyh ôh, ƀiă lah ma Yêhôva; păng gŭ ndrel ma khân may dôl khân may phat dôih.$b$,false),
('bunong-vn','2CH',19,7,null,$b$Pô ri ăn khân may geh nau klach ma Yêhôva; njrăng hom moh ndơ khân may ƀư, yor lah Yêhôva Brah Ndu he, mâu dơi tih ôh đah nau sŏng, mâu geh gŭ mpeh du ding ôh, mâu lĕ sa ndơ bu blŏl.”$b$,false),
('bunong-vn','2CH',19,8,null,$b$Rmeh ma nau nây Y-Jôsaphat săch đŏng tâm phung Lêvi, kôranh ƀư brah jêh ri phung kôranh ma ndŭl mpôl Israel, dơm khân păng ta ƀon Yêrusalem, gay phat dôih yor ma Yêhôva jêh ri phat dôih ăn tâm di.$b$,false),
('bunong-vn','2CH',19,9,null,$b$Păng ntăm ma khân ô băl: “Pô aơ khân may mra ƀư tâm nau klach yơk ma Yêhôva; ma nau n'hêl nanê̆ jêh ri ma lĕ khân may:$b$,false),
('bunong-vn','2CH',19,10,null,$b$Ta ntŭk geh du ntil dôih tât ma khân may bơh phung oh nâu gŭ tâm ƀon khân păng, moh nau tâm kuh tâm phong, mâu lah yor nau pling mham, mâu lah nau vay jêh ri nau ntăm, ăn khân may ntĭm nti khân păng lơi ƀư tih ôh đah Yêhôva, klach geh nau ji nuih tât ma may jêh ri oh nâu may. Khân may ƀư pô nây, mâu jêng tih ôh.$b$,false),
('bunong-vn','2CH',19,11,null,$b$Aơ, Y-Amaria kôranh ƀư brah toyh jêng kôranh ma khân may tâm lĕ nau di ma Yêhôva; jêh ri Y-Sêbadia kon bu klâu Y-Ismaêl, kôranh chiă uănh ndŭl mpôl phung Yuđa, jêng kôranh ma khân may tâm lĕ kan di ma hađăch; jêh ri phung Lêvi mra pah kan ma khân may jêng phung kôranh. Ƀư hom nau janh, jêh ri dăn ma Yêhôva gŭ ndrel ma phung sŏng!”$b$,false),
('bunong-vn','2CH',20,1,null,$b$Jêh nau nây, phung Môap jêh ri phung Amôn, ndrel ma ƀa ƀă phung Mêun văch tâm lơh đah Y-Jôsaphat.$b$,true),
('bunong-vn','2CH',20,2,null,$b$Geh ƀa ƀă bu klâu tât mbơh ma Y-Jôsaphat, “Du phung âk ngăn văch jêh ŭch tâm lơh đah may bơh bri Êđôm, bơh đah ri dak mƀŭt; jêh ri ta aơ, khân păng gŭ tâm ƀon Hasasôn Tamar” (trơn amoh ƀon Êngêdi).$b$,true),
('bunong-vn','2CH',20,3,null,$b$Pô ri Y-Jôsaphat klach jêh ri joi săch Yêhôva, jêh ri ntĭnh nau ât sông sa lam n'gor Yuđa.$b$,true),
('bunong-vn','2CH',20,4,null,$b$Phung Yuđa tâm rƀŭn ŭch joi nau Yêhôva kơl, bơh lĕ rngôch ƀon n'gor Yuđa, khân păng văch ŭch joi Yêhôva.$b$,false),
('bunong-vn','2CH',20,5,null,$b$Y-Jôsaphat gŭ dâk tâm nau tâm rƀŭn phung Yuđa jêh ri phung ƀon Yêrusalem, tâm trôm ngih brah pa năp ndring mhe,$b$,true),
('bunong-vn','2CH',20,6,null,$b$mbơh sơm pô aơ: Ơ Yêhôva Brah Ndu phung che hên! Mâu di hĕ May jêng Brah Ndu klơ trôk? Mâu di hĕ May jêng kôranh ma lĕ rngôch ƀon bri hađăch phung ndŭl mpôl bunuyh? Tâm ti May geh nau brah jêh ri nau ktang, pô ri mâu geh du huê dơi tâm rdâng ôh đah May.$b$,false),
('bunong-vn','2CH',20,7,null,$b$Ơ Brah Ndu hên, mâu di hĕ May mprơh jêh phung gŭ tâm bri aơ pa năp phung ƀon lan Israel, jêh ri jao bri aơ n'ho ro ma phung kon sau Y-Abraham mĭt jiăng May?$b$,false),
('bunong-vn','2CH',20,8,null,$b$Khân păng gŭ jêh tâm bri aơ jêh ri ndâk jêh ma May du ntŭk kloh ueh ma Amoh May dôl nây lah:$b$,false),
('bunong-vn','2CH',20,9,null,$b$“Tơ lah nau mhĭk tât ma hên, ƀă tak đao, mâu nau phat dôih, mâu lah nau ji kuet, mâu lah sa sât ji ngot, hên mra gŭ dâk ta năp ngih aơ jêh ri pa năp May, (yor lah Amoh May gŭ tâm ngih aơ), jêh ri vơl dăn ma May dôl hên geh nau rêh ni, jêh ri May mra tăng jêh ri May tâm rklaih hên.$b$,false),
('bunong-vn','2CH',20,10,null,$b$Dôl phung ƀon lan Israel hao tă bơh n'gor Êjipt, May mâu ăn ôh khân păng lăp tâm lơh tât tâm n'gor phung Amôn, phung Môap jêh ri phung yôk Sêir, phung Israel mâu ŭch tâm mâp khân păng, jêh ri mâu ƀư rai khân păng ôh.$b$,false),
('bunong-vn','2CH',20,11,null,$b$Nĕ Aơ, khân păng plơ̆ mbơh ma hên ma nau, văch tât ŭch mprơh hên tă bơh neh ndơn drăp may, neh nây may ăn jêh pha ma hên.$b$,true),
('bunong-vn','2CH',20,12,null,$b$Ơ Brah Ndu hên, mâu di hĕ may mra phat dôih khân păng? Yor lah hên mâu geh nau ktang ôh tâm lơh đah phung âk râk aơ văch lơh hên. Hên mâu gĭt ôh mâm mra ƀư, ƀiă lah măt hên gŭ uănh ma May.”$b$,false),
('bunong-vn','2CH',20,13,null,$b$Dôl nây lĕ rngôch phung bu klâu Yuđa gŭ dâk pa năp Yêhôva ndrel ma phung kon jê̆, phung ur, jêh ri phung kon khân păng.$b$,true),
('bunong-vn','2CH',20,14,null,$b$Huêng brah Yêhôva jŭr gŭ ta Y-Jahasiêl kon bu klâu Y-Sakari, sau Y-Bênaya, se Y-Jêiêl, săn Y-Matania, du huê Lêvi bơh phung kon bu klâu Y-Asap, ta nklang phung tâm rƀŭn.$b$,true),
('bunong-vn','2CH',20,15,null,$b$Jêh ri păng lah: Iăt hom, Ơ lĕ rngôch phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem, jêh ri hađăch Jôsaphat: Pô aơ Yêhôva lah ma khân may: ‘Lơi ta klach ôh jêh ri lơi ta rdja nuih n'hâm ôh yor phung âk râk nây, yor lah nau tâm lơh aơ mâu jêng kan khân may ôh, ƀiă lah jêng kan$b$,false),
('bunong-vn','2CH',20,16,null,$b$Ôi taơ trŭnh tâm lơh hom đah khân păng; aơ khân păng văch hao n'gŏ trong ntŭk hao ta Ƀon Sis; pa lơ bri rdah Jêruêl.$b$,false),
('bunong-vn','2CH',20,17,null,$b$Khân may mâu mra tâm lơh ôh; dăp hom ta han khân may, gŭ du ntŭk, jêh ri kăp uănh nau Yêhôva dơi tâm nau Păng tâm lơh ăn ma khân may. Ơ phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem. Lơi ta klach ôh, jêh ri lơi ta rdja nuih n'hâm ôh; ôi taơ tâm mâp hom đah khân păng, jêh ri Yêhôva mra gŭ ndrel ma khân may.”$b$,true),
('bunong-vn','2CH',20,18,null,$b$Y-Jôsaphat chŭn muh măt tâm neh, jêh ri lĕ rngôch phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem chon mon pa năp Yêhôva yơk mbah ma Păng.$b$,true),
('bunong-vn','2CH',20,19,null,$b$Phung Lêvi jêng noi Kôhat jêh ri noi Kôra gŭ dâk ŭch mât ton ma Yêhôva Brah Ndu Israel ma bâr ngơi huy ngăn.$b$,false),
('bunong-vn','2CH',20,20,null,$b$Khân păng kah rngăl ơm ôi luh hăn tâm bri rdah Têkôa; jêh ri dôl khân păng luh du, Y-Jôsaphat gŭ dâk jêh ri lah: “Iăt hom gâp, Ơ phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem! Chroh răp jăp ma Yêhôva Brah Ndu khân may, jêh ri khân may jêng nâp; chroh ngăn ma nau kôranh nơm mbơh lor păng ngơi, jêh ri khân may mra dơi.”$b$,true),
('bunong-vn','2CH',20,21,null,$b$Tơ lah khân păng tâm chră jêh đah phung ƀon lan, păng dơm phung mprơ jêh ri mât ton ma Yêhôva ma ndơ nkrơ̆ kloh ueh, dôl khân păng chuat pa năp phung ta han, jêh ri lah: “Tâm rnê hom ma Yêhôva, yor lah nau păng rŏng n'hêl nanê̆ gŭ ƀa ƀơ n'ho ro.”$b$,false),
('bunong-vn','2CH',20,22,null,$b$Tơ lah khân păng ntơm mprơ jêh ri tâm rnê, Yêhôva dơm du phung gŭ kâp lơh ma phung Amôn jêh ri phung Môap, jêh phung yôk Sêir, phung nây văch jêh ŭch tâm lơh đah phung Yuđa, pô ri yơh phung nây rai roh.$b$,true),
('bunong-vn','2CH',20,23,null,$b$Yor lah phung ta han Amôn jêh ri phung Môap dâk tâm lơh đah phung gŭ ta klơ yôk Sêir, jêh ri ƀư rai lĕ khân ô băl; tơ lah khân păng ƀư rai jêh phung gŭ ta klơ yôk Sêir, lĕ rngôch khân păng ƀư rai ndrăng khân păng nơm.$b$,false),
('bunong-vn','2CH',20,24,null,$b$Tơ lah phung Yuđa tât jêh ma ngih tŭm tâm bri rdah, khân păng n'gơr uănh mpeh phung âk nây, jêh ri saơ săk jăn bunuyh mplâng khĭt rdăp tâm neh, mâu geh du huê dơi klaih ôh.$b$,true),
('bunong-vn','2CH',20,25,null,$b$Y-Jôsaphat jêh ri phung ƀon lan păng tât sŏk pit in ndô ndơ khân păng, saơ geh âk ngăn ndô ndơ, săk bunuyh khĭt, jêh ri ndơ khlay, ndô ndơ sŏk pit nây kŏ tât khân păng mâu dơi du nchuăn ôh; khân păng sŏk nchuăn ndơ nây tâm pe nar, yor lah ndô ndơ dŭt âk ngăn.$b$,false),
('bunong-vn','2CH',20,26,null,$b$Tât năng puăn khân păng tâm rƀŭn tâm rlŭng Bêraka, yor lah ta nây khân păng mât ton ma Yêhôva; yor nây bu ntơ ntŭk nây Rlŭng Bêraka n'ho tât ma nar aơ.$b$,false),
('bunong-vn','2CH',20,27,null,$b$Jêh ri khân păng plơ̆ sĭt, ăp nơm phung Yuđa, phung gŭ tâm ƀon Yêrusalem jêh ri Y-Jôsaphat hăn lor pa năp, plơ̆ sĭt rlet ƀon Yêrusalem ma nau răm maak; yor lah Yêhôva hŏ ƀư ăn ma khân păng hâk răm, yor ma ta han phung rlăng khân păng lơh rai jêh.$b$,false),
('bunong-vn','2CH',20,28,null,$b$Khân păng sĭt ma ƀon Yêrusalem kreh gong rêng, uh n'hôm, jêh ri uh nŭng tât ta ngih Yêhôva.$b$,false),
('bunong-vn','2CH',20,29,null,$b$Nau klach ma Brah Ndu tât ma lĕ rngôch bri dak chiau meng tơ lah khân păng tăng lư ma Yêhôva tâm lơh jêh đah phung rlăng Israel.$b$,false),
('bunong-vn','2CH',20,30,null,$b$Pô ri ƀon bri hađăch Y-Jôsaphat gŭ đăp mpăn, yor lah Brah Ndu ăn ma păng nau rlu puăn njônh.$b$,true),
('bunong-vn','2CH',20,31,null,$b$Pô ri, Y-Jôsaphat ƀư hađăch bri Yuđa; tơ lah păng ntơm chiă uănh; păng geh pe jât ma prăm năm, jêh ri păng chiă uănh bar jât ma prăm năm tâm ƀon Yêrusalem. Amoh me păng H'Asuba kon bu ur Y-Sihi.$b$,true),
('bunong-vn','2CH',20,32,null,$b$Păng chuat tĭng trong Y-Asa mbơ̆ păng, jêh ri mâu veh teng bơh trong nây ôh; păng ƀư nau di ta năp măt Yêhôva.$b$,true),
('bunong-vn','2CH',20,33,null,$b$Ƀiă lah păng mâu ƀư rai ôh ntŭk prêh, jêh ri phung ƀon lan ê hŏ prăp ôh nuih n'hâm khân păng ma Brah Ndu$b$,false),
('bunong-vn','2CH',20,34,null,$b$Kan ƀa ƀă Y-Jôsaphat ƀư ntơm bơh sa ơm tât lôch bu chih jêh tâm ndrom sămƀŭt nau Y-Jêhu kon bu klâu Y-Hanani nkoch bri, nau nây bu chih prăp jêh tâm ndrom sămƀŭt Phung Hađăch Israel.$b$,false),
('bunong-vn','2CH',20,35,null,$b$Jêh nau nây Y-Jôsaphat hađăch Yuđa tâm rnglăp đah Y-Ahasia hađăch Israel, nơm ƀư nau ƀai.$b$,true),
('bunong-vn','2CH',20,36,null,$b$Y-Jôsaphat tâm rnglăp đah păng ƀư kŭmpăn hăn ma bri Tarsis, jêh ri khân păng ƀư kŭmpăn nây tâm ƀon Êsiôn-Gêber.$b$,false),
('bunong-vn','2CH',20,37,null,$b$Nôk nây Y-Êliêser kon bu klâu Y-Dôdavahu bơh ƀon đah Marêsa mbơh lor nau tâm rdâng đah Y-Jôsaphat, lah: “Yor lah may tâm rnglăp jêh đah Y-Ahasia, Yêhôva mra ƀư rai ndơ may lĕ ƀư jêh.” Jêh ri kŭmpăn khân păng ƀư nây chah ro, pô ri kŭmpăn nâu mâu dơi hăn tât ma bri Tarsis ôh.$b$,false),
('bunong-vn','2CH',21,1,null,$b$Y-Jôsaphat khĭt hăn gŭ ndrel ma phung che păng, jêh ri bu tâp păng ndrel ma phung che păng tâm ƀon Y-Đavit; jêh ri Y-Jôram kon bu klâu păng chiă uănh thoi păng.$b$,true),
('bunong-vn','2CH',21,2,null,$b$Păng geh phung oh phung kon bu klâu Y-Jôsaphat: Y-Asaria, ri Y-Sêphatia; lĕ rngôch phung nây jêng phung kon bu klâu Y-Jôsaphat hađăch Israel.$b$,false),
('bunong-vn','2CH',21,3,null,$b$Mbơ̆ khân păng ăn jêh ma khân păng âk ndô ndơ khlay ma prăk, mah, ndơ khlay, nđâp ma ƀon geh pôih ta han tâm bri Yuđa; ƀiă lah păng ăn ƀon bri hađăch ma Y-Jôram, yor lah ô băl jêng kon bôk rah.$b$,false),
('bunong-vn','2CH',21,4,null,$b$Tơ lah Y-Jôram hao jêh klơ sưng hađăch mbơ̆ păng jêh ri jêng nâp jêh, păng ƀư nkhĭt lĕ phung oh păng ma đao jêh ri nđâp ƀa ƀă phung kôranh Israel.$b$,true),
('bunong-vn','2CH',21,5,null,$b$Y-Jôram geh pe jât ma bar năm tơ lah păng ntơm jêng hađăch, jêh ri nau păng chiă uănh pham năm tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',21,6,null,$b$Păng chuat tĭng ndô̆ trong phung hađăch Israel, nâm bu ntil nau ngih Y-Ahap hŏ ƀư jêh, yor lah kon bu ur Y-Ahap jêng ur păng. Jêh ri păng ƀư nau mhĭk ta năp măt Yêhôva.$b$,false),
('bunong-vn','2CH',21,7,null,$b$Ƀiă lah, yor lah Yêhôva hŏ ƀư jêh nau tâm rnglăp đah Y-Đavit, Păng hŏ ton ăn du mlâm ŭnh jrêng ăn Y-Đavit jêh ri ăn tât ma kon ma sau păng ƀa ƀơ n'ho ro, yor ri Păng mâu ŭch ƀư rai ngih Y-Đavit.$b$,false),
('bunong-vn','2CH',21,8,null,$b$Tâm rnôk rô̆ Y-Jôram, phung Êđôm tâm rdâng đah nau phung Yuđa chiă uănh jêh ri njêng du huê hađăch ma khân păng nơm.$b$,true),
('bunong-vn','2CH',21,9,null,$b$Y-Jôram ndrel ma phung ta han păng jêh ri lĕ rngôch ndeh seh păng, dôl bri măng du dâk, hăn tâm lơh đah phung Êđôm gŭ nchueng păng jêh ri phung kôranh ta han ndeh seh păng.$b$,false),
('bunong-vn','2CH',21,10,null,$b$Pô ri bri Êđôm tâm rdâng ma nau phung Yuđa chiă uănh tât ta nar aơ. Nôk nây lĕ ƀon Lipna tâm rdâng đah nau Y-Jôram chiă uănh, yor lah păng cha lơi jêh Yêhôva Brah Ndu phung che păng.$b$,false),
('bunong-vn','2CH',21,11,null,$b$Rlau ma nĕ đŏng păng ƀư ntŭk prêh bri klơ dor Yuđa, jêh ri njŭn leo phung gŭ tâm ƀon Yêrusalem tâm nau mâu ŭch gŭ n'hêl nanê̆, jêh ri ăn phung Yuđa teng êng bơh trong Brah Ndu$b$,true),
('bunong-vn','2CH',21,12,null,$b$Bu njŭn sămƀŭt ma păng tă bơh kôranh nơm mbơh lor Y-Êli, lah: “Pô aơ Yêhôva Brah Ndu Y-Đavit che may lah: ‘Yor lah may mâu chuat ôh tâm trong Y-Jôsaphat mbơ̆ may, mâu lah tâm trong Y-Asa hađăch Yuđa,$b$,false),
('bunong-vn','2CH',21,13,null,$b$ƀiă lah may chuat hăn jêh tĭng trong phung hađăch Israel, jêh ri lĕ rngôch jêh phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem ma nau mâu gŭ n'hêl nanê̆ ƀư nâm bu ngih Y-Ahap lĕ njŭn jêh phung Israel ma nau mâu ŭch gŭ n'hêl nanê̆, jêh ri tâm ban lĕ may nkhĭt jêh phung oh nâu may bơh ngih mbơ̆ may, khân păng jêng phung ueh uĭn ma may nơm;$b$,false),
('bunong-vn','2CH',21,14,null,$b$aơ, Yêhôva ăn tât nau ji ƀư nkhĭt ƀon lan may, ma phung kon may, ma phung ur may, jêh ri lĕ rngôch ndô ndơ may geh,$b$,false),
('bunong-vn','2CH',21,15,null,$b$jêh ri may nơm mra geh du nau ji glăm ngăn jêng nau ji proch khŭng, tât proch khŭng may luh du pa dih lơ nar lơ hâu glăm yor nau ji nây.”$b$,false),
('bunong-vn','2CH',21,16,null,$b$Yêhôva nsônh nau ma phung Philistin jêh ri phung Arabi gŭ dăch phung Êthiôpi ji ji nuih ma Y-Jôram;$b$,true),
('bunong-vn','2CH',21,17,null,$b$jêh ri khân păng văch tâm lơh đah phung Yuđa, n'ho lăp tâm n'gor Yuđa jêh ri pit in lĕ ndô ndơ khân păng saơ tâm ngih hađăch, jêh ri nhŭp kon bu klâu nđâp ma ur păng tât mâu hôm geh kon bu klâu gŭ ndrel păng nơm, knŏng hôm e Y-Jôacha kon bu klâu kon mpô̆ t.$b$,false),
('bunong-vn','2CH',21,18,null,$b$Jêh lĕ nau nây Yêhôva dong păng ma nau ji tâm proch khŭng mâu hôm blau bah ôh.$b$,true),
('bunong-vn','2CH',21,19,null,$b$Jêh ji bar năm, proch khŭng păng luh du pa dih yor nau ji nây, jêh ri păng khĭt ma nau nđêh nji ngăn. Phung ƀon lan păng mâu geh mpoh ŭnh yơk ma păng ôh, kơt nâm bu ŭnh bu hŏ mpoh jêh ma phung che păng kăl e.$b$,false),
('bunong-vn','2CH',21,20,null,$b$Tơ lah păng ntơm chiă uănh, năm deh geh pe jât ma bar năm, jêh ri păng chiă uănh pham năm ta ƀon Yêrusalem; păng khĭt mâu geh ôh bunuyh klâng ndrê ma păng; bu tâp păng tâm ƀon Y-Đavit, mâu di tâm môch phung hađăch ôh.$b$,false),
('bunong-vn','2CH',22,1,null,$b$Phung gŭ tâm ƀon Yêrusalem njêng Y-Ahasia, Y-Ahasia jêng hađăch Jôacha.’ Kon bu klâu mpô̆ t Y-Jôram, jêng hađăch thoi păng; yor lah phung ta han văch ndrel phung Arap hăn rduh lăp pôih ta han, hŏ ƀư nkhĭt lĕ rngôch kon bu klâu păng kranh lơn. Yor ri Y-Ahasia, kon bu klâu Y-Jôram, hađăch phung Yuđa, hao jêng hađăch.$b$,true),
('bunong-vn','2CH',22,2,null,$b$Y-Ahasia geh bar jât ma bar năm tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh du năm tâm ƀon Yêrusalem. Amoh me păng H'Athali, kon bu ur Y-Ômri.$b$,false),
('bunong-vn','2CH',22,3,null,$b$Păng ăt tâm ban lĕ tĭng trong ngih Y-Ahap; yor lah me păng jêng nơm nsŭk bu ƀư nau mhĭk.$b$,false),
('bunong-vn','2CH',22,4,null,$b$Păng ƀư nau mhĭk ta năp măt Yêhôva, nâm bu ngih Y-Ahap ƀư jêh; yor lah jêh khĭt mbơ̆ păng phung ngih Y-Ahap jêng phung ntĭm nsak ma păng; nau phung nây nsak ăn tât nau mhĭk ma păng.$b$,false),
('bunong-vn','2CH',22,5,null,$b$Nđâp păng tĭng nau phung nây nsak ndơm hăn ndrel ma Y-Jôram, kon bu klâu Y-Ahap, hađăch Israel, hăn tât Ramôt ta Galaat, gay tâm lơh đah Y-Hasael, hađăch Syri. Phung Syri ƀư ăn ma Y-Jôram geh nau rmanh,$b$,true),
('bunong-vn','2CH',22,6,null,$b$jêh ri păng sĭt ma ƀon Jerêel, gay săm ăn bah nau sôt rmanh, nau rmanh păng geh ta ƀon Rama, dôl păng tâm lơh đah Y-Hasael, hađăch Syri, Y-Ahasia, kon bu klâu Y-Jôram, hađăch Yuđa, jŭr hăn uănh Y-Jôram, kon bu klâu Y-Ahap tâm ƀon Jesêel, yor lah păng dôl gŭ păm ji.$b$,false),
('bunong-vn','2CH',22,7,null,$b$Ƀiă lah Brah Ndu săch jêh nau tŭp ăn Y-Ahasia, mra tât nau mhĭk tâm nau păng hăn khâl ma Y-Jôram. Yor lah tơ lah păng tât ta nây, păng du luh hăn ndrel ma Y-Jôram ŭch hăn lơh Y-Jêhu, kon bu klâu Y-Nimsi, nơm aơ Yêhôva tŏ jêh dak ƀâu kah ăn ƀư rai ngih Y-Ahap.$b$,true),
('bunong-vn','2CH',22,8,null,$b$Geh nau dôl ŭch ƀư rai ngih Y-Ahap, tâm mâp đŏng đah phung kôranh bri Yuđa jêh ri phung kon bu klâu phung oh nâu Y-Ahasia, phung kơl Y-Ahasia, n'ho nkhĭt nđâp ma khân păng ro.$b$,false),
('bunong-vn','2CH',22,9,null,$b$Y-Jêhu tĭng joi Y-Ahasia dôl gŭ krap tâm ƀon Samari, bu nhŭp păng, njŭn leo ma Y-Jêhu, jêh nây nkhĭt lơi păng. Bu tâp păng, yor lah bu lah: “Păng jêng sau ma Y-Jôsaphat nơm joi Yêhôva ma lĕ nuih n'hâm.” Jêh ri ngih Y-Ahasia mâu geh du huê dơi chiă uănh ƀon bri hađăch ôh.$b$,false),
('bunong-vn','2CH',22,10,null,$b$Tơ lah H'Thali mê̆ Y-Ahasia, saơ ma kon bu klâu păng khĭt jêh, păng dâk jêh ri ƀư rai lĕ rngôch noi deh hađăch ngih Yuđa.$b$,true),
('bunong-vn','2CH',22,11,null,$b$Ƀiă lah H'Jôsabêat, kon bu ur hađăch, nhŭp rdu Y-Jôsa, kon bu klâu Y-Ahasia, rđah bơh phung kon bu klâu hađăch bu ŭch nkhĭt, jêh ri bu nhŭp ô băl nđâp ma nơm rong ô băl dơm ăn tâm du mlâm jrô bêch. Pô ri, H'Jôsabêat, kon bu ur hađăch Jôram, ur kôranh ƀư brah Y-Jêhôida, pôn Y-Jôas lơi ăn H'Athali saơ, jêh ri H'Athali mâu dơi nkhĭt ô băl ôh; H'Jôsabêat jêng oh Y-Ahasia.$b$,true),
('bunong-vn','2CH',22,12,null,$b$Y-Jôas gŭ krap ndrel khân păng tâm prao năm tâm ngih brah Brah Ndu; bi ma H'Athali chiă uănh tâm n'gor.$b$,false),
('bunong-vn','2CH',23,1,null,$b$Tâm năm rơh pơh, Y-Jêhôida tâm păng lĕ geh nau dăng ktang, ƀư nau tâm rnglăp đah phung kôranh ta han ma du rhiăng nuyh, amoh Y-Asaria kon bu klâu Y-Jôrôham, Y-Ismaêl kon bu klâu Y-Jôhanan, Y-Asaria kon bu klâu Y-Ôbet, Y-Masaya kon bu klâu Y-Adaya, jêh ri Y-Êlisaphat kon bu klâu Y-Sikri.$b$,true),
('bunong-vn','2CH',23,2,null,$b$Khân păng nsong lam n'gor Yuđa jêh ri tâm rƀŭn phung Lêvi bơh lĕ rngôch rplay ƀon tâm n'gor Yuđa, jêh ri phung kôranh ma ndŭl mpôl phung Israel, jêh ri khân ô băl văch ma ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',23,3,null,$b$Jêh ri lĕ rngôch phung tâm rƀŭn ƀư nau tâm rnglăp đah hađăch tâm ngih Brah Ndu. Y-Jêhôida lah ma khân păng: “Aơ, kon bu klâu hađăch! Ăn nau chiă uănh tĭng nâm Yêhôva ngơi jêh di ma phung kon bu klâu Y-Đavit.$b$,false),
('bunong-vn','2CH',23,4,null,$b$Aơ jêng nau ăn khân may ƀư: Du kô̆ tâm pe tâm phung khân may, jêng phung kôranh ƀư brah jêh ri phung Lêvi, tât sruh tâm nar Saƀat, mra mât chăm mpông sâng;$b$,false),
('bunong-vn','2CH',23,5,null,$b$jêh ri du kô̆ tâm pe mra gŭ chăm ngih hađăch, jêh ri du kô̆ tâm pe gŭ ntŭk mpông pêr; bi lĕ rngôch phung ƀon lan êng mra gŭ tâm nkual ngih Yêhôva.$b$,false),
('bunong-vn','2CH',23,6,null,$b$Lơi ăn du huê lăp ôh tâm ngih Yêhôva, knŏng ma phung kôranh ƀư brah jêh ri phung Lêvi gŭ pah kan; khân păng dơi lăp, yor lah khân păng jêng phung kloh ueh; lĕ rngôch phung ƀon lan mra djôt kan Yêhôva ntăm.$b$,false),
('bunong-vn','2CH',23,7,null,$b$Phung Lêvi mra gŭ jŭm hađăch, ăp nơm djôt ndơ tâm lơh; mbu nâm lăp tâm ngih brah bu mra ƀư nkhĭt. Lĕ phung khân may gŭ ndrel hađăch tơ lah păng luh jêh ri tơ lah păng lăp.”$b$,false),
('bunong-vn','2CH',23,8,null,$b$Phung Lêvi jêh ri lĕ rngôch phung Yuđa ƀư tĭng nâm nau Y-Jêhôida kôranh ƀư brah ntĭnh jêh. Ăp nơm khân păng dơn leo phung băl păng, ƀư lôch lĕ kan ta nar Saƀat mâu lah phung ntơm rdơn kan tâm nar Saƀat; yor lah kôranh ƀư brah Y-Jêhôida mâu ăn phung mpôl sĭt rlu ôh.$b$,true),
('bunong-vn','2CH',23,9,null,$b$Kôranh ƀư brah Y-Jêhôida ăn ma phung kôranh ta han tak, khêl toyh jêh ri jê̆ Hađăch Đavit bu dơm tâm ngih Brah Ndu;$b$,false),
('bunong-vn','2CH',23,10,null,$b$jêh ri păng dơm lĕ rngôch phung ƀon lan jêng du phung gak hađăch, ăp nơm bu klâu djôt ndơ tâm lơh, dăp mbor văr jŭm hađăch jong tĭng nơng jêh ri ngih brah, ntơm bơh pa ma ngih brah tât ma pa chiau ngih brah.$b$,false),
('bunong-vn','2CH',23,11,null,$b$Nôk nây păng leo kon hađăch pa năp, jêh ri ndô đon hađăch klơ bôk ô băl, jêh ri ăn ma ô băl nau vay; jêh ri n'hao ô băl jêng hađăch; Y-Jêhôida jêh ri phung kon bu klâu păng tŏ dak ƀâu kah ma Y-Jôas, jêh ri khân păng lah: “Hađăch n'ho ro!”$b$,false),
('bunong-vn','2CH',23,12,null,$b$Tơ lah H'Athali tăng nteh phung ƀon lan nchuăt jêh ri mât ton ma hađăch, păng hăn tât ma phung ƀon lan gŭ tâm ngih brah Yêhôva.$b$,true),
('bunong-vn','2CH',23,13,null,$b$Păng uănh saơ hađăch gŭ dâk klơ ndring êp meh ta mpông ntŭk lăp; jêh ri phung kôranh ta han nđâp ma phung uh nŭng gŭ ta meng hađăch, jêh ri lĕ rngôch phung ƀon lan tâm n'gor bri hâk răm uh nŭng, jêh ri phung mprơ uh dĭng talơ̆ nchreng, tâm rnê ma Brah Ndu. H'Athali nkhêk bok ao păng jêh ri nter lah: Nau ƀlêp ƀlêr! Nau ƀlêp ƀlêr!”$b$,false),
('bunong-vn','2CH',23,14,null,$b$Nôk nây Y-Jêhôida kôranh ƀư brah njŭn phung chiă uănh kôranh ta han jêh ri lah ma khân ô băl: “Njŭn păng luh pa dih ta nklang phung ta han; mbu moh tĭng ndô̆ păng bu mra nkhĭt ma đao.” Yor lah kôranh ƀư brah hŏ nti jêh: “Lơi ƀư nkhĭt păng tâm ngih Yêhôva ôh.”$b$,false),
('bunong-vn','2CH',23,15,null,$b$Pô ri khân păng yơr ti kuăn H'Athali leo trong ma păng; tơ lah păng lăp Mpông Pêr seh ngih hađăch, jêh ri khân păng nkhĭt ô băl ta nây.$b$,false),
('bunong-vn','2CH',23,16,null,$b$Y-Jêhôida ƀư du nau tâm rnglăp păng nơm đah lĕ rngôch phung ƀon lan jêh ri hađăch, gay ma khân păng mra jêng phung ƀon lan ma Yêhôva.$b$,true),
('bunong-vn','2CH',23,17,null,$b$Jêh ri lĕ rngôch phung ƀon lan hăn tât ta ndrơng brah Baal da dê, jêh ri ƀư rlâm lơi păng; khân păng nchah hăch rhên nơng jêh ri rup brah, jêh ri nkhĭt Y-Matan kôranh ƀư brah ma brah Baal pa năp nơng.$b$,false),
('bunong-vn','2CH',23,18,null,$b$Y-Jêhôida dơm phung ta han gak ma ngih Yêhôva tâm ti phung kôranh ƀư brah Lêvi, jêh ri phung Lêvi; phung nây Y-Đavit njêng jêh ăn djôt kan ngih Yêhôva, nhhơr mpa nhhơr gŭch ma Yêhôva tĭng nâm nau chih jêh tâm ndrom sămƀŭt nau vay Y-Môis ma nau hâk răm jêh ri nau mprơ tĭng nâm nau Y-Đavit ntăm jêh.$b$,false),
('bunong-vn','2CH',23,19,null,$b$Păng dơm phung chiă mât mpông pêr ta mpông pêr ngih Yêhôva, pô ri mâu geh du huê bunuyh ƀơ̆ dơi lăp ta nây ôh.$b$,false),
('bunong-vn','2CH',23,20,null,$b$Păng jă phung kôranh ta han, phung bu vay yơk, phung kôranh chiă uănh phung ƀon lan, jêh ri lĕ rngôch phung ƀon lan tâm bri nây; jêh ri khân păng njŭn hađăch jŭr bơh ngih Yêhôva chuat găn mpông pêr ta klơ tât ma ngih hađăch. Khân păng ăn hađăch gŭ ta klơ sưng hađăch.$b$,true),
('bunong-vn','2CH',23,21,null,$b$Pô ri lĕ rngôch phung ƀon lan tâm bri nây hâk răm; jêh ri ƀon Yêrusalem gŭ đăp mpăn jêh bu nkhĭt H'Athali ma đao.$b$,false),
('bunong-vn','2CH',24,1,null,$b$Y-Jôas geh pơh năm tơ lah păng ntơm ƀư hađăch; păng chiă uănh puăn jât năm ta ƀon Yêrusalem; me păng amoh H'Sibia bơh ƀon Sêr-Sêba.$b$,true),
('bunong-vn','2CH',24,2,null,$b$Y-Jôas ƀư nau di ta năp măt Yêhôva lĕ rngôch rô̆ Y-Jêhôida kôranh ƀư brah.$b$,false),
('bunong-vn','2CH',24,3,null,$b$Y-Jêhôida joi bar hê ur ma păng, jêh ri păng geh phung kon bu klâu jêh ri phung kon bu ur.$b$,false),
('bunong-vn','2CH',24,4,null,$b$Jêh nau nây Y-Jôas ŭch nkra tay ngih Yêhôva.$b$,true),
('bunong-vn','2CH',24,5,null,$b$Păng tâm rƀŭn phung kôranh ƀư brah jêh ri phung Lêvi lah ma khân păng: “Hăn hom ma lĕ rngôch ƀon tâm n'gor Yuđa jêh ri riu bơh lĕ rngôch phung Israel prăk gay nkra tay ngih Brah Ndu khân may ăp tay năm; jêh ri ƀư hom kan ăn gơnh.” Ƀiă lah phung Lêvi mâu ƀư gơnh ôh kan nây.$b$,false),
('bunong-vn','2CH',24,6,null,$b$Pô ri hađăch kuăl Y-Jôhôida nơm jêng kôranh ƀư brah toyh jêh ri lah ma păng: “Mâm ƀư may mâu mâp ntĭnh ma phung Lêvi djôt leo ndơ phung Yuđa, jêh ri phung gŭ tâm ƀon Yêrusalem rnoh pi tĭng nâm Y-Môis oh mon Yêhôva nal jêh ma phung Israel tâm rƀŭn prăp ma ngih bok nau mbơh?”$b$,false),
('bunong-vn','2CH',24,7,null,$b$Yor lah phung kon bu klâu H'Athali, bu ur ƀai nây, ƀư bluh jêh ri lăp tâm ngih Brah Ndu; jêh ri tâm ban lĕ khân păng hŏ nhhơr jêh lĕ rngôch ndô ndơ kloh prăp jêh ma kan ngih Yêhôva ăn ma brah Baal.$b$,false),
('bunong-vn','2CH',24,8,null,$b$Pô ri hađăch ntrŭnh ăn bu ƀư du mlâm hip, dơm pa dih mpông ngih Yêhôva.$b$,true),
('bunong-vn','2CH',24,9,null,$b$Jêh ri bu mbơh jêh ri ntĭnh lam n'gor Yuđa jêh ri lĕ rngôch phung gŭ tâm ƀon Yêrusalem ăp nơm dơi djôt leo nhhơr ma Yêhôva prăk pi Y-Môis oh mon Brah Ndu, hŏ tâm nal jêh ma phung Israel ta bri rdah.$b$,false),
('bunong-vn','2CH',24,10,null,$b$Lĕ rngôch phung kôranh jêh ri lĕ rngôch phung ƀon lan hâk răm da dê, djôt leo prăk pi chê̆ tâm hip kŏ tât bêng.$b$,false),
('bunong-vn','2CH',24,11,null,$b$Tơ lah phung Lêvi saơ tâm hip geh âk prăk, djôt leo păng njŭn ma phung pah kan hađăch kơp; nơm chih sămƀŭt hađăch jêh ri kôranh ma kan kôranh ƀư brah toyh văch ngluh prăk tâm hip nây, jêh ri mplơ̆ sĭt hip ma ntŭk ơm. Ăp nar khân păng ƀư kơt nĕ, jêh ri khân păng bun prăp jêh prăk âk râk ngăn.$b$,false),
('bunong-vn','2CH',24,12,null,$b$Hađăch jêh ri Y-Jêhôida ăn prăk nây ma phung chiă uănh kan ngih Yêhôva, jêh ri khân păng nkhôm phung pah kan châm lŭ jêh ri trah si gay nkra tay ngih Yêhôva, nđâp ma phung pah kan ma loih, jêh ri kông gay nkra ngih brah ma Yêhôva.$b$,false),
('bunong-vn','2CH',24,13,null,$b$Pô ri, lĕ rngôch phung bu nkhôm gŭ pah kan, jêh ri khân păng kâp nkra ngih Brah Ndu$b$,false),
('bunong-vn','2CH',24,14,null,$b$Tơ lah lĕ lôch jêh kan khân păng ƀư, khân păng leo prăk hôm e ta năp hađăch jêh ri Y-Jêhôida; jêh ri ma prăk nây bu ƀư khăl ngan ma ngih Yêhôva, jêng lĕ ndơ dŏng prăp ma kan nhhơr mpa nhhơr gŭch, jêh ri ƀư ngan nhhơr ndơ ƀâu kah, jêh ri khân păng ƀư khăl ngan mah jêh ri prăk. Khân păng nhhơr mpa nhhơr gŭch tâm ngih Yêhôva ƀa ƀơ lĕ rô̆ Y-Jêhôida gŭ rêh.$b$,false),
('bunong-vn','2CH',24,15,null,$b$Pô ri, Y-Jêhôida lĕ dŭt ranh ngăn, jêh ri păng khĭt; ta nar păng khĭt păng geh du rhiăng pe jât năm.$b$,true),
('bunong-vn','2CH',24,16,null,$b$Khân păng tâp ô băl tâm ƀon Y-Đavit ndrel ma phung hađăch, yor lah ô băl ƀư nau ueh tâm n'gor Israel, pah kan Brah Ndu, jêh ri nkra tay ngih brah Păng.$b$,false),
('bunong-vn','2CH',24,17,null,$b$Jêh Y-Jêhôida hŏ khĭt jêh, phung kôranh Yuđa văch ƀư nau yơk mbah hađăch. Nôk nây hađăch iăt ro nau khân păng.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','2CH',24,18,null,$b$Khân păng cha lơi ngih Brah Yêhôva jêng Brah Ndu phung che khân păng, jêh ri pah kan ma brah Asêrim jêh ri ma phung rup brah êng. Nau Yêhôva ji nuih tât ma phung Yuđa jêh ri phung ƀon Yêrusalem, yor lah nau khân păng ƀư jêng tih jêh.$b$,false),
('bunong-vn','2CH',24,19,null,$b$Ƀiă lah Yêhôva prơh hăn phung kôranh nơm mbơh lor tât ma khân păng, gay têk ndrêng khân păng plơ̆ sĭt ma Yêhôva, ƀiă lah khân păng mâu tông ôh.$b$,false),
('bunong-vn','2CH',24,20,null,$b$Pô ri Huêng Brah Brah Ndu mbêng Y-Sakari kon bu klâu Y-Jêhôida kôranh ƀư brah; jêh ri păng gŭ ta năp phung ƀon lan, jêh ri lah ma khân păng: “Pô aơ Brah Ndu lah: ‘Mâm ƀư khân may rlau nau Yêhôva ntăm, yor nây khân may mâu jêng hao ôh? Yor lah khân may cha lơi Yêhôva, Păng lĕ cha lơi jêh khân may tâm ban lĕ.”$b$,true),
('bunong-vn','2CH',24,21,null,$b$Ƀiă lah khân păng tâm chră ŭch ƀư ma păng, jêh ri tĭng nâm nau hađăch, ntĭnh, khân păng klŭp ô băl ma lŭ tâm nkual ngih brah Yêhôva.$b$,false),
('bunong-vn','2CH',24,22,null,$b$Pô ri hađăch Jôas mâu hôm kah gĭt ôh nau ueh Y-Jêhôida mbơ̆ Y-Sakari tâm mpơl jêh ma păng, ƀiă lah păng nkhĭt lơi kon ô băl. Tơ lah ô băl dăch khĭt, ô băl lah: “Ăn Yêhôva saơ jêh ri plơng bôk!”$b$,false),
('bunong-vn','2CH',24,23,null,$b$Ta năm dăch lôch phung ta han Syri văch tâm lơh đah Y-Jôas. Khân păng tât ma ngih Yuđa jêh ri ma ƀon Yêrusalem, jêh ri ƀư rai lĕ rngôch phung kôranh ƀon lan, jêh ri njuăl lĕ ndô ndơ khân păng pit in ma hađăch Damas.$b$,false),
('bunong-vn','2CH',24,24,null,$b$Nđâp lah phung ta han Syri văch knŏng ƀhôi dơm ta han kđôi lĕ, Yêhôva jao jêh tâm ti khân păng du phung ta han toyh, yor lah khân păng cha lơi jêh Yêhôva Brah Ndu phung che khân păng, Pô ri, phung Syri phat dôih tâm rmal Y-Jôas.$b$,false),
('bunong-vn','2CH',24,25,null,$b$Tơ lah phung ta han Syri lĕ du sĭt jêh bơh Y-Jôas, cha lơi êng păng gŭ păm rmanh jru, phung oh mon păng tâm chră ƀư ma păng yor lah mham kon bu klâu kôranh ƀư brah Y-Jêhôida, jêh ri nkhĭt păng ta sưng păng bêch jêh ri păng khĭt; bu tâp păng tâm ƀon Y-Đavit, ƀiă lah mâu di tâm môch ma phung hađăch ôh.$b$,true),
('bunong-vn','2CH',24,26,null,$b$Aơ jêng phung ŭch rdâng đah păng geh Y-Saƀat kon bu klâu H'Simêa bu ur Amôn, jêh ri Y-Jêhôida kon bu klâu H'Simrit bu ur Môap.$b$,false),
('bunong-vn','2CH',24,27,null,$b$Nau nkoch bri ma phung kon bu klâu păng, jêh ri âk nau ngơi tâm rdâng đah păng, jêh ri nau nkoch bri ma nkra tay ngih Brah Ndu bu chih jêh tâm Sămƀŭt Rblang ma Ndrom Sămƀŭt Phung Hađăch, jêh ri Y-Amasia kon bu klâu păng chiă uănh thoi păng.$b$,false),
('bunong-vn','2CH',25,1,null,$b$Y-Amasia geh bar jât ma prăm năm tơ lah păng ntơm chiă uănh jêh ri păng chiă uănh bar jât ma sĭn năm tâm ƀon Yêrusalem. Amoh me păng H'Jôadan bơh ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',25,2,null,$b$Păng ƀư nau di ta năp măt Yêhôva, ƀiă lah nuih n'hâm mâu dơi jêng kloh rsang ngăn ôh.$b$,false),
('bunong-vn','2CH',25,3,null,$b$Jêh păng ƀư nâp ƀon bri hađăch păng, păng nkhĭt phung oh mon păng, phung hŏ nkhĭt jêh hađăch, mbơ̆ păng.$b$,true),
('bunong-vn','2CH',25,4,null,$b$Ƀiă lah păng mâu nkhĭt phung kon khân păng, tĭng ntil nau hŏ chih jêh tâm ndrom sămƀŭt nau vay Y-Môis, nâm bu Yêhôva hŏ ntăm jêh: “Mbơ̆ mâu mra khĭt yor kon, kon tâm ban lĕ mâu mra khĭt yor mbơ̆ ; ƀiă lah ăp nơm mra khĭt yor nau tih nơm.”$b$,false),
('bunong-vn','2CH',25,5,null,$b$Y-Amasia tâm rƀŭn phung Yuđa, tâm pă tĭng mpôl tâm noi deh Yuđa, jêh ri Benjamin, njêng phung kôranh chiă uănh ma du rbăn nuyh jêh ri du rhiăng nuyh. Păng riu phung geh bar jât năm leo klơ, jêh ri rnoh kơp khân păng geh pe rsen nuyh bu klâu ueh lơn, blau tâm lơh dơi djôt tak jêh ri khêl.$b$,true),
('bunong-vn','2CH',25,6,null,$b$Păng nkhôm tâm ban lĕ geh du rsen nuyh phung dăng ktang tâm phung Israel, rnoh du rhiăng talâng prăk.$b$,false),
('bunong-vn','2CH',25,7,null,$b$Ƀiă lah geh du huê bunuyh Brah Ndu tât ma păng jêh ri lah: “Ơ hađăch, lơi ta ăn phung ta han Israel hăn ndrel ma may ôh, yor lah Yêhôva mâu gŭ ndrel ôh ma phung Israel, nđâp ma lĕ rngôch phung Êphraim aơ.$b$,true),
('bunong-vn','2CH',25,8,null,$b$Bi tơ lah may ŭch hăn, ăn may hăn hom, nsan ăn dăng ktang ma nau tâm lơh; Brah Ndu mra n'glưh may pa năp phung rlăng. Yor lah Brah Ndu geh nau brah dơi kơl mâu lah n'glưh.”$b$,false),
('bunong-vn','2CH',25,9,null,$b$Y-Amasia lah bunuyh Brah Ndu: “Ƀiă lah mâm hên mra ƀư ma du rhiăng talâng gâp ăn jêh ma phung ta han Israel?” Bunuyh Brah Ndu plơ̆ lah: “Yêhôva dơi ăn ma may âk rmeh lơn ma rnoh nây.”$b$,false),
('bunong-vn','2CH',25,10,null,$b$Pô ri Y-Amasia mplơ̆ sĭt ma ngih đơ phung ta han văch jêh ma păng bơh phung Êphraim, jêh ri khân păng ji nuih ngăn ma phung Yuđa, jêh ri plơ̆ sĭt ma ngih ma nau ji nuih ngăn.$b$,false),
('bunong-vn','2CH',25,11,null,$b$Ƀiă lah Y-Amasia ƀư janh, njŭn leo phung ƀon lan păng, jêh ri hăn rlet ma Rlŭng Boh jêh ri nkhĭt du rmưn nuyh bu klâu ƀon Sêir.$b$,true),
('bunong-vn','2CH',25,12,null,$b$Phung ta han Yuđa nhŭp rêh du rmưn nuyh êng jêh ri njŭn leo khân păng ta klơ n'glơn yôk lŭ nây, jêh ri bơh klơ n'glơn yôk lŭ nây khân păng nklơ̆ rlă tâm dâng, lĕ rngôch khĭt rlă lĕ ƀhiau.$b$,false),
('bunong-vn','2CH',25,13,null,$b$Bi ma phung ta han Y-Amasia mplơ̆ sĭt ma ngih, mâu rom khân păng hăn ndrel, ma nau tâm lơh; khân păng lăp lơh ƀon phung Yuđa, ntơm bơh ƀon Samari tât Bet-Hôron, lơh nkhĭt pe rbăn nuyh ta nây, jêh ri sŏk in âk ndô ndơ.$b$,false),
('bunong-vn','2CH',25,14,null,$b$Jêh Y-Amasia sĭt tâm lơh tă bơh ƀon Êđôm, păng djôt leo nsĭt rup brah phung Sêir jêh ri ndâk ndơ nây jêng brah ma păng, mbah yơk jêh ri nhhơr mpa ma rup nây.$b$,true),
('bunong-vn','2CH',25,15,null,$b$Yor nây Yêhôva ji nuih ma Y-Amasia, jêh ri prơh hăn ma păng du huê kôranh nơm mbơh lor lah ma păng: “Mâm ƀư may hăn dăn ma brah mâu dơi tâm rklaih phung ƀon lan păng nơm, bơh ti may?”$b$,true),
('bunong-vn','2CH',25,16,null,$b$Ƀiă lah dôl ô băl gŭ ngơi, hađăch lah ma ô băl: “Hên mâp njêng lĕ ăn may jêng nơm nkah ma hađăch? Gŭ klăk hom! Mpa khlay bu nkhĭt lơi may?” Pô ri kôranh nơm mbơh lor gŭ klăk, ƀiă lah ê lor păng dŭt nau ngơi, păng lah: “Gâp gĭt Brah Ndu chôk jêh ŭch ƀư rai may, yor lah may hŏ ƀư jêh nau aơ jêh ri mâu ŭch iăt ôh nau gâp nkah.”$b$,false),
('bunong-vn','2CH',25,17,null,$b$Pô ri Y-Amasia hađăch Yuđa, tâm chră jêh ri njuăl bâr ngơi ma Y-Jôas kon bu klâu Y-Jôacha, sau Y-Jêhu hađăch Israel lah: “Văch hom ăn he tâm uănh muh măt.”$b$,true),
('bunong-vn','2CH',25,18,null,$b$Y-Jôas hađăch Israel njuăl bâr ngơi ma Y-Amasia hađăch Yuđa, “Pôm lok ta bri Liban njuăl bâr ngơi ma du n'gâng tơm si Sêdar ta bri Liban, lah: ‘Ăn hom kon bu ur may jêng ur ma kon bu klâu gâp’; jêh ri du mlâm jun bri Liban găn jêh ri jot pôm lok nây.$b$,true),
('bunong-vn','2CH',25,19,null,$b$May lah: ‘Uănh hom, gâp dong jêh bri Êđôm,’ jêh ri nuih n'hâm may ƀư sưr may nơm. Ƀiă lah aƀaơ ri gŭ hom tâm ngih; mâm ƀư may ŭch nsônh nau uh ah, tơ lah pô nây, may jêh ri phung Yuđa ndrel ma may mra tŭp?”$b$,false),
('bunong-vn','2CH',25,20,null,$b$Ƀiă lah Y-Amasia mâu ŭch iăt ôh, yor lah nau nây luh bơh Brah Ndu, gay jao khân păng tâm ti phung rlăng, yor lah khân păng joi brah phung Êđôm.$b$,true),
('bunong-vn','2CH',25,21,null,$b$Pô ri Y-Jôas hađăch Israel hăn hao; păng jêh ri Y-Amasia tâm uănh măt tâm nau tâm lơh ta ƀon Bet-Sêmes, ƀon nây jêng ndơ phung Yuđa.$b$,false),
('bunong-vn','2CH',25,22,null,$b$Phung ta han Israel dơi đah phung ta han Yuđa, jêh ri ăp nơm nchuăt du ma rmlak khân păng nơm.$b$,true),
('bunong-vn','2CH',25,23,null,$b$Ta Bet-Sêmes, Y-Jôas hađăch Israel, nhŭp Y-Amasia, hađăch Yuđa, kon bu klâu Y-Jôas, sau Y-Amasia, jêh ri njŭn leo ô băl ma ƀon Yêrusalem, pô nây khân păng ƀư rlâm lơi mpêr ntơm bơh Mpông Pêr Êphraim tât ma Mpông Pêr Njônh, du rva jong geh puăn rhiăng hăt rlau.$b$,false),
('bunong-vn','2CH',25,24,null,$b$Păng sŏk lĕ mah, prăk, jêh ri lĕ rngôch khăl ngan păng saơ tâm ngih Brah Ndu, jêh ri nhŭp đŏng Y-Ôbet- Êđôm, mât uănh nđâp ma drăp ndơ ngih hađăch, bunuyh ăt nhŭp lĕ gay nhŭp ntơm, jêh ri păng djôt sĭt ma ƀon Samari.$b$,false),
('bunong-vn','2CH',25,25,null,$b$Y-Amasia, kon bu klâu Y-Jôsa, hađăch Yuđa, hôm e rêh jât ma prăm năm đŏng, jêh Y-Jôas kon bu klâu Y-Jôacha hađăch Israel khĭt.$b$,true),
('bunong-vn','2CH',25,26,null,$b$Kan êng êng Y-Amasia ƀư ntơm bơh sa-ơm tât lôch dŭt, mâu di hĕ bu chih tâm ndrom sămƀŭt Phung Hađăch Yuđa jêh ri Israel?$b$,false),
('bunong-vn','2CH',25,27,null,$b$Ntơm bơh rnôk păng cha lơi Yêhôva, bu ƀư nau tâm chră ŭch ƀư ma Y-Amasia tâm ƀon Yêrusalem, jêh ri păng du rlet ƀon Lakis. Ƀiă lah bu tĭng păng tât ta ƀon Lakis jêh ri nkhĭt păng ta nây.$b$,false),
('bunong-vn','2CH',25,28,null,$b$Bu rdeng păng ma seh, jêh ri bu tâp păng ndrel ma phung che păng tâm ƀon Y-Đavit.$b$,false),
('bunong-vn','2CH',26,1,null,$b$Lĕ rngôch phung ƀon lan Yuđa sŏk Y-Usia, păng geh jât ma prao năm, jêh ri njêng păng hađăch thoi mbơ̆ păng Y-Amasia.$b$,true),
('bunong-vn','2CH',26,2,null,$b$Jêh hađăch mbơ̆ hŏ khĭt jêh sĭt ndrel phung che păng, păng ndâk ƀon Êlat jêh ri bu mplơ̆ sĭt ô băl ma n'gor Yuđa.$b$,false),
('bunong-vn','2CH',26,3,null,$b$Y-Usia geh jât ma prao năm, tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh prăm jât năm tâm ƀon Yêrusalem. Amoh me păng H'Jêkôlia bơh ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',26,4,null,$b$Păng ƀư nau di ta năp măt Yêhôva, tĭng nâm lĕ rngôch nau mbơ̆ păng Y-Amasia ƀư jêh.$b$,true),
('bunong-vn','2CH',26,5,null,$b$Păng săch joi Brah Ndu tâm rnôk Y-Sakari, nơm sâm nti păng nau klach yơk ma Brah Ndu; jêh ri dôl păng tĭng joi ndah jŏ, Brah Ndu ăn ma păng nau chăt jêng tĭng jŏ dah nây lĕ.$b$,false),
('bunong-vn','2CH',26,6,null,$b$Păng du luh hăn tâm lơh đah phung Philistin, jêh ri lơh rlâm mpêr ƀon Gat, mpêr ƀon Japnê, jêh ri mpêr ƀon Asdôt, păng ndâk âk play ƀon tâm neh bri Asdôt, jêh ri âk ntŭk êng tâm bri Philistin.$b$,true),
('bunong-vn','2CH',26,7,null,$b$Brah Ndu kơl păng tâm lơh đah phung Philistin jêh ri đah phung Arap gŭ tâm ƀon Gurbaal, jêh ri đah phung Mêun.$b$,false),
('bunong-vn','2CH',26,8,null,$b$Phung Amôn chê̆ pi ma Y-Usia, jêh ri nau lư n'găr păng bu tăng lư tât ta n'har neh n'gor Êjipt, yor lah păng hao hŏ dơi chăt jêng ngăn.$b$,false),
('bunong-vn','2CH',26,9,null,$b$Rlau ma nây đŏng Y-Usia ndâk ngih tŭm tâm ƀon Yêrusalem, ta Mpông Pêr Njônh jêh ri Mpông Pêr Rlŭng, jêh ri Mpông Pêr kêng Kue, jêh ri dơm ta han tâm ngih tŭm nây.$b$,false),
('bunong-vn','2CH',26,10,null,$b$Păng ndâk ngih tŭm tâm bri rdah, jêh ri kuyh âk ndrâm ntu (ntu dak), yor lah păng geh âk ngăn biăp, ndrôk, nđâp tâm ntŭk neh lâng, jêh ri geh phung ƀư mir, phung tăm play kriăk ƀâu ta klơ dor lâng jêh ri tâm bri jêng ndơ, yor lah păng ŭch nau tuch tăm.$b$,true),
('bunong-vn','2CH',26,11,null,$b$Rmeh ma nau nây, Y-Usia geh du phung ta han blau tâm lơh, tâm pă tĭng mbŭch, tĭng nâm rnoh Y-Jêiêl kôranh chih sămƀŭt, jêh ri Y-Maseya kôranh ta han kơp ray hŏ ƀư, tâm dâng nau ƀĭt gai Y-Hanania, nơm jêng du huê kôranh, ma phung ta han hađăch.$b$,true),
('bunong-vn','2CH',26,12,null,$b$Rnoh kơp lĕ rngôch phung kôranh noi deh jêng ta han dăng ktang geh bar rbăn prao rhiăng nuyh.$b$,false),
('bunong-vn','2CH',26,13,null,$b$Khân păng chiă uănh du phung ta han geh pe rsen pơh rbăn prăm rhiăng nuyh, phung dơi tâm lơh ma nau ktang, ŭch kơl hađăch tâm lơh đah phung rlăng.$b$,false),
('bunong-vn','2CH',26,14,null,$b$Y-Usia nkra lĕ rngôch ta han khêl, tak, đon loih, ao loih nsiap, na, jêh ri lŭ prăp klŭp.$b$,false),
('bunong-vn','2CH',26,15,null,$b$Tâm ƀon Yêrusalem păng nkra ndeh tĭng nâm phung njêh njêng mhe dơm ta ngih tŭm ta ntŭk njônh, gay pănh hăr jêh ri klŭp lŭ toyh. Nau lư n'găr păng bu tăng ngai, yor lah bu kơl păng khlay ir ar kŏ tât păng jêng ktang.$b$,false),
('bunong-vn','2CH',26,16,null,$b$Ƀiă lah tơ lah păng jêng ktang jêh, păng ntơm sưr, nau nây ƀư roh păng. Yor lah păng mâu gŭ răp jăp ôh đah Brah Ndu păng, jêh ri lăp tâm ngih brah Yêhôva ŭch su mpa ƀâu kah ta nơng mpa ƀâu kah.$b$,true),
('bunong-vn','2CH',26,17,null,$b$Ƀiă lah Y-Asaria kôranh ƀư brah lăp pa kơi păng ndrel ma pham jât nuyh, kôranh ƀư brah Yêhôva jêng phung janh ktang;$b$,false),
('bunong-vn','2CH',26,18,null,$b$jêh ri khân păng tâm rdâng đah hađăch Usia, jêh ri lah ma păng: “Ơ Y-Usia, mâu di kan may ôh su ndơ ƀâu kah ma Yêhôva, nây jêng kan phung kôranh ƀư brah, phung kon bu klâu Y-Arôn, bu prăp ăn jêh ma kan su ndơ ƀâu kah. Luh hom bơh jrô kloh ueh aơ, yor lah may ƀư tih jêh; jêh ri yor lah kan aơ Yêhôva mâu mra ƀư ăn may dơi geh nau chrêk rmah ôh.”$b$,false),
('bunong-vn','2CH',26,19,null,$b$Y-Usia ji nuih ngăn; Păng djôt ta ti du mlâm khăl dơ ŭnh gay su ndơ ƀâu kah, jêh ri dôl păng hao nuih ma phung kôranh ƀư brah, păng geh phŭng luh ta ndăr kleng păng ta năp phung kôranh ƀư brah, tâm ngih Yêhôva êp sưng su ndơ ƀâu kah.$b$,false),
('bunong-vn','2CH',26,20,null,$b$Y-Asaria kôranh ƀư brah toyh, jêh ri lĕ rngôch phung kôranh ƀư brah êng, uănh ma păng, saơ păng geh phŭng ta ndăr kleng, bu mprơh păng luh du tă bơh nây; jêh ri păng nơm luh ndal đŏng, yor lah Yêhôva dong păng jêh.$b$,false),
('bunong-vn','2CH',26,21,null,$b$Hađăch Usia jêng du huê bunuyh geh phŭng tât nar păng khĭt, jêh ri yor ma nau ji phŭng du luh gŭ du mlâm ngih êng, mâu hôm dơi lăp tâm ngih Yêhôva đŏng ôh; Y-Jôtham kon bu klâu păng jêng kôranh chiă uănh ngih hađăch, jêh ri phat dôih phung ƀon lan tâm bri nây.$b$,false),
('bunong-vn','2CH',26,22,null,$b$Kan ƀa ƀă Y-Usia ƀư ntơm bơh sa ơm tât lôch dŭt Y-Êsai, kôranh nơm mbơh lor, kon bu klâu Y-Amôt, chih jêh.$b$,true),
('bunong-vn','2CH',26,23,null,$b$Y-Usia khĭt hăn gŭ ndrel phung che păng, jêh ri bu tâp păng ndrel phung che păng tâm mir dăch ntŭk môch prăp ma phung hađăch, yor lah bu lah bu lah: “Păng jêng du huê geh phŭng.” Jêh ri Y-Jôtham kon bu klâu păng chiă uănh thoi păng.$b$,false),
('bunong-vn','2CH',27,1,null,$b$Y-Jôtham geh bar jât ma pham năm tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh jât ma prao năm ta ƀon Yêrusalem. Amoh me păng H'Jêrusa kon bu ur Y-Sadôk.$b$,true),
('bunong-vn','2CH',27,2,null,$b$Păng ƀư di ta năp măt Yêhôva tĭng nâm lĕ rngôch nau mbơ̆ păng Y-Usia ƀư jêh knŏng păng mâu dơi lăp tâm ngih brah Yêhôva ôh. Ƀiă lah phung ƀon lan ăt hôm lơ ƀư blă blơ đŏng.$b$,false),
('bunong-vn','2CH',27,3,null,$b$Păng ndâk Mpông Pêr Ta Klơ tâm ngih Yêhôva, jêh ri ƀư âk kan ndâk n'gŏ mpêr ƀon Ôphel.$b$,false),
('bunong-vn','2CH',27,4,null,$b$Rmeh ma nây đŏng păng ndâk âk play ƀon tâm bri klơ dor Yuđa jêh ri pôih ta han, jêh ri ngih tŭm ta klơ yôk geh krŏng.$b$,true),
('bunong-vn','2CH',27,5,null,$b$Păng tâm lơh dơi đah hađăch phung Amôn. Phung Amôn ăn ma păng năm nây, du rhiăng ta lâng prăk, du rmưn kôr ba răch (ƀlê), jêh ri du rmưn kôr ba Ôrgơ. Phung Amôn chê̆ đŏng ma păng dŭm nây lĕ tâm năm rơh bar jêh ri rơh pe.$b$,true),
('bunong-vn','2CH',27,6,null,$b$Pô ri, Y-Jôtham jêng ktang, yor lah păng tĭng ndô̆ trong di ta năp măt Yêhôva păng.$b$,false),
('bunong-vn','2CH',27,7,null,$b$Kan êng Y-Jôtham ƀư, lĕ nau păng tâm lơh, jêh ri trong chuat hăn, aơ bu chih jêh tâm ndrom sămƀŭt Phung Hađăch Israel jêh ri Yuđa.$b$,false),
('bunong-vn','2CH',27,8,null,$b$Păng geh bar jât ma bar năm tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh jât ma prao năm ta ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',27,9,null,$b$Y-Jôtham khĭt hăn gŭ ndrel phung che păng, jêh ri bu tâp păng tâm ƀon Y-Đavit, jêh ri Y-Ahas kon bu klâu păng chiă uănh thoi păng.$b$,false),
('bunong-vn','2CH',28,1,null,$b$Y-Ahas geh bar jât năm, tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh jât ma prao năm tâm ƀon Yêrusalem. Jêh ri păng mâu ƀư ueh ôh ta năp măt Yêhôva nâm bu che păng Y-Đavit,$b$,true),
('bunong-vn','2CH',28,2,null,$b$ƀiă lah chuat tĭng ndô̆ trong phung hađăch Israel. Nđâp păng tŏ chiăr rup brah ma brah Baal.$b$,false),
('bunong-vn','2CH',28,3,null,$b$Păng su ndơ ƀâu kah tâm rlŭng kon bu klâu Y-Hinôm, jêh ri păng su kon nơm tâm ŭnh jêng ndơ nhhơr, tĭng nâm kan phung mpôl băl bunuyh Yêhôva tâm rmot hŏ mprơh du jêh tă bơh phung ƀon lan Israel.$b$,false),
('bunong-vn','2CH',28,4,null,$b$Păng nhhơr mpa ƀư brah jêh ri su ndơ ƀâu kah ta ntŭk prêh, ta klơ gôl yôk, jêh ri ăp tơm si tâm krŏng.$b$,false),
('bunong-vn','2CH',28,5,null,$b$Yor nây Yêhôva Brah Ndu păng jao păng ma ti hađăch Syri, nơm tâm lơh đah păng, jêh ri nhŭp leo âk bunuyh ƀon lan păng jêng bu nă jêh ri njŭn leo khân ô băl ma ƀon Damas. Yêhôva jao păng tâm ban lĕ ma ti hađăch Israel, nơm tâm lơh dơi đah păng jêh ri nkhĭt âk bunuyh.$b$,true),
('bunong-vn','2CH',28,6,null,$b$Yor lah Y-Pêka kon bu klâu Y-Rêmalia ƀư nkhĭt du rsen bar rmưn bunuyh phung Yuđa tâm du nar, lĕ rngôch khân ô băl jêng phung dăng ktang, yor lah khân păng cha lơi Yêhôva Brah Ndu phung che khân păng.$b$,true),
('bunong-vn','2CH',28,7,null,$b$Jêh ri Y-Sikri, du huê dăng ktang bơh bri Êphraim, nkhĭt Y-Maseya, kon bu klâu hađăch, jêh ri Y-Asrikam, kôranh ta han chiă ngih hađăch, jêh ri Y-Êlkana, kôranh groi hađăch.$b$,true),
('bunong-vn','2CH',28,8,null,$b$Phung ta han Israel nhŭp ndrăng mpôl băl nơm bar rsen nuyh ƀư nă, nđâp ma bu ur, phung kon bu klâu, phung kon bu ur; khân păng sŏk pit tâm ban lĕ geh âk ndô ndơ bơh khân ô băl jêh ri djôt leo ndơ nây ma ƀon Samari.$b$,true),
('bunong-vn','2CH',28,9,null,$b$Geh ta nây, du huê kôranh nơm mbơh lor Yêhôva, amoh Y-Ôdet; luh hăn mâp phung ta han dôl plơ̆ sĭt bơh Samari, jêh ri pô aơ: “Aơ, yor lah Yêhôva Brah Ndu phung che khân may nuih ma phung Yuđa, yor ri Păng jao khân ô băl tâm ti khân may, ƀiă lah khân may nkhĭt khân ô băl ma nau ji nuih, nau nây lư n'hôl tât trôk.$b$,true),
('bunong-vn','2CH',28,10,null,$b$Aƀaơ ri, khân may mĭn ŭch nglăp phung ƀon lan Yuđa jêh ri phung Yêrusalem, bu ur nđâp ma bu klâu, njêng dĭk ma khân may ƀơh! Bi ma khân may, mâu di hĕ khân may ƀư tih đah Yêhôva Brah Ndu ma phung khân may?$b$,true),
('bunong-vn','2CH',28,11,null,$b$Pô ri aƀaơ, iăt hom nau gâp, jêh ri mplơ̆ sĭt lĕ bu nă jêng mpôl băl ma khân may nơm, phung khân may hŏ geh nhŭp jêh tâm phung oh nâu khân may nơm; yor lah nau Yêhôva ji nuih duh tât jêh ma khân may.”$b$,false),
('bunong-vn','2CH',28,12,null,$b$Geh đŏng ƀa ƀă kôranh bơh phung Êphraim, Y-Asaria kon bu klâu Y-Jôhanan, Y-Bêrêkia kon bu klâu Y-Mêsilêmôt, Y-Jêhiskia kon bu klâu Y-Salum, jêh ri Y-Amasa kon bu klâu Y-Hadlai, du dâk tâm rdâng đah phung plơ̆ sĭt tă tâm lơh,$b$,false),
('bunong-vn','2CH',28,13,null,$b$jêh ri lah ma khân păng pô aơ: “Khân may mâu mra njŭn leo bu nă lăp ta aơ ôh, yor lah khân may joi nau jêng tih ăn ma he geh nau tih đah Yêhôva, ntop đŏng nau tih jêh ri nau djơh mhĭk ma phung he aƀaơ aơ. Yor lah nau he tih jêng toyh ngăn, jêh ri nau kôranh Brah ji nuih duh tât jêh ma phung Israel.”$b$,false),
('bunong-vn','2CH',28,14,null,$b$Pô ri phung ta han mƀơk lơi phung bu nă jêh ri bun lĕ ndô ndơ pit in ăn ta năp măt phung kôranh jêh ri lĕ rngôch phung tâm rƀŭn.$b$,false),
('bunong-vn','2CH',28,15,null,$b$Lĕ rngôch phung bu kuăl amoh săk jêh lor nây, khân păng dâk, sŏk phung bu nă luh du jêh ri sŏk ndô ndơ bu pit in sâm nsoh lĕ rngôch bunuyh gŭ săk hưl, ta nklang khân ô băl; khân păng ăn khân ô băl nsoh kho ao, nsoh ntô jot jêh ri ăn khân ô băl sông sa, nhêt, jêh ri mhĭng dak si ma khân ô băl. Khân păng rdeng ma seh phung bu ranh mâu hôm dăng jêh ri njŭn khân ô băl sĭt tât ma ndŭl mpôl khân ô băl nơm ta ƀon Yêrikô, ƀon geh Tơm Play Đung. Jêh ri khân păng plơ̆ sĭt ma ƀon Samari.$b$,true),
('bunong-vn','2CH',28,16,null,$b$Dôl nôk nây, Hađăch Ahas prơh bu hăn dăn hađăch Asiri kơl.$b$,true),
('bunong-vn','2CH',28,17,null,$b$Yor lah phung Êđôm plơ̆ lăp jêh ri tâm lơh dơi păng đah phung Yuđa, jêh ri njŭn sĭt âk bu nă.$b$,false),
('bunong-vn','2CH',28,18,null,$b$Phung Philistin ăt tâm lơh đŏng đah ăp ƀon tâm bri neh lâng jêh ri bri rđŭng pa dâng tâm n'gor Yuđa, jêh ri lĕ sŏk pit jêh ƀon Bet-Sêmes, Aijalon, Gêdêrôt, Sôkô nđâp ma ƀon dăch păng, Timnu nđâp ma ƀon dăch păng, jêh ri Gismô nđâp ma ƀon dăch păng; jêh ri khân păng n'ho gŭ tâm ăp ntŭk nây.$b$,true),
('bunong-vn','2CH',28,19,null,$b$Yor ma Y-Ahas, hađăch Yuđa, Yêhôva geh n'glưh lơi Yuđa jŭr. Yor lah Y-Ahas hŏ nsŭk ăn phung Yuđa ƀư blă blơ jêh ri ƀư tih jru đah Yêhôva.$b$,false),
('bunong-vn','2CH',28,20,null,$b$Pô ri, Y-Tigla-Pilêser, hađăch Asiri, văch tât ma păng, jêh ri tŭn jot ô băl, ƀiă lah mâu geh kơl du ntil ôh.$b$,false),
('bunong-vn','2CH',28,21,null,$b$Yor lah Y-Ahas sŏk bơh ngih Yêhôva, sŏk tâm ngih hađăch, jêh ri tâm ngih phung kôranh ndơ bu chê̆ pi ma hađăch Asiri; ƀiă lah ndơ nây mâu jêng nau kơl ma păng ôh.$b$,true),
('bunong-vn','2CH',28,22,null,$b$Tâm nau rêh ni, Hađăch Ahas plơ̆ ƀư tih lơn đah Yêhôva;$b$,true),
('bunong-vn','2CH',28,23,null,$b$yor lah păng ƀư brah phung brah ƀon Damas, jêng phung ƀon lan lơh nơm; jêh ri lah: “Yor lah phung brah hađăch Asiri hŏ kơl jêh khân păng, pô ri gâp mra ƀư brah ma phung brah nây gay khân păng kơl gâp.” Ƀiă lah phung brah nây jêng nau ƀư roh rai ma păng, jêh ri lĕ rngôch phung Israel.$b$,false),
('bunong-vn','2CH',28,24,null,$b$Y-Ahas rgum lĕ khăl ngan ngih Yêhôva, dong ăn păng chah lơi, jêh ri nchăng mpông ngih brah Yêhôva; Jêh ri păng ndâk ma păng nơm nơng tâm ăp njônh tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',28,25,null,$b$Tâm ăp ƀon, n'gor Yuđa păng ƀư ntŭk prêh gay su ndơ ƀâu kah ma phung brah êng, gay nsônh ăn Yêhôva Brah Ndu phung che păng ji nuih.$b$,false),
('bunong-vn','2CH',28,26,null,$b$Ƀă kan êng păng ƀư, jêh ri lĕ rngôch trong păng chuat, bơh ntơm sa ơm tât kêng lôch, aơ bu chih jêh tâm ndrom sămƀŭt Phung Hađăch Yuđa jêh ri Israel.$b$,true),
('bunong-vn','2CH',28,27,null,$b$Jêh ri Y-Ahas khĭt hăn gŭ ndrel phung che păng, jêh ri bu tâp păng tâm ƀon Yêrusalem, yor lah bu mâu njŭn ôh păng ma môch phung hađăch Israel. Jêh ri Y-Hêsêkia kon bu klâu păng chiă uănh thoi păng.$b$,false),
('bunong-vn','2CH',29,1,null,$b$Y-Hêsêkia, geh bar jât ma prăm năm, tơ lah păng ntơm chiă uănh; păng chiă uănh tâm ƀon Yêrusalem, Amoh me păng, H'Abija kon bu ur Y-Sakari.$b$,true),
('bunong-vn','2CH',29,2,null,$b$Păng ƀư nau di ta năp măt Yêhôva tĭng nâm lĕ rngôch nau che păng Y-Đavit, hŏ ƀư jêh. Mbah Yơk. Tâm Ngih Yêhôva$b$,false),
('bunong-vn','2CH',29,3,null,$b$Khay nguay năm sa ơm păng chiă uănh, păng pơk mpông ngih Yêhôva, jêh ri nkra mpông nây.$b$,false),
('bunong-vn','2CH',29,4,null,$b$Păng leo phung kôranh ƀư brah jêh ri phung Lêvi lăp, jêh ri rgum khân păng tâm ndring mpeh pa lơ,$b$,false),
('bunong-vn','2CH',29,5,null,$b$jêh ri lah ma khân Ô băl: “Iăt hom gâp, Ơ phung Lêvi! Aƀaơ ri ƀư hom khân may nơm, jêh ri ƀư kloh lơi ngih Yêhôva Brah Ndu phung che khân may, jêh ri sŏk mƀăr lơi ndơ ƀơ̆ ƀơch bơh jrô kloh ueh.$b$,false),
('bunong-vn','2CH',29,6,null,$b$Yor lah phung che he mâu gŭ răp jăp ôh jêh ri tŭp nau tih, ƀư nau mhĭk ta năp măt Yêhôva Brah Ndu he; cha lơi Păng, jêh ri mâu ŭch rle muh măt uănh ma ntŭk Yêhôva gŭ, ndôn kơi ma Păng.$b$,false),
('bunong-vn','2CH',29,7,null,$b$Khân păng nchăng lơi tâm ban lĕ đơ mpông ta ndring, jêh ri nhhât lơi ŭnh kađen, mâu su ôh ndơ ƀâu kah jêh ri mâu nhhơr ôh mpa nhhơr gŭch ta ntŭk kloh ăn ma Yêhôva phung Israel.$b$,false),
('bunong-vn','2CH',29,8,null,$b$Yor ri, nau Yêhôva ji nuih tât ma phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem, jêh ri Păng jao khân păng ma nau nđêh nji, nau roh rai, nau bu gơm mưch, tĭng nâm măt khân may nơm lĕ saơ jêh.$b$,false),
('bunong-vn','2CH',29,9,null,$b$Yor nau nây, aơ phung che he chôt khĭt ma đao, ƀă phung kon bu klâu, ƀă phung kon bu ur, jêh ri phung ur he jêng bu nă.$b$,false),
('bunong-vn','2CH',29,10,null,$b$Aƀaơ, gâp geh nau mĭn ŭch ƀư nau tâm rnglăp đah Yêhôva Brah Ndu phung Israel, gay nau ji nuih Păng du ngai bơh phung he.$b$,false),
('bunong-vn','2CH',29,11,null,$b$Ơ phung kon bu klâu gâp, lơi ta brơl rlach ôh, yor lah geh săch jêh khân may jêng oh mon Păng, gay gŭ dâk pa năp Păng, gay pah kan jêh ri su ndơ ƀâu kah ma Păng.”$b$,false),
('bunong-vn','2CH',29,12,null,$b$Pô ri phung Lêvi dâk, Y-Mahat kon bu klâu Y-Amasai jêh ri Y-Jôel kon bu klâu Y-Asaria bơh phung noi Y-Kôhat; jêh ri bơh phung noi Y-Mêrari geh Y-Kis kon bu klâu Y-Apdi, jêh ri Y-Ysaria kon bu klâu Y-Jêhalêlel; jêh ri bơh phung noi Gersôn geh Y-Jôa kon bu klâu Y-Sima, jêh ri Y-Êđen kon bu klâu Y-Jôa;$b$,true),
('bunong-vn','2CH',29,13,null,$b$jêh ri bơh phung noi Y-Êlisaphan geh Y-Simri jêh ri Y-Jêuêl; jêh ri bơh phung noi Y-Asap geh Y-Sakari jêh ri Y-Mataniah;$b$,false),
('bunong-vn','2CH',29,14,null,$b$jêh ri bơh phung noi Y-Hêman geh Y-Jêhuêl jêh ri Y-Simei; jêh ri bơh phung noi Y-Yêduthun geh Y-Sêmaya jêh ri Y-Usiêl.$b$,false),
('bunong-vn','2CH',29,15,null,$b$Khân păng rƀŭn phung oh nâu khân păng jêh ri ƀư kloh lơi khân păng nơm, jêh ri lăp tâm ngih brah tĭng nâm hađăch ntăm jêh, tĭng nâm nau Yêhôva ngơi gay ƀư kloh ngih Yêhôva.$b$,false),
('bunong-vn','2CH',29,16,null,$b$Phung kôranh ƀư brah lăp tâm trôm jrô ngih Yêhôva, gay ƀư kloh ô băl, jêh ri ngluh mƀăr pa dih, tâm nhuang vâl ngih brah, lĕ rngôch ndơ ƀơ̆ khân păng saơ tâm trôm ngih Yêhôva; jêh ri phung Lêvi sŏk ndơ nây djôt leo nkhŭt ta n'hor dak Sêdrôn.$b$,false),
('bunong-vn','2CH',29,17,null,$b$Nar năng nguay khay rơh nguay khân păng ntơm ƀư kloh ngih brah; jêh ri tât nar năng pham khay nây, khân păng tât ta ndring ngih Yêhôva; tâm pham nar khân păng ƀư kloh ngih brah Yêhôva; jêh ri tât nar jât ma prao khay nguay, kan pah lôch jêh.$b$,false),
('bunong-vn','2CH',29,18,null,$b$Khân păng lăp tâm ngih hađăch Êsêkia, jêh ri lah: “Hên ƀư kloh lĕ rngôch jêh ngih brah Yêhôva, nơng gŭch mpa nhhơr gŭch nđâp lĕ rngôch ndơ dŏng ma păng, sưng dơm piăng let nhhơr ma Brah Ndu jêh ri lĕ rngôch ndơ dŏng ma păng.$b$,false),
('bunong-vn','2CH',29,19,null,$b$Lĕ rngôch ndơ dŏng Hađăch Ahas klŭp mƀăr lơi jêh dôl rnôk păng chiă uănh, ma nau păng mâu gŭ răp jăp ôh, hên nkra jêh ri ƀư kloh da dê; aơ, lĕ rngôch ndơ nây gŭ pa năp nơng Yêhôva.$b$,false),
('bunong-vn','2CH',29,20,null,$b$Hađăch Hêsêkia kah rngăl ơm ôi, tâm rƀŭn phung kôranh tâm ƀon, jêh ri hăn hao ma ngih Yêhôva.$b$,true),
('bunong-vn','2CH',29,21,null,$b$Khân păng têk leo pơh mlâm ndrôk nkuăng, pơh mlâm biăp nkuăng, pơh mlâm kon biăp, jêh ri pơh mlâm be nkuăng prăp ma mpa nhhơr yor nau tih ma ƀon bri hađăch, ma jrô kloh ueh, jêh ri ma phung Yuđa. Păng ntĭnh ma phung kôranh ƀư brah, phung kon bu klâu Y-Arôn ăn nhhơr ndơ nây ta klơ nơng Yêhôva.$b$,false),
('bunong-vn','2CH',29,22,null,$b$Pô ri khân păng nkhĭt ndrôk nkuăng, jêh ri phung kôranh ƀư brah dâng sŏk mham nsrih ta klơ nơng; jêh ri khân păng nkhĭt biăp nkuăng, jêh ri nsrih mham nây ta klơ nơng.$b$,false),
('bunong-vn','2CH',29,23,null,$b$Jêh ri bu têk leo be nkuăng prăp mpa nhhơr chuai nau tih văch dăch êp pa năp hađăch jêh ri phung tâm rƀŭn, jêh ri khân păng dra ti khân păng ta klơ be nây,$b$,false),
('bunong-vn','2CH',29,24,null,$b$jêh ri phung kôranh ƀư brah nkhĭt khân ô băl, jêh ri dâng sŏk mham nsrih klơ nơng gay ƀư brah chuai nau tih ăn ma lĕ rngôch phung Israel; yor lah hađăch ntĭnh kơt aơ mpa nhhơr gŭch jêh ri mpa nhhơr chuai nau tih nhhơr yor ma lĕ rngôch phung Israel.$b$,false),
('bunong-vn','2CH',29,25,null,$b$Hađăch dơm phung Lêvi tâm ngih brah Yêhôva djôt dang, gong rêng jêh ri n'hôm, tĭng nâm nau vay ntrŭnh bơh Y-Đavit, jêh ri Y-Gat, jêng nơm bu tâm saơ ma hađăch, jêh ri bơh kôranh nơm mbơh lor Y-Nathan ntăm; yor lah nau vay ntăm nây luh bơh Yêhôva ma bâr mbung phung kôranh nơm mbơh lor Păng ntĭm nti.$b$,true),
('bunong-vn','2CH',29,26,null,$b$Phung Lêvi gŭ dâk djôt ndơ mprơ Y-Đavit jêh ri phung kôranh ƀư brah djôt nŭng.$b$,false),
('bunong-vn','2CH',29,27,null,$b$Jêh ri Y-Hêsêkia ntĭnh ăn bu nhhơr mpa ƀư brah gŭch ta klơ nơng. Tơ lah bu ntơm nhhơr mpa nhhơr gŭch. Bu ntơm mprơ tâm rnê ma Yêhôva tâm ban lĕ, jêh ri bu uh nŭng tâm rnglăp đah ndơ mpât mprơ Y-Đavit hađăch Israel.$b$,false),
('bunong-vn','2CH',29,28,null,$b$Lĕ rngôch phung tâm rƀŭn yơk mbah, jêh ri phung mprơ gŭ mprơ, jêh ri phung uh nŭng gŭ uh nŭng. Bu ƀư nau nây tât lôch jêh kan nhhơr mpa nhhơr gŭch.$b$,false),
('bunong-vn','2CH',29,29,null,$b$Tơ lah nau nhhơr lôch jêh, hađăch jêh ri lĕ rngôch phung gŭ ta nây ndrel ma păng kŭnh bôk mbah yơk.$b$,true),
('bunong-vn','2CH',29,30,null,$b$Hađăch Hêsêkia jêh phung kôranh ntĭnh ma phung Lêvi ăn mprơ tâm rnê ma Yêhôva ma rplay ngơi Y-Đavit jêh ri Y-Asap nơm tâm saơ chih jêh. Khân păng mprơ nau mât ton ma nau răm maak, jêh ri khân păng kŭnh bôk mbah yơk.$b$,false),
('bunong-vn','2CH',29,31,null,$b$Jêh ri Y-Hêsêkia lah: “Aƀaơ ri khân may prăp jêh khân may nơm jêng kloh ma Yêhôva; văch dăch hom, njŭn mpa ƀư brah jêh ri nhhơr ndơ tâm rnê lăp tâm ngih Yêhôva.” Jêh ri phung tâm rƀŭn leo mpa ƀư brah jêh ri ndơ nhhơr tâm rnê; bi ma nơm geh nuih n'hâm ŭch djôt leo mpa nhhơr gŭch.$b$,true),
('bunong-vn','2CH',29,32,null,$b$Rnoh kơp mpa nhhơr gŭch phung tâm rƀŭn ndjôt leo pơh jât mlâm ndrôk nkuăng, du rhiăng mlâm biăp nkuăng, jêh ri bar rhiăng mlâm kon biăp; lĕ rngôch ndơ nây prăp ma mpa nhhơr gŭch ma Yêhôva.$b$,false),
('bunong-vn','2CH',29,33,null,$b$Rnoh kơp mpa nhhơr prăp êng ăn kloh geh prao rhiăng ndrôk nkuăng jêh ri pe rbăn mlâm biăp.$b$,false),
('bunong-vn','2CH',29,34,null,$b$Ƀiă lah phung kôranh ƀư brah ƀhôi ir, mâu dơi doih ntâu lĕ rngôch mpa nhhơr gŭch ôh, pô ri kŏ tât phung kôranh ƀư brah êng lĕ ƀư kloh jêh khân păng nơm, phung oh nâu khân păng phung Lêvi kơl kan khân păng, tât lĕ kan dơi jêh yor lah phung Lêvi geh nuih n'hâm sŏng lơn ma phung kôranh ƀư brah tâm nau ƀư kloh khân păng nơm.$b$,false),
('bunong-vn','2CH',29,35,null,$b$Lơ geh âk lơn mpa nhhơr gŭch, ngi mpa nhhơr nau đăp mpăn, jêh ri geh ndơ nhhơr nhêt tŏ ăp mpa nhhơr gŭch. Pô ri, bu hŏ ndâk njêng jêh mpa ƀư brah tâm ngih Yêhôva.$b$,false),
('bunong-vn','2CH',29,36,null,$b$Y-Hêsêkia jêh ri lĕ rngôch phung ƀon lan hâk răm yor nau Brah Ndu ƀư jêh ma phung ƀon lan; yor lah nau kan nây ƀât lât dơm ƀiă lah ƀư jêng ro.$b$,true),
('bunong-vn','2CH',30,1,null,$b$Y-Hêsêkia njuăl bâr ngơi ma lĕ rngôch phung Israel jêh ri phung Yuđa, tâm ban lĕ chih njuăl sămƀŭt ma phung Êphraim jêh ri phung Manasê, gay ma khân păng văch tât ma ngih Yêhôva ta ƀon Yêrusalem gay kah gĭt yơk ma nau nhêt ƀun Nau Găn ma Yêhôva Brah Ndu Israel.$b$,true),
('bunong-vn','2CH',30,2,null,$b$Yor lah hađăch jêh ri phung kôranh nđâp ma lĕ rngôch phung tâm rƀŭn ta ƀon Yêrusalem tâm chră jêh gay kah gĭt yơk ma nau nhêt ƀun Nau Găn tâm khay rơh bar,$b$,false),
('bunong-vn','2CH',30,3,null,$b$yor lah khân păng mâu dơi hăn râng nhêt ƀun Nau Găn dôl nôk nây, yor lah rnoh phung kôranh brah ƀư kloh khân păng nơm ê hŏ tŏng nŭm ôh, jêh ri phung ƀon lan ê hŏ rgum đŏng ta ƀon Yêrusalem,$b$,false),
('bunong-vn','2CH',30,4,null,$b$jêh ri nau dăp kan nây hađăch jêh ri lĕ rngôch phung tâm rƀŭn mĭn lĕ di.$b$,false),
('bunong-vn','2CH',30,5,null,$b$Pô ri, khân păng ntĭnh gay ƀư du nau mbơh lam bri Israel, ntơm bơh ƀon Bêr-Sêba tât ma ƀon Dan, gay ma phung ƀon lan văch jêh ri kah gĭt yơk ma nhêt ƀun Nau Găn ma Yêhôva Brah Ndu phung Israel ta ƀon Yêrusalem; yor lah hŏ jŏ jêh âk khân păng mâu geh hăn râng nhêt ƀun Nau Găn nây tĭng nâm nau hŏ chih jêh tâm nau vay.$b$,false),
('bunong-vn','2CH',30,6,null,$b$Pô ri, phung nsong mbơh lam bri dak njŭn sămƀŭt hađăch jêh ri phung kôranh hăn lam n'gor bri Israel jêh ri n'gor Yuđa, sămƀŭt nchih pô aơ: “Ơ phung kon sau Israel, plơ̆ sĭt hom ma Yêhôva Brah Ndu Y-Abraham, ma Y-Isăk jêh ri ma Israel, gay ma Yêhôva plơ̆ n'gĭl tay ma phung khân may hôm e klen dơi klaih jêh tă bơh ti phung hađăch Asiri.$b$,true),
('bunong-vn','2CH',30,7,null,$b$Lơi ta kơt nâm bu phung che jêh ri phung oh nâu khân may ôh, khân păng mâu ŭch gŭ răp jăp ôh ma Yêhôva Brah Ndu phung che khân păng, yor nây Yêhôva ƀư rai jêh khân păng tĭng nâm khân may saơ.$b$,false),
('bunong-vn','2CH',30,8,null,$b$Lơi ta jêng dăng bôk ôh nâm bu phung che khân may, ƀiă lah yơr hom ti khân may nơm ma Yêhôva, jêh ri văch ma ntŭk kloh ueh Păng, hŏ prăp êng jêng kloh n'ho ro; jêh ri pah kan hom ma Yêhôva Brah Ndu khân may, gay ma nau Păng duh ji nuih dơi du ngai bơh khân may.$b$,false),
('bunong-vn','2CH',30,9,null,$b$Yor lah tơ lah khân may plơ̆ sĭt ma Yêhôva, phung oh nâu khân may, jêh ri phung kon khân may mra geh nau yô̆ ta năp măt phung nhŭp khân păng jêng bună; jêh ri khân păng mra dơi plơ̆ sĭt tâm n'gor aơ, yor tă Yêhôva Brah Ndu khân may geh nuih n'hâm gĭt yô̆ jêh ri klâng rvê, Păng nâu mra ndôn kơi Păng bơh khân may, tơ lah khân may plơ̆ sĭt ma Păng.”$b$,false),
('bunong-vn','2CH',30,10,null,$b$Pô ri phung njŭn sămƀŭt hăn bơh ƀon aơ tât ƀon ri, tâm lam n'gor Êphraim, Mamasê, jêh ri tât neh Sabulôn; ƀiă lah bu gơm mưch, suai rak ma khân păng.$b$,true),
('bunong-vn','2CH',30,11,null,$b$Nđâp lah kơt nĕ, ăt geh lĕ tâm phung Aser, Manasê, jêh ri Sabulôn khân păng geh nau dêh rhêt jêh ri văch tât ma ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',30,12,null,$b$Tâm ban lĕ ti Brah Ndu yơr ma phung Yuđa gay ăn ma khân păng geh du ai nau ŭch ƀư nau hađăch jêh ri phung kôranh ntăm jêh tĭng nâm Yêhôva ngơi.$b$,false),
('bunong-vn','2CH',30,13,null,$b$Âk bunuyh ƀon lan tât ndrel n'grŭp tâm ƀon Yêrusalem jêng du phung tâm rƀŭn toyh ŭch nhhơr yơk ma Nau Sa Piăng Let Mâu Geh Ndrui tâm khay rơh bar.$b$,true),
('bunong-vn','2CH',30,14,null,$b$Khân păng ntơm ndrăp, jêh ri prăp lơi nơng bu ndâk ma brah êng tâm ƀon Yêrusalem, jêh ri lĕ rngôch gri su ndơ ƀâu kah khân păng leo nchuăn mƀăr tâm rlŭng Kidrôn.$b$,false),
('bunong-vn','2CH',30,15,null,$b$Khân păng nkhĭt biăp Nau Găn ta nar jât ma puăn khay rơh bar. Phung n'gâng kan ƀư brah jêh ri phung Lêvi, geh nau prêng, pô ri khân păng ƀư kloh êng nơm, jêh ri leo mpa ƀư brah nhhơr gŭch tâm ngih Yêhôva.$b$,false),
('bunong-vn','2CH',30,16,null,$b$Khân păng djôt kan bu jao, kơt kănđai hŏ ntrŭnh jêh tâm nau vay Y-Môis, bunuyh Brah Ndu; jêh ri n'gâng kan ƀư brah sŏk mham tâm ti phung Lêvi jêh ri nsrih mham nây.$b$,false),
('bunong-vn','2CH',30,17,null,$b$Yor lah geh âk ƀiă lah tâm phung tâm rƀŭn mâu geh ƀư kloh ôh khân păng nơm, yor nây phung Lêvi nkhĭt kon biăp Nau Găn rgâl ăn ma ăp nơm ê hŏ kloh ôh, gay ăn ma khân păng dơi jêng kloh ma Yêhôva.$b$,false),
('bunong-vn','2CH',30,18,null,$b$Yor lah geh âk bunuyh phung ƀon lan phung Êphraim, Manasê, Isakar, jêh ri Sabulôn ê hŏ ƀư kloh khân păng nơm ôh, ƀiă lah ăt khân păng sa Nau Găn, mâu tĭng kơt ôh nau vay bu hŏ chih jêh. Yor lah Y-Hêsêkia mbơh sơm ma khân păng, lah pô aơ:$b$,false),
('bunong-vn','2CH',30,19,null,$b$“Dăn ma Yêhôva jêng Nơm ueh, yô̆ an nau tih ma lĕ rngôch bunuyh hŏ geh nuih n'hâm tĭng joi Yêhôva Brah Ndu phung che khân păng; nđâp tơ lah mâu hŏ di ôh tĭng nâm nau vay ma jrô kloh ueh, gay ƀư kloh he nơm lor.$b$,false),
('bunong-vn','2CH',30,20,null,$b$Yêhôva dơi iăt nau mbơh sơm bơh Y-Hêsêkia, jêh ri ƀư bah an phung ƀon lan.$b$,false),
('bunong-vn','2CH',30,21,null,$b$Phung ƀon lan Israel văch ma ƀon Yêrusalem, kah gĭt yơk nau Sa Piăng Let Mâu Geh Ndrui; dôl tâm pơh nar ma nau răm maak ngăn ngên. Phung Lêvi, phung n'gâng kan ƀư brah tâm rnê ma Yêhôva ăp nar; uh n'hôm rlet mprơ tâm rnê ma Yêhôva.$b$,true),
('bunong-vn','2CH',30,22,null,$b$Y-Hêsêkia ngơi n'hao nuih ma lĕ rngôch phung Lêvi tâm mpơl nau blau mĭn ma kan mbah yơk ma Yêhôva. Pô ri, phung ƀon lan sông sa tâm pơh nar, nhhơr mpa ma nau đăp mpăn, jêh ri nhhơr mpa nau lah ueh ma Yêhôva Brah Ndu phung che khân păng.$b$,false),
('bunong-vn','2CH',30,23,null,$b$Lĕ rngôch phung tâm rƀŭn sŏk dơn du ai thoi đŏng pơh nar, kah gĭt yơk nau sông sa; pô ri khân păng bêng ma nau răm maak.$b$,true),
('bunong-vn','2CH',30,24,null,$b$Yor lah Y-Hêsêkia, hađăch Yuđa, hŏ ăn jêh ma phung tâm rƀŭn geh du rbăn mlâm ndrôk nkuăng jêh ri pơh rbăn mlâm biăp prăp ma nau nhhơr, jêh ri phung kôranh ăn ma phung tâm rƀŭn du rbăn mlâm ndrôk nkuăng jêh ri pơh rbăn mlâm biăp. Geh âk đŏng phung n'gâng kan ƀư brah ƀư kloh khân păng nơm.$b$,false),
('bunong-vn','2CH',30,25,null,$b$Lĕ rngôch phung tâm rƀŭn Yuđa jêh ri phung n'gâng kan ƀư brah nđâp ma phung Lêvi, jêh ri phung Israel văch tâm rƀŭn, nđâp phung bu năch, phung gŭ njưh tâm n'gor Israel, phung gŭ njưh tâm n'gor Yuđa, răm maak da dê.$b$,false),
('bunong-vn','2CH',30,26,null,$b$Pô ri, tâm ƀon Yêrusalem răm maak ngăn ngên yơh; yor lah bơh rô̆ Y-Salômôn, kon bu klâu Y-Đavit, hađăch Israel, ta ƀon Yêrusalem ê hŏ geh ôh nau nâm pô nây.$b$,false),
('bunong-vn','2CH',30,27,null,$b$Pô nây, phung n'gâng kan ƀư brah jêh ri phung Lêvi gŭ dâk mât ton ma phung bunuyh ƀon lan; Brah Ndu dơi iăt bâr khân păng, nau mbơh sơm khân păng ntoh tât ma ntŭk kloh ueh Yêhôva klơ trôk.$b$,false),
('bunong-vn','2CH',31,1,null,$b$Tơ lah lĕ nau kan nây lôch jêh, lĕ rngôch phung Israel văch tât jêh ta ƀon Yêrusalem dâk hăn ăp ƀon tâm n'gor Yuđa, jêh ri mbang chah lơi meh jrŏng rup brah jêh ri kăl lơi rup Asêrim jêh ri nklưh lơi ntŭk prêh, rôk lĕ nơng tâm lam n'gor Yuđa, Benjamin, Êphraim, jêh ri Manasê, kŏ tât khân păng hŏ ƀư rai lĕ ƀhiau ndơ nây. Pô nây, lĕ rngôch phung ƀon lan Israel plơ̆ sĭt ma ƀon khân păng nơm, êng ƀon êng sĭt ma neh păng.$b$,true),
('bunong-vn','2CH',31,2,null,$b$Y-Hêsêkia tâm pă mpôl êng êng phung n'gâng kan ƀư brah jêh ri phung Lêvi, ăp mpôl tĭng nâm kan khân păng, gay nhhơr mpa nhhơr gŭch jêh ri ndơ nhhơr nau đăp mpăn, gay tâm rnê, nau mât ton jêh ri mprơ tâm rnê Kôranh Brah ta mpông pêr nkual ntŭk njưh Yêhôva.$b$,true),
('bunong-vn','2CH',31,3,null,$b$Ndơ hađăch nơm nhhơr bơh ndơ păng prăp ma mpa nhhơr gŭch geh: Mpa nhhơr gŭch ma ôi jêh ri mhaơ, jêh ri mpa nhhơr gŭch ma nar Saƀat, ma nar mhe luh, jêh ri ma nar sông sa khlay nal jêh, tĭng nâm bu chih jêh tâm ndrom sămƀŭt nau vay Yêhôva.$b$,false),
('bunong-vn','2CH',31,4,null,$b$Păng ntĭnh ma bunuyh ƀon lan gŭ ta ƀon Yêrusalem ăn nhhơr kơl ma phung n'gâng kan ƀư brah jêh ri phung Lêvi, gay ma khân păng dơi jao khân păng nơm mray nau vay Yêhôva.$b$,true),
('bunong-vn','2CH',31,5,null,$b$Tơ lah nau hađăch ntrŭnh tăng lam jêh, phung ƀon lan Israel nhhơr ma nau âk rmeh ndơ bôk rah tă bơh ba, tă bơh dak play kriăk ƀâu, bơh dak sŭt, bơh dak play Ôlivơ, jêh ri lĕ rngôch ndô ndơ êng luh bơh mir; khân păng leo njŭn tât nhhơr du kô̆ tâm jât tâm ăp ntil dŭt âk râk.$b$,false),
('bunong-vn','2CH',31,6,null,$b$Phung Israel jêh ri phung Yuđa gŭ tâm ăp ƀon n'gor Yuđa, ăt djôt leo tât nhhơr du kô̆ tâm jât bă ndrôk jêh ri biăp tâm ban lĕ; jêh ri nhhơr ndơ khân păng prăp êng jêh ma Yêhôva Brah Ndu khân păng, jêh ri bun êng êng tĭng mbŭch ndơ nhhơr nây.$b$,true),
('bunong-vn','2CH',31,7,null,$b$Khay rơh pe, khân păng kuak rgum tĭng mbŭch, tât khay pơh mơ lĕ.$b$,false),
('bunong-vn','2CH',31,8,null,$b$Tơ lah Y-Hêsêkia jêh ri phung kôranh văch tât, uănh saơ âk mbŭch bu bun ndơ nhhơr khân păng tâm rnê ma Yêhôva jêh ri ma phung ƀon lan Israel.$b$,false),
('bunong-vn','2CH',31,9,null,$b$Y-Hêsêkia ôp ma phung n'gâng kan ƀư brah jêh ri phung Lêvi ma nau bun mbŭch ndơ nhhơr nây.$b$,false),
('bunong-vn','2CH',31,10,null,$b$Y-Asaria, n'gâng kan ƀư brah toyh, noi deh Y-Sadôk, plơ̆ lah ma păng: “Ntơm bơh nar phung ƀon lan ntơm leo ndơ nhhơr tâm ngih Yêhôva, hên geh sông sa tŏng jêh, jêh ri geh âk ndơ rmeh; yor lah Yêhôva hŏ ăn jêh nau ueh uĭn ma ƀon lan Păng; pô ri yơh hên geh âk ndơ aơ hôm e.”$b$,false),
('bunong-vn','2CH',31,11,null,$b$Y-Hêsêkia ntăm ma khân păng nkra an jrô tâm ngih Yêhôva; jêh ri khân păng nkra đŏng,$b$,true),
('bunong-vn','2CH',31,12,null,$b$jêh ri djôt nglăp sŏng srăng lĕ ndô ndơ, nhhơr du kô̆ jât, ndơ prăp êng ma Yêhôva. Kôranh mât chiă ndơ nây jêng Y-Kênania, phung Lêvi, ndrel ma Y-Simei oh păng jêng nơm groi kâp kơl:$b$,false),
('bunong-vn','2CH',31,13,null,$b$Dôl Y-Jêhiêl, Y-Asasia, Y-Nahat, Y-Asahel, Y-Jêrimôt, Y-Jôsabat, Y-Êliêl, Y-Ismachhia, Y-Mahat, jêh ri Y-Bênaya jêng phung kôranh chiă uănh kơl Y-Kênania jêh ri Y-Simei oh păng, tĭng nâm nau Hađăch Hêsêkia jêh ri Y-Asaria kôranh chiă uănh ngih Brah Ndu$b$,false),
('bunong-vn','2CH',31,14,null,$b$Y-Kôrê kon bu klâu Y-Imma du huê Lêvi, nơm chiă uănh mpông pêr pa lơ, jêng nơm mât ndơ nhhơr ma Brah Ndu ma nau ŭch, gay tâm pă ndơ bu nhhơr prăp jêh ma Yêhôva jêh ri ndơ nhhơr kloh ueh lơn.$b$,false),
('bunong-vn','2CH',31,15,null,$b$Y-Êđen, Y-Miniamin, Y-Jêsna, Y-Sêmaya, Y-Amaria, jêh ri Y-Sêkania ma nau răp jăp kơl Y-Kôrê tâm lĕ rngôch ƀon phung n'gâng kan ƀư brah, gay tâm pă tâm ban ndơ nây ma phung oh nau khân păng, mâu lah phung bu ranh nđâp phung mom tĭng nâm mpôl khân păng,$b$,false),
('bunong-vn','2CH',31,16,null,$b$phung bu mâu chih ôh amoh tâm ndrom sămƀŭt noi deh, ntơm pe năm rlet klơ, jêng đơ phung tĭng nâm mbŭch khân păng lăp ngih Yêhôva gay pah tĭng nâm kan khân păng, moh nar pah kan kơp tĭng nar nây.$b$,false),
('bunong-vn','2CH',31,17,null,$b$Tâm pă đŏng ăn ma phung n'gâng kan ƀư brah hŏ tĭng jêh ntil mpôl păng dơi chih amoh ndrel noi deh, jêh ri ăn phung Lêvi ntơm bar jât năm rlet klơ, tĭng nâm kan pah jêh ri mbŭch khân păng.$b$,false),
('bunong-vn','2CH',31,18,null,$b$Ăt tâm pă đŏng ăn ma lĕ rngôch kon jê̆ khân păng, ur khân păng, kon bu klâu jêh ri kon bu ur khân păng, nâm bu ntĭt lĕ rngôch phung tâm rƀŭn hŏ chih amoh jêh ndrel ma noi deh; yor lah khân păng gŭ răp jăp mât săk nơm jêng kloh ueh.$b$,false),
('bunong-vn','2CH',31,19,null,$b$Bi ma kon sau Y-Arôn, nâm bu ntĭt đơ phung n'gâng kan ƀư brah gŭ tâm neh mir; gŭ chah rai tâm âk rplay ƀon khân păng, geh nơm tâm ăp ƀon đơ phung geh amoh bu kuăl, gay tâm pă rnoh ăn ma lĕ rngôch phung bu klâu tâm phung n'gâng kan ƀư brah jêh ri ăn ma ăp nơm tâm phung Lêvi hŏ geh chih amoh săk ndrel ma noi deh.$b$,true),
('bunong-vn','2CH',31,20,null,$b$Pô nây, Y-Hêsêkia ƀư lam n'gor Yuđa. Păng ƀư nau ueh jêh ri di n'hêl nanê̆ ta năp Yêhôva Brah Ndu păng.$b$,true),
('bunong-vn','2CH',31,21,null,$b$Lĕ rngôch nau păng ndâk njêng tâm kan ngih Brah Ndu, mâu lah tâm nau vay nđâp ma nau ntăm gay tĭng joi Brah Ndu păng, păng ƀư ma lĕ rngôch nuih n'hâm, jêh ri păng dơi chăt jêng.$b$,false),
('bunong-vn','2CH',32,1,null,$b$Lôch kan aơ jêh ri nau răp jăp Y-Hêsêkia ƀư nây, geh Y-Sênakêrip hađăch Asiri văch tât lăp n'gor Yuđa, nchueng ŭch tâm lơh đah ƀon geh pôih ta han, ntôn lah sŏk ƀon nây ma păng nơm.$b$,true),
('bunong-vn','2CH',32,2,null,$b$Tơ lah Y-Hêsêkia saơ Y-Sênakêrip hŏ tât jêh, ŭch tâm lơh đah ƀon Yêrusalem,$b$,true),
('bunong-vn','2CH',32,3,null,$b$păng tâm chră đah phung kôranh jêh ri đah phung kôranh ta han janh ktang păng gay bât lơi tu dak ta mpâr ƀon; jêh ri khân ô băl kơl păng đŏng.$b$,false),
('bunong-vn','2CH',32,4,null,$b$Bunuyh ƀon lan văch rgum âk râk, bât nkrŭl lĕ rngôch dak n'hor jêh ri n'hong dak hoch tâm nklang n'gor bri, lah: “Mâm ƀư gay ăn hađăch Asiri tât, saơ geh dak âk?”$b$,false),
('bunong-vn','2CH',32,5,null,$b$Păng săch êng kan, ndâk đŏng mpêr ƀon hŏ mplŭng jêh, jêh ri ndâk ngih tŭm klơ păng, jêh nây ndâk đŏng mpêr êng mpeh pa dih; păng ƀư dŭt nâp Milô tâm ƀon Y-Đavit, jêh ri păng ƀư tâm ban lĕ âk ntil ndơ tâm lơh jêh ri khêl.$b$,false),
('bunong-vn','2CH',32,6,null,$b$Păng dơm phung kôranh ta han chiă uănh phung ƀon lan, jêh ri rgum khân ô băl gŭ êp ma păng ta ƀon toyh dăch mpông pêr, jêh ri ngơi n'hao nuih ma khân ô băl, jêh ri lah:$b$,false),
('bunong-vn','2CH',32,7,null,$b$“Ƀư ktang hom, nâp nuih n'hâm, lơi ta klach, lơi ta krit phơr ta năp măt hađăch Asiri, jêh ri mpôl phung ta han âk râk tĭng păng, yor lah geh du huê Nơm gŭ ndrel he dơi lơn đah nơm gŭ ndrel păng.$b$,false),
('bunong-vn','2CH',32,8,null,$b$Păng geh knŏng du đah ti nglay săk; bi ndrel he geh Yêhôva Brah Ndu phung he, gay kâp kơl, jêh ri sâm tâm lơh ăn ma he. Bunuyh ƀon lan nsing rnơm bơh nau Y-Hêsêkia, hađăch Yuđa ngơi.$b$,false),
('bunong-vn','2CH',32,9,null,$b$Jêh nau nây, Y-Sênakêrip, hađăch Asiri, ndrel ma lĕ rngôch phung ta han păng hôm nchueng ƀon Lakis, păng njuăl phung oh mon păng tât Y-Hêsêkia jêh ri phung Yuđa gŭ ta Yêrusalem, lah:$b$,true),
('bunong-vn','2CH',32,10,null,$b$“Y-Sênakêrip hađăch Asiri, lah pô aơ: Moh ntil khân may nsing rnơm, tât khân may tâm rdâng đah nau bu nchueng ŭch lơh ƀon Yêrusalem?$b$,false),
('bunong-vn','2CH',32,11,null,$b$Y-Hêsêkia lah: “Yêhôva Brah Ndu phung he mra rklaih he tă bơh ti hađăch Asiri nau nây hĕ di păng nsŭk khân may gay ăn vĭ, gay ma păng dơi jao khân may tâm nau khĭt ji ngot-ji hir, mâu lah mâu?”$b$,true),
('bunong-vn','2CH',32,12,null,$b$Mâu hĕ di Y-Hêsêkia aơ lĕ sŏk mƀăr lơi jêh ntŭk prêh jêh ri nơng Yêhôva jêh nây ntĭnh phung ƀon lan Yuđa jêh ri Yêrusalem pô aơ: “Khân may mbah yơk pa năp du mlâm nơng, jêh ri ta klơ nơng nây khân may mra su mpa khân may ƀư brah”?$b$,false),
('bunong-vn','2CH',32,13,null,$b$Khân may mâu hŏ gĭt hĕ nau gâp jêh ri chô yau gâp ƀư ma lĕ phung ƀon lan tâm bri êng? Brah phung ndŭl mpôl bri nây geh nau dơi rklaih bri dak khân păng tă bơh ti gâp lĕ?$b$,false),
('bunong-vn','2CH',32,14,null,$b$Mbu moh brah tâm lĕ rngôch brah phung ndŭl mpôl nây phung chô yau gâp hŏ ƀư rai lĕ jêh, mâu hôm geh brah êng đŏng ôh tâm rklaih ndŭl mpôl păng tă bơh ti gâp? Mâm nơih pơih geh du huê Brah. Khân may tâm rklaih khân may tă bơh ti gâp hia?$b$,false),
('bunong-vn','2CH',32,15,null,$b$Yor ri aƀaơ, lơi ăn Y-Hêsêkia ndơm mâu lah njŭn leo khân may tâm nau vĭ nâm bu pô nây, jêh ri lơi ta khân may iăt nau păng; yor lah mâu hôm geh brah êng ôh tâm lĕ rngôch ndŭl mpôl bunuyh, mâu lah ƀon bri hađăch dơi rklaih ƀon lan păng tă bơh ti gâp mâu lah bơh ti chô yau gâp. Ang ma Brah Ndu khân may lah dơi tâm rklaih khân may tă bơh ti gâp!$b$,false),
('bunong-vn','2CH',32,16,null,$b$Phung oh mon păng ăt hôm ngơi ndjơh đŏng đah Yêhôva jêng Brah Ndu ngăn, jêh ri tâm rdâng đah Y-Hêsêkia jêng oh mon Păng.$b$,true),
('bunong-vn','2CH',32,17,null,$b$Păng chih sămƀŭt mưch ma Yêhôva Brah Ndu Israel, jêh ri ngơi mhĭk tâm rdâng đah Păng, lah: “Nâm bu phung Brah Ndŭl mpôl bri êng, mâu hŏ dơi tâm rklaih ôh phung ƀon lan khân păng bơh ti gâp; tâm ban lĕ Brah Ndu Y-Hêsêkia mâu dơi tâm rklaih ôh phung ƀon lan păng bơh ti gâp.”$b$,false),
('bunong-vn','2CH',32,18,null,$b$Khân păng troh nter ma bâr ngơi huy ngăn tâm nau ngơi Yuđa ma phung ƀon lan Yêrusalem gŭ ta klơ mpêr ƀon toyh, ƀư rnam gay nhhu ăn bu klach, ŭch lơh pit ƀon toyh.$b$,true),
('bunong-vn','2CH',32,19,null,$b$Khân păng ngơi tât ma Brah Ndu ƀon Yêrusalem nâm bu khân păng ngơi di ma phung brah phung ƀon lan ta neh ntu, jêng kan ma ti bunuyh ƀư.$b$,false),
('bunong-vn','2CH',32,20,null,$b$Hađăch Hêsêkia, jêh ri kôranh nơm mbơh lor Y-Êsai, kon bu klâu Y-Amôt mbơh sơm yor nau nây jêh ri vơl nđor n'hôl tât trôk.$b$,true),
('bunong-vn','2CH',32,21,null,$b$Yêhôva prơh hăn du huê tông mpăr ueh ƀư nkhĭt lơi lĕ rngôch phung ta han janh ktang jêh ri phung kôranh ta han jêh ri phung kôranh êng tâm pôih ta han hađăch Asiri. Păng plơ̆ sĭt ma n'gor păng nơm, ma muh măt prêng. Tơ lah păng lăp tâm ngih brah păng, ƀa ƀă tâm phung kon bu klâu păng nơm sreh păng ma đao.$b$,false),
('bunong-vn','2CH',32,22,null,$b$Pô ri Yêhôva tâm rklaih Y-Hêsêkia jêh ri phung gŭ tâm ƀon Yêrusalem tă bơh ti Y-Sênakêrip, hađăch Asiri, jêh ri klaih bơh ti phung rlăng păng; jêh ri Yêhôva ăn ma khân păng rlu văr jŭm;$b$,true),
('bunong-vn','2CH',32,23,null,$b$Geh âk bunuyh djôt leo ndơ nhhơr ma Yêhôva ta Yêrusalem, jêh ri ndơ khlay ma Y-Hêsêkia, hađăch Yuđa; pô ri păng geh nau bu yơk ta năp măt lĕ rngôch mpôl băl bunuyh, ntơm bơh nôk nây tât ô klak.$b$,false),
('bunong-vn','2CH',32,24,null,$b$Tâm rnôk nây Y-Hêsêkia geh nau ji bơi khĭt, jêh ri păng mbơh sơm ma Yêhôva; jêh ri Yêhôva plơ̆ lah ma păng, jêh ri ăn ma păng nau tâm mbên.$b$,true),
('bunong-vn','2CH',32,25,null,$b$Ƀiă lah Y-Hêsêkia mâu ŭch mplơ̆ sĭt di ma Yêhôva tĭng nâm nau ueh Yêhôva ƀư jêh ma păng, yor lah nuih n'hâm păng sưr. Yor nây nau ji nuih Kôranh Brah tât ma păng nđâp ma phung Yuđa jêh ri Yêrusalem.$b$,false),
('bunong-vn','2CH',32,26,null,$b$Ƀiă lah Y-Hêsêkia ntrŭnh lơi nau sưr tâm nuih n'hâm păng, dêh rhêt păng nơm jêh ri phung gŭ tâm ƀon Yêrusalem tâm ban lĕ, pô ri nau Yêhôva ji nuih mâu tât ôh dôl rô̆ Y-Hêsêkia.$b$,false),
('bunong-vn','2CH',32,27,null,$b$Y-Hêsêkia geh nau ndrŏng jêh ri nau bu yơk toyh ngăn; păng ndâk ma păng nơm jrô prăp prăk, mah, lŭ khlay, dak si ƀâu kah, khêl, jêh ri ăp ntil khăl ngan khlay,$b$,true),
('bunong-vn','2CH',32,28,null,$b$păng ƀư tâm ban lĕ, jay tuh ba, jay ăn dak play kriăk ƀâu jêh ri dak play ôlivơ; jêh ri ndrung krŭng ăp ntil mpô mpa, phung biăp, jêh ri ndrôk.$b$,false),
('bunong-vn','2CH',32,29,null,$b$Păng ăt ndâk tâm ban lĕ âk play ƀon, geh âk phung biăp jêh ri ndrôk; yor lah Brah Ndu ăn ma păng geh dŭt âk drăp ndơ.$b$,false),
('bunong-vn','2CH',32,30,null,$b$Y-Hêsêkia aơ lĕ bât n'hor dak Gihôn, jêh ri n'hoch ô băl hoch mŭr tâm dâng neh mpeh pa dâng ƀon Y-Đavit. Tâm lĕ kan Y-Hêsêkia ƀư dơi chăt jêng ngăn.$b$,false),
('bunong-vn','2CH',32,31,null,$b$Ƀiă lah tơ lah bunuyh n'hut bơh bri Babilôn bu prơh hăn tât ma păng ŭch ôp suk nau mbên khlay hŏ geh tât jêh tâm n'gor păng, pô ri Brah Ndu ăn păng săch tĭng nâm păng nơm mĭn; ŭch rlong uănh păng, jêh ri ŭch gĭt lĕ rngôch ntil nau tâm nuih n'hâm păng.$b$,false),
('bunong-vn','2CH',32,32,null,$b$Lĕ kan êng Y-Hêsêkia ƀư, jêh ri lĕ kan ueh păng ƀư, bu chih da dê jêh tâm ndrom sămƀŭt kôranh nơm lor Y-Êsai, kon bu klâu Y-Amôt, jêh ri tâm ndrom sămƀŭt Phung Hađăch Yuđa jêh ri Israel.$b$,true),
('bunong-vn','2CH',32,33,null,$b$Jêh ri Y-Hêsêkia khĭt hăn gŭ ndrel phung che păng, jêh ri bu tâp păng tâm môch prêh klơ ma kon sau Y-Đavit; lĕ rngôch phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem yơk ma păng da dê, dôl nar păng khĭt; Y-Manasê, kon bu klâu păng, chiă uănh thoi păng.$b$,false),
('bunong-vn','2CH',33,1,null,$b$Y-Manasê geh jât ma bar năm tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh prăm jât ma prăm năm ta ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',33,2,null,$b$Păng ƀư nau djơh ta năp măt Yêhôva, tĭng nau djơh Brah Ndu tâm rmot nau phung ndŭl mpôl Brah Ndu hŏ mprơh du jêh tă bơh tâm phung Israel.$b$,false),
('bunong-vn','2CH',33,3,null,$b$Păng ndâk tay đŏng lĕ ntŭk prêh klơ Y-Hêsêkia mbơ̆ păng, hŏ ƀư rlâm lơi, jêh ri păng ndâk tay nơng ma brah Baal, jêh ri ƀư rup brah Asêra, jêh ri mbah yơk ma lĕ rngôch ntil brah tâm trôk, jêh ri pah kan ma phung nây.$b$,true),
('bunong-vn','2CH',33,4,null,$b$Păng ndâk âk ngăn nơng tâm ngih Yêhôva, ngih nây Yêhôva hŏ lah: “Amoh Gâp mra gŭ tâm ƀon Yêrusalem n'ho ro.”$b$,false),
('bunong-vn','2CH',33,5,null,$b$Păng ăt ndâk tâm ban lĕ nơng ăn ma lĕ rngôch ntil brah tâm trôk, tâm ntŭk bar đah ndring nhuang ngih Yêhôva,$b$,false),
('bunong-vn','2CH',33,6,null,$b$jêh ri păng gŭch kon păng tâm ŭnh, ta rlŭng kon bu klâu Y-Hinôm, njêng mpa nhhơr; păng chrâng pol, ŭch gĭt lor, dŏng nau vay, ƀư kan n'hŭm, jêh ri bêch gru tâm ngơi đah bunuyh khĭt jêh ri phung gru rƀên. Păng ƀư âk nau djơh ta năp măt Yêhôva nsônh nau ji nuih ô băl.$b$,false),
('bunong-vn','2CH',33,7,null,$b$Păng dơm rup brah păng trah tâm ngih Brah Ndu, ma ngih nây yơh Brah Ndu lah jêh ma Y-Đavit jêh ri ma Y-Salômôn kon bu klâu păng, pô aơ: “Tâm ngih brah aơ jêh ri ta ƀon Yêrusalem, ƀon Gâp hŏ săch jêh tâm lĕ rngôch ndŭl mpôl phung Israel, Gâp mra dơm Amoh Gâp gŭ n'ho ro;$b$,false),
('bunong-vn','2CH',33,8,null,$b$tơ lah phung Israel mât mray ƀư tĭng lĕ rngôch nau vay, nau ntăm, jêh ri nau ntrŭnh, Gâp ăn jêh ma Y-Môis ntĭm nti ma khân păng, pô ri Gâp mâu mra rhuăt ôh jâng khân păng luh du tă bơh neh Gâp hŏ ăn jêh ma phung chô yau khân păng.”$b$,false),
('bunong-vn','2CH',33,9,null,$b$Y-Manasê ndơm phung Yuđa jêh ri phung gŭ tâm ƀon Yêrusalem, ŭch ăn ma khân păng ƀư nau mhĭk âk lơn ma phung ndŭl mpôl Yêhôva hŏ ƀư rai jêh ta năp phung ƀon lan Israel.$b$,true),
('bunong-vn','2CH',33,10,null,$b$Yêhôva ngơi lah ma Y-Manasê jêh ri phung ƀon lan păng, ƀiă lah khân păng mâu chrê ôh.$b$,true),
('bunong-vn','2CH',33,11,null,$b$Yor nây Yêhôva ntrŭt phung kôranh ta han hađăch Asiri tât lơh khân păng; phung nây nhŭp nkông Y-Manasê, jêh ri nkông păng ma rse rvăk kông jêh ri njŭn leo păng ma ƀon Babilôn.$b$,false),
('bunong-vn','2CH',33,12,null,$b$Tơ lah păng gŭ tâm nau rêh ni păng vơl ma nau Yêhôva Brah Ndu păng yô̆ an, jêh ri n'hôi săk păng nơm dêh rhêt ngăn ngên ta năp Yêhôva phung che păng.$b$,false),
('bunong-vn','2CH',33,13,null,$b$Y-Manasê mbơh sơm ma Brah Ndu; jêh ri Brah Ndu sŏk dơn nau păng vơl, jêh ri iăt lĕ nau păng dăn, njŭn păng sĭt rlet ma ƀon Yêrusalem tâm bri hađăch păng; nôk nây mơ Y-Manasê gĭt năl ma Yêhôva jêng Brah Ndu.$b$,true),
('bunong-vn','2CH',33,14,null,$b$Jêh nau nây, păng ƀư mpêr pa dih ƀon Y-Đavit, mpeh pa dâng Gihôn tâm rlŭng tât ma ntŭk lăp Mpông Pêr Ka, jêh ri văr jŭm n'ho tât Ôphel, jêh ri bu ƀư mpêr nây prêh ngăn; jêh nây păng dơm phung kôranh ta han tâm ăp ƀon geh pôih ta han tâm n'gor Yuđa.$b$,true),
('bunong-vn','2CH',33,15,null,$b$Păng ngluh lơi pa dih ngih Yêhôva lĕ rngôch brah bri bu năch, rup brah, jêh ri nơng ƀư brah păng hŏ ƀư jêh ta klơ yôk ngih Yêhôva jêh ri ta ƀon Yêrusalem, jêh ri klŭp mƀăr ndơ nây pa dih ƀon.$b$,false),
('bunong-vn','2CH',33,16,null,$b$Pô nây, păng nkra tay nơng ƀư brah ma Yêhôva, păng nhhơr ta nây mpa ƀư brah đăp mpăn, jêh ri nau tâm rnê; jêh ri păng ntĭnh ma phung Yuđa pah kan ma Yêhôva Brah Ndu$b$,false),
('bunong-vn','2CH',33,17,null,$b$Nđâp lah pô nây, phung ƀon lan ăt hôm e ƀư brah tâm ntŭk prêh ta klơ, ƀiă lah knŏng ƀư brah ăn Yêhôva Brah Ndu khân păng dơm.$b$,false),
('bunong-vn','2CH',33,18,null,$b$Kan êng Y-Manasê ƀư, nau păng mbơh sơm ma Brah Ndu păng, jêh ri nau phung tâm saơ ngơi jêh ma păng tâm amoh Yêhôva Brah Ndu Israel, aơ bu chih jêh tâm ndrom sămƀŭt Phung Hađăch Israel.$b$,true),
('bunong-vn','2CH',33,19,null,$b$Nau păng mbơh sơm, jêh ri nau Brah Ndu dơn nau păng vơl, nau păng ƀư tih, jêh ri lĕ nau păng mâu gŭ răp jăp ôh, ntŭk prêh ta klơ păng ndâk, ndâk ăn brah Asêrim jêh ri rup brah trah, lor ma păng ê hŏ dêh rhêt êng păng nơm, aơ bu chih jêh tâm ndrom sămƀŭt Nau Nkoch Bri ma Phung Tâm saơ.$b$,true),
('bunong-vn','2CH',33,20,null,$b$Pô ri, Y-Manasê khĭt hăn gŭ ndrel ma phung che păng, jêh ri bu tâp păng tâm nhuang vâl păng; jêh ri Y-Amôn, kon bu klâu păng chiă uănh thoi păng.$b$,true),
('bunong-vn','2CH',33,21,null,$b$Y-Amôn geh bar jât ma bar năm, tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh bar năm tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',33,22,null,$b$Păng ƀư nau mhĭk ta năp măt Yêhôva, nâm bu Y-Manasê, mbơ̆ păng hŏ ƀư jêh. Y-Amôn ƀư brah ma lĕ rngôch rup trah Y-Manasê, mbơ̆ păng, ƀư jêh, jêh ri pah kan ma rup brah nây.$b$,false),
('bunong-vn','2CH',33,23,null,$b$Păng mâu ŭch dêh rhêt ôh păng nơm ta năp măt Yêhôva nâm bu Y-Manasê, mbơ̆ păng, hŏ ƀư jêh; ƀiă lah păng ƀư tih lơ hâu lơn.$b$,false),
('bunong-vn','2CH',33,24,null,$b$Phung oh mon păng, joi nau, ƀư ma păng jêh ri ƀư nkhĭt păng tâm ngih păng nơm.$b$,false),
('bunong-vn','2CH',33,25,null,$b$Bi phung ƀon lan tâm n'gor nây nkhĭt lĕ phung joi nau nkhĭt hađăch Amôn; jêh ri njêng Y-Jôsia kon bu klâu păng jêng hađăch thoi păng.$b$,false),
('bunong-vn','2CH',34,1,null,$b$Y-Jôsia geh pham năm, tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh pe jât ma nguay năm ta ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',34,2,null,$b$Păng ƀư nau ueh ta năp măt Yêhôva, jêh ri chuat tĭng trong Y-Đavit, che păng, jêh ri mâu teng pa ma mâu lah pa chiau ôh.$b$,false),
('bunong-vn','2CH',34,3,null,$b$Năm rơh pham rô̆ păng chiă uănh, tơ lah păng dôl jêng du huê kon se, pô ri păng ntơm joi Brah Ndu Y-Đavit, che păng; jêh ri năm rơh jât ma bar, păng ntơm ƀư kloh n'gor Yuđa jêh ri ƀon Yêrusalem mƀăr lơi ntŭk prêh ta klơ, brah Asêrim, rup nsêr, rup tŏ chiăr.$b$,true),
('bunong-vn','2CH',34,4,null,$b$Bu ƀư rlâm lơi lĕ rngôch nơng brah Baal ta năp păng; jêh ri kăl lơi nơng su ndơ ƀâu kah gŭ ta klơ nơng brah Baal nây; jêh ri ƀư chah hăch rhên rup brah Asêrim, rup nsêr, jêh ri rup bu tŏ chiăr; păng ƀư tât môi rup nây, jêh ri suy ndruyh ta klơ môch phung ƀư brah ma rup nây.$b$,false),
('bunong-vn','2CH',34,5,null,$b$Tâm ban lĕ păng su nting phung kôranh ƀư brah ta klơ nơng phung brah nây, jêh ri ƀư kloh n'gor Yuđa jêh ri ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',34,6,null,$b$Tâm ăp ƀon Manasê, ƀon Êphraim, jêh ri ƀon Simêôn, jêh ri tât ta nkual Naptali, tât lam văr jŭm ntŭk lĕ rai jêh,$b$,true),
('bunong-vn','2CH',34,7,null,$b$păng ƀư rlâm lĕ nơng, jêh ri juh se tât môi lĕ rngôch rup brah Asêrim, rup nsêr, jêh ri rup tŏ chiăr, kăl nchôt meh gâng bu mbah ma măt nar tâm lam bri Israel; jêh ri păng plơ̆ sĭt ma ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',34,8,null,$b$Năm rơh jât ma pham rô̆ păng chiă uănh, tơ lah păng hŏ ƀư kloh jêh bri dak, jêh ri ngih brah, păng prơh hăn Y-Saphan, kon bu klâu Y-Asalia jêh ri Y-Maseya, kôranh ƀon toyh, jêh ri Y-Jôa, kon bu klâu Y-Jôahas, nơm kâp chih lĕ nau tât, ăn khân ô băl nkra ngih brah Yêhôva Brah Ndu păng.$b$,true),
('bunong-vn','2CH',34,9,null,$b$Phung nây hăn tât ma Y-Hilkia, kôranh ƀư brah toyh, jêh ri jao prăk bu nhhơr jêh ma ngih Brah Ndu, jêng prăk phung Lêvi, phung mât mpông, prăp mkrem tă bơh ti phung Manasê, phung Êphraim, jêh ri tă bơh lĕ rngôch phung Israel hôm klen, bơh lĕ rngôch phung Yuđa, phung Benjamin, jêh ri bơh phung gŭ tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',34,10,null,$b$Khân păng jao prăk nây ma phung pah kan chiă uănh ngih Yêhôva; khân păng pă ăn lĕ rngôch phung nkra tay mhe, nkra ngih brah;$b$,false),
('bunong-vn','2CH',34,11,null,$b$Khân păng jao prăk nây ma phung chap meh, phung ndâk ngih gay rvăt lŭ ơm bu châm, jêh ri tơm si prăp ƀư ryong rda ngih, ngih brah nây hađăch phung Yuđa lĕ cha lơi ôm rai jêh.$b$,false),
('bunong-vn','2CH',34,12,null,$b$Lĕ phung pah kan nây răp jăp da dê. Bu dơm bunuyh chiă uănh phung pah kan geh Y-Jahat jêh ri Y-Ôbadia jêng phung Lêvi bơh phung noi deh Y-Mêrari, Y-Sakari, jêh ri Y-Mêsulam jêng noi deh Y-Kôhat nđâp ma phung Lêvi êng, blau ăp ntil ndơ kreh mpât mprơ.$b$,true),
('bunong-vn','2CH',34,13,null,$b$Khân păng chiă uănh phung tung mbăk, jêh ri chiă uănh đơ phung pah kan ăp ntil; jêh ri ƀa ƀă phung Lêvi jêng phung chih sămƀŭt, phung kôranh jêh ri phung chiă uănh mpông pêr.$b$,false),
('bunong-vn','2CH',34,14,null,$b$Tơ lah bu njŭn prăk nhhơr hŏ nglăp jêh tâm ngih brah Yêhôva jêh ri luh; Y-Hilkia; kôranh ƀư brah, dơi joi saơ ndrom sămƀŭt nau vay Yêhôva yor tă bơh Y-Môis ăn jêh.$b$,true),
('bunong-vn','2CH',34,15,null,$b$Y-Hilkia lah ma Y-Saphan kôranh chih sămƀŭt: “Gâp saơ jêh ndrom sămƀŭt nau vay tâm ngih Yêhôva.” Jêh ri Y-Hilkia ăn ndrom sămƀŭt nây ma Y-Saphan.$b$,true),
('bunong-vn','2CH',34,16,null,$b$Y-Saphan djôt leo ndrom sămƀŭt nây ăn ma hađăch, jêh ri mbơh ma hađăch tâm ban lĕ: “Lĕ rngôch kan bu jao jêh ma phung oh mon may, khân păng dôl ƀư.$b$,true),
('bunong-vn','2CH',34,17,null,$b$Khân păng hŏ sŏk jêh prăk saơ tâm ngih brah Yêhôva, jêh ri leo jao prăk nây ta ti phung chiă uănh jêh phung pah kan.$b$,false),
('bunong-vn','2CH',34,18,null,$b$Kôranh chih sămƀŭt Y-Saphan mbơh ma hađăch: “Y-Hilka, kôranh ƀư brah geh ăn ma gâp du ndrom sămƀŭt. Y-Saphan rŏ uănh sămƀŭt nây ta năp hađăch.$b$,false),
('bunong-vn','2CH',34,19,null,$b$Tơ lah hađăch tăng jêh nau ngơi tâm ndrom sămƀŭt nau vay nây, păng nkhêk bok ao păng.$b$,true),
('bunong-vn','2CH',34,20,null,$b$Hađăch ntĭnh ma Y-Hilkia, Y-Ahikam, kon bu klâu Y-Saphan, Y-Apđôn kon bu klâu Y-Mika Y-Saphan, kôranh chih sămƀŭt, jêh ri Y-Asaya oh mon hađăch, lah:$b$,false),
('bunong-vn','2CH',34,21,null,$b$“Hăn ôp hom ma Yêhôva yor gâp, yor phung Israel, jêh ri yor phung Yuđa hôm e klen, ma lĕ rngôch nau ngơi tâm ndrom sămƀŭt aơ hŏ joi saơ jêh; yor lah nau Yêhôva ji nuih nkhŭt jêh ta klơ he dŭt toyh ngăn, yor tă bơh phung che he mâu ŭch djôt prăp ôh nau Yêhôva ntăm, jêh ri mâu tĭng kơt lĕ ntil nau hŏ chih jêh tâm ndrom sămƀŭt aơ.”$b$,false),
('bunong-vn','2CH',34,22,null,$b$Pô ri, Y-Hilkia jêh ri lĕ phung hađăch prơh hăn tât ma H'Hulda, kôranh nơm mbơh lor, bu ur jêng ur Y-Salum, kon bu klâu Y-Tôkhat, sau Y-Hasra; nơm chiă mât jrô prăp bok ao, (bu ur nây gŭ ta ƀon Yêrusalem nkual mrô bar); jêh ri khân păng ngơi đah bu ur nây tĭng nâm nau hađăch hŏ lah jêh.$b$,true),
('bunong-vn','2CH',34,23,null,$b$Bu ur nây lah ma khân păng: “Pô aơ nau Yêhôva Brah Ndu Israel, lah: ‘Mbơh hom ma nơm hŏ prơh jêh khân may văch tât ma gâp.$b$,false),
('bunong-vn','2CH',34,24,null,$b$Yêhôva lah pô aơ: “Gâp mra ăn nau mhĭk tât ntŭk aơ, jêh ri ma phung ƀon lan gŭ ta ntŭk aơ, lĕ rngôch nau bu rtăp rak hŏ chih jêh tâm ndrom sămƀŭt bu hŏ răk uănh jêh ta năp măt hađăch Yuđa.$b$,false),
('bunong-vn','2CH',34,25,null,$b$Yor lah khân păng cha lơi jêh Gâp, su ndơ ƀâu kah ăn ma brah êng, sŏk lĕ rngôch ntil kan ma ti khân păng ƀư gay nsônh nau Gâp ji nuih; yor ri yơh nau ji nuih Gâp mra nkhŭt ta ntŭk aơ, mâu dơi rhân ôh. (Mâu bah ji nuih)$b$,true),
('bunong-vn','2CH',34,26,null,$b$Bi ma hađăch Yuđa hŏ prơh jêh khân may hăn tât ôp ma Yêhôva, ăn khân may mbơh ma păng pô nây: Bi ma nau ngơi may hŏ tăng jêh, Yêhôva Brah Ndu$b$,false),
('bunong-vn','2CH',34,27,null,$b$Tơ lah may tăng jêh nau Gâp ngơi tâm rdâng đah ntŭk aơ, jêh ri tâm rdâng đah phung ƀon lan gŭ tâm ntŭk aơ, pô ri ăn may geh nuih n'hâm rdơ̆ rbăn, n'hôi săk nơm dêh rhêt ta năp Gâp, nkhêk bok ao may, jêh ri nhhiăng nhĭm ta năp Gâp; Gâp ăt tâm ban lĕ iăt jêh nau may. Yêhôva lah.$b$,false),
('bunong-vn','2CH',34,28,null,$b$Aơ, Gâp mra ăn may khĭt hăn gŭ ndrel phung che may, jêh ri bu mra tâp may tâm môch ma nau đăp mpăn, jêh ri măt may mâu mra saơ ôh lĕ rngôch nau mhĭk Gâp mra ăn tât ta ntŭk aơ jêh ri ma phung gŭ tâm ntŭk aơ.’ ” Jêh ri khân păng plơ̆ leo nau mbơh nây ma hađăch.$b$,true),
('bunong-vn','2CH',34,29,null,$b$Hađăch prơh bu hăn tâm rƀŭn lĕ rngôch phung bu bŭnh bu ranh n'gor Yuđa jêh ri ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',34,30,null,$b$Pô nây, hađăch hăn hao ngih Yêhôva, ndrel ma lĕ rngôch phung Yuđa, jêh ri lĕ rngôch phung gŭ ta ƀon Yêrusalem, phung kôranh ƀư brah, phung Lêvi, jêh ri lĕ rngôch phung ƀon lan nđâp toyh, nđâp jê̆, tĭng păng da dê; păng răk uănh ăn khân păng tăng lĕ rngôch nau ngơi tâm Ndrom Sămƀŭt Nau Tâm Rnglăp bu saơ jêh tâm ngih Yêhôva.$b$,false),
('bunong-vn','2CH',34,31,null,$b$Hađăch gŭ dâk tâm ntŭk păng, jêh ri ƀư nau tâm rnglăp ta năp Yêhôva, ton chuat tĭng Yêhôva lĕ rngôch nuih n'hâm, lĕ nau mĭn djôt prăp lĕ nau Păng ntăm, nau Păng mbơh, jêh ri nau vay Păng, gay ƀư rah vah ma nau ngơi tâm rnglăp hŏ chih jêh tâm ndrom sămƀŭt aơ.$b$,false),
('bunong-vn','2CH',34,32,null,$b$Păng ăt ntĭnh phung gŭ ta ƀon Yêrusalem jêh ri Benjamin gŭ ngao dơn nau tâm rnglăp nây. Pô ri, phung ƀon lan gŭ ta ƀon Yêrusalem ƀư tĭng nâm nau tâm rnglăp bơh Brah Ndu, jêng Brah Ndu phung che khân păng.$b$,false),
('bunong-vn','2CH',34,33,null,$b$Y-Jôsia sŏk mƀăr lĕ rngôch ndơ Yêhôva tâm rmot tă bơh bri neh phung ƀon lan Israel, jêh ri ăn lĕ rngôch phung gŭ tâm bri Israel pah kan ma Yêhôva Brah Ndu khân păng. Du bông rô̆ Y-Jôsia gŭ rêh, khân păng mâu nkhah du ôh nau tĭng ndô̆ Yêhôva Brah Ndu phung che khân păng.$b$,false),
('bunong-vn','2CH',35,1,null,$b$Y-Jôsia kah gĭt yơk Nau Găn ma Yêhôva ta ƀon Yêrusalem; jêh ri khân păng sreh nkhĭt kon biăp Nau Găn ta nar năng jât ma puăn tâm khay rơh nguay.$b$,true),
('bunong-vn','2CH',35,2,null,$b$Păng dơm phung kôranh ƀư brah dơn ma kan khân păng nơm, jêh ri ntrôl khân păng tâm kan ngih Yêhôva.$b$,false),
('bunong-vn','2CH',35,3,null,$b$Păng lah ma phung Lêvi ăt nti ma lĕ rngôch phung Israel, jêh ri phung hŏ prăp êng jêh ma Yêhôva: “Sŏk dơm hom hip kloh ăn tâm ngih brah Y-Salômôn kon bu klâu Y-Đavit, hađăch Israel, hŏ ndâk jêh; phung khân may mâu hôm khăch tung ôh hip nây klơ săng nglik khân may. Aƀaơ ri, pah kan hom ma Yêhôva Brah Ndu khân may jêh ri kơl kan ăn phung Israel jêng phung ƀon lan Păng.$b$,false),
('bunong-vn','2CH',35,4,null,$b$Nkra hom khân may nơm tĭng nâm noi deh jêh ri tĭng nâm mpôl khân may, rơm ndrăp ơm, tĭng kơt nau vay Y-Đavit, hađăch Israel, jêh ri Y-Salômôn, kon bu klâu păng hŏ ntăm jêh.$b$,false),
('bunong-vn','2CH',35,5,null,$b$Pô ri dâk hom tâm ntŭk kloh ueh, tĭng tâm groi mpôl noi deh oh mâu khân may, jêng ƀon lan Israel, jêh ri tĭng tâm groi noi deh phung Lêvi.$b$,false),
('bunong-vn','2CH',35,6,null,$b$Phung khân may sreh nkhĭt hom kon biăp Nau Găn, ƀư kloh hom khân may nơm, jêh ri nkra Nau Găn ăn ma phung oh nâu khân may, gay ƀư ăn di nâm bu nau Yêhôva ngơi ma bâr mbung Y-Môis.”$b$,false),
('bunong-vn','2CH',35,7,null,$b$Y-Jôsia ăn ma bunuyh ƀon lan phung mpô mpa jê̆, rnoh geh pe rmưn kon biăp, jêh ri kon be, nđâp pe rbăn mlâm ndrôk nkuăng, dŏng lôch nar Nau Găn ăn ma phung geh măt râng ta nây; lĕ rngôch mpô mpa nây jêng ndơ hađăch.$b$,true),
('bunong-vn','2CH',35,8,null,$b$Lĕ phung kôranh ăt tâm ban lĕ du ai ăn mpô mpa ma phung ƀon lan, kơl ma phung kôranh ƀư brah jêh ri phung Lêvi. Y-Hilkia, Y-Sakari, jêh ri Y-Jêiêl, jêng phung kôranh ngih brah Brah Ndu, kơl ăn phung kôranh ƀư brah, bar rbăn prao rhiăng mlâm biăp, jêh ri pe rhiăng mlâm ndrôk gay dŏng tâm Nau Găn.$b$,false),
('bunong-vn','2CH',35,9,null,$b$Tâm ban lĕ Y-Kênania, Y-Sêmaya, Y-Nêthanel, jêh ri phung oh păng, jêh ri Y-Hahabia, Y-Jêiêl, jêh ri Y-Jôsaphat phung kôranh ma phung Lêvi ăn ma phung Lêvi ndơ nhhơr prăp ma nau Găn prăm rbăn mlâm biăp kon jêh ri be kon, jêh ri prăm rhiăng mlâm ndrôk nkuăng.$b$,false),
('bunong-vn','2CH',35,10,null,$b$Pô ri, nau ƀư brah hŏ ndrăp jêh, phung kôranh ƀư brah gŭ dâk ta ntŭk khân păng nơm, jêh ri phung Lêvi tĭng mpôl khân păng iăt nâm bu nau hađăch ntăm.$b$,true),
('bunong-vn','2CH',35,11,null,$b$Phung Lêvi sreh nkhĭt kon biăp Nau Găn, jêh ri phung kôranh ƀư brah sŏk dơn mham tă bơh ti khân păng djôt nsrih mham nây; bi phung Lêvi doih n'huk ntâu mpa ƀư brah nây.$b$,false),
('bunong-vn','2CH',35,12,null,$b$Khân păng dơm ăn êng mpa nhhơr gŭch, gay tâm pă ma bunuyh ƀon lan, tâm groi tĭng mpôl noi deh khân păng, gay nhhơr ma Yêhôva, tĭng nâm nau bu chih jêh tâm ndrom sămƀŭt Y-Môis; khân păng ƀư tâm ban pô nây lĕ ma ndrôk nkuăng.$b$,false),
('bunong-vn','2CH',35,13,null,$b$Khân păng pâr (kreng) kon biăp Nau Găn tâm ŭnh tĭng nâm nau ntĭnh; jêh ri khân păng gâm mpa nhhơr kloh ueh tâm glah, glah ƀŭng, jêh ri tâm glah ƀai, jêh nây leo gơnh ndơ nây tâm pă ăn ma phung ƀon lan.$b$,true),
('bunong-vn','2CH',35,14,null,$b$Jêh nau nây, khân păng ndrăp nkra ma khân păng nơm jêh ri ma phung kôranh ƀư brah; yor lah lĕ rngôch phung kôranh ƀư brah, jêng kon sau Y-Arôn, gŭ pah kan nhhơr mpa nhhơr gŭch jêh ri rchuăl ngi kŏ tât măng; yor nây, phung Lêvi ndrăp nkra ma khân păng nơm jêh ri phung kôranh ƀư brah, jêng kon sau Y-Arôn.$b$,true),
('bunong-vn','2CH',35,15,null,$b$Phung mprơ, jêng kon sau Y-Asap, gŭ ta ntŭk khân păng nơm da dê, tĭng nâm nau vay Y-Đavit, Y-Asap, Y-Hêman, jêh ri Y-Yêduthun nơm tâm saơ ma hađăch, hŏ ntăm; jêh ri phung chiă mpông pêr gŭ ta ăp mpông, mâu khăch trơn du ôh bơh kan khân păng, yor lah oh nâu khân păng, jêng phung Lêvi, ndrăp nkra ndơ dŏng ăn khân păng.$b$,false),
('bunong-vn','2CH',35,16,null,$b$Pô ri lĕ rngôch kan yơk mbah Yêhôva bu hŏ nkra jêh nar nây, gay kah gĭt yơk ma Nau Găn, jêh ri gai nhhơr mpa nhhơr gŭch ta klơ nơng Yêhôva, tĭng nâm nau Hađăch Jôsia ntăm.$b$,true),
('bunong-vn','2CH',35,17,null,$b$Phung ƀon lan Israel tât ta nây, kah gĭt yơk ma Nau Găn da dê tâm nôk nây, jêh ri sa piăng let mâu geh ndrui tâm pơh nar.$b$,false),
('bunong-vn','2CH',35,18,null,$b$Ntơm bơh rô̆ kôranh nơm mbơh lor Y-Samuel, tâm bri Israel, mâu mâp geh ôh Nau Găn tâm ban pô nây, ăt mâu geh lĕ du huê hađăch Israel mâp kah gĭt yơk ma Nau Găn nâm bu Y-Jôsia, ndrel phung kôranh ƀư brah, phung Lêvi, lĕ rngôch phung Yuđa, jêh ri phung Israel geh măt râng ta nây, jêh ri phung ƀon lan gŭ ta ƀon Yêrusalem, văch râng.$b$,false),
('bunong-vn','2CH',35,19,null,$b$Bu kah gĭt yơk ma Nau Găn aơ tâm năm rơh jât ma pham rnôk rô̆ Y-Jôsia chiă uănh.$b$,false),
('bunong-vn','2CH',35,20,null,$b$Jêh nau kan nây, tơ lah Y-Jôsia nkra jêh ngih brah. Geh Y-Nêkô hađăch Êjipt hăn hao ŭch tâm lơh ta ƀon Karkêmis ta dak krong Ơphrat, jêh ri Y-Jôsia du luh hăn tâm lơh đah păng.$b$,true),
('bunong-vn','2CH',35,21,null,$b$Ƀiă lah hađăch Êjipt prơh hăn phung ntuh bâr ma Y-Jôsia, lah: “Ơ hađăch Yuđa, moh nau geh ndrăng he? Nar aơ gâp mâu văch tâm lơh đah may ôh, ƀiă lah tâm lơh đah phung rlăng ma ngih neh gâp; jêh ri Brah Ndu ntĭnh jêh ma gâp ăn ƀư gơnh. Pô ri, rlu hom, lơi tâm rdâng đah Brah Ndu ôh, Nơm gŭ ndrel gâp, klach lah Păng ƀư rai may.$b$,false),
('bunong-vn','2CH',35,22,null,$b$Ƀiă lah Y-Jôsia mâu ŭch rŭch plơ̆ ôh bơh hađăch Êjipt. Păng mâu ŭch iăt ôh nau Y-Nêkô ngơi bơh bâr mbung Brah Ndu, ƀiă lah lơ hâu nsoh nkrơ̆ ƀư bu êng ŭch tâm lơh đah ô băl, tâm rlŭng Mêgidô.$b$,false),
('bunong-vn','2CH',35,23,null,$b$Phung pănh na pănh hađăch Jôsia, jêh ri hađăch lah ma phung oh mon păng: “Chông leo hom gâp ma ntŭk êng, yor lah gâp rmanh jru ngăn.”$b$,false),
('bunong-vn','2CH',35,24,null,$b$Pô ri phung oh mon păng chông păng bơh ndeh seh păng jêh ri rdeng păng tâm ndeh rơh bar păng ơm geh jêh, jêh ri njŭn păng leo sĭt ma ƀon Yêrusalem. Păng khĭt, bu tâp păng tâm môch ndrel phung che păng. Lĕ rngôch phung Yuđa phung gŭ tâm ƀon Yêrusalem nhĭm ndrê ma Y-Jôsia.$b$,true),
('bunong-vn','2CH',35,25,null,$b$Tâm ban lĕ Y-Yêrêmi nhĭm vơl ma Y-Jôsia; jêh ri lĕ rngôch phung bu klâu bu ur mprơ nhĭm khĭt ma Y-Jôsia tât ma nar aơ. Khân păng ăn nau nhĭm vơl aơ jêng nau vay tâm bri Israel; aơ bu chih jêh tâm Ndrom Sămƀŭt Nhĭm Vơl.$b$,false),
('bunong-vn','2CH',35,26,null,$b$Kan êng Y-Jôsia ƀư, jêh ri kan ueh păng ƀư tĭng nâm nau bu chih jêh tâm nau vay$b$,false),
('bunong-vn','2CH',35,27,null,$b$kan păng ntơm bơh sa ơm tât nglĕ dŭt, aơ bu chih jêh tâm ndrom sămƀŭt Phung Hađăch Israel jêh ri Yuđa.$b$,false),
('bunong-vn','2CH',36,1,null,$b$Phung ƀon kan tâm bri aơ njêng Y-Jêhôahas, kon bu klâu Y-Jôsia, ƀư hađăch ntrok mbơ̆ păng ta ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',36,2,null,$b$Y-Jêhôahas geh bar jât ma pe năm, păng ntơm ƀư hađăch, jêh ri chiă uănh pe khay ta ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',36,3,null,$b$Hađăch Êjipt n'glưh păng tâm ƀon Yêrusalem, jêh ri ăn bri păng chê̆ pi du rhiăng ta lâng prăk jêh ri du talâng mah.$b$,true),
('bunong-vn','2CH',36,4,null,$b$Hađăch Êjipt ăn Y-Êliakim oh păng jêng hađăch chiă uănh n'gor Yuđa jêh ri ƀon Yêrusalem, jêh ri trơn amoh săk păng jêng Y-Jêhôjakim; ƀiă lah Y-Nêkô djôt leo nâu păng Y-Jêhôahas rlet ma n'gor bri Êjipt.$b$,true),
('bunong-vn','2CH',36,5,null,$b$Y-Jêhôjakim geh bar jât ma prăm năm, tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh jât ma nguay năm tâm ƀon Yêrusalem. Păng ƀư nau mhĭk ta năp măt Yêhôva Brah Ndu păng.$b$,true),
('bunong-vn','2CH',36,6,null,$b$Y-Nêbukatnetsar, hađăch Babilôn, văch tâm lơh đah păng, bu kât păng ma rse rvăk, jêh ri têk leo păng ma ƀon Babilôn.$b$,false),
('bunong-vn','2CH',36,7,null,$b$Y-Nêbukatnetsar sŏk tâm ban lĕ ƀa ƀă khăl ngăn bơh ngih Yêhôva djôt leo ma ƀon Babilôn jêh ri dơm ndơ nây tâm ngih hađăch păng ta ƀon Babilôn.$b$,false),
('bunong-vn','2CH',36,8,null,$b$Lĕ kan êng Y-Jêhôjakim ƀư, jêh ri nau mhĭk Yêhôva tâm rmot ma păng hŏ ƀư jêh, jêh ri bu dơi saơ tâm nuih n'hâm păng; aơ bu chih jêh tâm ndrom sămƀŭt Phung Hađăch Israel jêh ri phung Yuđa; jêh nây Y-Jêhôjachhin kon bu klâu păng chiă uănh thoi păng.$b$,true),
('bunong-vn','2CH',36,9,null,$b$Y-Jêhôjachhin geh jât ma pham năm, tơ lah păng ntơm chiă uănh, jêh ri chiă uănh pe khay jât nar ta ƀon Yêrusalem. Păng ƀư nau mhĭk đŏng ta năp măt Yêhôva.$b$,true),
('bunong-vn','2CH',36,10,null,$b$Dôl yan kao si tâm năm nây Hađăch Nêbukatnetsar prơh bunuyh hăn njŭn leo păng ma ƀon Babilôn, nđâp ma khăl ngan khlay bơh ngih Yêhôva, jêh ri ăn oh păng Y-Sêdêkia jêng hađăch chiă uănh n'gor Yuđa jêh ri ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',36,11,null,$b$Y-Sêdêkia geh bar jât ma nguay năm tơ lah păng ntơm chiă uănh, jêh ri păng chiă uănh jât ma nguay năm ta ƀon Yêrusalem.$b$,true),
('bunong-vn','2CH',36,12,null,$b$Păng ƀư nau mhĭk ta năp măt Yêhôva Brah Ndu păng. Păng mâu ŭch dêh rhêt păng nơm ôh ta năp Y-Yêrimi, jêng kôranh nơm mbơh lor ntuh bâr Yêhôva gay ntĭm nti păng.$b$,true),
('bunong-vn','2CH',36,13,null,$b$Păng tâm ban lĕ tâm rdâng đah Hađăch Nêbukatnetsar, jêng hađăch hŏ nchâp păng ton săk knŏng ma Brah Ndu; ƀiă lah păng ƀư dăng bôk jêh ri ƀư dăng nuih n'hâm, mâu ŭch plơ̆ sĭt ma Yêhôva Brah Ndu$b$,false),
('bunong-vn','2CH',36,14,null,$b$Lĕ rngôch phung n'gâng kôranh ƀư brah jêh ri phung ƀon lan tâm ban lĕ mâu gŭ răp jăp ôh, tĭng ndô̆ lĕ nau nhĭm Yêhôva tâm rmot nau phung mpôl băl êng mơng ƀư tih jêh âk rlau keh; ƀư ƀơ̆ ƀơch ngih Yêhôva ngih Păng hŏ ƀư kloh jêh ăn bu yơk tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','2CH',36,15,null,$b$Yêhôva Brah Ndu phung che khân păng, yor lah Păng geh nau yô̆ ma phung ƀon lan Păng jêh ri ngih brah Păng; pô ri Păng prơh phung hăn mbơh ma khân păng ƀa ƀơ;$b$,false),
('bunong-vn','2CH',36,16,null,$b$ƀiă lah khân păng mưch ma phung bunuyh Brah Ndu prơh hăn, tâm rmot ma nau ô băl ngơi, gơm mưch ma phung kôranh nơm mbơh lor Păng, kŏ tât Yêhôva ji nuih hao lam ma phung ƀon lan Păng, tât mâu hôm dơi bah ôh.$b$,false),
('bunong-vn','2CH',36,17,null,$b$Yor nây Yêhôva leo hađăch phung Kaldê tâm lơh dah khân păng, phung nây ƀư nkhĭt bu klâu ndăm khân păng ma đao tâm ntŭk kloh ueh khân păng; jêh ri mâu yô̆ ôh ma phung ndăm mâu lah bu druh; bu ranh mâu lah phung bôk mra; Yêhôva jao khân păng ma ti hađăch phung Kaldê.$b$,true),
('bunong-vn','2CH',36,18,null,$b$Lĕ rngôch khăl ngan ngih Brah Ndu, jê̆ nđâp toyh; drăp ndơ Yêhôva, drăp ndơ hađăch, jêh ri phung kôranh păng, lĕ rngôch djôt leo ma Babilôn da dê.$b$,false),
('bunong-vn','2CH',36,19,null,$b$Khân păng su ngih Brah Ndu, mbang rlâm mpêr ƀon toyh Yêrusalem, sŏk ŭnh su lĕ ngih hađăch, jêh ri ƀư rai lĕ ƀhiau khăl ngan khlay.$b$,false),
('bunong-vn','2CH',36,20,null,$b$Păng njŭn leo lĕ rngôch bu nă ma bri Babilôn, đơ phung hôm klen bu nkhĭt ma đao, jêh ri khân păng jêng oh mon ma păng jêh ri ma kon bu klâu păng kŏ tât rnôk bu ndâk ƀon bri hađăch Persi,$b$,false),
('bunong-vn','2CH',36,21,null,$b$gay ăn tâm di nau ngơi Yêhôva hŏ dŏng jêh bâr mbung Y-Yêrêmi ntuh an, nâm bu ntĭt kŏ tât tơ lah n'gor dơi dơn tay năm Saƀat Brah Ndu hŏ nal jêh, yor lah lĕ rngôch lam n'gor rlu nar Saƀat, gay ƀư lôch năng tâm nal pơh jât năm.$b$,false),
('bunong-vn','2CH',36,22,null,$b$Tâm năm rơh nguay Y-Sirus hađăch Persi chiă uănh, Yêhôva ŭch ƀư ăn tâm di nau Păng ngơi hŏ dŏng jêh bâr mbung Y-Yêrêmi ntuh an, Yêhôva sŭk nsôr nuih n'hâm Y-Sirus, hađăch Persi, gay ma păng tơih mbơh lam ƀon bri hađăch păng, jêh ri tâm ban lĕ chih sămƀŭt ntrŭnh lah pô aơ:$b$,true),
('bunong-vn','2CH',36,23,null,$b$“Y-Sirus, hađăch Persi lah pô aơ: ‘Yêhôva Brah Ndu klơ trôk, ăn jêh ma gâp lĕ rngôch ƀon bri hađăch ta neh ntu, jêh ri đă gâp ndâk ăn Păng du rplay ngih brah ta ƀon Yêrusalem tâm n'gor Yuđa. Tâm phung khân may, mbu moh jêng ƀon lan Păng, hăn hao hom ma Yêrusalem; dăn ma Yêhôva Brah Ndu păng gŭ ndrel ma păng!$b$,false);
