insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','EZR',1,1,null,$b$Năm rơh nguay rnôk rô̆ Y-Sirus, hađăch Persơ gay ƀư ăn di nanê̆ ngăn nau Yêhôva ngơi ăn bâr mbung Y-Yêrêmi ntuh an, yor ri Yêhôva hŏ sŭk nsôr nuih n'hâm Y-Sirus, hađăch Persơ, nkoch mbơh tâm lam bri dak păng, jêh ri chih nau nây tâm sămƀŭt ntrŭnh bâr tâm ban lĕ.$b$,true),
('bunong-vn','EZR',1,2,null,$b$Pô aơ Y-Sirus, hađăch Persơ lah: Yêhôva Brah Ndu tâm trôk, hŏ ăn ma lĕ rngôch bri dak lam neh ntu jao jêh ma gâp, jêh ri Păng nơm yơh hŏ ntăm jêh ma gâp ndâk ăn păng du mlâm ngih brah ta ƀon Yêrusalem, tâm n'gor Yuđa.$b$,false),
('bunong-vn','EZR',1,3,null,$b$Mbu tâm phung khân may jêng phung ƀon lan păng, jêh ri ăn păng hăn rlet ma ƀon Yêrusalem tâm n'gor Yuđa, jêh ri ndâk tay đŏng ngih Yêhôva jêng Brah Ndu phung Israel păng jêng Brah Ndu tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','EZR',1,4,null,$b$Mbu jêng phung Yuđa hôm e-klen, nđâp tơ lah mbah ntŭk păng gŭ; geh nau kơl tă bơh bri ntŭk mpôl bunuyh păng gŭ; dơi kơl ma prăk, mah, ndô ndơ, jêh ri mpô mpa, mâu kơp ôh ndơ nhhơr hŏ mĭn jêh ma ngih Brah Ndu ta ƀon Yêrusalem.$b$,false),
('bunong-vn','EZR',1,5,null,$b$Rnôk nây, phung kôranh ma noi deh phung Yuđa jêh ri phung Benjamin, phung kôranh ƀư brah, jêh ri phung Lêvi, lĕ rngôch ăp nơm Brah Ndu hŏ sŭk nsôr tâm nuih n'hâm geh nau mĭn ŭch hăn ndâk njêng đŏng ngih brah Yêhôva ta ƀon Yêrusalem.$b$,true),
('bunong-vn','EZR',1,6,null,$b$Lĕ rngôch phung chiau meng khân păng kơl ndơ ma khân păng da dê, ma khăl ngan prăk, ma mah, ndô ndơ, mpô mpa, jêh ri ndô ndơ khlay, mâu kơp ôh ndơ nhhơr hŏ mĭn jêh tâm nuih n'hâm.$b$,false),
('bunong-vn','EZR',1,7,null,$b$Hađăch Sirus tâm ban lĕ mplơ̆ sĭt tay khăl ngăn ngih brah Yêhôva, ndơ hađăch Nêbukatnetsar sŏk nchuăn jêh tă bơh ƀon Yêrusalem jêh ri dơm tâm ngih phung brah păng.$b$,true),
('bunong-vn','EZR',1,8,null,$b$Y-Sirus, hađăch Persơ, mbơh ma Y-Nit-Rêdat, kôranh djôt prăk, sŏk lĕ rngôch ndơ nây, kơp jêh ri jao ma Y-Sês-Basar (nâm bu ntĭt, nây jêng amoh Y-Sôrôbabel, nau ngơi Kaldê), phung kôranh Yuđa.$b$,false),
('bunong-vn','EZR',1,9,null,$b$Aơ jêng rnoh kơp ndơ nây; pe jât mlâm ngan grưng mah (mâm); du rbăn mlâm ngan grưng prăk; bar jât ma sĭn mlâm pêih;$b$,false),
('bunong-vn','EZR',1,10,null,$b$pe jât mlâm ngan rlŭ mah; bar rbăn puăn rhiăng jât mlâm ngan rlŭ prăk, jêh ri du rbăn mlâm khăl ngan êng.$b$,false),
('bunong-vn','EZR',1,11,null,$b$Lĕ rngôch khăl ngan mah jêh ri prăk geh prăm rbăn puăn rhiăng mlâm. Lĕ rngôch ndơ nây Y-Ses-Basar djôt leo ndrel rnôk bu mplơ̆ sĭt phung ƀư bună tă bơh Babilôn, leo sĭt ma ƀon Yêrusalem.$b$,false),
('bunong-vn','EZR',2,1,null,$b$Tâm phung kon sau lĕ ntil mpôl bunuyh gŭ tâm n'gor Yuđa, du luh tă bơh nau jêng bu nă jêng phung Nêbukatnetsar, hađăch Babilôn, hŏ veng leo jêng bună ma Babilôn; aơ phung bunuyh bună nây hăn hao sĭt ma ƀon Yêrusalem, jêh ri n'gor Yuđa; ăp nơm sĭt tâm ƀon khân păng nơm,$b$,true),
('bunong-vn','EZR',2,2,null,$b$geh Y-Sôrôbabel, Y-Jêsua, Y-Nêhêmi, Y-Sêraya, Y-Rêelaya, Y-Môndêkai, ri Y-Bana njŭn leo. Pô ri, aơ jêng ndrom sămƀŭt kơp rnoh phung bu klâu phung ƀon lan Israel.$b$,false),
('bunong-vn','EZR',2,3,null,$b$Mpôl phung Parôs, geh bar rbăn du rhiăng pơh jât ma bar nuyh.$b$,true),
('bunong-vn','EZR',2,4,null,$b$Phung mpôl Sêphatia, geh pe rhiăng pơh jât ma bar nuyh.$b$,false),
