('bunong-vn','EZR',2,40,null,$b$Phung Lêvi: Phung mpôl Jêsua, jêh ri Katmiêl, kon sau Y-Hôdavia, geh pơh jât ma puăn nuyh.$b$,true),
('bunong-vn','EZR',2,41,null,$b$Phung kâp mprơ: Phung mpôl Asap, du rhiăng bar jât ma pham nuyh.$b$,false),
('bunong-vn','EZR',2,42,null,$b$Phung mpôl phung mât njrăng mpông pêr: Phung kon sau Y-Salum, kon sau Y-Ater, kon sau Y-Talmôn, kon sau Y-Akup, kon sau Y-Hatita, jêh ri phung kon sau Y-Sôbai, lĕ rngôch geh du rhiăng pe jât ma sĭn nuyh.$b$,true),
('bunong-vn','EZR',2,43,null,$b$Phung oh mon (bu ntơ Nêthimim) jêng phung oh mon pah kan trôm ngih brah: Kon sau Y-Siha, kon sau Y-Hasupa, kon sau Y Tabaôt,$b$,true),
('bunong-vn','EZR',2,44,null,$b$kon sau Y-Kêrôs, kon sau Y-Siaha, kon sau$b$,false),
