insert into public.bible_footnotes (translation_id, book_code, chapter, verse, verse_end, mark, part, text) values
('bunong-vn','EST',2,2,null,$b$a$b$,null,$b$Oh mon, phung răk rong hađăch, mâu lah ntuh bâr hađăch. 2:3 dak kôlônh, dak ƀâu kah hĭng sŏk. Prăng ntơ: Eua de cologne. 2:9 jrô nŭng: Jrô prăp êng ma bu ur druh ma hađăch.$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'JOB', $b$Y-Yôp$b$, $b$["Ndrom Sămƀŭt", "Y-YÔP"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JOB',1,1,null,$b$Tâm n'gor bri Us geh du huê amoh păng Y-Yôp; bunuyh nây mâu geh nau bu dơi nduyh ôh jêh ri sŏng srăng, du huê bunuyh klach yơk ma Brah Ndu, jêh ri der lĕ nau mhĭk.$b$,true),
('bunong-vn','JOB',1,2,null,$b$Păng geh pơh nuyh kon bu klâu jêh ri pe nuyh kon bu ur;$b$,true),
('bunong-vn','JOB',1,3,null,$b$păng geh pơh rbăn mlâm biăp, pe rbăn mlâm seh samô, du rbăn mlâm ndrôk kai mir, prăm rhiăng mlâm seh bri me, jêh ri âk ngăn oh mon; yor nây păng jêng nơm toyh lơn ma lĕ rngôch phung bunuyh ƀon lan tâm bi Pa lơ.$b$,false),
('bunong-vn','JOB',1,4,null,$b$Phung kon bu klâu păng vay hăn râng nhêt sa, tâm tơh ndrăng rnăk vâl ăp nơm khân păng; jêh ri khân păng vay prơh bu hăn jă pe nuyh oh nur khân păng văch nhêt sông ndrel ma khân păng.$b$,true),
('bunong-vn','JOB',1,5,null,$b$Tơ lah lĕ lôch jêh nau nhêt sa, Y-Yôp vay kuăl ƀư ăn kloh lơi phung kon păng, jêh ri păng kah rngăl ơm ôi jêh ri nhhơr ndơ nhhơr gŭch tĭng nâm ăp nơm khân păng; yor lah Y-Yôp lah, “Klăp lah phung kon gâp ƀư tih jêh, jêh ri rak suai ma Brah Ndu tâm nuih n'hâm khân păng.” Tâm ban pô nây Y-Yôp vay ƀư mro.$b$,true),
('bunong-vn','JOB',1,6,null,$b$Pô nây, geh du nar tâm nal phung kon bu klâu Brah Ndu văch mpơl măt khân păng nơm ta năp Yêhôva, jêh ri nđâp Satan lĕ tât ndrel ma khân păng.$b$,true),
('bunong-vn','JOB',1,7,null,$b$Yêhôva lah ma Satan, “Mbah tă may văch?” Satan plơ̆ sĭt lah ma Yêhôva, “Gâp tă rsong ta aơ ta ri tâm neh ntu, trŭnh jêh ri hao.”$b$,false),
('bunong-vn','JOB',1,8,null,$b$Yêhôva lah ma Satan, “may mâp rmiăng treng uănh lĕ ma oh mon gâp Y-Yôp, yor lah mâu geh ôh du huê bunuyh nâm bu păng ta neh ntu, du huê păng mâu geh nau bu dơi nduyh ôh jêh ri sŏng srăng, klach yơk ma Brah Ndu jêh ri der lĕ nau mhĭk?”$b$,true),
('bunong-vn','JOB',1,9,null,$b$Pô ri Satan plơ̆ lah đŏng ma Yêhôva, “Mâm ƀư Y-Yôp klach yơk ma Brah Ndu dơm dam lĕ?$b$,false),
('bunong-vn','JOB',1,10,null,$b$Mâu di hĕ may jan n'gar jŭm păng, ngih păng, jêh ri lĕ rngôch ndơ păng geh? May mât ton jêh nau ueh uĭn ma kan ti păng ƀư, jêh ri ndơ păng geh bĭk rơ̆ âk tâm n'gor bri.$b$,true),
('bunong-vn','JOB',1,11,null,$b$Ƀiă lah aƀaơ ri yơr hom ti may jêh ri ƀư hom ma lĕ rngôch ndơ păng geh, rnôk nây yơh păng rak rtăp ma may ta năp măt may.”$b$,true),
('bunong-vn','JOB',1,12,null,$b$Yêhôva lah ma Satan, “Aơ, may geh nau dơi ƀư ma lĕ rngôch ndơ păng geh, knŏng lơi may yơr ti ƀư ma păng nơm ôh.” Pô ri Satan du luh tă bơh ta năp măt Yêhôva.$b$,true),
('bunong-vn','JOB',1,13,null,$b$Geh du nar dôl phung kon bu klâu jêh ri kon bu ur păng gŭ sông sa jêh ri nhêt dak play kriăk ƀâu tâm ngih nâu ranh khân păng.$b$,true),
('bunong-vn','JOB',1,14,null,$b$Rnôk nây geh du huê nơm mbơh tât ma Y-Yôp jêh ri lah: “Ndrôk dôl kai mir (chuar mir); seh bri dôl gŭ sa gơ̆ dăch kêng khân păng;$b$,false),
('bunong-vn','JOB',1,15,null,$b$jêh ri phung Sêbêan văch rduh nhŭp khân păng n'ho djôt rdu, jêh ri sreh nkhĭt phung oh mon ma đao; knŏng êng du huê gâp dơi klaih gay mbơh ma may.”$b$,false),
('bunong-vn','JOB',1,16,null,$b$Bunuyh aơ dôl hôm ngơi, geh du huê êng tât jêh ri lah: “Ŭnh Brah Ndu tă bơh trôk jŭr su biăp jêh ri phung oh mon ŭnh sa lĕ rngôch khân păng; knŏng êng du huê gâp dơi klaih gay mbơh ma may.”$b$,true),
('bunong-vn','JOB',1,17,null,$b$Bunuyh aơ dôl hôm ngơi, geh du huê êng tât jêh ri lah: “Phung Kaldê tâm pă pe phung văch pit in djôt rdu seh samô, jêh ri sreh nkhĭt phung oh mon ma đao, jêh ri knŏng êng du huê gâp dơi klaih gay mbơh ma may.”$b$,true),
('bunong-vn','JOB',1,18,null,$b$Bunuyh aơ dôl hôm ngơi, geh du huê tât jêh ri lah: “Phung kon bu klâu jêh ri bu ur may gŭ sông sa jêh ri nhêt dak play kriăk ƀâu tâm ngih nâu ranh khân păng;$b$,true),
('bunong-vn','JOB',1,19,null,$b$jêh ri aơ, phŭt chuănh văch tă bơh bri rdah khôm mpruh, ƀư ma puăn njônh ngih, jêh ri rlâm nklân lĕ phung mom ndăm nây, jêh ri khân păng khĭt lĕ; knŏng êng du huê gâp dơi klaih gay mbơh ma may.”$b$,false),
('bunong-vn','JOB',1,20,null,$b$Pô ri Y-Yôp du dâk, nkhêk ao jâr păng, poih sŏk păng, chon mon ta neh, jêh ri mbah yơk,$b$,true),
('bunong-vn','JOB',1,21,null,$b$Păng lah: “Gâp luh du bơh trôm ndŭl me gâp săk hưl, jêh ri gâp mra hăn sĭt săk hưl lĕ; Yêhôva hŏ ăn, jêh ri Yêhôva sŏk sĭt tay; mât ton tâm rnê amoh Yêhôva.”$b$,false),
('bunong-vn','JOB',1,22,null,$b$Tâm lĕ nau nây Y-Yôp mâu ƀư tih ôh, mâu lĕ phong nduyh Brah Ndu.$b$,true),
('bunong-vn','JOB',2,1,null,$b$Geh du nar tâm nal đŏng tơ lah phung kon bu klâu bơh Brah Ndu tât gay mpơl khân păng nơm ta năp Yêhôva jêh ri nđâp Satan lĕ tât ndrel ma khân păng gay tâm mpơl păng nơm ta năp Yêhôva.$b$,true),
('bunong-vn','JOB',2,2,null,$b$Yêhôva lah ma Satan, “Mbah tă may văch?” Satan plơ̆ sĭt lah ma Yêhôva, “Gâp tă rsong ta aơ ta ri tâm neh ntu, trŭnh jêh ri hao.$b$,true),
('bunong-vn','JOB',2,3,null,$b$Yêhôva lah đŏng ma Satan, “May mâp rmiăng treng uănh lĕ ma oh mon gâp Y-Yôp, yor lah mâu geh ôh du huê nuyh nâm bu păng ta neh ntu, du huê păng mâu geh nau bu dơi nduyh ôh jêh ri sŏng srăng, klach yơk ma Brah Ndu jêh ri der lĕ nau mhĭk? Nđâp tơ lah may ntrôl gâp ƀư ma păng gay ƀư rai păng mâu geh nau, ăt păng gŭ răp jăp lĕ.”$b$,false),
('bunong-vn','JOB',2,4,null,$b$Jêh ri Satan plơ̆ sĭt lah ma Yêhôva, “Sŏk ntâu ntrok ma ntâu! Du huê bunuyh mra ăn lĕ rngôch ndơ păng geh gay tâm rklaih nau rêh păng.$b$,false),
('bunong-vn','JOB',2,5,null,$b$Ƀiă lah yơr hom ti may aƀaơ ri ƀư ma nting jêh ri nglay săk păng, rnôk nây păng mra rak suai ma may tra năp măt may.”$b$,false),
('bunong-vn','JOB',2,6,null,$b$Yêhôva lah ma Satan, “Aơ, păng lĕ gŭ tâm ti may, ƀiă lah knŏng prăp an nau rêh păng.”$b$,false),
('bunong-vn','JOB',2,7,null,$b$Pô nây Satan du luh bơh ta năp Yêhôva, jêh ri ƀư nkrit ma Y-Yôp ma eh ok mhĭk ngăn ntơm bơh mpang jâng tât klơ bôk.$b$,true),
('bunong-vn','JOB',2,8,null,$b$Păng sŏk du rlat rsong yăng chah kuach chiăt, jêh ri gŭ tâm ŭnh buh.$b$,true),
('bunong-vn','JOB',2,9,null,$b$Ur păng lah ma păng, “Mâm ƀư may hôm e gŭ răp jăp lĕ? Rak rtăp hom ma Brah Ndu jêh ri khĭt!”$b$,false),
('bunong-vn','JOB',2,10,null,$b$Păng plơ̆ lah: Ay ngơi nâm bu du huê bu ur rluk. Mâm ƀư, he knŏng sŏk dơn nau ueh tă bơh ti Brah Ndu nây dơm hĕ, jêh ri mâu sŏk dơn ôh nau mhĭk? “Tâm lĕ nau nây Y-Yôp mâu mâp ƀư tih ôh ma trôm mbung păng.$b$,false),
('bunong-vn','JOB',2,11,null,$b$Tơ lah pe nuyh mĭt jiăng Y-Yôp tăng lư ma lĕ nau mhĭk nây tât jêh ma păng, ăp nơm khân păng văch tât tă bơh ntŭk păng nơm Y-Êlipas tă bơh ƀon Têman, Y-Bildat tă bơh phung Suah, jêh ri Y-Sôphar tă bơh phung Nama. Khân păng tâm nal klân rvê ndrel ma ô băl jêh ri bonh leng ô băl.$b$,true),
('bunong-vn','JOB',2,12,null,$b$Tơ lah khân păng saơ ô băl hôm ngai, khân păng mâu gĭt năl ô băl ôh; khân păng nter jêh ri nhĭm. Khân păng nkhêk ao jâr khân păng jêh ri sui ndruyh neh rlet klơ trôk ta klơ bôk khân păng.$b$,false),
('bunong-vn','JOB',2,13,null,$b$Tâm pơh nar jêh ri pơh năng jêh ri khân păng gŭ ndrel ô băl ta neh, mâu geh du huê ngơi ma ô băl ôh yor lah khân păng saơ ô băl nđêh nji hâu ngăn.$b$,false),
('bunong-vn','JOB',3,1,null,$b$Jêh nau nây, Y-Yôp hă ngơi jêh ri rak rtăp ma nar me deh ma păng.$b$,true),
('bunong-vn','JOB',3,2,null,$b$Jêh ri Y-Yôp lah:$b$,true),
('bunong-vn','JOB',3,3,null,$b$“Ăn nar bu deh ma gâp rai lơi, nđâp măng tâm ban lĕ, ‘Bu deh jêh ma du huê kon bu klâu.’$b$,false),
('bunong-vn','JOB',3,4,null,$b$Ăn nar nây jêng ngo! Ăn Brah Ndu ta klơ mâu joi ôh nar nây, mâu lĕ ăn nau ang păng nchrang.$b$,false),
('bunong-vn','JOB',3,5,null,$b$Ăn nau rngot jêh ri ngo klĕng sŏk păng. Ăn tŭk nkŭm ta klơ păng; ăn nau ngo măng lĭng nhhu nkrit păng$b$,true),
('bunong-vn','JOB',3,6,null,$b$Măng nây ăn nau ngo klĕng kuăn rdâng păng! Lơi ăn păng hâk răm ôh ndrel ma lĕ nar êng tâm năm lơi ăn bu kơp păng ôh ndrel ma lĕ khay.$b$,false),
('bunong-vn','JOB',3,7,null,$b$N'hêl nanê̆, ăn măng nây jêng nâm bu bu ur ndrô gâng; lơi ăn bu tăng bâr nter gơm răm ôh tâm păng.$b$,true),
('bunong-vn','JOB',3,8,null,$b$Ăn phung vay rak rtăp nar nây, jêh ri phung blau rhiăl Lêviathan ăn dâk, Rak rtăp hom păng!$b$,true),
('bunong-vn','JOB',3,9,null,$b$Ăn lĕ rngôch mănh ƀhit rvi ang păng jêng ngo; ăn păng kâp gân ăn ang, ƀiă lah lơi geh ang ôh, kŏ mâu saơ lĕ nau ang kêng ang ôi!$b$,true),
('bunong-vn','JOB',3,10,null,$b$Yor lah păng mâu rdâl ôh ndŭl mê̆ gâp kŏ mâu pôn lĕ nau nđêh nji bơh trôm măt gâp.$b$,true),
('bunong-vn','JOB',3,11,null,$b$“Mâm ƀư gâp dĭng mâu khĭt ôh tâm trôm rsok? Mâm ƀư dĭng mâu krŭl n'hâm tơ lah luh du tă bơh ndŭl mê̆ gâp?$b$,true),
('bunong-vn','JOB',3,12,null,$b$Mâm ƀư kômâk bar đah sŏk ngluh gâp. Jêh ri toh gay ăn gâp pu?$b$,true),
('bunong-vn','JOB',3,13,null,$b$Lah mâu kơt nĕ, aƀaơ ri gâp lĕ lâng jêh ri gŭ klêm. Gâp bêch jêh ri gâp gŭ rlu;$b$,true),
('bunong-vn','JOB',3,14,null,$b$Ndrel ma phung hađăch jêh ri phung kôranh tâm chră ta neh ntu, phung ndâk tay ma khân păng nơm ndơ lĕ rai jêh,$b$,false),
('bunong-vn','JOB',3,15,null,$b$mâu lah ndrel ma phung kôranh geh mah, jêh ri prăp bun prăk ăn bêng ngih vâl păng;$b$,false),
('bunong-vn','JOB',3,16,null,$b$mâu lah mâm dĭng gâp mâu jêng ôh du huê kon bu rlêh ndâp, nâm bu du huê kon jê̆ mâu saơ nau ang ôh?$b$,false),
('bunong-vn','JOB',3,17,null,$b$Ta nây phung ƀai rlu nau khân păng rkhŭk bu, ta nây phung lêt rgănh gŭ rlu.$b$,true),
('bunong-vn','JOB',3,18,null,$b$Ta nây phung bună gŭ rlu mpăn ndrel n'grŭp. Mâu hôm tăng nau phung kôranh rgât grap đŏng ôh.$b$,true),
('bunong-vn','JOB',3,19,null,$b$Ta ntŭk nây phung jê̆ jêh ri toyh gŭ ndrel, jêh ri phung dĭk bu mƀơk dơi ăn jêng kon me tă bơh kôranh păng.$b$,true),
('bunong-vn','JOB',3,20,null,$b$“Mâm dĭng bu ăn nau ang ma nơm rêh ni, jêh ri ăn nau rêh ma nơm geh huêng rngot rvê?$b$,true),
('bunong-vn','JOB',3,21,null,$b$Bunuyh kơt nĕ ŭch nau khĭt, ƀiă lah nkhơng mâu dơi khĭt; jêh ri ŭch joi nau nây âk lơn ma nơm kuyh neh joi drăp khlay lĕ pôn ndâp jêh.$b$,true),
('bunong-vn','JOB',3,22,null,$b$Tơ lah bunuyh nây dơi joi tât ta môch, răm maak jêh ri rhơn ngăn ngên.$b$,true),
('bunong-vn','JOB',3,23,null,$b$Mbu moh mâu gĭt trong ăn păng tĭng ndô̆ jêh ri mâm hôm dơi geh nau rêh lĕ Brah Ndu nchuêng lĕ puăn njônh?$b$,true),
('bunong-vn','JOB',3,24,null,$b$Yor lah ê lor gâp sa, gâp hŏ nter jêh jêh ri nau gâp nter mprănh rsach nâm bu dak$b$,true),
('bunong-vn','JOB',3,25,null,$b$Yor lah nau gâp klach hŏ văch tât ma gâp; jêh ri nau gâp krit klach tât ngăn jêh ma gâp.$b$,false),
('bunong-vn','JOB',3,26,null,$b$Gâp mâu dơi gŭ mpăn, kŏ mâu dơi gŭ răk klăk lĕ, gâp mâu geh nau đăp rmên ôh, ƀiă lah nau uh ah tât ma gâp.”$b$,true),
('bunong-vn','JOB',4,1,null,$b$Rnôk nây, Y-Êlipas, bơh ƀon Têman plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',4,2,null,$b$“Tơ lah bu rlong ngơi ma may, may mra rngot lĕ. Ƀiă lah mbu nơm dơi buay mâu ăn ngơi?$b$,false),
('bunong-vn','JOB',4,3,null,$b$Aơ, may hŏ nti jêh âk bunuyh, jêh ri may ƀư ktang jêh ti lĕ ra ai,$b$,true),
('bunong-vn','JOB',4,4,null,$b$Nau may ngơi hŏ rđâng jêh nơm văk prah, Jêh ri kômâk rbăn may hŏ ƀư ăn nâp.$b$,false),
('bunong-vn','JOB',4,5,null,$b$Ƀiă lah aƀaơ nau nây tât ma may nơm, nkhơng may biănh; nau nây ƀư ma may, jêh ri may rdja nuih.$b$,true),
('bunong-vn','JOB',4,6,null,$b$Nau may klach yơk ma Brah Ndu, nau nây mâu di hĕ jêng nau may nsing? Jêh ri nau may gŭ răp jăp jêng nau may kâp gân?$b$,true),
('bunong-vn','JOB',4,7,null,$b$“May gŭ nklân hom, mbu moh mâu geh nau tih lĕ rai yot jêh? Mâu lah ta ntŭk phung sŏng srăng lĕ rai lôch jêh?$b$,true),
('bunong-vn','JOB',4,8,null,$b$Tĭng nâm gâp hŏ saơ jêh, mbu kai nau kue jêh ri srih nau uh ah mra rek play păng kơt nĕ lĕ.$b$,true),
('bunong-vn','JOB',4,9,null,$b$Yor tă n'hâm bơh Brah Ndu nsôr dĭng khân păng geh nau roh rai, jêh ri tă bơh Păng bruh n'hâm ji nuih, dĭng khân păng geh nau rai lôch.$b$,true),
('bunong-vn','JOB',4,10,null,$b$Rđuh ngrông yau mŭr, jêh ri bâr yau mŭr janh hŏ rngơt jêh. Jêh ri neng phung yau mŭr kon lĕ răch jêh.$b$,true),
('bunong-vn','JOB',4,11,null,$b$Yau mŭr ktang lĕ khĭt yor lah mâu geh mpô mpa sa hêk, jêh ri phung yau mŭr kon lĕ du pru.$b$,true),
('bunong-vn','JOB',4,12,null,$b$“Bu mbơh du nau ndâp tât ma gâp, tôr gâp tăng jêh nau bu ngơi rah rơch nây,$b$,true),
('bunong-vn','JOB',4,13,null,$b$Dôl gŭ rvê mĭn ma nau tâm saơ bri măng, phung kon bunuyh dôl lêt bêch jêh,$b$,false),
('bunong-vn','JOB',4,14,null,$b$Nau klach krit tât ma gâp, jêh ri nau râm nsâr lĕ rngôch nting gâp n'gơ mprâm.$b$,false),
('bunong-vn','JOB',4,15,null,$b$Geh brah mpăn rgăn ta năp muh măt gâp, jêh ri gâp rak bôk, rak rsau săk.$b$,true),
('bunong-vn','JOB',4,16,null,$b$Brah dâk ta nây, ƀiă lah gâp mâu gĭt năl ôh. Geh du mlâm rup pa năp gâp; Gâp tăng ngơi ƀŭk jê̆ jê̆, lah:$b$,true),
('bunong-vn','JOB',4,17,null,$b$“Dơi lĕ du huê bunuyh blau khĭt jêng sŏng ta năp Brah Ndu? Dơi lĕ du huê bunuyh jêng rsang ta năp Nơm Njêng păng?”$b$,false),
('bunong-vn','JOB',4,18,null,$b$Aơ, Brah Ndu mâu nsing ôh ma phung oh mon Păng, Păng vay nduyh nau tih ma phung tông mpăr Păng.$b$,true),
('bunong-vn','JOB',4,19,null,$b$Rlau lơn ma nây lĕ ma phung bu njêng ma neh bŏk, bu rƀlê khân păng klơ mbon ndruyh neh, phung bu piăch nâm bu nchiăr ƀon.$b$,true),
('bunong-vn','JOB',4,20,null,$b$Vah vang kêng ôi tât kêng măng lĕ bu ƀư rai jêh khân păng. Khân păng rai lôch n'ho ro, mâu geh nơm chrê ôh.$b$,true),
('bunong-vn','JOB',4,21,null,$b$Tơ lah rse suan nau rêh khân păng lĕ tăch jêh, mâu di hĕ khân păng lĕ khĭt jêh, jêh ri khĭt mâu geh nau blau mĭn ôh?$b$,true),
('bunong-vn','JOB',5,1,null,$b$Pô nây, “Kuăl hom aƀaơ ri geh lĕ nuyh plơ̆ lah ma may? Ma mbu phung kloh ueh may mra nsing?$b$,true),
('bunong-vn','JOB',5,2,null,$b$Yor lah nau thăm man nkhĭt bunuyh rluk, nau tâm nach nkhĭt bunuyh dơm dam.$b$,true),
('bunong-vn','JOB',5,3,null,$b$Gâp saơ jêh bunuyh rluk ntơm chăt hon reh, ƀiă lah ƀât lât gâp rak rtăp jêh ma ntŭk păng gŭ.$b$,true),
('bunong-vn','JOB',5,4,null,$b$Phung kon sau păng mâu geh nau mpăn ôh, bu jot plên khân păng ta mpông pêr, jêh ri mâu geh nơm kơl khân păng ôh.$b$,true),
('bunong-vn','JOB',5,5,null,$b$Phung ji ngot ji hir sa lơi play păng kăch roih, kŏ tât păng pĕ play ta nklang mpach lok; jêh ri ran grŭ gră ma drăp ndơ păng$b$,true),
('bunong-vn','JOB',5,6,null,$b$Yor lah krit rngot mâu ôh luh tă ndruyh neh, mâu lĕ nau jâk jêr chăt hon tă bơh neh;$b$,false),
('bunong-vn','JOB',5,7,null,$b$Ƀiă lah bu deh bunuyh ma nau uh ah, nâm bu kao ŭnh sial khôm ta klơ.$b$,false),
('bunong-vn','JOB',5,8,null,$b$“Bi ma gâp, gâp mra joi Brah Ndu, jêh ri gâp mra jao nau gâp geh ma Brah Ndu,$b$,true),
('bunong-vn','JOB',5,9,null,$b$Păng pah kan toyh ngăn jêh ri bu mâu dơi gĭt rbăng ôh. Kan khlay ngăn bu mâu dơi kơp ôh;$b$,false),
('bunong-vn','JOB',5,10,null,$b$Păng ăn trôk mih ta neh ntu, ăn dak djrah lam mir;$b$,false),
('bunong-vn','JOB',5,11,null,$b$Păng n'hao phung dêh rhêt jêh ri pư chông phung nhĭm nhhiăng n'gân ta ntŭk ueh mpăn.$b$,false),
('bunong-vn','JOB',5,12,null,$b$Păng ăn roh lơi kan phung blau plĕch ŭch ƀư, pô ri kan ti khân păng ƀư mâu dơi jêng ôh.$b$,true),
('bunong-vn','JOB',5,13,null,$b$Păng sŏk kân phung blau mĭn tâm nau plĕch rlăm khân păng; jêh ri păng ƀư ăn lôch lơi gơnh kan phung plĕch rlăm ƀư.$b$,true),
('bunong-vn','JOB',5,14,null,$b$Dôl nôk nar khân păng mâp nau ngo, Dôl nar nklang bôk khân păng hăn but nâm bu klong măng ngo klĕng.$b$,true),
('bunong-vn','JOB',5,15,null,$b$Brah Ndu rklaih phung kon đơi tă bơh trôm mbung phung nây jêh ri klaih bơh ti phung ktang$b$,true),
('bunong-vn','JOB',5,16,null,$b$Pô ri, phung o ach geh nau kâp gân, jêh ri ma phung kue mêm mbung dơm (ât ndơ sa).$b$,false),
('bunong-vn','JOB',5,17,null,$b$“Aơ, ueh maak ngăn bunuyh Brah Ndu nduyh; yor nây lơi tâm rmot ôh ma nau Nơm Geh Lĕ Nau Brah Nduyh nkra.$b$,true),
('bunong-vn','JOB',5,18,null,$b$Yor lah păng ăn sôt, ƀiă lah păng put; păng dong, ƀiă lah ti păng ƀư bah.$b$,true),
('bunong-vn','JOB',5,19,null,$b$Păng mra tâm rklaih may tă bơh prao ntil nau tât uh ah; nđâp pơh ntil kđôi lĕ nau ƀai mâu mra ƀư ma may ôh.$b$,true),
('bunong-vn','JOB',5,20,null,$b$Tâm nau sa sât ji ngot, Păng mra sâm rklaih bơh nau khĭt, jêh ri dôl geh nau tâm lơh, sâm rklaih may tă bơh mpiăt đao.$b$,true),
('bunong-vn','JOB',5,21,null,$b$May mra dơi nchuăt krap klaih tă bơh mpiăt nau krit; jêh ri may mâu mra klach ôh tơ lah geh nau bu ƀư rai tât.$b$,true),
('bunong-vn','JOB',5,22,null,$b$May mra gơm rum ma nau ƀư rai jêh ri nau sa sât ji ngot, jêh ri may mâu mra klach lĕ ma mpô mpa bri ta neh ntu;$b$,true),
('bunong-vn','JOB',5,23,null,$b$Yor lah may mra geh nau tâm rnglăp ma lŭ tâm mir, jêh ri mpô mpa bri mra gŭ đăp mpăn ndrel may.$b$,false),
('bunong-vn','JOB',5,24,null,$b$May mra gĭt ma ngih bok may gŭ mpăn, jêh ri may mra chop uănh biăp ndrôk may. Jêh ri saơ khân păng lĕ nŭm da dê.$b$,true),
('bunong-vn','JOB',5,25,null,$b$May mra saơ tâm ban lĕ ma phung kon sau may mra jêng âk, jêh ri phung kon may nâm bu gơ̆ ta neh ntu.$b$,true),
('bunong-vn','JOB',5,26,null,$b$May mra jŏk rêh tât ranh tơ lah rnôk may lăp tâm trôm môch, nâm bu du nchăp ba tât ta ntŭk bu mprah di yan păng.$b$,true),
('bunong-vn','JOB',5,27,null,$b$Aơ, hên sek uănh nanê̆ jêh; nau nây jêng ngăn. Iăt hom, jêh ri gĭt nau nây jêng di ma may.$b$,true),
('bunong-vn','JOB',6,1,null,$b$Y-Yôp plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',6,2,null,$b$“Ơ! Ŭch lĕ nau bu ƀư nđêh nji gâp veh njing ăn di. Jêh ri lĕ nau jâk jêr gâp dơn gay veh njing ăn sŏng srăng!$b$,false),
('bunong-vn','JOB',6,3,null,$b$Yor lah aƀaơ ri păng jâk lơn ma choih tâm dak mƀŭt; Yor nây dăng gâp ngơi ro yơh.$b$,true),
('bunong-vn','JOB',6,4,null,$b$Yor lah hăr Nơm Geh Lĕ Nau Brah leng di ta gâp jêh; nuih n'hâm gâp nhêt rvăn dak kăch khân păng; nau Brah Ndu nkrit ƀư ma gâp.$b$,true),
('bunong-vn','JOB',6,5,null,$b$Mâm ƀư seh bri nhhiăng nter lĕ tơ lah păng geh gơ̆ sa? Mâu lah ndrôk ƀuh lĕ tơ lah păng geh rhe?$b$,true),
('bunong-vn','JOB',6,6,null,$b$Dơi lĕ bu sa ndơ sât nây tơ lah mâu geh boh ôh? Bi ma ndơ nglang tâm tăp iăr, moh ndơ ƀâu păng?$b$,true),
('bunong-vn','JOB',6,7,null,$b$Gâp mâu ŭch sa ndơ nây ôh; ndơ nây jêng nâm bu ndơ sông sa gâp tâm rmot$b$,true),
('bunong-vn','JOB',6,8,null,$b$“Ơ! Gay dơi geh ngăn moh nau gâp dăn, jêh ri gay ma Brah Ndu ăn tât nau gâp ŭch!$b$,false),
('bunong-vn','JOB',6,9,null,$b$Gay ma Brah Ndu geh nau maak jot plên gâp, gay ma păng yơr ti păng jêh ri ngroh lơi gâp!$b$,true),
('bunong-vn','JOB',6,10,null,$b$Nau nây mra jêng nau njung leng ma gâp; gâp ăt mra maak tâm nau ji gâp glăm ngăn Yor lah gâp mâu mâp dun ôh nau Nơm Kloh Ueh ngơi.$b$,true),
('bunong-vn','JOB',6,11,null,$b$Ntŭk hôm geh n'hâm suan gay ăn gâp dơi gŭ kâp? Mâm jêng nau lôch dŭt ma gâp, kŏ tât gâp dơi gŭ nsrôih nsram?$b$,true),
('bunong-vn','JOB',6,12,null,$b$N'hâm suan gâp jêng nâm bu nau ktang lŭ lĕ, mâu lah nglay săk gâp jêng kông lĕ?$b$,true),
('bunong-vn','JOB',6,13,null,$b$N'hêl nanê̆ gâp mâu geh nau dơi kơl gâp nơm ôh, nau blau mĭn gâp lĕ bu rdu ngai jêh bơh gâp. Mâu hĕ di kơt nĕ?$b$,true),
('bunong-vn','JOB',6,14,null,$b$Du huê rdja nuih rngot lĕ huăr bơi cha lôt, di ngăn dơi geh mĭt jiăng văch tât kơl, klach lah păng cha lơi nau klach yơk ma Nơm Geh Lĕ Nau Brah.$b$,true),
('bunong-vn','JOB',6,15,null,$b$Phung oh nâu gâp jêng phung ƀlêp ƀlêr nâm bu dak n'hor lĕ suăt dak, nâm bu n'hor dak hoch lĕ kroh.$b$,true),
('bunong-vn','JOB',6,16,null,$b$Păng rkhăl yor ma glo dak pler, yor pler lêk krŭt trong.$b$,true),
('bunong-vn','JOB',6,17,null,$b$Ƀiă lah tơ lah lĕ duh jêh khân păng suăt ro, tơ lah geh nau duh ring khân păng du roh bơh ntŭk khân păng.$b$,true),
('bunong-vn','JOB',6,18,null,$b$Phung mpôl bunăch hăn rgăn der trong khân păng, hăn hao bri rdah, jêh ri rai lôch.$b$,true),
('bunong-vn','JOB',6,19,null,$b$Phung mpôl bunăch bơh n'gor bri Têma joi dak păng, phung nsong tăch drăp bơh n'gor bri Sêba rnơm ma păng;$b$,true),
('bunong-vn','JOB',6,20,null,$b$Ƀiă lah khân păng ji bêk yor lah rnơm ma păng. Tơ lah tât jêh ta n'hor dak, khân păng prêng.$b$,false),
('bunong-vn','JOB',6,21,null,$b$Aƀaơ ri khân may tâm ban ma gâp mâu geh du ntil ndơ, khân may saơ jêh nau rêh ni gâp, jêh ri khân may klach nsâr.$b$,true),
('bunong-vn','JOB',6,22,null,$b$Gâp mâp geh lah lĕ, ‘Ăn hom ndơ ma gâp?’ Mâu lah ‘Nhhơr hom ndơ nkhôm ma gâp ndô ndơ khân may?’$b$,true),
('bunong-vn','JOB',6,23,null,$b$Mâu lah, ‘Tâm rklaih hom gâp bơh ti phung rlăng gâp’? Mâu lah ‘Tâm chuai hom gâp bơh ti phung tŭn jot gâp’?$b$,false),
('bunong-vn','JOB',6,24,null,$b$“Nti hom ma gâp, jêh ri gâp mra gŭ klêm; ntĭm ăn gâp gĭt rbăng moh nau gâp lĕ tih jêh.$b$,true),
('bunong-vn','JOB',6,25,null,$b$Nau ngơi nanê̆ ngăn geh nau sŭk nsôr ngăn! Ƀiă lah moh khlay nau khân may nduyh?$b$,true),
('bunong-vn','JOB',6,26,null,$b$Khân may mĭn gay ŭch dơi nduyh lĕ nau gâp ngơi? Ƀiă lah nau ngơi ma du huê bunuyh lĕ rdja nuih knŏng nâm bu rlong sial.$b$,true),
('bunong-vn','JOB',6,27,null,$b$N'hêl nanê̆, khân may mpet phung kon đơi. Jêh ri kuyh ntu ăn rhuh mĭt jiăng khân may.$b$,true),
('bunong-vn','JOB',6,28,null,$b$“Ƀiă lah aƀaơ ri ăn khân may geh nau maak uănh ma gâp; Yor lah gâp mâu ngơi mƀruh ôh ta năp muh măt khân may.$b$,true),
('bunong-vn','JOB',6,29,null,$b$Gâp dăn ma khân may, rle hom, lơi ăn geh nau kue ôh. Mĭn hom rvê tay đŏng, ăn khân may Gĭt năl nau sŏng srăng gâp.$b$,true),
('bunong-vn','JOB',6,30,null,$b$Geh lĕ nau kue ta mpiăt gâp? Mâu di hĕ gâp dơi chiăm gay gĭt rbăng nau rêh ni gâp?$b$,true),
('bunong-vn','JOB',7,1,null,$b$“Bunuyh ta neh ntu mâu geh hĕ nau kan jêr? Nar păng gŭ rêh mâu hĕ di nâm bu nar bu pah kan nkhôm?$b$,true),
('bunong-vn','JOB',7,2,null,$b$Nâm bu du huê dĭk bu ŭch ngăn ma ntŭk n'hâm, jêh ri nâm bu bunuyh pah kan nkhôm kâp gân ma prăk khay.$b$,true),
('bunong-vn','JOB',7,3,null,$b$Pô nây lĕ bu ăn ma gâp nđêh nji ăp măng jêh ri ăn âk khay mâu geh nau khlay ôh.$b$,true),
('bunong-vn','JOB',7,4,null,$b$Tơ lah gâp lâng săk bêch, gâp lah: ‘Ndah nâm jŏ gâp mra dâk?’ Ƀiă lah măng jêng jŏ, jêh ri gâp rlĭ rlang kŏ tât ƀhit rvi ang.$b$,true),
('bunong-vn','JOB',7,5,null,$b$Nglay săk gâp bêng ma ndrĭt rhai jêh ri krêp ndruyh neh; ntâu gâp jêng đang jêh ri hoch ndâng!$b$,true),
('bunong-vn','JOB',7,6,null,$b$Nar gâp gŭ rêh gơnh lôch prăl lơn ma mpih tanh bu tanh. Jêh ri lôch dŭt mâu geh nau kâp gân ôh.$b$,true),
('bunong-vn','JOB',7,7,null,$b$“Kah gĭt hom ma nau rêh gâp gơnh lôch nâm bu suh n'hâm; măt gâp mâu mra saơ nau ueh maak đŏng ôh.$b$,true),
('bunong-vn','JOB',7,8,null,$b$Măt bu uănh ma gâp mâu mra saơ gâp đŏng ôh; dôl măt may gŭ uănh gâp, ƀiă lah gâp mâu hôm saơ.$b$,true),
('bunong-vn','JOB',7,9,null,$b$Nâm bu ndâr tŭk lĕ chah rai, pô nây lĕ nơm trŭnh hăn ma Ƀon Phung Khĭt mâu hôm hao luh du ôh.$b$,true),
('bunong-vn','JOB',7,10,null,$b$Păng mâu hơm plơ̆ sĭt đŏng ôh ma ngih vâl păng, jêh ri bu mâu hôm saơ ôh păng ta ntŭk păng gŭ sa ơm.$b$,true),
('bunong-vn','JOB',7,11,null,$b$“Yor nây, gâp mâu dơi ât nkân ôh nau gâp ŭch ngơi. Tâm nau rêh ni yor nuih n'hâm gâp rngot, gâp mra ngơi. Tâm nau rngot bơh huêng gâp, gâp mra vơh vơl.$b$,true),
('bunong-vn','JOB',7,12,null,$b$Gâp ngơi ma Brah Ndu lah: Gâp jêng dak mƀŭt lĕ, mâu lah bêh toyh tâm dak mƀŭt, kŏ tât may ƀư n'gar krŭng gâp?$b$,true),
('bunong-vn','JOB',7,13,null,$b$Tơ lah gâp lah: ‘Ta sưng bêch gâp mra bonh leng gâp, dôl gâp bêch mra geh nau rthi ăn nau đăp mpăn!’$b$,true),
('bunong-vn','JOB',7,14,null,$b$Rnôk nây may nkrit gâp ma nau mbơi, jêh ri nhhu gâp ma nau tâm saơ gay ăn gâp klach.$b$,false),
('bunong-vn','JOB',7,15,null,$b$Yor nây gâp ŭch bu nhăt glăn trô ko gâp, kŏ tât khĭt ueh lơn đah hôm e rêh ma nau ji tâm nting gâp aơ.$b$,true),
('bunong-vn','JOB',7,16,null,$b$Gâp hŏ dŭt jêh ma nau rêh. Nanê̆ gâp mâu mra rêh mro mrăng ô. Dăn Kôranh Brah lơi may ƀư ma gâp ôh. Yor lah lĕ nar gâp gŭ rêh knŏng ƀât lât dơm.$b$,true),
('bunong-vn','JOB',7,17,null,$b$Moh bunuyh jêng kŏ tât may kơp păng jêng khlay? Mâm dĭng may gŭ mĭn ma păng.$b$,true),
('bunong-vn','JOB',7,18,null,$b$Kŏ tât may chop khâl păng ăp ôi. Jêh ri rlong uănh păng mro mrăng?$b$,true),
('bunong-vn','JOB',7,19,null,$b$Ndah dŭt jŏ dĭng may mâu hôm uănh ôh ma gâp, mâu lah cha lơi gâp mâu hôm ƀư ôh ma gâp?$b$,true),
('bunong-vn','JOB',7,20,null,$b$Tơ lah gâp ƀư tih, moh nau gâp ƀư ma may. Hơi nơm kâp rmiăng ma bunuyh? Mâm may njêng gâp jêng mut pla ăn may pănh? Mâm may ƀư jêr may nơm ŭch ƀư ma gâp?$b$,true),
('bunong-vn','JOB',7,21,null,$b$Mâm may mâu yô̆ an nau tih gâp jêh ri sŏk lơi nau kue gâp? Yor lah aƀaơ ri gâp mra bêch tâm neh. May mra joi gâp, ƀiă lah mâu mra saơ gâp ôh.$b$,true),
('bunong-vn','JOB',8,1,null,$b$Y-Bildat, phung Suah plơ̆ lah:$b$,true),
('bunong-vn','JOB',8,2,null,$b$“Ndah nâm jŏ may mra ngơi nau aơ. Jêh ri nau ngơi tă mbung may tât nâm bu phŭt ndah nâm jŏ?$b$,false),
('bunong-vn','JOB',8,3,null,$b$Mâm Brah Ndu nsŭk ăn tih nau sŏng srăng lĕ? Mâu lah Nơm Geh Lĕ Nau Brah nsŭk ăn tih đah nau di lĕ?$b$,true),
('bunong-vn','JOB',8,4,null,$b$Tơ lah phung kon may ƀư tih ma Păng, Păng ăn khân păng dơn nau tâm rmal yor nau tih khân păng hŏ ƀư jêh.$b$,true),
('bunong-vn','JOB',8,5,null,$b$Tơ lah may gơih joi Brah Ndu, jêh ri vơh vơl ma Nơm Geh Lĕ Nau Brah,$b$,true),
('bunong-vn','JOB',8,6,null,$b$jêh ri tơ lah may jêng rsang jêh ri sŏng srăng, pô ri n'hêl nanê̆ Păng mra dâk kơl may, jêh ri chiă uănh may ăn ueh jêng nau nkhôm ma may.$b$,false),
('bunong-vn','JOB',8,7,null,$b$Jêh ri nđâp tơ lah aƀaơ ri may jêng jê̆, ƀiă lah kêng dăch lôch may mra jêng toyh ngăn.$b$,true),
('bunong-vn','JOB',8,8,null,$b$“Gâp vơh vơl ma may, ôp hom ma phung rô̆ kăl e, jêh ri ôp sek hom moh nau phung chô yau mâp saơ jêh;$b$,true),
('bunong-vn','JOB',8,9,null,$b$Yor lah he jêng knŏng phung mbe, jêh ri mâu gĭt âk nau ôh, jêh ri rnôk he gŭ rêh ta neh ntu jêng nâm bu du ntŭk nde n'hâm.$b$,false),
('bunong-vn','JOB',8,10,null,$b$Mâu hĕ khân păng mra nti ma may jêh ri nkoch ma may, jêh ri ngơi nau khân păng gĭt rbăng jêh hĕ?$b$,true),
('bunong-vn','JOB',8,11,null,$b$“Dơi lĕ tơm siăt hon tâm ntŭk mâu geh trâp? Dơi lĕ treng chăt hom ntŭk mâu geh dak ôh?$b$,true),
('bunong-vn','JOB',8,12,null,$b$Tơ lah hôm chăt nse, mâu hŏ bu muyh ôh, khân păng lĕ ơm kro jêh ma gơ̆ tơm si êng.$b$,true),
('bunong-vn','JOB',8,13,null,$b$Pô nây yơh nau tât ma lĕ rngôch phung chuêl ma Brah Ndu; nau kâp gân phung bunuyh mâu chroh ôh ma Brah Ndu mra rai lôch$b$,true),
('bunong-vn','JOB',8,14,null,$b$Nau păng rnơm-nsing lĕ roh jêh, jêh ri ntŭk păng nsing gơnh tăch nâm bu ntêng vĭl.$b$,false),
('bunong-vn','JOB',8,15,null,$b$Bunuyh nây nsing ma ngih vâl păng nơm, ƀiă lah ngih kŏ mâu nâp lĕ; păng kuăn rdâng ô băl, ƀiă lah ô băl mâu hôm dơi nâp ôh.$b$,true),
('bunong-vn','JOB',8,16,null,$b$Nâm bu tơm si chăt nse ta duh nar, nkeh păng chăt nkâm lam tâm n'gar păng.$b$,true),
('bunong-vn','JOB',8,17,null,$b$Reh păng sŏr tâm mbŭch lŭ păng hon ta nklang nđa lŭ.$b$,true),
('bunong-vn','JOB',8,18,null,$b$Tơ lah bu rôk păng tă bơh ntŭk păng, pô ri ntŭk păng gŭ jêh mra dun ma păng, lah: “Gâp mâu mâp saơ may ôh?”$b$,true),
('bunong-vn','JOB',8,19,null,$b$Nây jêng nau răm maak ma trong păng. Mra geh si gơ̆ êng luh hon tă bơh neh.$b$,true),
('bunong-vn','JOB',8,20,null,$b$“Aơ, Brah Ndu mâu mra dun ôh ma bunuyh sŏng srăng, mâu lĕ mra kơl ma bunuyh djơh mhĭk.$b$,true),
('bunong-vn','JOB',8,21,null,$b$Ƀiă lah Kôranh Brah mra mbêng ăn trôm mbung may gơm maak; Jêh ri may mra răm rhơn.$b$,true),
('bunong-vn','JOB',8,22,null,$b$Phung tâm rmot mra bêng ma nau bêk prêng. Jêh ri ngih bok phung ƀai mra rai lôch.”$b$,true),
('bunong-vn','JOB',9,1,null,$b$Y-Yôp plơ̆ lah ma Y-Bildat:$b$,true),
('bunong-vn','JOB',9,2,null,$b$N'hêl nanê̆ gâp gĭt nau nây jêng di; ƀiă lah mâm kon bunuyh ƀư gay dơi geh nau sŏng tra năp măt Brah Ndu?$b$,false),
('bunong-vn','JOB',9,3,null,$b$Tơ lah bu ŭch tâm dun đah Brah Ndu, bu mâu dơi plơ̆ sĭt lah ma păng ôh du tơ̆ tâm du rbăn, kŏ mâu geh lĕ.$b$,true),
('bunong-vn','JOB',9,4,null,$b$Brah Ndu geh nau mĭn blau, jêh ri bêng ma nau brah. Mbu moh ƀư dăng đah Păng dơi ueh lĕ?$b$,true),
('bunong-vn','JOB',9,5,null,$b$Brah Ndu yơh dơi rlơk trơn yôk, jêh ri nklơ̆ rlă khân păng yor nau păng ji nuih, ƀiă lah yôk mâu gĭt ôh.$b$,true),
('bunong-vn','JOB',9,6,null,$b$Păng rgu neh ntu tă bơh mbon păng, jêh ri lĕ meh păng mpât n'gơ.$b$,true),
('bunong-vn','JOB',9,7,null,$b$Păng ntĭnh ma măt nar, jêh ri păng mâu hôm luh ôh. Păng nkŭm mănh mâu ăn khân păng chrang ôh.$b$,true),
('bunong-vn','JOB',9,8,null,$b$Knŏng êng Păng dơm ling ăn dĭ trôk, jêh ri chuat hăn ta klơ n'ha dak rbuh.$b$,true),
('bunong-vn','JOB',9,9,null,$b$Păng njêng mănh Mbing, mănh Ôritôn, mănh Plêat jêh ri mănh tâm bri rđŭng.$b$,true),
('bunong-vn','JOB',9,10,null,$b$Păng ƀư lĕ kan toyh ngăn rmeh ma nau gĭt rbăng, jêh ri nau khlay mâu hôm dơi kơp ôh.$b$,true),
('bunong-vn','JOB',9,11,null,$b$Aơ, Păng hăn rgăn dăch gâp, jêh ri gâp mâu saơ Păng ôh; Păng hăn n'hot, ƀiă lah gâp mâu năl Păng ôh.$b$,true),
('bunong-vn','JOB',9,12,null,$b$Tơ lah Păng nhŭp rdu, mbu nơm dơi buay păng? Mbu nơm dơi lah păng: ‘Moh may ƀư nây?’$b$,true),
('bunong-vn','JOB',9,13,null,$b$“Brah Ndu mâu dơi djoh ôh nau Păng ji nuih; Phung kơl Rahap chon mon tâm dâng Păng,$b$,false),
('bunong-vn','JOB',9,14,null,$b$Pô nây mâm gâp dơi plơ̆ sĭt lah ma Păng, jêh ri joi rplay ngơi gay tâm dun đah Păng!$b$,false),
('bunong-vn','JOB',9,15,null,$b$Nđâp tơ lah gâp gŭ sŏng kđôi lĕ, ăt gâp mâu jo lĕ tâm dun đah Păng; ƀiă lah knŏng gâp vơl dăn nau yô̆bơh Nơm phat dôih ma gâp.$b$,true),
('bunong-vn','JOB',9,16,null,$b$Tơ lah gâp vơl dăn ma Păng jêh ri Păng plơ̆ lah ma gâp, gâp mâu hŏ lah nchroh ôh Păng iăt jêh nau ngơi gâp.$b$,true),
('bunong-vn','JOB',9,17,null,$b$Yor lah Păng ăn phŭt chuănh ƀư cha lôt gâp, jêh ri lơ hâu ntop nau sôt gâp âk lơn mâu geh nau ôh.$b$,true),
('bunong-vn','JOB',9,18,null,$b$Păng mâu ăn ôh gâp nsôr n'hâm ƀiă lah Păng mbêng gâp ma nau rngot ngăn ngên.$b$,true),
('bunong-vn','JOB',9,19,null,$b$Tơ lah tâm rlong ma nau dăng ktang, Păng yơh geh nau dơi! Tơ lah ma nau phat dôih, Păng lah: “Mbu nơm janh nduyh nkra gâp?”$b$,true),
('bunong-vn','JOB',9,20,null,$b$Nđâp tơ lah gâp gŭ sŏng kđôi lĕ, trôm mbung gâp mra ngơi mpơl jêh nau tih gâp nơm; nđâp tơ lah gâp jêng sŏng srăng păng mra ăn n'hêl nanê̆ gâp jêng kue.$b$,true),
('bunong-vn','JOB',9,21,null,$b$Nđâp tơ lah gâp mâu geh tih, gâp nkoch êng gâp nơm mâu khlay ôh; gâp tâm rmot ma nau rêh gâp.$b$,true),
('bunong-vn','JOB',9,22,null,$b$Lĕ rngôch tâm ban da dê, yor nây gâp lah: ‘Păng ƀư rai bunuyh sŏng nđâp bunuyh tih lĕ.’$b$,true),
('bunong-vn','JOB',9,23,null,$b$Tơ lah nau ƀư rai ăn tât nau khĭt ƀât lât dơm, Păng mưch ma nau rêh ni phung mâu geh tih.$b$,false),
('bunong-vn','JOB',9,24,null,$b$Bu jao jêh phung neh ntu tâm ti phung ƀai; păng nkŭm muh măt phung kôranh phat dôih ta neh ntu. Tơ lah mâu di păng, pô ri mbu moh?$b$,true),
('bunong-vn','JOB',9,25,null,$b$“Nar gâp gŭ rêh jêng prăl lơn ma du huê nchuăt; khân păng nchuăt du mâu saơ nau ueh maak ôh.$b$,true),
('bunong-vn','JOB',9,26,null,$b$Khân păng vah rgăn nâm bu rkĭt tơm rpho, nâm bu klang pah sĭm$b$,true),
('bunong-vn','JOB',9,27,null,$b$Tơ lah gâp lah: ‘Gâp chuêl lĕ nau gâp nter, gâp mra tâm mpơl muh măt maak jêh ri gơm rum?$b$,false),
('bunong-vn','JOB',9,28,null,$b$Gâp klach krit ngăn lĕ nau nđêh nji gâp; yor lah gâp gĭt may mâu mra kơp ôh gâp jêng rsang tih.$b$,true),
('bunong-vn','JOB',9,29,null,$b$N'hêl nanê̆, Brah Ndu kơp gâp tih jêh; pô ri mâm gâp pah kan dơm dam?$b$,true),
('bunong-vn','JOB',9,30,null,$b$Tơ lah gâp ŭm ma kƀu, jêh ri rao ti gâp ma dak buh,$b$,true),
('bunong-vn','JOB',9,31,null,$b$ăt may klŭp đŏng gâp tâm dak nung, jêh ri kho ao gâp mra ƀâu chrĭ$b$,false),
('bunong-vn','JOB',9,32,null,$b$Yor lah Păng mâu di jêng kon bunuyh nâm bu gâp, dĭng gâp janh plơ̆ sĭt lah ma Păng. Gay ma he dơi tât ndrel ma nau phat dôih.$b$,false),
('bunong-vn','JOB',9,33,null,$b$Kŏ mâu geh lĕ du huê nơm ta nklang he, nơm dơi dra ti ma lĕ he bar hê,$b$,true),
('bunong-vn','JOB',9,34,null,$b$pô ri mơ Brah Ndu sŏk lơi mâng Păng dong gâp, jêh ri nau klach ma Păng mâu mra tât ma gâp đŏng ôh.$b$,false),
('bunong-vn','JOB',9,35,null,$b$Rnôk nây, gâp mra lah, mâu hôm geh nau klach ôh, yor lah gâp nơm mâu dơi ƀư pô nây ôh aƀaơ ri.$b$,true),
('bunong-vn','JOB',10,1,null,$b$“Gâp lĕ dĭl jêh ma nau rêh gâp; gâp mra nkoch mpơl lĕ nau gâp rêh ni; gâp mra ngơi ma nau rngot ngăn ngên tâm nuih n'hâm gâp.$b$,true),
('bunong-vn','JOB',10,2,null,$b$Gâp mra lah ma Brah Ndu pô aơ: Lơi ta kơp ôh gâp lĕ jêng tih jêh; ăn gâp gĭt moh nau may tâm dun đah gâp.$b$,true),
('bunong-vn','JOB',10,3,null,$b$May lĕ saơ jêh hĕ nau khlay dôl may tŭn jot gâp, ŭch tâm rmot ma kan ti may nơm ƀư, jêh ri nchrang ăn phung ƀai mĭn ŭch ƀư?$b$,true),
('bunong-vn','JOB',10,4,null,$b$May geh măt nâm bu bunuyh lĕ? May saơ nâm bu du huê bunuyh saơ lĕ?$b$,true),
('bunong-vn','JOB',10,5,null,$b$Nar may gŭ rêh nâm bu nar bunuyh gŭ rêh lĕ? Mâu lah năm may gŭ rêh nâm bu năm bunuyh lĕ?$b$,true),
('bunong-vn','JOB',10,6,null,$b$Mâm dĭng may sek uănh nau kue gâp, jêh ri joi nau tih gâp,$b$,true),
('bunong-vn','JOB',10,7,null,$b$nđâp tơ lah may gĭt jêh ma gâp mâu geh ôh nau tih, jêh ri mâu geh ôh nơm dơi tâm rklaih gâp tă bơh ti may?$b$,false),
('bunong-vn','JOB',10,8,null,$b$Ti may rhăk mon tât dơi jêng gâp; Jêh ri aƀaơ may plơ̆ ƀư rai gâp đŏng!$b$,true),
('bunong-vn','JOB',10,9,null,$b$Ăn may kah gĭt may hŏ mon jêh gâp ma neh auk; jêh ri may mra mplơ̆ lĕ gâp ma ndruyh neh?$b$,true),
('bunong-vn','JOB',10,10,null,$b$Mâu hĕ di may kêt nkhŭt gâp nâm bu dak toh ndrôk, jêh ri ƀư kŏt gâp nâm bu ƀănh dak toh ndrôk?$b$,true),
('bunong-vn','JOB',10,11,null,$b$May ăn gâp geh ntâu jêh ri nglay puăch, jêh ri pêng gâp sŏk nting tâm băr đah rse suan.$b$,true),
('bunong-vn','JOB',10,12,null,$b$May ăn ma gâp nau rêh jêh ri nau rŏng răp jăp; jêh ri may chiă uănh hŏ king prăp jêh huêng gâp.$b$,true),
('bunong-vn','JOB',10,13,null,$b$Ƀiă lah nđâp geh nau nây kđôi lĕ, may pôn ndâp lĕ nau nây tâm nuih n'hâm may, gâp gĭt nau aơ jêng nau may ŭch ƀư:$b$,true),
('bunong-vn','JOB',10,14,null,$b$Tơ lah gâp ƀư tih, may kâp rmiăng ma gâp, jêh ri lơi yô̆ ôh nau kue gâp.$b$,false),
('bunong-vn','JOB',10,15,null,$b$Tơ lah gâp jêng djơh mhĭk, di ngăn ma gâp rêh ni! Tơ lah gâp gŭ ngao sŏng srăng, kŏ mâu dơi lĕ n'gơr bôk klơ, yor lah gâp bêng ma nau prêng, jêh ri mĭn saơ nau rêh ni gâp.$b$,true),
('bunong-vn','JOB',10,16,null,$b$Tơ lah gâp jêng sưr, may mra tĭng pănh gâp tâm ban bu pănh du mlâm yau mŭr, jêh ri mpơl ma gâp nau brah may khlay ngăn ngên.$b$,true),
('bunong-vn','JOB',10,17,null,$b$May ƀư ăn mhe tay nau may ŭch ƀư ma gâp, jêh ri ntop n'hao nau nđêh nji ma gâp; may leo phung ta han mhe tâm lơh đah gâp.$b$,true),
('bunong-vn','JOB',10,18,null,$b$“Mâm dĭng may ngluh gâp tă trôm ndŭl me gâp? Ueh lơn ăn gâp khĭt rngăt, lơi ăn hôm măt bu saơ gâp!$b$,true),
('bunong-vn','JOB',10,19,null,$b$Ri mơ, gâp mra jêng tâm ban bu mâu mâp deh ôh bơh ndŭl me gâp; bu leo ro rlet tâm môch!$b$,true),
('bunong-vn','JOB',10,20,null,$b$Mâu hĕ di ma nar gâp gŭ rêh jêng djê̆ lê̆ ? Pô nây, Hơi Kôranh Brah; Lơi hôm ƀư ôh ma gâp, gay ăn gâp dơi geh djê̆ lê̆ nau bonh leng.$b$,true),
('bunong-vn','JOB',10,21,null,$b$Ê lor ma gâp hăn tâm ntŭk ngo klĕng jêh ri nau khĭt yot, tă bơh ntŭk nây gâp mâu mra plơ̆ sĭt đŏng ôh,$b$,true),
('bunong-vn','JOB',10,22,null,$b$ma bri dak rngot rvê jêh ri geh nau uh ah, mâu geh nau ang ôh knŏng nau ngo vêt vê.$b$,false),
('bunong-vn','JOB',11,1,null,$b$Y-Sôphar jêng bunuyh bri Naama, plơ̆ lah:$b$,true),
('bunong-vn','JOB',11,2,null,$b$“Jêng di lĕ ma bu mâu plơ̆ lah ôh ma nau ngơi âk ir? Bunuyh ngơi âk geh nau bu kơp sŏng lĕ?$b$,false),
('bunong-vn','JOB',11,3,null,$b$Jêng di lĕ nau may ngơi blă blơ ăn phung bunuyh gŭ klêm, jêh ri tơ lah may mưch, mâu hĕ bu ăn may geh nau bêk prêng?$b$,true),
('bunong-vn','JOB',11,4,null,$b$Yor lah may lah, ‘Ntil nau gâp chroh jêng kloh rsang, jêh ri gâp mâu geh nau ƀơ̆ ƀơch ôh ta năp măt Brah Ndu.’$b$,true),
('bunong-vn','JOB',11,5,null,$b$Ƀiă lah mâu ŭch ngăn ma Brah Ndu hă trôm mbung ngơi jêh ri ngơi ndrel ma may,$b$,false),
('bunong-vn','JOB',11,6,null,$b$gay ma Păng mbơh ma may nau ndâp tâm nau blau mĭn! Yor lah nau blau mĭn ngăn Păng geh âk lơn, pô ri ăn may gĭt ma Brah Ndu tâm rmal may nkhơng mâu khư đah nau tih may.$b$,false),
('bunong-vn','JOB',11,7,null,$b$Tơ lah may mêt uănh nanê̆, may gĭt rbăng nau jru Brah Ndu mĭn, jêh ri mâm may gĭt rbăng rah vah ma Nơm Geh Lĕ Nau Brah?$b$,true),
('bunong-vn','JOB',11,8,null,$b$Nau nây prêh lơn ma trôk moh ndơ may dơi ƀư? Nau nây jru lơn ma Ƀon Phung Khĭt moh ndơ may dơi gĭt?$b$,true),
('bunong-vn','JOB',11,9,null,$b$Tơ lah bu veh păng bu saơ jong lơn ma neh ntu, jêh ri toyh lơn ma dak mƀŭt.$b$,true),
('bunong-vn','JOB',11,10,null,$b$Tơ lah Brah Ndu hăn rgăn, jêh ri nhŭp krŭng bu, jêh ri kuăl ma nau phat dôih, mbu nơm dơi nkân buay lơi Păng?$b$,true),
('bunong-vn','JOB',11,11,null,$b$Yor lah Păng gĭt năl mbu nơm jêng phung n'hi săk, tơ lah păng saơ nau kue, ƀiă lah kon bunuyh mâu gĭt saơ ôh nau nây.$b$,true),
('bunong-vn','JOB',11,12,null,$b$Dơi lĕ du mlâm seh bri deh jêng du huê bunuyh? Kơt nây lĕ du huê bunuyh rluk tât dơi jêng ma nau blau mĭn!$b$,true),
('bunong-vn','JOB',11,13,null,$b$Pô nây, tơ lah may tâm rgâl nuih n'hâm may ăn jêng sŏng, jêh ri yơr ti may mbơh sơm ma Păng,$b$,true),
('bunong-vn','JOB',11,14,null,$b$tơ lah may mƀăr lơi nau kue may ƀư, jêh ri lơi ăn nau ƀai gŭ ndrel ma may ôh,$b$,false),
('bunong-vn','JOB',11,15,null,$b$n'hêl nanê̆ rnôk nây may mra n'gơr muh măt may mâu geh nau prêng ôh; may mra gŭ mpăn, jêh ri mâu geh klach ôh.$b$,false),
('bunong-vn','JOB',11,16,null,$b$May mra chuêl lĕ nau may rêh ni; may mra kah gĭt nau nây nâm bu dak hoch jêh.$b$,true),
('bunong-vn','JOB',11,17,null,$b$Jêh ri nau rêh may mra jêng ang lơn nâm nar nklang bôk, jêh ri nau ngo tâm nau rêh may plĕch jêng nau ang ơm ôi$b$,true),
('bunong-vn','JOB',11,18,null,$b$Jêh ri may mra geh nau rnơm ngăn, yor lah geh jêh nau kâp gân; may mra geh nau n'gang jêh ri gŭ rlu ma nau ueh mpăn.$b$,false),
('bunong-vn','JOB',11,19,null,$b$May mra lâng bêch, jêh ri mâu geh nơm nhhu may ôh; âk bunuyh mra vơh vơl gay may kơl.$b$,true),
('bunong-vn','JOB',11,20,null,$b$Ƀiă lah măt phung ƀai mra chieh; mâu hôm geh ôh ntŭk ma khân păng nchuăt krap. Jêh ri nau khân păng ŭch kâp gân, nây jêng nau tăch n'hâm.$b$,true),
('bunong-vn','JOB',12,1,null,$b$Y-Yôp plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',12,2,null,$b$“N'hêl nanê̆ khân may jêng bunuyh ngăn jêh ri mra roh tơ lah khân may khĭt.$b$,false),
('bunong-vn','JOB',12,3,null,$b$Ƀiă lah gâp geh nau gĭt rbăng nâm bu khân may lĕ; nau blau mĭn gâp mâu ir lĕ tâm dâng lơn ma khân may. Mbu nơm mâu gĭt nau tâm ban pô nây?$b$,true),
('bunong-vn','JOB',12,4,null,$b$Gâp hŏ mbơh sơm jêh ma Brah Ndu, jêh ri Brah Ndu plơ̆ lah jêh ma gâp. Aƀaơ gâp jêng bunuyh geh mĭt jiăng gâp njrŏ rlĭn; gâp nơm jêng du huê bunuyh sŏng jêh ri răp jăp, ƀiă lah nkhơng jêng du huê bunuyh bu gơm mưch!$b$,true),
('bunong-vn','JOB',12,5,null,$b$Du huê gŭ ueh mpăn geh nau mĭn tâm rmot ma nau rêh ni; nau rêh ni ntơm tât jêh ma nơm lĕ mbĭr jâng.$b$,true),
('bunong-vn','JOB',12,6,null,$b$Ngih bok phung ntŭng gŭ đăp rmên, jêh ri phung rhiăl nuih Brah Ndu gŭ mpăn tâm ti khân păng Brah Ndu ăn ndô ndơ âk rmeh.$b$,true),
('bunong-vn','JOB',12,7,null,$b$“Ƀiă lah ôp hom ma mpô mpa, jêh ri khân păng mra sâm nti khân may; jêh ri ôp hom ma sĭm, khân păng mra sâm mbơh lĕ ma khân may;$b$,true),
('bunong-vn','JOB',12,8,null,$b$mâu lah đŏng, ôp hom ma gơ̆ tơm si ta neh ntu, jêh ri khân păng mra nti ma khân may. Nđâp ka tâm dak lêng mra mbơh ma khân may lĕ.$b$,false),
('bunong-vn','JOB',12,9,null,$b$Tâm lĕ ntil mpa nây, mbu ntil mpa mâu gĭt ma ti Brah Ndu hŏ ƀư jêh lĕ nau nây?$b$,true),
('bunong-vn','JOB',12,10,null,$b$Tâm ti Brah Ndu yơh djôt nau rêh lĕ rngôch mpô mpa rêh, jêh ri n'hâm nsôr lĕ rngôch bunuyh tâm ban lĕ.$b$,true),
('bunong-vn','JOB',12,11,null,$b$Mâu di hĕ tôr kâp iăt nau ngơi nâm bu trôm mbung chiăm ndơ sông sa?$b$,true),
('bunong-vn','JOB',12,12,null,$b$Phung bu bŭnh bu ranh geh nau blau mĭn, jêh ri geh nau gĭt rbăng yor nau jŏk rêh.$b$,true),
('bunong-vn','JOB',12,13,null,$b$“Nau blau mĭn jêh ri nau brah gŭ tâm Brah Ndu; nau blau nchră jêh ri nau gĭt rbăng jêng ndơ Brah Ndu.$b$,true),
('bunong-vn','JOB',12,14,null,$b$Tơ lah Păng ƀư rai, mâu geh bunuyh dơi ndâk đŏng ôh. Tơ lah Păng krŭng du huê bunuyh, mâu geh nơm dơi pơk ôh.$b$,true),
('bunong-vn','JOB',12,15,null,$b$Tơ lah Păng nkrŭl dak, dak mra suăt; tơ lah Păng ăn dak hoch, dak lip bri neh.$b$,true),
('bunong-vn','JOB',12,16,null,$b$Tâm Păng geh nau brah jêh ri blau mĭn; nơm bu ndơm jêh ri nơm ndơm bu jêng ndơ Păng.$b$,true),
('bunong-vn','JOB',12,17,null,$b$Păng ăn phung nchră ƀư nâm bu rluk, jêh ri ăn phung kôranh phat dôih jêng nkhơng brŭt rluk.$b$,true),
('bunong-vn','JOB',12,18,null,$b$Păng doh lơi rse rvăk phung hađăch kât, jêh ri vân rse rvăk ta gang bŭt khân păng$b$,true),
('bunong-vn','JOB',12,19,null,$b$Păng ăn phung kôranh ƀư brah jêng bună, jêh ri n'glưh lơi phung ktang.$b$,false),
('bunong-vn','JOB',12,20,null,$b$Păng ăn mlo phung nchră bu vay nsing ma păng, jêh ri sŏk rdu lơi nau blau mĭn phung bu ranh.$b$,true),
('bunong-vn','JOB',12,21,null,$b$Păng ăn bu mưch ma phung kôranh, jêh ri doh lơi rse vân bŭt phung ktang.$b$,true),
('bunong-vn','JOB',12,22,null,$b$Păng tâm mpơl moh nau bu pôn ndâp jêh tâm nau ngo, jêh ri njêng gui nau khĭt ăn ma nau ang.$b$,true),
('bunong-vn','JOB',12,23,null,$b$Păng ăn phung mpôl bunuyh văch ma hao toyh, jêh ri ƀư rai lơi khân păng. Păng ăn bĭk rơ̆ bri dak khân păng, jêh ri ƀư n'hŭch lơi khân păng đŏng.$b$,true),
('bunong-vn','JOB',12,24,null,$b$Păng sŏk lơi nau gĭt rbăng tă bơh phung kôranh ƀon lan ta neh ntu. Jêh ri ăn khân păng hăn mblêng Tâm bri rdah mâu geh trong ôh.$b$,true),
('bunong-vn','JOB',12,25,null,$b$Khân păng rvơ tâm ntŭk ngo mâu geh nau ang; jêh ri ăn khân păng chuat hăn ndiu ndao nâm bu bunuyh nhŭl. Y-Yôp Mpơl Păng Jêng Sŏng.$b$,true),
('bunong-vn','JOB',13,1,null,$b$Aơ, măt gâp lĕ saơ jêh lĕ nau nây, tôr gâp lĕ tăng jêh ri gĭt rbăng jêh nau nây.$b$,true),
('bunong-vn','JOB',13,2,null,$b$Moh nau khân may gĭt, gâp gĭt tâm ban lĕ, gâp mâu jêng tâm dâng lơn khân may ôh.$b$,true),
('bunong-vn','JOB',13,3,null,$b$Ƀiă lah gâp ŭch ngơi ma Nơm Geh Lĕ Nau Brah. Jêh ri ŭch tâm dun gâp đah Brah Ndu.$b$,true),
('bunong-vn','JOB',13,4,null,$b$Bi ma khân may, khân may mhĭng mâu mƀruh ma nau ngăn; lĕ rngôch khân may jêng nai dak si dơm dam.$b$,true),
('bunong-vn','JOB',13,5,null,$b$Khân may ŭch ngăn gŭ klăk klêm! Nau nây mra jêng nau blau mĭn ma khân may.$b$,true),
('bunong-vn','JOB',13,6,null,$b$Pô nây, iăt hom nau gâp tâm dun, jêh ri kâp iăt ma nau bâr mbung gâp vơh vơl.$b$,true),
('bunong-vn','JOB',13,7,null,$b$Mâm khân may dơi janh ngơi ntang ma Brah Ndu ma nau vĭ lĕ? Jêh ri ngơi ntang ma Brah Ndu ma nau ndơm lĕ?$b$,true),
('bunong-vn','JOB',13,8,null,$b$Khân may mra gŭ mpeh Brah Ndu lĕ? Khân may mra ngơi dôih tâm rlăch Nau di đah Brah Ndu lĕ?$b$,true),
('bunong-vn','JOB',13,9,null,$b$Mâm ƀư tơ lah Păng sek uănh ma khân may, khân may jêng ueh ma nau nây lĕ? Khân may dơi lĕ ndơm Păng nâm bu khân may ndơm du huê bunuyh?$b$,true),
('bunong-vn','JOB',13,10,null,$b$N'hêl nanê̆ Păng mra nduyh ma khân may, tơ lah khân may tĭng nding du đah.$b$,true),
('bunong-vn','JOB',13,11,null,$b$Mâu di hĕ nau rnam Păng mra nhhu nkrit khân may, jêh ri nau ƀư nkrit Păng mra ăn tât ma khân may?$b$,true),
('bunong-vn','JOB',13,12,null,$b$Nau khân may ngơi hôr jêng nâm bu nau hôr ŭnh buh,$b$,true),
('bunong-vn','JOB',13,13,null,$b$Gŭ rklăk hom khân may gay ma gâp ngơi, Moh nau tât ma gâp kđôi lĕ$b$,false),
('bunong-vn','JOB',13,14,null,$b$Gâp mra ƀư tĭng nâm nau gâp ŭch ƀư, nđâp tơ lah mra ƀư roh nau rêh gâp kđôi lĕ.$b$,false),
('bunong-vn','JOB',13,15,null,$b$Nđâp tơ lah Kôranh Brah nkhĭt gâp kđôi lĕ, ăt gâp mra nsing ma Păng;$b$,true),
('bunong-vn','JOB',13,16,null,$b$ƀiă lah gâp king nau gâp ƀư ta năp muh măt Păng.$b$,false),
('bunong-vn','JOB',13,17,null,$b$Iăt hom nanê̆ nau gâp ngơi, jêh ri ăn nau gâp mbơh lăp tâm trôm tôr khân may.$b$,true),
('bunong-vn','JOB',13,18,null,$b$Aơ, gâp hŏ nkra jêh nau gâp mra ngơi king; gâp gĭt ma gâp mra geh nau ngơi di.$b$,true),
('bunong-vn','JOB',13,19,null,$b$Geh lĕ nơm ŭch tâm dun đah gâp? Pô nây tơ lah gâp gŭ klăk, jêng gâp lĕ khĭt jêh.$b$,true),
('bunong-vn','JOB',13,20,null,$b$Knŏng geh bar ntil nau ăn ma gâp, pô ri gâp mâu mra pôn krap ôh gâp nơm tă bơh muh măt may:$b$,true),
('bunong-vn','JOB',13,21,null,$b$Dăn Kôranh Brah rhuăt lơi ti may ngai đah gâp, jêh ri lơi may ăn nau klach krit may nhhu nkrit gâp.$b$,false),
('bunong-vn','JOB',13,22,null,$b$Jêh ri kuăl hom gâp, pô ri gâp mra plơ̆ sĭt lah, mâu lah gâp ngơi, jêh ri ăn may plơ̆ lah ma gâp.$b$,true),
('bunong-vn','JOB',13,23,null,$b$Ndah nâm âk nau kue jêh ri nau tih gâp? Dăn Kôranh Brah ăn gâp gĭt nau gâp rlau nau vay jêh ri nau tih gâp.$b$,true),
('bunong-vn','JOB',13,24,null,$b$Mâm may pôn muh măt may jêh ri kơp nkhơng gâp jêng rlăng ma may?$b$,true),
('bunong-vn','JOB',13,25,null,$b$May mra nkrit lĕ du n'ha sial đô̆ rdu jêh, jêh ri tĭng rhe lĕ kro jêh?$b$,true),
