('bunong-vn','JOB',13,27,null,$b$may lĕ nkông jêh jâng gâp, jêh ri kâp uănh ma lĕ trong gâp hăn; may tâm nal n'har jêh ma ntŭk jâng gâp hăn.$b$,false),
('bunong-vn','JOB',13,28,null,$b$Bi ma gâp ntơm ôm lêk nâm bu ndơ ôm, nâm bu bok ao nchiăr reh jêh.$b$,true),
('bunong-vn','JOB',14,1,null,$b$“Bunuyh deh jêh tă bơh bu ur gŭ rêh knŏng ƀât lât, jêh ri bêng ma nau rêh ni.$b$,true),
('bunong-vn','JOB',14,2,null,$b$Păng dang nâm bu kao si, jêh ri huănh ro; păng trơn nâm bu gui n'hâm, mâu hôm saơ ôh.$b$,true),
('bunong-vn','JOB',14,3,null,$b$Nđâp tơ lah pô nây, Kôranh Brah hôm lin măt uănh ma du huê tâm ban pô nây lĕ? Jêh ri ăn gâp văch tât dơn nau phat dôih ta năp may lĕ?$b$,true),
('bunong-vn','JOB',14,4,null,$b$Mbu nơm dơi du luh bơh nau ƀơ̆ dơi sŏk nau kloh? Du huê kŏ mâu geh lĕ!$b$,true),
('bunong-vn','JOB',14,5,null,$b$Yor lah may lĕ nal jêh nar ma păng gŭ rêh, jêh ri may nal ndah nâm khay prăp ma păng, mâu lĕ păng dơi rlau rmeh ma nar may hŏ tâm nal jêh.$b$,true),
('bunong-vn','JOB',14,6,null,$b$Pô nây dăn Kôranh Brah lơi hôm treng uănh ma păng ƀiă lah ăn ma ô băl dơi gŭ mpăn, gay ma păng geh nau răm maak dôl păng gŭ rêh nâm bu du huê pah kan nkhôm.$b$,true),
('bunong-vn','JOB',14,7,null,$b$“Yor lah tơm si geh nau kâp gân tơ lah bu lĕ kăl jêh, ăt păng mra chăt tay đŏng; jêh ri hon nkeh mâu geh rlu ôh.$b$,true),
('bunong-vn','JOB',14,8,null,$b$Nđâp tơ lah reh păng tâm neh lĕ kranh kđôi lĕ, jêh ri tơm păng lĕ kro jêh,$b$,true),
('bunong-vn','JOB',14,9,null,$b$ƀiă lah tơ lah geh dak păng mra chăt nse đŏng jêh ri n'gĭng nâm bu tơm si nse.$b$,false),
('bunong-vn','JOB',14,10,null,$b$Ƀiă lah bunuyh khĭt, jêh ri bu tâp păng; bunuyh tăch n'hâm, jêh ri păng mâu hôm ôh.$b$,true),
('bunong-vn','JOB',14,11,null,$b$Nâm bu dak nglao lĕ suăt jêh ri dak n'hor suăt kroh jêh,$b$,true),
('bunong-vn','JOB',14,12,null,$b$pô nây lĕ bunuyh khĭt mâu hôm dâk rêh đŏng ôh; kŏ tât mâu hôm geh trôk ôh, păng mâu hôm kah rngăl ôh, mâu lĕ bu dơi rlay păng.$b$,false),
('bunong-vn','JOB',14,13,null,$b$May ŭch ngăn pôn gâp tâm Ƀon Phung Khĭt gay nkŭm ndâp lơi gâp kŏ tât lôch nar nau may ji nuih jêh, gay tâm nal rô̆ ma gâp, jêh ri kah gĭt ma gâp rnôk nây!$b$,true),
('bunong-vn','JOB',14,14,null,$b$Tơ lah du huê bunuyh khĭt, păng mra dâk rêh lĕ? Du bông nar tâm lơh đah gâp, gâp mra gŭ kâp, ndah nâm jŏ tât dĭng gâp dơi kon me$b$,true),
('bunong-vn','JOB',14,15,null,$b$may mra kuăl, jêh ri gâp mra plơ̆ sĭt lah, may mra klân rvê đŏng ma kan ti may lĕ ƀư jêh.$b$,false),
('bunong-vn','JOB',14,16,null,$b$Ƀiă lah aƀaơ ri, may kơp lĕ nhuat gâp chuat, may mâm dĭng mâu uănh nau tih gâp ƀư jêh?$b$,true),
('bunong-vn','JOB',14,17,null,$b$Lĕ nau tih gâp ƀư may lĕ nsĭr pôn tâm trôm dŭng, Jêh ri may mra nkŭm lơi lĕ nau kue gâp.$b$,true),
('bunong-vn','JOB',14,18,null,$b$“Ƀiă lah yôk chah rlâm jêh tât jêng neh muy, jêh ri lĕ rlă trơn tă bơh ntŭk păng nơm,$b$,true),
('bunong-vn','JOB',14,19,null,$b$jêh ri dak rchoh lŭ; dak thăng koch rdu lĕ neh; tâm ban pô nây lĕ may ƀư rai nau bunuyh kâp gân.$b$,false),
('bunong-vn','JOB',14,20,null,$b$May ŭch dong jêh ri lĕ dơi may jêh đah kon bunuyh, pô nây păng lĕ du hăn jêh.$b$,true),
('bunong-vn','JOB',14,21,null,$b$Tơ lah phung kon bu klâu păng tât ma nau bu yơk, păng mâu gĭt nau nây ôh; tơ lah bu ntrŭnh khân păng, păng mâu saơ nau nây ôh.$b$,true),
('bunong-vn','JOB',14,22,null,$b$Păng gĭt knŏng nau ji săk jăn păng nơm, jêh ri nhhiăng nhĭm knŏng ma păng nơm.$b$,true),
