('bunong-vn','JOB',15,13,null,$b$Moh nau dĭng nau mĭn may ŭch tâm rdâng đah Brah Ndu, jêh ri luh ngơi tâm ban pô nây lĕ rlau keh ir?$b$,true),
('bunong-vn','JOB',15,14,null,$b$Moh bunuyh jêng kŏ tât păng dơi jêng kloh rsang? Mâu lah nơm deh jêh tă bơh bu ur kŏ tât păng jêng sŏng?$b$,true),
('bunong-vn','JOB',15,15,null,$b$Aơ, Brah Ndu mâu rnơm ôh ma phung kloh ueh Păng, kŏ tât phung trôk mâu jêng kloh ngăn ôh ta năp măt Păng.$b$,true),
