('bunong-vn','JOB',15,19,null,$b$knŏng ma phung nây bu ăn jêh bri jêh ri mâu geh ôh phung bu năch gŭ ndrel ma khân păng.$b$,false),
('bunong-vn','JOB',15,20,null,$b$Du bông rêh bunuyh tih mpât săk jăn ma nau ji dôl ăn lĕ năm bu nal jêh ma phung djơh djơt.$b$,true),
('bunong-vn','JOB',15,21,null,$b$Păng tăng nteh klach krit ngăn; dôl geh nau ueh mpăn nơm ƀư rai mra tât ma păng.$b$,true),
('bunong-vn','JOB',15,22,null,$b$Păng ntôn lah mâu dơi du luh ôh tă bơh nau ngo, jêh ri bu thăm jêh păng ma nau khĭt đah đao.$b$,true),
('bunong-vn','JOB',15,23,null,$b$Păng hăn ntŭk aơ rlau ntŭk ri gay joi ndơ sông sa, jêh ri lah: “Ndơ sa ta ntŭk joi?” Păng gĭt ma nar geh nau ngo dăch tât jêh;$b$,true),
