('bunong-vn','JOB',15,28,null,$b$jêh ri păng hŏ gŭ jêh tâm ƀon rngol, tâm chuanh rŭng sat, mâu hôm bu gŭ ôh, bu thăm jêh jêng mbŭch lŭ ndơ lĕ rai jêh.$b$,false),
('bunong-vn','JOB',15,29,null,$b$Păng mâu mra jêng ndrŏng ôh; drăp ndơ păng tâm ban lĕ mâu hôm kơn jŏ jong ôh; mâu lĕ hôm sŏr reh lam ta klơ neh;$b$,true),
('bunong-vn','JOB',15,30,null,$b$păng mâu mra klaih ôh tă bơh nau ngo, mpiăt ŭnh hŭr kro lơi nkeh păng, jêh ri sial nsôr n'hâm Kôranh Brah đô̆ rdu păng.$b$,false),
('bunong-vn','JOB',15,31,null,$b$Lơi ta rnơm ôh ma nau dơm dam păng nơm, jêng du nau ndơm; yor lah nau dơm dam jêng nau nkhôm ma păng.$b$,true),
('bunong-vn','JOB',15,32,null,$b$Bu mra nkhôm păng lĕ nŭm lor tât nar păng, jêh ri n'gĭng păng mâu hôm jêng nse ôh.$b$,true),
('bunong-vn','JOB',15,33,null,$b$Păng ngrưh lơi play vĭt nâm bu du tơm play kriăk ƀâu. Păng rgu rŭng kao păng nâm bu du tơm play ôlivơ.$b$,true),
('bunong-vn','JOB',15,34,null,$b$Yor lah phung noi bunuyh ƀai mra jêng ndrô gâng, jêh ri ŭnh mra sa ngih bok phung sŏk dơn drăp sa bêch.$b$,true),
('bunong-vn','JOB',15,35,null,$b$Păng ntreo ma nau mhĭk, jêh ri deh ma nau ƀai, jêh ri nuih n'hâm khân păng nkra nau ndơm.$b$,true),
('bunong-vn','JOB',16,1,null,$b$Y-Yôp plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',16,2,null,$b$“Gâp tăng jêh âk nau tâm ban pô nây; lĕ rngôch khân may jêng phung njung leng dơm dam mâu khlay ôh.$b$,false),
('bunong-vn','JOB',16,3,null,$b$Nau ngơi mâu geh kô̆ mâm dĭng mâu lôch? Mbu moh ntrôl dĭng khân may ngơi nây?$b$,true),
('bunong-vn','JOB',16,4,null,$b$Gâp ŭch dơi ngơi nâm bu khân may ngơi lĕ; Tơ lah huêng khân may ntrok ăn huêng gâp, Gâp dơi ngơi nduyh khân may tâm ban lĕ jêh ri rteh bôk ma khân may.$b$,true),
('bunong-vn','JOB',16,5,null,$b$Ƀiă lah nau gâp ngơi dơi ƀư ktang khân may, jêh ri ma nau gâp ngơi bonh mra ăn hŭch nau ji khân may.$b$,true),
('bunong-vn','JOB',16,6,null,$b$“Nđâp tơ lah gâp ngơi, nau ji gâp mâu hŭnh ôh; jêh ri tơ lah gâp gŭ rklăk, nau ji mâu du ôh bơh gâp.$b$,true),
('bunong-vn','JOB',16,7,null,$b$N'hêl nanê̆ aƀaơ Brah Ndu ƀư ăn gâp rgănh jêh, Kôranh Brah hŏ ăn roh lĕ rngôch ngih vâl gâp.$b$,true),
('bunong-vn','JOB',16,8,null,$b$Kôranh Brah hŏ ƀư ma gâp huănh nhop jêh, nau nây jêng nau mbơh tâm rdâng đah gâp. Nau rgay gâp nây jêng mbơh tâm rdâng ma gâp đŏng, Nduyh lah tra năp măt gâp.$b$,true),
('bunong-vn','JOB',16,9,null,$b$Păng nkhêk jêh gâp dôl păng ji nuih, jêh ri joi nau ƀư ma gâp, păng rchiăt sêk ŭch lơh gâp; nơm rlăng ma gâp uănh ntơ̆ măt ma gâp.$b$,true),
('bunong-vn','JOB',16,10,null,$b$Khân păng hă mbung ŭch kăp sa gâp, tap bom gâp ma nau uănh ntêh; khân păng rgum băl ŭch ƀư ma gâp.$b$,true),
('bunong-vn','JOB',16,11,null,$b$Brah Ndu hŏ jao gâp ma phung mâu chroh ôh, jêh ri mƀăr lơi gâp tâm ti phung ƀai.$b$,true),
('bunong-vn','JOB',16,12,null,$b$Gâp kăl e ueh mpăn, Păng lơh ndjơh gâp, Păng glăn trô ko gâp jêh ri piăch gâp hăch rhên. Păng pla gâp nâm bu mut păng,$b$,true),
('bunong-vn','JOB',16,13,null,$b$phung djôt hăr na Păng nchueng jŭm gâp. Păng pănh pŭng vĕ gâp, mâu blau yô̆ ôh; păng ăn huch dak play măt gâp ta neh.$b$,false),
('bunong-vn','JOB',16,14,null,$b$Păng ntâp gâp bluh bah aơ rho ari. Rduh lơh gâp nâm bu du huê bunuyh dăng tâm lơh.$b$,true),
('bunong-vn','JOB',16,15,null,$b$Gâp jĭm ao kroh dâr săk jăn gâp, jêh ri gâp pung bôk gâp tâm neh muy.$b$,true),
('bunong-vn','JOB',16,16,null,$b$Muh măt gâp gŭr yor gâp nhĭm, jêh ri gui nau khĭt ta n'gô măt gâp;$b$,true),
('bunong-vn','JOB',16,17,null,$b$ƀiă lah ti gâp mâu ƀư nau ƀai ôh, jêh ri nau gâp mbơh sơm jêng kloh rsang.$b$,false),
('bunong-vn','JOB',16,18,null,$b$Hơi neh, lơi brôi mham gâp! jêh ri ăn gâp nter ma nau kon me mâu geh nau nkân ôh.$b$,true),
('bunong-vn','JOB',16,19,null,$b$Aƀaơ ri ro yơh, Nơm mbơh ma gâp gŭ klơ trôk, jêh ri Nơm ăn nanê̆ ngăn gâp gŭ ta klơ.$b$,true),
('bunong-vn','JOB',16,20,null,$b$Phung mĭt jiăng gâp mưch ma gâp. Bi gâp nhĭm luh dak măt ma Brah Ndu,$b$,true),
('bunong-vn','JOB',16,21,null,$b$gay ma Păng king nau di ta nklang du huê bunuyh đah Brah Ndu, ta nklang kon bunuyh jêh ri nơm chiau meng păng.$b$,false),
('bunong-vn','JOB',16,22,null,$b$Yor lah hôm djê̆ năm mra tât, jêh nây gâp mra hăn trong gâp mâu mra plơ̆ sĭt đŏng ôh.$b$,true),
('bunong-vn','JOB',17,1,null,$b$N'hâm gâp ntơm lôch, nar gâp ntơm lĕ, bu nkra jêh môch ma gâp!$b$,true),
('bunong-vn','JOB',17,2,null,$b$N'hêl nanê̆ geh phung mưch gŭ jŭm gâp, jêh ri măt gâp gŭ uănh ma nau khân păng mưch rmot.$b$,true),
('bunong-vn','JOB',17,3,null,$b$“Dăn Kôranh Brah ăn ma gâp dơi geh du nau king n'gang; sâm ăn hom ma gâp gŭ êp may; yor lah pa dih may mbu nơm mra sâm njrăng an ma gâp?$b$,true),
('bunong-vn','JOB',17,4,null,$b$Yor lah may ăn nuih n'hâm khân păng mâu gĭt rbăng, yor nây may mâu mra n'hao ăn ma khân păng dơi ôh.$b$,true),
('bunong-vn','JOB',17,5,null,$b$Mbu nơm phung ma mĭt jiăng păng ŭch pit in du kô̆ drăp ndơ ô băl, măt phung kon păng mra jêng ngo.$b$,true),
('bunong-vn','JOB',17,6,null,$b$Ƀiă lah Brah Ndu njêng gâp jêng ndơ ƀon lan ntêh rmot, jêh ri gâp jêng du huê bunuyh bu soh dak diu.$b$,true),
('bunong-vn','JOB',17,7,null,$b$Măt gâp lĕ blak yor nau rngot, jêh ri lĕ rngôch jâng ti gâp jêng nâm bu gui.$b$,true),
('bunong-vn','JOB',17,8,null,$b$Phung bunuyh sŏng srăng hih rhâl ma nau nây, bi ma bunuyh gŭ sŏng mra hao nuih ŭch ƀư đah nơm mhĭk nây.$b$,true),
('bunong-vn','JOB',17,9,null,$b$Ƀiă lah bunuyh sŏng mra hăn nâp tâm trong păng, jêh ri bunuyh geh ti kloh mra jêng lơ hâu ktang lơn.$b$,true),
('bunong-vn','JOB',17,10,null,$b$Ƀiă lah, hơi khân may, lĕ rngôch ngơi hom đŏng; ƀiă lah gâp mâu saơ ôh tâm khân may geh du huê bunuyh blau ngăn.$b$,true),
('bunong-vn','JOB',17,11,null,$b$Lĕ nau gâp rêh hŏ lôch jêh, lĕ mbor nau gâp ŭch mĭn, jêng nau ŭch ndrăp mĭn tâm nuih n'hâm, hŏ roh hêng jêh.$b$,true),
('bunong-vn','JOB',17,12,null,$b$Khân păng ngơi rlơ̆ nôk nar jêng măng; pa năp nau ngo, khân păng lah, ‘Nau ang bơi ŭch tât jêh!’$b$,true),
('bunong-vn','JOB',17,13,null,$b$Tơ lah gâp gŭ kâp Ƀon Phung Khĭt jêng ngih ma gâp, tơ lah gâp nkra sưng bêch gâp tâm ntŭk ngo,$b$,false),
('bunong-vn','JOB',17,14,null,$b$tơ lah gâp ngơi ntĭt lah, ma ntu môch: ‘May yơh jêng mbơ̆ gâp,’ jêh ri lah ma rhai: ‘Mê̆ gâp,’ mâu lah ‘Yuh gâp’,$b$,false),
('bunong-vn','JOB',17,15,null,$b$pô ri ta ntŭk nau gâp gŭ kâp gân? Nau gâp kâp gân, mbu nơm mra saơ?$b$,false),
('bunong-vn','JOB',17,16,null,$b$Tơ lah gâp dơn nau gŭ rlu tâm ndruyh neh, pô ri nanê̆ nau kâp gân nây mra hăn trŭnh tâm mpông Ƀon Phung Khĭt.$b$,true),
('bunong-vn','JOB',18,1,null,$b$Y-Bildat bunuyh n'gor bri Suah plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',18,2,null,$b$“Ndah nâm jŏ may lĕ joi nau gay ŭch ngơi nây? Rvê mĭn hom, jêh ri he mra ngơi.$b$,false),
('bunong-vn','JOB',18,3,null,$b$Mâm dĭng may uănh ma hên nâm bu mpô mpa? Jêh ri rluk mâl tra năp măt may?$b$,true),
('bunong-vn','JOB',18,4,null,$b$May hao ji nuih gay ŭch tor ƀư sôt êng may nơm, mâu hĕ yor ma may ri dĭng neh ntu mra jêng rngol, jêh ri bu mra rlă lĕ lŭ tă bơh ntŭk păng yor may?$b$,true),
('bunong-vn','JOB',18,5,null,$b$N'hêl nanê̆ bu nhhât lơi nau ang phung ƀai, jêh ri mpiăt ŭnh păng mâu mra nchrat ang ôh$b$,true),
('bunong-vn','JOB',18,6,null,$b$Nau ang tâm ngih bok păng jêng ngo, jêh ri bu nhhât lơi ŭnh kađen êp kêng păng.$b$,false),
('bunong-vn','JOB',18,7,null,$b$Bu ăn gleh lơi nhuat jong păng, Nau plĕch rlăm păng ŭch ƀư ăn văk prah êng păng nơm.$b$,true),
('bunong-vn','JOB',18,8,null,$b$Yor lah jâng păng nơm geh jot tâm dăk jêh ri păng hăn ta klơ bu dâr ma nhuăl ƀư rhuh păng.$b$,true),
('bunong-vn','JOB',18,9,null,$b$Păng geh dăk ta ndơl jâng păng, nhuăl rêt păng.$b$,true),
('bunong-vn','JOB',18,10,null,$b$Bu drŭp rse dăk tâm neh, jêh ri bu dơm ta rlong păng gay geh ntơt păng.$b$,true),
('bunong-vn','JOB',18,11,null,$b$Nau krit klach gŭ jŭm păng, Jêh ri tĭng groi pa kơi ăp nhuat chuat păng.$b$,true),
('bunong-vn','JOB',18,12,null,$b$Nau dăng ktang păng lĕ huơi jêh yor ji ngot, nau rêh ni gŭ kâp kêng meng păng.$b$,true),
('bunong-vn','JOB',18,13,null,$b$Nau ji sa lơi ntâu păng, kon bôk rah nau khĭt ƀư rai jâng ti păng.$b$,true),
('bunong-vn','JOB',18,14,null,$b$Păng lĕ bu mphâk tă bơh ngih bok păng gŭ mpăn, jêng ntŭk păng nsing. Pô nây bu leo păng ma hađăch Nau krit klach toyh lơn.$b$,true),
('bunong-vn','JOB',18,15,null,$b$Mâu geh du huê băl păng gŭ tâm ngih bok păng ôh; bu nkhŭt lŭ ŭnh ta klơ ngih păng.$b$,true),
('bunong-vn','JOB',18,16,null,$b$Reh păng kro tâm dâng. Jêh ri ta klơ lĕ te n'gĭng.$b$,true),
('bunong-vn','JOB',18,17,null,$b$Bu mâu hôm kah gĭt ma păng ôh ta neh ntu, jêh ri păng mâu geh lư n'găr ôh tâm n'gor.$b$,true),
('bunong-vn','JOB',18,18,null,$b$Păng lĕ bu mƀăr tă bơh ntŭk ang lăp tâm nau ngo. Jêh ri bu mpet păng tă bơh neh ntu.$b$,true),
('bunong-vn','JOB',18,19,null,$b$Păng mâu mra geh kon sau ôh ta nklang phung ƀon lan păng, du huê hôm e rêh kŏ mâu geh lĕ ta ntŭk păng gŭ;$b$,true),
('bunong-vn','JOB',18,20,null,$b$Phung bơh n'gor bri pa dâng hih rhâl ma nau tât ma păng; jêh ri nau krit ktang ngăn tât ma phung bơh bri pa lơ.$b$,false),
('bunong-vn','JOB',18,21,null,$b$N'hêl nanê̆ nây jêng ntŭk ma phung ƀai, jêh ri nây jêng ntŭk mâu gĭt năl Brah Ndu ôh.”$b$,true),
('bunong-vn','JOB',19,1,null,$b$Y-Yôp plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',19,2,null,$b$“Ndah nâm jŏ may ƀư nđêh nji gâp, jêh ri nchah gâp hăch rhên ma nau ngơi?$b$,false),
('bunong-vn','JOB',19,3,null,$b$Aơ jêng jât tơ̆ jêh may nduyh gâp; may mâu prêng ôh ƀư nau mhĭk ma gâp.$b$,true),
('bunong-vn','JOB',19,4,null,$b$Nđâp tơ lah ngăn gâp jêng tih jêh, nau tih gâp hôm e ndrel ma gâp nơm.$b$,true),
('bunong-vn','JOB',19,5,null,$b$Tơ lah ngăn khân may ŭch n'hao may nơm ƀư ma gâp, jêh ri sŏk nau rêh ni gâp jêng nau khân may gay ŭch har plơng đah gâp.$b$,true),
('bunong-vn','JOB',19,6,null,$b$Pô ri, ăn khân may gĭt jêng Brah Ndu yơh ƀư ma gâp, jêh ri văk tâm nhuăl Păng nthăng jŭm gâp. Aơ gâp nter, “Geh nau djơh mhĭk!”$b$,true),
('bunong-vn','JOB',19,7,null,$b$Ƀiă lah gâp mâu gay ma bu plơ̆ sĭt lah ôh; Gâp vơh vơl bu kơl, ƀiă lah bu mâu ƀư nau di ôh.$b$,true),
('bunong-vn','JOB',19,8,null,$b$Kôranh Brah king trong gâp, pô ri gâp mâu dơi lăn ôh, jêh ri Păng nkŭm ăn nau ngo klĕng rgŏ trong gâp hăn.$b$,true),
('bunong-vn','JOB',19,9,null,$b$Păng doh lơi jêh nau chrêk rmah gâp, jêh ri sŏk rdu lơi đon hađăch bơh bôk gâp.$b$,true),
('bunong-vn','JOB',19,10,null,$b$Păng ƀư nchah gâp văr jŭm chiau meng kŏ tât gâp rai lôch; păng rôk nau gâp kâp gân nâm bu rôk du tơm si.$b$,true),
('bunong-vn','JOB',19,11,null,$b$Păng hao ji nuih ma gâp tâm ban lĕ, kơp gâp jêng du huê nơm rlăng păng$b$,true),
('bunong-vn','JOB',19,12,null,$b$Phung ta han Păng văch rduh ndrel; khân păng nchueng ŭch ƀư ma gâp, jêh ri gŭ jŭm ngih bok gâp.$b$,false),
('bunong-vn','JOB',19,13,null,$b$“Păng rđah phung oh nâu gâp ăn gŭ ngai đah gâp, Jêh ri ăn phung mĭt jiăng gâp jêng bunăch ngăn ngên ma gâp.$b$,true),
('bunong-vn','JOB',19,14,null,$b$Băl mpôl gâp lĕ cha lơi jêh gâp, jêh ri phung mĭt lăng jiăng sŏng lĕ chuêl jêh ma gâp.$b$,true),
('bunong-vn','JOB',19,15,null,$b$Phung gŭ tâm ngih gâp, jêh ri oh mon, bu ur gâp kơp gâp jêng du huê bu năch. Ta năp măt khân păng, gâp hŏ jêng jêh du huê bunuyh bu êng.$b$,true),
('bunong-vn','JOB',19,16,null,$b$Gâp kuăl oh mon gâp, ƀiă lah khân păng mâu hôm plơ̆ lah ôh ma gâp; nđâp tơ lah gâp vơl ma păng ma bâr mbung gâp ăt tâm ban lĕ.$b$,true),
('bunong-vn','JOB',19,17,null,$b$Nsôr n'hâm gâp ƀư ăn ur tâm rmot ma gâp, jêh ri kon bu klâu mê̆ gâp nuih ma nau gâp vơl dăn.$b$,true),
('bunong-vn','JOB',19,18,null,$b$Kŏ tât phung kon se jê̆ mưch rmot ma gâp tâm ban lĕ; tơ lah gâp dâk khân păng ntêh rmot ma gâp.$b$,true),
('bunong-vn','JOB',19,19,null,$b$Phung mĭt jiăng gâp răp jăp tâm rmot ngăn ma gâp. Phung gâp rŏng jêh plơ̆ ƀư rlăng đŏng đah gâp.$b$,true),
('bunong-vn','JOB',19,20,null,$b$Nting gâp lĕ tâm dop đah ntâu jêh ri mpơl nting nđăng dơm, Gâp hŏ klaih jêh knŏng hôm e dơm ntâu dâr lưnh sêk gâp.$b$,true),
('bunong-vn','JOB',19,21,null,$b$Hơi phung mĭt jiăng gâp, yô̆ an hom ma gâp, yô̆ an hom ma gâp! Yor lah ti Brah Ndu dong jêh gâp.$b$,false),
('bunong-vn','JOB',19,22,null,$b$Mâm ƀư khân may tĭng nhŭp gâp tâm ban ma Brah Ndu, jêh ri ê hŏ hơm đŏng ma puăch gâp?$b$,true),
('bunong-vn','JOB',19,23,null,$b$“Ơ! Ŭch ngăn bu lĕ chih jêh nau gâp ngơi! Ŭch ngăn ăn bu dơi chih păng tâm du ndrom sămƀŭt!$b$,true),
('bunong-vn','JOB',19,24,null,$b$Ŭch ngăn ma mâng chih loih jêh ri ndrak bu tor păng ta klơ lŭ gay ndray hôm mro mrăng!$b$,true),
('bunong-vn','JOB',19,25,null,$b$Bi gâp, gâp gĭt Nơm Tâm Chuai gâp ăt hôm rêh. Kŏ tât nar kêng lôch Păng dâk ta neh ntu.$b$,true),
('bunong-vn','JOB',19,26,null,$b$Jêh ri tơ lah ntâu gâp lĕ rai jêh ăt tâm săk jăn gâp mra saơ Brah Ndu,$b$,true),
('bunong-vn','JOB',19,27,null,$b$gâp mra saơ Păng ma măt gâp nơm yơh, mâu di ma bu êng ôh. Nuih n'hâm gâp lĕ huăr jêh!$b$,false),
('bunong-vn','JOB',19,28,null,$b$Tơ lah khân may lah: ‘Mâm he mra tĭng păng?’ Jêh ri ‘Tơm nau jêr aơ luh tă păng nơm.’$b$,true),
('bunong-vn','JOB',19,29,null,$b$Klach hom ma mpiăt đao, Yor lah đao jêng ndơ tâm lơh janh djơh ngăn ŭch rmal nau tih mhĭk. Gay ăn khân may gĭt geh nau phat dôih.”$b$,false),
('bunong-vn','JOB',20,1,null,$b$Y-Sôphar, bunuyh n'gor Naama plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',20,2,null,$b$Yor nau nây ntĭm nti ma gâp plơ̆ sĭt lah, jêh ri yor nây gâp ngơi ro.$b$,false),
('bunong-vn','JOB',20,3,null,$b$Gâp hŏ tăng nau bu nduyh: Jêng nau bu suai rak ma gâp; jêh ri sŏk bơh nau gâp blau mĭn tâm nau mĭn gâp găn gâp plơ̆ sĭt lah.$b$,true),
('bunong-vn','JOB',20,4,null,$b$Ăn gĭt rah vah hom pô aơ, bơh rô̆ kăl e ntơm bơh rnôk bu dơi dơm bunuyh ta neh ntu,$b$,true),
('bunong-vn','JOB',20,5,null,$b$nau dơi phung ƀai jêng ƀât lât, jêh ri nau răm maak phung mâu chroh knŏng du tơ̆ nây dơm.$b$,false),
('bunong-vn','JOB',20,6,null,$b$Nđâp tơ lah nau păng sưr rlau hao tât klơ trôk, jêh ri bôk păng tom (tât) ta tŭk,$b$,true),
('bunong-vn','JOB',20,7,null,$b$păng mra rai lôch n'ho ro nâm bu ek păng nơm. Phung lĕ tă mâp saơ păng mra ôp lah: ‘Ta ntŭk păng gŭ?’$b$,false),
('bunong-vn','JOB',20,8,null,$b$Păng mra roh hêt nâm bu mbơi măng, jêh ri bu mâu hôm mâp păng đŏng ôh. Nanê̆ ngăn, păng mra roh nâm bu saơ huêng măng.$b$,false),
('bunong-vn','JOB',20,9,null,$b$Măt vay uănh păng, mâu mra saơ păng đŏng ôh. Ntŭk păng gŭ kŏ mâu hôm saơ păng đŏng.$b$,true),
('bunong-vn','JOB',20,10,null,$b$Phung kon păng mra dăn ndơ phung o ach, jêh ri ti păng mra mplơ̆ lơi ndơ păng lĕ sŏk jêh ndơ bu.$b$,true),
('bunong-vn','JOB',20,11,null,$b$Jâng ti păng bêng ma nau ktang dôl hôm mom; ƀiă lah mra gŭ ndrel păng ta nar păng khĭt.$b$,true),
('bunong-vn','JOB',20,12,null,$b$“Nđâp tơ lah nau ƀai jêng nau ngơi ueh tâm trôm mbung păng, nđâp tơ lah păng pôn tâm dâng mpiăt păng.$b$,true),
('bunong-vn','JOB',20,13,null,$b$Jêh ri mâu ŭch cha lơi păng ôh, kân păng tâm trôm mbung păng,$b$,true),
('bunong-vn','JOB',20,14,null,$b$ƀiă lah ndơ păng sa tâm rgâl jêng mhĭk tâm khŭng proch păng jêh ri jêng kăch bêh ku tâm trôm ndŭl păng.$b$,false),
('bunong-vn','JOB',20,15,null,$b$Păng sa rvăn ndô ndơ, jêh ri hok tay pa dih; Brah Ndu mra huai ndơ nây ngluh tă bơh ndŭl păng.$b$,true),
('bunong-vn','JOB',20,16,null,$b$Păng mra djrêp nhêt dak kăch bêh ku; mpiăt bêh rmâng mra nkhĭt păng.$b$,true),
('bunong-vn','JOB',20,17,null,$b$Păng mâu mra saơ dak krong jêh ri n'hor dak sŭt hoch nđâp ma dak toh ndrôk luh hoch.$b$,true),
('bunong-vn','JOB',20,18,null,$b$Păng mra mplơ̆ ăn nau geh bơh kan păng pah, mâu dơi dŏng ôh; păng ntrok lơi tĭng rnoh khlay păng, mâu geh sa kao bơh ndơ păng tăch rgâl.$b$,true),
('bunong-vn','JOB',20,19,null,$b$Yor lah păng jot plên jêh ri mâu chrê ôh ma phung o ach, pit in ngih vâl păng mâu mâp prot ndâk ôh.$b$,true),
('bunong-vn','JOB',20,20,null,$b$“Yor tă nau păng kơnh mâu blau mpay păng mâu mra prăp ôh du ntil ndơ păng ŭch nây.$b$,true),
('bunong-vn','JOB',20,21,null,$b$Mâu hôm geh ôh ndơ hôm e ma păng sông sa. Pô nây nau chăt hao păng mâu mra gŭ jŏ ôh.$b$,true),
('bunong-vn','JOB',20,22,null,$b$Dôl păng geh ăp ntil ndô ndơ nau rêh ni mra tât ma păng; Phung bunuyh rêh ni mra har plơng ma du huê păng.$b$,true),
('bunong-vn','JOB',20,23,null,$b$Brah Ndu mra njuăl nau Păng hao ji nuih ƀư ma păng. Gay ƀư ăn bêng tâm nuih n'hâm păng, jêh ri Păng mra ăn tât nau nây ma păng dôl păng gŭ sông sa.$b$,true),
('bunong-vn','JOB',20,24,null,$b$Nđâp tơ lah păng du nchuăt ma ndơ tâm lơh bu ƀư ma loih, Hôm hăr kông mra tĭng păng kŏ băm jru ngăn.$b$,true),
('bunong-vn','JOB',20,25,null,$b$Păng tŏk lơi hăr tă tâm săk jăn păng chiông hăr mplanh sôr ta klơm păng; Nau klach toyh ƀư nkrit păng.$b$,true),
('bunong-vn','JOB',20,26,null,$b$Lĕ nau ngo jêng ndơ bu prăp ma păng; ŭnh bu mâu khôm mra sa păng jêh ri bunuyh hôm tâm ngih bok păng mra ŭnh sa lĕ rngôch.$b$,true),
('bunong-vn','JOB',20,27,null,$b$Trôk mra tâm mpơl nau kue păng, jêh ri neh ntu mra dâk tâm rdâng đah păng.$b$,true),
('bunong-vn','JOB',20,28,null,$b$Ndô ndơ tâm ngih păng bu mra gro nchuăn lĕ; bu mra nchuăn tâm nar Brah Ndu ji nuih.$b$,true),
('bunong-vn','JOB',20,29,null,$b$Nây ro yơh jêng kô̆ Brah Ndu prăp ma bunuyh ƀai, jêh ri nây jêng drăp ndơn Brah Ndu hŏ rơm ơm jêh ma păng.$b$,true),
('bunong-vn','JOB',21,1,null,$b$Y-Yôp plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',21,2,null,$b$“Iăt hom ăn nanê̆ nau gâp ngơi; ăn nau nây jêng nau bonh leng khân may.$b$,false),
('bunong-vn','JOB',21,3,null,$b$Srôih iăt gâp, gay ăn gâp ngơi: Hŏ lôch jêh nau gâp ngơi, khân may mưch tay hom.$b$,true),
('bunong-vn','JOB',21,4,null,$b$Bi ma gâp, nau gâp ngơi vơl săk geh ngơi nter tât ma bu lĕ? Mâm dĭng nau mĭn gâp mâu blau nsrôih?$b$,true),
('bunong-vn','JOB',21,5,null,$b$Uănh hom ma gâp, jêh ri hih rhâl hom, sŏk ti rdêp lơi mbung păng nơm.$b$,true),
('bunong-vn','JOB',21,6,null,$b$Tơ lah gâp nklân ma nau nây gâp klach ngăn, jêh ri săk jăn gâp jêng nsâr êng.$b$,true),
('bunong-vn','JOB',21,7,null,$b$Mâm dĭng phung ƀai gŭ rêh kŏ tât ranh, jêh ri nau dơi chăt jêng?$b$,true),
('bunong-vn','JOB',21,8,null,$b$Phung noi deh khân păng njêng gay ăn măt khân păng saơ, jêh ri nđâp kon sau khân păng đŏng.$b$,true),
('bunong-vn','JOB',21,9,null,$b$Ngih vâl khân păng gŭ mpăn mâu geh ntil klach ôh, jêh ri Brah Ndu mâu hôm dong khân păng ôh.$b$,true),
('bunong-vn','JOB',21,10,null,$b$Ndrôk nkuăng khân păng tâm jơng mâu ach ôh, jêh ri ndrôk me deh kon mâu geh rlêh lĕ.$b$,true),
('bunong-vn','JOB',21,11,null,$b$Khân păng ăn phung kon se jê̆ khân păng pâl rlưn nâm bu du phung biăp, jêh ri phung kon sau khân păng ta lô̆ pâl ndrel.$b$,true),
('bunong-vn','JOB',21,12,null,$b$Khân păng mpât mprơ tĭng nteh gâr jêh ri gong rêng, jêh ri răm maak ma nau uh n'hôm uh rlet.$b$,true),
('bunong-vn','JOB',21,13,null,$b$Khân păng gŭ rêh tâm nau ƀun lap du bông nau rêh khân păng, jêh nây hăn ma Ƀon Phung Khĭt ueh lĕ.$b$,true),
('bunong-vn','JOB',21,14,null,$b$Khân păng lah ma Brah Ndu pô aơ: “May gŭ ngai hom đah hên, Yor lah hên mâu ŭch ôh gĭt nau nti bơh may.”$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JOB',21,15,null,$b$Mbu moh Nơm Geh Lĕ Nau Brah, gay hên pah kan ma Păng? Moh nau khlay tơ lah hên mbơh sơm ma Păng?$b$,true),
('bunong-vn','JOB',21,16,null,$b$Aơ, nau ƀun lap khân păng mâu hôm gŭ tâm ti khân păng nơm ôh: Lĕ nau ƀai phung kue ƀah ngai đah gâp.$b$,true),
('bunong-vn','JOB',21,17,null,$b$Ŭnh kađen nau ang phung ƀai lĕ nhhât, Nau rai yot tât ma khân păng, Pô nây nau Brah Ndu ji nuih ăn nau nđêh nji ma khân păng, Mâm nau nây mâu hĕ mra tât?$b$,true),
('bunong-vn','JOB',21,18,null,$b$Mâu hĕ khân păng jêng nâm bu rhe sial đô̆, nâm bu lâk phŭt chuănh khôm mpruh.$b$,true),
('bunong-vn','JOB',21,19,null,$b$Khân may lah: Brah Ndu têm prăp nau kue khân păng gay rơm tâm rmal ăn ma phung kon khân păng nơm, gay ăn khân păng nơm gĭt nau nây.$b$,true),
('bunong-vn','JOB',21,20,null,$b$Ăn măt khân păng nơm saơ nau ƀư rai tât ma khân păng, jêh ri ăn khân păng nhêt nau Nơm Geh Lĕ Nau Brah ji nuih.$b$,true),
('bunong-vn','JOB',21,21,null,$b$Yor lah tơ lah nar bu nal ma khân păng gŭ rêh lĕ lôch jêh, mâm dĭng khân păng mâu chrê ma phung kon khân păng du nar kăndơ̆ ?$b$,true),
('bunong-vn','JOB',21,22,null,$b$Brah Ndu phat dôih ma phung gŭ ta klơ; pô nây, geh lĕ nơm sâm nti an nau gĭt rbăng Păng?$b$,true),
('bunong-vn','JOB',21,23,null,$b$Du huê aơ khĭt tô dôl geh nau dăng ktang săk jăn, geh nau đăp mpăn Jêh ri mleh rmên,$b$,true),
('bunong-vn','JOB',21,24,null,$b$săk jăn păng lay rmŏng ma dak toh jêh ri glo nting păng bêng ma dak rêh.$b$,false),
('bunong-vn','JOB',21,25,null,$b$Du huê êng khĭt nđêh nji tâm huêng, Mâu mâp chiăm lep ôh nau ueh.$b$,true),
('bunong-vn','JOB',21,26,null,$b$Tâm ban lĕ khân ô băl gŭ tâm trôm môch ndrĭt rhai sa ô băl.$b$,true),
('bunong-vn','JOB',21,27,null,$b$“Aơ, gâp gĭt nau khân may mĭn, jêh ri nau khân may ŭch ƀư mhĭk ma gâp.$b$,true),
('bunong-vn','JOB',21,28,null,$b$Yor lah khân may lah: “Ta ntŭk ngih nơm djơh mhĭk? Ngih bok nơm ƀai ntŭk tra păng?”$b$,true),
('bunong-vn','JOB',21,29,null,$b$Mâu hĕ khân may mâp ôp ma phung hăn rŏ trong? Dĭng lah mâu tă bơh nau khân păng sâm mbơh an,$b$,true),
('bunong-vn','JOB',21,30,null,$b$tâm nar ƀư rai, phung mhĭk dơi klaih, jêh ri tâm nar geh nau ji nuih păng dơi nchuăt klaih?$b$,false),
('bunong-vn','JOB',21,31,null,$b$Tra năp măt păng, mbu nơm janh nduyh păng, yor nau di păng hŏ ƀư jêh?$b$,true),
('bunong-vn','JOB',21,32,null,$b$Bu tung leo păng rlet tâm môch jêh ri bu mra gak njrăng môch păng.$b$,true),
('bunong-vn','JOB',21,33,null,$b$Glo neh tâm rlŭng ƀư ăn nđik rngêt ma păng; lĕ rngôch bunuyh groi tĭng păng, jêh ri phung lĕ hăn lor ma păng mâu hôm dơi kơp ôh.$b$,true),
('bunong-vn','JOB',21,34,null,$b$Pô ri, mâm khân may dơi bonh leng gâp ma nau dơm dam? Nau khân may plơ̆ sĭt lah jêng nau mƀruh.”$b$,true),
('bunong-vn','JOB',22,1,null,$b$Y-Êlipas, bunuyh ƀon Teman plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',22,2,null,$b$“Moh nau khlay kon bunuyh ăn ma Brah Ndu? Bunuyh blau mĭn knŏng ăn nau khlay ma păng nơm dơm.$b$,false),
('bunong-vn','JOB',22,3,null,$b$Nđâp tơ lah may jêng sŏng, geh lĕ nau maak may ƀư ma Nơm Geh Lĕ Nau Brah? Nau may gŭ rêh nanê̆ ngăn bu mâu dơi nduyh ôh, nau nây moh nau khlay may ăn ma Păng?$b$,true),
('bunong-vn','JOB',22,4,null,$b$Di lĕ yor may klach yơk ma păng, păng nduyh may, jêh ri phat dôih may?$b$,true),
('bunong-vn','JOB',22,5,null,$b$Nau khĭt may mâu hĕ jêng toyh ngăn? Phung oh mon may ntôn may lah mâu lĕ glăm ngăn?$b$,true),
('bunong-vn','JOB',22,6,null,$b$Yor lah may hŏ sŏk jêh ndơ bu nchăm bơh oh nâu may mâu geh ntil nau ôh. Jêh ri doh lơi bok ao phung bunuyh ăn bu gŭ rhôk.$b$,true),
('bunong-vn','JOB',22,7,null,$b$May mâu mâp ăn ma phung ji hir dăn dak nhêt, mâu ŭch ăn ôh ma bunuyh ji ngot sông sa.$b$,true),
('bunong-vn','JOB',22,8,null,$b$Bi may lĕ geh jêng jêh neh, mir lĕ jêng ndơ may; bunuyh bu yơk lĕ gŭ jêh ta neh nây.$b$,true),
('bunong-vn','JOB',22,9,null,$b$May mprơh lơi phung bu ur ndrô sĭt ma mpang ti dơm, jêh ri nkêch lơi ti, phung kon đơi mâu hôm geh ntŭk nsing rnơm.$b$,true),
('bunong-vn','JOB',22,10,null,$b$Yor nau nây, dăk sân jŭm may, jêh ri nau ƀư nkrit ƀât lât dơi ƀư ma may nđêh nji;$b$,true),
('bunong-vn','JOB',22,11,null,$b$Mâu lah nau ngo nkŭm kŏ tât may mâu hôm saơ ang ôh, jêh ri dak lip bŭk nkrâm may.$b$,false),
('bunong-vn','JOB',22,12,null,$b$“Mâm Brah Ndu mâu hĕ gŭ tâm trôk prêh ta klơ? Uănh hom phung mănh mbing, khân păng gŭ ta ntŭk prêh hâu ngăn ngên!$b$,true),
('bunong-vn','JOB',22,13,null,$b$Bi ma may lah, ‘Moh nau Brah Ndu gĭt’ Mâm, Păng dơi lĕ phat dôih jêh ri uănh tâm ntŭk ngo klĕng?$b$,true),
('bunong-vn','JOB',22,14,null,$b$Tŭk mbâl nklâm lơi Păng, kŏ tât păng mâu dơi saơ ôh; Păng hăn ta klơ phung trôk nđôch.$b$,true),
('bunong-vn','JOB',22,15,null,$b$Mâm may ăt hôm djôt prăp tĭng trong kăl e jêng trong phung ƀai hŏ hăn jêh?$b$,true),
('bunong-vn','JOB',22,16,null,$b$Bu nhŭp rdu khân păng lor pa năp ma đah nar tâm nal ma khân păng; bu ngroh lơi ntŭk mbon nau rêh khân păng nâm bu dak blôn rdu roh.$b$,true),
('bunong-vn','JOB',22,17,null,$b$Khân păng lah ma Brah Ndu pô aơ: ‘May du ngai hom đah hên’ jêh ri lah đŏng: ‘Moh ndơ Nơm Geh Lĕ Nau Brah dơi ƀư ma hên?’$b$,true),
('bunong-vn','JOB',22,18,null,$b$Nđâp tơ lah pô nây, Păng hŏ ƀư ma ngih khân păng bêng ma ndơ ueh. Ăn nau phung ƀai nchră gŭ ngai đah gâp.$b$,false),
('bunong-vn','JOB',22,19,null,$b$Phung sŏng saơ nau nây jêh ri răm maak; bi phung mâu geh nau tih gơm mưch ma khân păng, jêh ri lah:$b$,true),
('bunong-vn','JOB',22,20,null,$b$‘N'hêl nanê̆, phung rlăng hên mra rai lôch jêh, jêh ri ndô ndơ khân păng hôm e cha lơi ŭnh sa lĕ ƀhiau.’$b$,false),
('bunong-vn','JOB',22,21,null,$b$Yor nây, may tâm rnglăp hom đah Brah Ndu, jêh ri may mra geh nau đăp mpăn: Pô ri nau ueh lăng mra tât ma may.$b$,false),
('bunong-vn','JOB',22,22,null,$b$Sŏk dơn hom nau vay nti tă bơh trôm mbung Păng, Jêh ri djôt prăp nau Păng ngơi tâm nuih n'hâm may.$b$,true),
('bunong-vn','JOB',22,23,null,$b$Tơ lah may plơ̆ sĭt ma Nơm Geh Lĕ Nau Brah ma nau dêh rhêt nanê̆ may mra njêng tay. Tơ lah may cha lơi lĕ nau kue bơh ngih bok may.$b$,true),
('bunong-vn','JOB',22,24,null,$b$Mƀăr lơi drăp khlay may tâm neh may. Jêh ri sŏk mah bơh bri Ôphir klŭp lơi Ta nklang lŭ tâm dak n'hor.$b$,true),
('bunong-vn','JOB',22,25,null,$b$Pô ri ăn may kơp Nơm Geh Lĕ Nau Brah jêng mah ma may. Păng jêng prăk khlay lơn ma may,$b$,true),
('bunong-vn','JOB',22,26,null,$b$yor lah rnôk nây, may mra răm rhơn ma Nơm Geh Lĕ Nau Brah jêh ri dơi n'gơr muh măt may leo Brah Ndu.$b$,false),
('bunong-vn','JOB',22,27,null,$b$May mra mbơh sơm ma Păng, Păng mra iăt dơn bâr may. Jêh ri Păng mra ƀư ăn nanê̆ ngăn ndơ may ton.$b$,true),
('bunong-vn','JOB',22,28,null,$b$Tơ lah may ton ngăn lĕ nau may ŭch, nanê̆ kan may mra dơi jêng, jêh ri nau ang mra sol nchrat rŏ trong may.$b$,true),
('bunong-vn','JOB',22,29,null,$b$Tơ lah, bu ƀư gay ŭch ntrŭnh may, pô ri may mra lah, Du dâk hom! Bi ma phung dêh rhêt Brah Ndu mra tâm rklaih;$b$,true),
('bunong-vn','JOB',22,30,null,$b$Kŏ tât Păng mra tâm rklaih nơm geh nau tih tâm ban lĕ; n'hêl nanê̆ nơm nây dơi tâm rklaih yor tă bơh ti may jêng kloh.”$b$,false),
('bunong-vn','JOB',23,1,null,$b$Y-Yôp plơ̆ sĭt lah;$b$,true),
('bunong-vn','JOB',23,2,null,$b$“Nđâp nar aơ gâp lŭng nter jêng rngot lơn. Ti păng ntŭn klơ gâp jâk lơn ma nau gâp lŭng nter.$b$,false),
('bunong-vn','JOB',23,3,null,$b$Ơ! Ntŭk gâp joi gay ŭch mâp ma Kôranh Brah, gay ma gâp dơi tât pa năp sưng hađăch Păng!$b$,true),
('bunong-vn','JOB',23,4,null,$b$Pô ri gay gâp nkoch nau gâp geh ta năp măt Păng, jêh ri ngơi tâm rlăch ăn lĕ nau.$b$,true),
('bunong-vn','JOB',23,5,null,$b$Gâp mra gĭt nau Păng plơ̆ lah ma gâp, Jêh ri gĭt rbăng nau Păng ŭch ngơi ndrel ma gâp.$b$,true),
('bunong-vn','JOB',23,6,null,$b$Păng mra tâm rlăch đah gâp ma lĕ nau brah toyh Păng lĕ? Mâu ôh, Păng mra gŭ iăt ma gâp.$b$,true),
('bunong-vn','JOB',23,7,null,$b$Ta nây du huê bunuyh sŏng dơi ngơi tâm rlăch đah Păng, jêh ri gâp dơi klaih bơh nơm phat dôih ma gâp ƀa ƀơ.$b$,true),
('bunong-vn','JOB',23,8,null,$b$Aơ, gâp hăn tât lor, ƀiă lah mâu geh Păng ta nây; gâp plơ̆ pa kơi, ƀiă lah gâp mâu lĕ dơi saơ Păng.$b$,true),
('bunong-vn','JOB',23,9,null,$b$Gâp n'gĭl pa chiau, tơ lah Păng ƀư kan nây, ƀiă lah gâp mâu dơi gĭt năl Păng ôh. Păng krap mpeh pa ma, ri dĭng gâp mâu saơ Păng.$b$,true),
('bunong-vn','JOB',23,10,null,$b$Ƀiă lah Kôranh Brah gĭt trong gâp hăn; Tơ lah Păng rlong uănh gâp, gâp mra jêng chrêk nâm bu mah.$b$,true),
('bunong-vn','JOB',23,11,null,$b$Jâng gâp tĭng ndô̆ trong Păng, Gâp ăt tĭng ndô̆ trong Păng, mâu geh teng ôh.$b$,true),
('bunong-vn','JOB',23,12,null,$b$Gâp mâu mâp cha lơi ôh lĕ ntil nau vay bơh trôm mbung Păng ntăm, ăt gâp tông tĭng nau ngơi bơh bâr mbung Păng lơn ma đah nau gâp nơm ŭch.$b$,true),
('bunong-vn','JOB',23,13,null,$b$Ƀiă lah Kôranh Brah mâu blau rgâl ôh, mbu nơm dơi ăn Păng rgâl lơi? Moh ntil nau Păng ŭch, Păng mra ƀư ro yơh.$b$,true),
('bunong-vn','JOB',23,14,null,$b$Yor lah nau Păng hŏ ƀư nŭm ăn gâp, Păng mra ƀư ăn jêh ro yơh. Tâm nau mĭn Păng hôm geh âk nau tâm ban pô nây.$b$,true),
('bunong-vn','JOB',23,15,null,$b$Yor nây, gâp geh nau klach ngăn gŭ pa năp măt Păng, dôl gâp gŭ mĭn nau nây gâp klach ma Păng.$b$,true),
('bunong-vn','JOB',23,16,null,$b$Yor lah Brah Ndu ăn nuih n'hâm gâp lĕ huơi ngăn Jêh. Nơm Geh Lĕ Nau Brah ƀư nkrit ma gâp.$b$,true),
('bunong-vn','JOB',23,17,null,$b$Yor lah gâp mâu klach ôh ma nau ngo, Tâm ban lĕ mâu klach yor ma nau ngo vêt vê nkŭm lơi muh măt gâp.$b$,true),
('bunong-vn','JOB',24,1,null,$b$Di nar Nơm Geh Lĕ Nau Brah hŏ nal jêh phat dôih phung ƀai. Mâm ƀư Păng mâu ăn bu gĭt năl Păng dơi saơ nar nây?$b$,true),
('bunong-vn','JOB',24,2,null,$b$Geh bunuyh trơn ndơ tâm nal n'har neh, Sŏk ntŭng phung biăp, jêh ri veng chiăp khân păng.$b$,true),
('bunong-vn','JOB',24,3,null,$b$Khân păng pit in veng rdu seh bri phung kon đơi, khân păng sŏk ndrôk bu ur ndrô ƀư ndơ nchăm.$b$,true),
('bunong-vn','JOB',24,4,null,$b$Khân păng ăn phung o ach cha lơi bơh trong nau di; jêh ri ăn lĕ rngôch phung o ach ta bri dak du krap.$b$,true),
('bunong-vn','JOB',24,5,null,$b$Aơ, bơh ơm ôi rŭk phung o ach hăn ƀư kan hŏt khân păng, nâm bu seh bri ta bri rdah, joi ndơ sông sa ma phung kon khân păng tâm bri rdah.$b$,true),
('bunong-vn','JOB',24,6,null,$b$Khân păng rek ma khân păng nơm rhe tâm mir, jêh ri dônh play kriăk ƀâu hôm e tâm đang kriăk ƀâu phung ƀai.$b$,true),
('bunong-vn','JOB',24,7,null,$b$Du măng kŏ ang khân păng bêch kuh mâu geh bok ao ôh. Jêh ri mâu geh phôi ntâk bah ji kăt.$b$,true),
('bunong-vn','JOB',24,8,null,$b$Khân păng bĕ mih sa tâm yôk, mâu geh ntŭk nde, jêh ri gŭ mbot lŭ.$b$,true),
('bunong-vn','JOB',24,9,null,$b$Geh bunuyh tâm pit nuyh kon đơi mbơ̆ ô băl hôm e pu, jêh ri nhŭp kon phung o ach jêng ndơ nchăm.$b$,true),
('bunong-vn','JOB',24,10,null,$b$Kŏ tât bunuyh o ach hăn săk hưl mâu geh bok ao ôh, khân păng djôt ba nchăp, ma ndŭl ji ngot.$b$,true),
('bunong-vn','JOB',24,11,null,$b$Khân păng păt iet dak play ta n'gar play ôlivơ phung ƀai; khân păng jot thŭng dak play kriăk ƀâu, ƀiă lah khân păng ăt hôm ji hir.$b$,true),
('bunong-vn','JOB',24,12,null,$b$Ta nklang ƀon phung dăch khĭt gŭ vơl nđor, jêh ri huêng phung sôt rmanh vơl nter gay geh bu kơl; ƀiă lah Brah Ndu mâu chrê ôh ma nau tih khân păng mbơh sơm ăt hôm tih ta nây.$b$,true),
('bunong-vn','JOB',24,13,null,$b$Hôm geh đŏng bu êng tâm rdâng đah nau ang; Mâu gĭt ôh nau nti trong nau ang, jêh ri mâu lĕ chuat hăn tâm trong nau ang.$b$,true),
('bunong-vn','JOB',24,14,null,$b$Ƀhit ang ôi phung nkhĭt bunuyh kah rngăl bêch, nkhĭt phung rêh ni o ach; jêh ri dôl bri măng păng jêng nâm bunuyh ntŭng.$b$,true),
('bunong-vn','JOB',24,15,null,$b$Măt nơm văng tĭr tâm ban lĕ gŭ kâp kŏ tât nsrŭp măng jêh ri lah: “Mâu geh ôh bunuyh dơi saơ gâp.” Jêh ri păng put muh măt păng nơm.$b$,true),
('bunong-vn','JOB',24,16,null,$b$Dôl klong măng khân păng lôk mpir lăp tâm ngih nôk nar khân păng du krap. Khân păng mâu gĭt nau ang ôh.$b$,true),
('bunong-vn','JOB',24,17,null,$b$Ang ôi jêng nau ngo ma nau khĭt ma lĕ rngôch khân păng, yor lah khân păng gĭt nau krit klach nau ngo ma nau khĭt.$b$,true),
('bunong-vn','JOB',24,18,null,$b$“Khân păng jêng tâm ban ndơ n'gơch nđông (thông) ta klơ mpiăt dak thăng; ndô ndơ khân păng jêng ndơ bu rak rtăp jêh ta neh ntu, khân păng mâu hôm plơ̆ sĭt ôh ma đang play kriăk ƀâu.$b$,true),
('bunong-vn','JOB',24,19,null,$b$Trôk prăng jêh ri duh nar ƀư suăt lơi dak tă bơh pler; tâm ban nây lĕ Ƀon Phung Khĭt ƀư jêh ma phung geh nau tih.$b$,true),
('bunong-vn','JOB',24,20,null,$b$Nuih n'hâm mê̆ mra chuêl ma khân păng; phung ndrŭng sa nkŭr khân păng; bu mâu hôm kah gĭt đŏng ôh ma khân păng; nau djơh mhĭk mra nchôt nâm bu du tơm si.”$b$,true),
('bunong-vn','JOB',24,21,null,$b$“Khân păng pit rvan ndô ndơ bu ur ndrô gâng. Jêh ri mâu ƀư nau ueh ôh ma bu ur ndrô khĭt sai.$b$,true),
('bunong-vn','JOB',24,22,null,$b$Ƀiă lah Brah Ndu sŏk nau brah Păng djôt leo nơm ktang; Păng rdâk an bunuyh mâu hôm kâp gân dơi geh nau rêh ôh.$b$,true),
('bunong-vn','JOB',24,23,null,$b$Brah Ndu ăn ma khân păng nau ueh mpăn, jêh ri rđâng khân păng, ƀiă lah măt Păng kâp uănh ma trong khân păng.$b$,true),
('bunong-vn','JOB',24,24,null,$b$Khân păng geh nau bu n'hao knŏng ƀât lât dơm, jêh ri khân păng roh hêng, khân păng cha lôt jêh ri khĭt nâm bu lĕ rngôch bunuyh êng; bu rek khân păng nâm bu nkong ba.$b$,true),
('bunong-vn','JOB',24,25,null,$b$Tơ lah mâu di pô nây, mbu moh mra lah ăn nanê̆ ma gâp jêng du huê mƀruh ir, jêh ri tâm mpơl nau gâp lah jêng dơm dam?”$b$,true),
('bunong-vn','JOB',25,1,null,$b$Y-Bildat bunuyh n'gor bri Suah plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',25,2,null,$b$“Nau dơi jêh ri nau klach jêng ndơ Kôranh Brah, Păng ăn tât nau đăp mpăn tâm ntŭk prêh ta klơ trôk.$b$,false),
('bunong-vn','JOB',25,3,null,$b$Mbu nơm dơi kơp phung ta han Kôranh Brah? Geh lĕ ma mbu nơm Păng mâu nchrat ang ôh nau ang păng?$b$,true),
('bunong-vn','JOB',25,4,null,$b$Pô nây mâm kon bunuyh dơi jêng sŏng lĕ ta năp Brah Ndu? Mbu moh deh tă bu ur mâm dơi jêng kloh ueh.$b$,true),
('bunong-vn','JOB',25,5,null,$b$Aơ, nđâp khay mâu sol ang ôh, jêh ri mănh mbing mâu lĕ dơi jêng kloh rsang ta năp măt Păng.$b$,true),
('bunong-vn','JOB',25,6,null,$b$Lơ hâu lơn bunuyh jêng nâm bu ndrŭng, jêh ri bunuyh jêng ndrŭng!”$b$,true),
('bunong-vn','JOB',26,1,null,$b$Y-Yôp plơ̆ sĭt lah:$b$,true),
('bunong-vn','JOB',26,2,null,$b$“Moh nau may lĕ mâp kơl jêh nơm mâu geh nau ktang ôh! Moh ntil may sâm rklaih jêh ri Ma nơm mâu geh n'hâm suan ôh!$b$,false),
('bunong-vn','JOB',26,3,null,$b$Moh nau may hŏ nchră jêh ma nơm mâu geh nau blau ôh, jêh ri mbơh lĕ rĭng nŭm jêh nau blau mĭn n'hêl nanê̆ ngăn!$b$,true),
('bunong-vn','JOB',26,4,null,$b$Mbu nơm kơl jêh may ngơi, Jêh ri mbu moh huêng luh tă bơh may?$b$,true),
('bunong-vn','JOB',26,5,null,$b$Phung khĭt râm nsâr tâm dâng dak toyh, jêh ri mpô mpa gŭ tâm dak tâm ban lĕ;$b$,true),
('bunong-vn','JOB',26,6,null,$b$Ƀon Phung Khĭt mpơl lĕ ta năp măt Brah Ndu, jêh ri ntu brŏng jru mâu geh ndơ nkŭm ôh.$b$,false),
('bunong-vn','JOB',26,7,null,$b$Kôranh Brah lăk dor pa lơ ta klơ ntŭk nsoih, păng yông play neh ta ntŭk dơm dam.$b$,true),
('bunong-vn','JOB',26,8,null,$b$Păng prăp dak tâm ndâr tŭk Păng, ƀiă lah ndâr tŭk nây mâu chah ôh tâm dâng nau jâk dak.$b$,true),
('bunong-vn','JOB',26,9,null,$b$Păng nkŭm muh măt sưng hađăch Păng, jêh ri ndâr tŭk Păng lăk ta klơ păng.$b$,true),
('bunong-vn','JOB',26,10,null,$b$Păng kach rup du rvang ta klơ n'ha dak, kŏ tât ta bôl nau ang đah nau ngo.$b$,true),
('bunong-vn','JOB',26,11,null,$b$Meh jrŏng trôk mpât n'gơ jêh ri hih rhâl Brah Ndu nduyh lah.$b$,true),
('bunong-vn','JOB',26,12,null,$b$Păng sŏk nau brah păng nơm ăn dak mƀŭt gŭ rngân, ma nau blau mĭn păng ƀư chah Rahap.$b$,true),
('bunong-vn','JOB',26,13,null,$b$Ma nau brah Păng, Păng nkrơ̆ nkra phung trôk; ti Păng ntâp bêh hung nchuăt du.$b$,true),
('bunong-vn','JOB',26,14,null,$b$Nây, knŏng jêng n'har ma lĕ trong Păng; jêh ri he tăng nau păng ngơi rah rơch djo-djoch! Ƀiă lah mbu dơi gĭt rbăng nglaih nau brah Păng?$b$,true),
('bunong-vn','JOB',27,1,null,$b$Y-Yôp ngơi đŏng jêh ri lah:$b$,true),
('bunong-vn','JOB',27,2,null,$b$“Gâp sân săk jăn ma Brah Ndu, hŏ dun jêh nau di ma gâp. Nơm Geh Lĕ Nau Brah ƀư ăn huêng gâp rngot rvê hâu ngăn, jêh ri Knŏng gâp ton sân săk jăn ma Păng:$b$,false),
('bunong-vn','JOB',27,3,null,$b$Lah nsôr n'hâm hôm e tâm gâp, jêh ri n'hâm Brah Ndu gŭ tâm trôm muh gâp,$b$,false),
('bunong-vn','JOB',27,4,null,$b$nanê̆ trôm mbung gâp mâu mra ngơi nau djơh ôh, jêh ri mpiăt gâp mâu mra ngơi nau ndơm lĕ.$b$,false),
('bunong-vn','JOB',27,5,null,$b$N'hêl nanê̆ gâp mâu dơi lah ma may jêng sŏng di ôh! Kŏ tât gâp khĭt, gâp mâu dơi lah ôh gâp jêng sŏng srăng ngăn.$b$,true),
('bunong-vn','JOB',27,6,null,$b$Gâp djôt nâp nau sŏng srăng gâp, jêh ri gâp mâu mra cha lơi păng ôh; Du bông nau rêh gâp, nuih n'hâm gâp mâu mra nduyh gâp nơm ôh.$b$,true),
('bunong-vn','JOB',27,7,null,$b$“Gay ma nơm rlăng gâp jêng nâm bu bunuyh djơh mhĭk, jêh ri ăn ma nơm dâk ŭch ƀư ma gâp jêng nâm bu nơm mâu geh nau sŏng ôh.$b$,true),
('bunong-vn','JOB',27,8,null,$b$Nđâp tơ lah nơm mhĭk geh drăp ndơ, Brah Ndu sŏk rhuăt lơi huêng păng. Pô ri, nau kâp gân păng mâm mra jêng?$b$,true),
('bunong-vn','JOB',27,9,null,$b$Tơ lah nau rêh ni tât ma păng, Brah Ndu mra iăt lĕ nau păng vơl?$b$,true),
('bunong-vn','JOB',27,10,null,$b$Păng mra joi lĕ ma Nơm Geh Lĕ Nau Brah? Păng mra kuăl mbơh sơm ƀa ƀơ lĕ ma Brah Ndu?$b$,true),
('bunong-vn','JOB',27,11,null,$b$Gâp mra nti ma may nau brah Brah Ndu; moh nau Nơm Geh Lĕ Nau Brah ŭch ƀư, gâp mâu mra mo ma may ôh.$b$,true),
('bunong-vn','JOB',27,12,null,$b$“Aơ, lĕ rngôch khân may nơm hŏ saơ jêh nau nây, pô ri mâm khân may hôm e rluk ngăn?$b$,true),
('bunong-vn','JOB',27,13,null,$b$Aơ jêng nau Brah Ndu prăp ma nơm mhĭk, jêh ri drăp ndơn ma phung tŭn jot sŏk dơn tă bơh Nơm Geh lĕ Nau Brah;$b$,true),
('bunong-vn','JOB',27,14,null,$b$tơ lah kon păng hao bĭk rơ̆ , nây jêng ndơ prăp ăn ma mpiăt đao nkhĭt; bi ma phung noi deh păng geh nau sa sât ji ngot mro.$b$,false),
('bunong-vn','JOB',27,15,null,$b$Phung hôm e rêh geh nau ji tưp mra khĭt roh. Jêh ri phung bu ur ndrô khân păng mâu hôm nhĭm nhhiăng ôh.$b$,true),
('bunong-vn','JOB',27,16,null,$b$Nđâp tơ lah prăp mkrem prăk rêl nâm bu ndruyh neh, jêh ri ndrăp rơm kho ao nâm bu dak bŏk;$b$,true),
('bunong-vn','JOB',27,17,null,$b$n'hêl nanê̆ păng dơi prăp rơm, ƀiă lah nkhơng ma phung sŏng mra nsoh n'gut ndơ nây, jêh ri prăk rêl phung sŏng srăng mra tâm pă ndrel.$b$,false),
('bunong-vn','JOB',27,18,null,$b$Ngih păng lĕ ndâk jêh jêng nâm bu ntêng vĭl pêng nâm bu ndưp bunuyh gŭ chăm mir vay ndâk.$b$,true),
('bunong-vn','JOB',27,19,null,$b$Păng gŭ bêch ma nau ndrŏng, ƀiă lah mâu mra ƀư tâm ban pô nây ôh, păng lin măt păng, nau ndrŏng păng lĕ roh jêh.$b$,true),
('bunong-vn','JOB',27,20,null,$b$Nau krit klach tât ndal ma păng nâm bu dak lip. Phŭt chuănh păng dôl bri măng đô̆ rdu păng.$b$,true),
('bunong-vn','JOB',27,21,null,$b$Sial tă pa lơ đô̆ rdu păng jêh ri n'ho roh hêng; sial khôm păng tă bơh ntŭk păng gŭ.$b$,true),
('bunong-vn','JOB',27,22,null,$b$Brah Ndu ntŭp nau rêh ni ta klơ păng, mâu geh nau yô̆ klâng ôh păng ŭch ngăn gay nchuăt du klaih bơh ti Brah Ndu.$b$,true),
('bunong-vn','JOB',27,23,null,$b$Bu mra tap ti rhơn yor kan păng, jêh ri huăch gay mprơh du păng bơh ntŭk păng gŭ.$b$,true),
('bunong-vn','JOB',28,1,null,$b$N'hêl nanê̆ prăk geh ntŭk bu dơi kuyh joi tâm neh, jêh ri mah geh ntŭk bu kret ăn chrêk păng.$b$,true),
('bunong-vn','JOB',28,2,null,$b$Loih bu sŏk păng tă tâm neh, jêh ri bu ƀư lêk lŭ gay jêng kông.$b$,true),
('bunong-vn','JOB',28,3,null,$b$Bunuyh mprơh nau ngo tât tâm ntŭk jru tâm dâng neh dôl joi lŭ tâm ntŭk ngo vêt vê.$b$,true),
('bunong-vn','JOB',28,4,null,$b$Bu kuyh ntu jru ta ntŭk mâu geh bunuyh gŭ ôh. Tâm bri mbâng mâu geh nuyh hăn tât ta nây; khân păng yông êng khân păng nơm nchah yông yai ƀah ngai đah bunuyh.$b$,true),
('bunong-vn','JOB',28,5,null,$b$Neh luh du ndơ sông sa, bi tâm dâng păng nkhơng ma geh ŭnh.$b$,true),
('bunong-vn','JOB',28,6,null,$b$Tâm lŭ păng geh lŭ khlay Saphir, jêh ri bu geh joi mbuh mah ta nây.$b$,true),
('bunong-vn','JOB',28,7,null,$b$“Sĭm chôk sa mâu dơi gĭt trong aơ; jêh ri măt klang ƀŭng mâu mâp saơ trong aơ ôh.$b$,true),
('bunong-vn','JOB',28,8,null,$b$Mpa janh mâu dơi hăn klơ păng, Yau mŭr mâu dơi prot rgăn ta nây.$b$,true),
('bunong-vn','JOB',28,9,null,$b$Kon bunuyh yơr ti ƀư ma lŭ kranh, Rlơk gôl yôk tât ta mbon păng.$b$,true),
('bunong-vn','JOB',28,10,null,$b$Păng kuar trôm tâm lŭ, jêh ri măt păng saơ lĕ ntil ndơ khlay tâm trôm.$b$,true),
('bunong-vn','JOB',28,11,null,$b$Păng bât kâng n'hor dak mâu ăn khân păng hoch; leo ngluh pa dih ndơ lĕ ndâp jêh.$b$,true),
('bunong-vn','JOB',28,12,null,$b$Bi ma nau blau mĭn ta ntŭk dơi joi? Ta ntŭk geh nau gĭt rbăng?$b$,true),
('bunong-vn','JOB',28,13,null,$b$Bu mâu dơi gĭt rnoh khlay nau blau; păng mâu gŭ ta klơ neh phung gŭ rêh.$b$,true),
('bunong-vn','JOB',28,14,null,$b$Tâm brŏng jru lah: ‘Păng mâu gŭ ôh tâm gâp,’ jêh ri dak mƀŭt lah: ‘Păng mâu gŭ ndrel gâp ôh.’$b$,true),
('bunong-vn','JOB',28,15,null,$b$Mâu dơi ôh bu sŏk mah gay rgâl păng, mâu lĕ dơi njing prăk gay ŭch rvăt păng.$b$,false),
('bunong-vn','JOB',28,16,null,$b$Bu mâu dơi tâm rđĭl ôh rnoh khlay păng đah mah bơh n'gor Ôphir, mâu lah đah lŭ khlay Ônik mâu lah Saphir.$b$,true),
('bunong-vn','JOB',28,17,null,$b$Mâu dơi tâm veh rđĭl ôh păng đah mah mâu lah nglăp nar gay dơi ban păng. Mâu lĕ bu dơi tâm rgâl păng đah nhong ƀư ma mah chrêk.$b$,true),
('bunong-vn','JOB',28,18,null,$b$Bi ma nau ntĭt đah lŭ khlay tâm dâng dak rlai jêh ri đah lŭ chrêk lơp, lơi nđok lah ôh. Rnoh khlay nau blau mĭn jêng khlay lơn đah lĕ rngôch nhong khlay.$b$,true),
('bunong-vn','JOB',28,19,null,$b$Lŭ tôpas tă bơh n'gor bri Êthiôpi mâu dơi tâm rđĭl ban păng ôh, mâu lĕ bu dơi veh rnoh khlay păng đah mah chrêk.$b$,true),
('bunong-vn','JOB',28,20,null,$b$“Pô ri mbah tă luh du nau blau mĭn? Jêh ri ta ntŭk nau gĭt rbăng gŭ?$b$,true),
('bunong-vn','JOB',28,21,null,$b$Păng ăt gŭ krap ndâp ma lĕ phung gŭ rêh, jêh ri bu pôn ma phung sĭm mpăr klơ.$b$,true),
('bunong-vn','JOB',28,22,null,$b$Ntŭk brŏng jru jêh ri nau khĭt lah: ‘Hên hŏ tăng lư jêh bu nkoch ma păng.’$b$,true),
('bunong-vn','JOB',28,23,null,$b$“Brah Ndu gĭt rbăng trong dơi tât ma nau blau mĭn, jêh ri gĭt ntŭk păng gŭ.$b$,false),
('bunong-vn','JOB',28,24,null,$b$Yor lah păng uănh tât ta bôl dŭt neh ntu, jêh ri saơ lĕ rngôch ndơ tâm dâng trôk.$b$,true),
('bunong-vn','JOB',28,25,null,$b$Tơ lah Păng nal nau jâk ma sial, rnhuan njing ăn ma dak,$b$,true),
('bunong-vn','JOB',28,26,null,$b$Păng lĕ nkra jêh nau vay ma dak mih, Jêh ri trong lơp nglaih.$b$,false),
('bunong-vn','JOB',28,27,null,$b$Rnôk nây Păng saơ nau blau mĭn, jêh ri tâm mpơl păng. Păng njêng nâp ô băl jêh ri klân treng ô băl đŏng.$b$,true),
('bunong-vn','JOB',28,28,null,$b$Pô nây, păng lah ma bunuyh pô aơ: Klach yơk ma Kôranh Brah, nây jêng nau blau mĭn; der lĕ nau mhĭk, nây jêng nau gĭt rbăng.”$b$,true),
('bunong-vn','JOB',29,1,null,$b$Y-Yôp ngơi đŏng jêh ri lah:$b$,true),
('bunong-vn','JOB',29,2,null,$b$“Ơ! Ŭch ngăn gâp dơi jêng nâm bu ntơm sa ơm. Nâm bu tâm nar Brah Ndu chiă uănh jêh ma gâp;$b$,false),
('bunong-vn','JOB',29,3,null,$b$Tơ lah ŭnh kađen Kôranh Brah sol ang klơ bôk gâp, jêh ri Yor tă nau ang Păng, gâp chuat rgăn lĕ nau ngo klĕng.$b$,false),
('bunong-vn','JOB',29,4,null,$b$Nâm bu gâp jêng tâm rnôk mom ndăm, tơ lah gâp jêng mĭt Jiăng ueh ma Brah Ndu hôm uănh treng ma ngih vâl gâp.$b$,true),
('bunong-vn','JOB',29,5,null,$b$Tơ lah Nơm Geh Lĕ Nau Brah hôm e gŭ ndrel gâp, jêh ri phung kon gâp gŭ jŭm gâp.$b$,true),
('bunong-vn','JOB',29,6,null,$b$Dôl gâp rao jâng ma dak toh ndrôk jêh ri lŭ luh dak jêng n'hor dak play ôlivơ ăn ma gâp!$b$,true),
('bunong-vn','JOB',29,7,null,$b$Tơ lah gâp luh tât ta mpông pêr ƀon, bu nkra ntŭk ăn ma gâp gŭ jêng kôranh,$b$,true),
('bunong-vn','JOB',29,8,null,$b$Phung ndăm saơ gâp jêh ri du der, Jêh ri phung bu ranh dâk jêh ri gŭ râng;$b$,false),
('bunong-vn','JOB',29,9,null,$b$Phung kôranh gŭ klăk klêm, jêh ri rdêp mbung khân păng.$b$,false),
('bunong-vn','JOB',29,10,null,$b$Bâr ngơi phung bu yơk rlu ngơi, Jêh ri mpiăt khân păng lĕ krêp jêh.$b$,true),
('bunong-vn','JOB',29,11,null,$b$Tơ lah bu tăng, bu ntơ gâp jêng nơm geh nau ueh uĭn, jêh ri tơ lah bu saơ, bu tâm rnê ma gâp.$b$,true),
('bunong-vn','JOB',29,12,null,$b$Nau nây yor lah gâp kơl yơk phung o ach gŭ nter dăn, jêh ri phung kon đơi mâu geh ôh nơm sâm kơl an,$b$,true),
('bunong-vn','JOB',29,13,null,$b$Nơm lĕ dăch rai yot mât ton ma gâp, Jêh ri gâp ƀư ăn nuih n'hâm bu ur ndrô ma nau hâk răm.$b$,false),
('bunong-vn','JOB',29,14,null,$b$Gâp nsoh nau sŏng srăng jêng nâm bu bok ao nkŭm gâp. Nau sŏng gâp jêng nâm bu du blah ao jâr jêh ri kưn mpân.$b$,true),
('bunong-vn','JOB',29,15,null,$b$Gâp jêng nâm bu măt ma bunuyh lĕ chieh, Jêh ri jâng ma bunuyh rven.$b$,true),
('bunong-vn','JOB',29,16,null,$b$Gâp hŏ jêng mbơ̆ ma phung o ach, jêh ri gâp sek uănh joi nau di rah vah ma nơm mâu gĭt năl ôh.$b$,true),
('bunong-vn','JOB',29,17,null,$b$Gâp nkêch lơi neng phung djơh mhĭk, jêh ri gâp mphâk lơi mpa păng gleng ta sêk păng.$b$,true),
('bunong-vn','JOB',29,18,null,$b$Gâp lah pô aơ: ‘Gâp mra khĭt tâm rsuăn gâp Jêh ri nar gâp gŭ rêh mra jêng âk nâm bu choih;$b$,true),
('bunong-vn','JOB',29,19,null,$b$reh gâp hung jong rgŏ dak, geh dak ngom ăp măng ta n'gĭng gâp.$b$,false),
('bunong-vn','JOB',29,20,null,$b$Nau chrêk rmah gâp jêng nse mro mrăng Jêh ri na gâp jêng dăng ktang tâm ti gâp.’$b$,true),
('bunong-vn','JOB',29,21,null,$b$Bu rkêng iăt nau gâp, jêh ri gŭ iăt rklăk lĕ nau gâp nchră$b$,false),
('bunong-vn','JOB',29,22,null,$b$Jêh gâp ngơi, khân păng mâu hôm ngơi đŏng ôh, nau gâp ngơi lĕ lăp jêh tâm nuih n'hâm khân păng.$b$,false),
('bunong-vn','JOB',29,23,null,$b$Khân păng gŭ kâp gâp nâm bu bu gŭ kâp dak mih, khân păng hă trôm mbung khân păng nâm bu dư̆ ng dak mih nglĕ dŭt.$b$,true),
('bunong-vn','JOB',29,24,null,$b$Gâp gơm rum gay ŭch bonh khân păng tơ lah khân păng rdja nuih; Jêh ri khân păng mƀrơn dôl uănh ma muh măt gâp maak.$b$,true),
('bunong-vn','JOB',29,25,null,$b$Gâp ntĭm trong ma khân păng, jêh ri jêng kôranh ma khân păng. Gâp gŭ rêh nâm bu du huê hađăch ta nklang phung ta han păng. Nâm bu du huê blau njung leng phung nhĭm nhhiăng.$b$,true),
('bunong-vn','JOB',30,1,null,$b$“Ƀiă lah aƀaơ ri, nơm ndăm lơn ma gâp ntêh rmot gâp, ma phung mbơ̆ khân păng gâp hŏ mưch, mâu khư ôh pah kan ndrel ma so chiăp ndrôk biăp gâp.$b$,true),
('bunong-vn','JOB',30,2,null,$b$N'hâm suan khân păng lĕ djoh jêh, pô ri, nau dăng ktang tâm ti khân păng lĕ ra-ai moh hôm khlay ma gâp?$b$,true),
('bunong-vn','JOB',30,3,null,$b$Khân păng lĕ rgay yor ji ngot mâu geh ndơ sông sa, khân păng kuyh sa neh sơh ntŭk lĕ jêng săr bu cha lơi jŏ jêh$b$,true),
('bunong-vn','JOB',30,4,null,$b$Khân păng pĕ ŭch sa kao jêh ri n'ha si, khân păng sŏk reh si lok gay njêng ndơ khân păng sa.$b$,false),
('bunong-vn','JOB',30,5,null,$b$Bu mprơh khân păng tă bơh phung ƀon lan; bu nter ma khân păng nâm bu bu nter ma nơm ntŭng.$b$,true),
('bunong-vn','JOB',30,6,null,$b$Khân păng gŭ tâm rlŭng ntŭk krit klach, tâm trôm neh jêh ri ta nklang trôm lŭ.$b$,true),
('bunong-vn','JOB',30,7,null,$b$Khân păng lŭng nter ta nklang pŭm tơm si, jêh ri kuen pung ndrel tâm dâng pôm lok.$b$,true),
('bunong-vn','JOB',30,8,null,$b$Khân păng jêng phung rluk mâl, dơm dam jêh ri bu tâm rmot bu mprơh jêh khân păng du luh bơh bri dak.$b$,true),
('bunong-vn','JOB',30,9,null,$b$Bi aƀaơ ri, gâp jêng ndơ khân păng mprĭng mprơ ma nau ntêh rmot.$b$,true),
('bunong-vn','JOB',30,10,null,$b$Khân păng tâm rmot ma gâp, du der ngai ma gâp, tơ lah khân păng saơ gâp khân păng soh dak diu tâm muh măt gâp.$b$,true),
('bunong-vn','JOB',30,11,null,$b$Yor lah Brah Ndu hŏ ntrôl nklơ̆ gâp, jêh ri mưch rmot gâp. Khân păng mâu hôm geh kân gâp ôh, ƀiă lah ƀư ma gâp tĭng nâm khân păng ŭch.$b$,true),
('bunong-vn','JOB',30,12,null,$b$Phung dơm dam aơ ŭch du dâk lơh gâp mpeh pa ma; khân păng mprơh gâp, khân păng joi trong ƀư rai gâp.$b$,true),
('bunong-vn','JOB',30,13,null,$b$Khân păng ƀư rai trong gâp, khân păng ntop đŏng nau rêh ni ma gâp, ƀiă lah mâu geh ôh nơm kơl an khân păng.$b$,true),
('bunong-vn','JOB',30,14,null,$b$Khân păng lăp ta ntŭk bluh toyh, ran rlet ma gâp ta nklang ntŭk lĕ rlâm jêh$b$,true),
('bunong-vn','JOB',30,15,null,$b$Lĕ nau klach krit ƀư ma gâp, tĭng groi nau geh jêng gâp nâm bu sial khôm rdu, jêh ri nau ueh lăng gâp hŏ roh jêh du nâm bu ndâr ntŭk.$b$,false),
('bunong-vn','JOB',30,16,null,$b$Aƀaơ ri, huêng gâp phit phơr tâm trôm gâp, nar rêh ni lĕ tât jêh ma gâp.$b$,true),
('bunong-vn','JOB',30,17,null,$b$Dôl bri măng geh nau ji tât ma nting gâp, nau ji sa hot gâp mâu rlu ôh.$b$,true),
('bunong-vn','JOB',30,18,null,$b$Yor ma nau ktang toyh Brah Ndu ƀư ma kho ao gâp mprôn lĕ, nau ktang nây rêt trô ko gâp nâm bu trô ko ao.$b$,true),
('bunong-vn','JOB',30,19,null,$b$Brah Ndu mƀăr gâp tâm dak bŏk, gâp jêng nâm bu ndruyh jêh ri ŭnh buh.$b$,true),
('bunong-vn','JOB',30,20,null,$b$Gâp vơh vơl ma may, ƀiă lah may mâu plơ̆ lah ôh ma gâp. Gâp dâk ta nây, jêh ri may mâu chrê ôh knŏng n'gơr uănh gâp.$b$,true),
('bunong-vn','JOB',30,21,null,$b$May lĕ jêng janh đah gâp, ma nau ktang ti may, ŭch tĭng ƀư ma gâp.$b$,true),
('bunong-vn','JOB',30,22,null,$b$May chông gâp leo klơ sial ndăng, gay ăn păng khôm rdu gâp, jêh ri ƀư rai gâp ta nklang phŭt sial.$b$,true),
('bunong-vn','JOB',30,23,null,$b$Yor lah gâp gĭt ma may mra njŭn leo gâp tâm ntŭk nau khĭt, jêng ntŭk may ton prăp ăn ma lĕ rngôch bunuyh rêh.$b$,true),
('bunong-vn','JOB',30,24,null,$b$Ƀiă lah dôl geh mbu moh bu ƀư rai, khân păng mâu hĕ dơi yơr ti? Mâu lah dôl geh nau rêh ni, khân păng mâu hĕ vơl nter gay bu kơl an?$b$,true),
('bunong-vn','JOB',30,25,null,$b$Mâu hĕ gâp nhĭm ma nơm dơn nau jêr? Jêh ri mâu hĕ gâp geh nau rngot ma phung o ach?$b$,true),
('bunong-vn','JOB',30,26,null,$b$Ƀiă lah tơ lah gâp gŭ kâp nau ueh, nkhơng ma nau mhĭk tât; jêh ri tơ lah gâp kâp gân nau ang, nkhơng nau ngo văch tât.$b$,true),
('bunong-vn','JOB',30,27,null,$b$Nuih n'hâm gâp phit phơr mâu geh nau mpăn ôh; ăp nar nau rêh ni văch mpet gâp.$b$,true),
('bunong-vn','JOB',30,28,null,$b$Gâp hăn săk jăn lĕ jêng krăk, ƀiă lah mâu di ôh duh nar nđat; gâp hăn dâk ta nklang phung âk jêh ri vơl dăn bu kơl an.$b$,true),
('bunong-vn','JOB',30,29,null,$b$Gâp jêng oh nâu ma so bri, jêh ri nơm hăn ndrel ma sĭm ôtrus.$b$,true),
('bunong-vn','JOB',30,30,null,$b$Ntâu săk gâp jêng krăk jêh ri plôk rŭng rsiap, jêh ri Ntĭng nđăng gâp duh ring.$b$,true),
('bunong-vn','JOB',30,31,null,$b$Gâp kreh gong rêng ma nau klân rvê, jêh ri uh n'hôm ma nau nhhiăng nhĭm.”$b$,true),
('bunong-vn','JOB',31,1,null,$b$Gâp hŏ ƀư nau tâm rnglăp jêh đah măt gâp; pô nây, mâm ƀư gâp dơi uănh ma du huê bu ur druh?$b$,true),
('bunong-vn','JOB',31,2,null,$b$Yor kô̆ tă Brah Ndu klơ trôk pă ăn ma gâp,$b$,true),
('bunong-vn','JOB',31,3,null,$b$jêh ri drăp ndơn gâp tă Nơm Geh Lĕ Nau Brah ta ntŭk prêh klơ, moh nau hăn? Mâu hĕ nau rêh ni ăn ma nơm djơh mhĭk, jêh ri nau rai yot tât ma phung pah kan nau kue?$b$,false),
('bunong-vn','JOB',31,4,null,$b$Mâu hĕ Brah Ndu saơ trong gâp, jêh ri kơp lĕ nhuat gâp?$b$,true),
('bunong-vn','JOB',31,5,null,$b$“Tơ lah gâp gŭ ngao ma nau mƀruh jêh ri jâng gâp chuat ndal ma nau ndơm;$b$,true),
('bunong-vn','JOB',31,6,null,$b$ăn Brah Ndu yơk njing gâp tâm du mlâm njing di; jêh ri ăn păng gĭt nau sŏng srăng gâp!$b$,false),
('bunong-vn','JOB',31,7,null,$b$Tơ lah jâng gâp der cha lơi trong di ngăn, jêh ri nuih n'hâm gâp kơnh ma ndơ măt gâp saơ, tơ lah geh nau ƀơ̆ ƀơch krêp ta ti gâp,$b$,true),
('bunong-vn','JOB',31,8,null,$b$pô ri ăn gâp srih, jêh ri geh nơm êng mra rek, ăn bu rôk lơi ndơ gâp tăm jêh!$b$,false),
('bunong-vn','JOB',31,9,null,$b$Tơ lah nuih n'hâm gâp tŭp nau bu ur ndơm, jêh ri tơ lah gâp gŭ grem kâp ta mpông nơm chiau meng gâp;$b$,true),
('bunong-vn','JOB',31,10,null,$b$pô ri ăn ur gâp peh ba ma nơm êng, jêh ri geh nơm êng bêch ndrel păng.$b$,false),
('bunong-vn','JOB',31,11,null,$b$Yor nau nây jêng nau tih jru mhĭk ngăn; nau nây jêng nau kue lĕ di ma phung kôranh phat dôih tâm rmal:$b$,true),
('bunong-vn','JOB',31,12,null,$b$Nau tih nây jêng ŭnh hit sa tât ma ntŭk bêch kuh rhôk, ƀư rai lĕ drăp ndơ gâp kŏ tât lĕ rngôch ƀhiau.$b$,false),
('bunong-vn','JOB',31,13,null,$b$Tơ lah gâp geh dun nau di ma oh mon bu ur mâu lah bu klâu gâp, dôl khân păng tâm rlăch đah gâp,$b$,true),
('bunong-vn','JOB',31,14,null,$b$pô ri mâm gâp mra ƀư tơ lah Brah Ndu du dâk? Tơ lah Păng tât ôp sek gâp, mâm gâp mra plơ̆ lah?$b$,false),
('bunong-vn','JOB',31,15,null,$b$Nơm hŏ njêng gâp tâm trôm ndŭl me gâp, mâu hĕ di bu rhăk njêng nđâp ma khân păng lĕ? Mâu hĕ di knŏng du huê Brah Ndu dơm nơm rli hên tâm trôm ndŭl me?$b$,true),
('bunong-vn','JOB',31,16,null,$b$Tơ lah gâp dun mâu ăn ôh ndơ phung o ach ŭch, ƀư ăn bu ur ndrô huănh măt ma nau nhĭm.$b$,true),
('bunong-vn','JOB',31,17,null,$b$Tơ lah gâp sa êng ndơ du huê gâp, jêh ri bunuyh kon đơi mâu dơi ăn sa ndrel ôh;$b$,true),
('bunong-vn','JOB',31,18,null,$b$N'hêl nanê̆ ntơm bơh gâp ndăm, păng văch ma toyh ndrel ma gâp nâm bu kon ndrel mbơ̆ . Bi ma bu ur ndrô, gâp hŏ kơl ncheng păng ntơm bơh gâp luh bơh ndŭl me gâp;$b$,false),
('bunong-vn','JOB',31,19,null,$b$tơ lah gâp saơ mbu nơm khĭt yor mâu geh bok ao, jêh ri bunuyh o ach mâu geh ndơ nsoh ntâk;$b$,false),
('bunong-vn','JOB',31,20,null,$b$Tơ lah nuih n'hâm păng mâu geh ôh mât ton nau ueh ma gâp, jêh ri păng tơ lah mâu geh ôh ao rsau biăp gâp dơi geh nau răm păng;$b$,false),
('bunong-vn','JOB',31,21,null,$b$tơ lah gâp yơr ti gâp gay ƀư ma phung kon đơi, yor lah gâp saơ geh bunuyh kâp kơl gâp tâm mpông pêr ƀon toyh$b$,false),
('bunong-vn','JOB',31,22,null,$b$pô ri ăn săng nglik gâp răch rŭng bơh săk jăn jêh ri ăn nting tur gâp tăch bơh ntŭk păng tâm rdjŭm.$b$,false),
('bunong-vn','JOB',31,23,null,$b$Yor lah nau rêh ni bơh Brah Ndu ntŭp ƀư ăn gâp klach krit, jêh ri ta năp nau rnam Păng, gâp mâu dơi ƀư ôh.$b$,true),
('bunong-vn','JOB',31,24,null,$b$Tơ lah gâp nsing ma mah, jêh ri lah đah mah chrêk pô aơ: May jêng ndơ gâp rnơm nsing;$b$,true),
('bunong-vn','JOB',31,25,null,$b$tơ lah gâp răm rhơn ma drăp ndơ gâp geh âk, jêh ri yor tă bơh ti gâp hŏ geh ndơ âk ngăn ngên;$b$,false),
('bunong-vn','JOB',31,26,null,$b$tơ lah gâp saơ măt nar sol ang, jêh ri khay luh mpơl nchrang lơ vơ$b$,false),
('bunong-vn','JOB',31,27,null,$b$pô ri nuih n'hâm gâp geh nau kơnh ntŭng ŭch yơk mbah ma ndơ nây.$b$,false),
('bunong-vn','JOB',31,28,null,$b$Nau nây jêng du ntil nau tih tâm ban lĕ di ma phung kôranh phat dôih tâm rmal, yor nây gâp jêng tih đah Brah Ndu ta klơ.$b$,true),
('bunong-vn','JOB',31,29,null,$b$“Tơ lah gâp răm maak yor ma nơm ƀư djơh gâp geh nau rêh ni, mâu lah rhơn tơ lah geh nau mhĭk tât ma păng;$b$,true),
('bunong-vn','JOB',31,30,null,$b$gâp mâu mâp ôh ăn trôm mbung gâp ƀư tih, gay ŭch sŏk nau rak rtăp thăm man, gay ƀư mhĭk nau rêh păng;$b$,false),
('bunong-vn','JOB',31,31,null,$b$tơ lah phung bunuyh tâm ngih mâu mâp lah ôh; “Mbu mra dơi joi mbu moh bunuyh mâu hŏ mâp sa mpay ndơ sông sa păng?’ ”$b$,false),
('bunong-vn','JOB',31,32,null,$b$Bu năch mâu geh bêch ôh rŏ trong; gâp pơk jêh mpông gâp ƀa ƀơ ăn bu năch nsong trong;$b$,true),
('bunong-vn','JOB',31,33,null,$b$Tơ lah gâp pôn mo nau tih gâp nơm nâm bu Y-Ađam, jêng pôn lơi nau djơh mhĭk gâp nơm tâm trôm nuih n'hâm gâp.$b$,false),
('bunong-vn','JOB',31,34,null,$b$Yor lah gâp geh nau klach krit ma khân păng âk ngăn, jêh ri klach lah mpôl băl mưch rmot; kŏ tât gâp gŭ klăk klêm, mâu janh chuat hăn luh du pa dih mpông.$b$,true),
('bunong-vn','JOB',31,35,null,$b$Ơ! Mâu geh ôh bunuyh gŭ iăt gâp! Aơ jêng gâp chih kach amoh gâp! Ăn Nơm Geh Lĕ Nau Brah plơ̆ sĭt lah ma gâp! Gay ăn nơm rlăng ma gâp geh sămƀŭt chih prăp!$b$,true),
('bunong-vn','JOB',31,36,null,$b$N'hêl nanê̆ gâp mra tuy nau nây ta klơ săng nglik gâp, ndô păng ta klơ bôk gâp nâm bu đon hađăch.$b$,true),
('bunong-vn','JOB',31,37,null,$b$Gâp mra nkoch ma păng lĕ rngôch nau gâp ƀư; Văch tât tra năp măt păng nâm bu du huê hađăch.$b$,true),
('bunong-vn','JOB',31,38,null,$b$Tơ lah neh nter tâm rdâng đah gâp, Jêh ri lĕ trong kai păng nhĭm ndrel;$b$,true),
('bunong-vn','JOB',31,39,null,$b$Tơ lah gâp sa jêh play păng mâu geh trok rnoh ôh, jêh ri ăn nau khĭt tât ma păng nơm.$b$,false),
('bunong-vn','JOB',31,40,null,$b$Ăn pôm lok hon ntrok ba, jêh ri gơ̆ mhĭk ntrok ma ba orgơ.” Tât ta aơ nau Y-Yôp ngơi lôch jêh.$b$,true),
('bunong-vn','JOB',32,1,null,$b$Rnôk nây, pe nuyh bu klâu nây lĕ rlu jêh nau plơ̆ sĭt lah ma Y-Yôp, yor lah Y-Yôp kơp ma păng nơm jêng sŏng.$b$,true),
('bunong-vn','JOB',32,2,null,$b$Y-Êtihu, kon bu klâu Y-Barakel, bunuyh n'gor bri Bus tă bơh mpôl băl Ram hao ji nuih. Păng nuih ma Y-Yôp yor lah păng lah êng păng nơm jêng sŏng rlau lơn ma Brah Ndu.$b$,true),
('bunong-vn','JOB',32,3,null,$b$Y-Êtihu ji nuih ma pe nuyh mĭt jiăng Y-Yôp tâm ban lĕ, yor lah khân păng mâu joi nau di ngăn ôh gay plơ̆ lah tay, nđâp tơ lah khân păng hŏ lah ma Y-Yôp tih jêh.$b$,false),
('bunong-vn','JOB',32,4,null,$b$Pô ri Y-Êtihu gŭ kâp lôch lĕ nau Y-Yôp ngơi ri mơ păng ngơi lah ma Y-Yôp, yor lah phung bunuyh nây lĕ bu ranh da dê rlau lơn ma păng.$b$,false),
('bunong-vn','JOB',32,5,null,$b$Pô ri, tơ lah Y-Êtihu saơ jêh ma pe nuyh nây mâu hôm saơ nau plơ̆ sĭt lah đŏng ôh, păng hao ji nuih ngăn.$b$,false),
('bunong-vn','JOB',32,6,null,$b$Jêh ri Y-Êtihu kon bu klâu Y-Barakel tă bơh n'gor bri Bus plơ̆ sĭt lah: “Gâp jêng ndăm, bi khân may jêng bu ranh jêh; yor nây gâp geh nau jêh ri mâu nănh nkoch nau gâp mĭn ma khân may.$b$,true),
('bunong-vn','JOB',32,7,null,$b$Gâp mĭn pô aơ: “Mbu hŏ gŭ rêh jŏ nar jêh mra ngơi, jêh ri nơm hŏ gŭ rêh jŏ năm jêh nti nau blau mĭn,$b$,true),
('bunong-vn','JOB',32,8,null,$b$Ƀiă lah geh huêng tâm kon bunuyh, jêh ri n'hâm nsôr tă bơh Nơm Geh Lĕ Nau Brah ăn khân păng nau gĭt rbăng.$b$,false),
('bunong-vn','JOB',32,9,null,$b$Bunuyh bu ranh mâu di nau blau mĭn ôh, mâu di lĕ du huê bu ranh dơi gĭt rbăng nau di.$b$,true),
('bunong-vn','JOB',32,10,null,$b$Yor nau nây gâp lah: ‘Iăt hom ma gâp, mpeh ma gâp mra nkoch nau gâp mĭn.’$b$,true),
('bunong-vn','JOB',32,11,null,$b$“Aơ, gâp gŭ kâp nau khân may ngơi, gâp kâp iăt ma nau khân may lah ma nau blau mĭn, dôl khân may joi moh nau ŭch plơ̆ sĭt lah.$b$,false),
('bunong-vn','JOB',32,12,null,$b$N'hêl nanê̆ gâp srôih iăt nau khân may, gâp saơ mâu geh du huê nuyh ôh tâm phung khân may dơi lơn đah Y-Yôp, mâu lah dơi plơng nau ngơi păng.$b$,true),
('bunong-vn','JOB',32,13,null,$b$Lơi ta lah ôh: He dơi joi nau blau mĭn, Brah Ndu dơi lơn ma bunuyh, kon bunuyh mâu dơi ƀư du ntil ôh.$b$,true),
('bunong-vn','JOB',32,14,null,$b$Pô nây, Y-Yôp mâu dơi geh nau tâm rlăch đah gâp ôh, pô ri, gâp mâu mra sŏk nau khân may ôh gay tâm plơng đah păng.$b$,true),
('bunong-vn','JOB',32,15,null,$b$Khân păng gŭ srŭng mâu hôm blau plơ̆ lah đŏng ôh; mâu hôm geh nau gay ŭch ma lah.$b$,true),
('bunong-vn','JOB',32,16,null,$b$Gâp mâu hôm dơi kâp ôh, yor lah khân păng mâu hôm ngơi, mâm mâu geh hĕ nau plơ̆ lah đŏng?$b$,true),
('bunong-vn','JOB',32,17,null,$b$Mpeh ma gâp tâm ban lĕ mra plơ̆ lah nau gŭ kâp nây; Gâp tâm ban lĕ mra tâm mpơl nau gâp mĭn.$b$,true),
('bunong-vn','JOB',32,18,null,$b$Yor lah gâp geh âk nau gâp ŭch lah, Nau mĭn tâm nuih n'hâm gâp ntrôl ăn gâp ngơi.$b$,true),
('bunong-vn','JOB',32,19,null,$b$Aơ, nuih n'hâm gâp nâm bu ndrănh krŭl n'hâm mâu geh trôm luh du ôh. Păng lĕ dăch prĭh nâm bu nông ntâu ndrănh mhe.$b$,true),
('bunong-vn','JOB',32,20,null,$b$Gâp mra ngơi jêh ri dơi ngơi păn thơ; gâp mra ntơm ngơi jêh ri plơ̆ sĭt lah.$b$,true),
('bunong-vn','JOB',32,21,null,$b$Gâp mâu mra gŭ nding mpeh ma du huê ôh. Mâu lĕ n'hi săk nơm.$b$,true),
('bunong-vn','JOB',32,22,null,$b$Yor lah gâp mâu blau ôh ngơi n'hi săk nơm, tơ lah pô nây Nơm Rhăk gâp ăn gâp rai lôch gơnh ro.$b$,true),
('bunong-vn','JOB',33,1,null,$b$Ƀiă lah pô nây, aƀaơ ri hơi Y-Yôp, ăn may iăt hom lĕ nau gâp nkoch. Jêh ri rkêng tôr iăt lĕ nau gâp lah.$b$,true),
('bunong-vn','JOB',33,2,null,$b$Aơ, gâp hŏ hă trôm mbung ngơi, mpiăt gâp ngơi tâm trôm khay dơ̆$b$,true),
('bunong-vn','JOB',33,3,null,$b$Lĕ nau gâp ngơi mra tĭng kơt nau di tâm nuih n'hâm gâp jêng nau sŏng srăng. Nau gâp gĭt trôm mbung gâp ngơi ma nau n'hêl nanê̆.$b$,false),
('bunong-vn','JOB',33,4,null,$b$Huêng Brah Brah Ndu rhăk njêng gâp, n'hâm gâp nsôr tă bơh Nơm Geh Lĕ Nau Brah ăn ma gâp nau rêh.$b$,true),
('bunong-vn','JOB',33,5,null,$b$Tơ lah dơi plơ̆ lah, plơ̆ sĭt lah hom ma gâp, dâk hom, ngơi hom ăn tâm di mbor lĕ nau may ngơi tra năp gâp!$b$,true),
('bunong-vn','JOB',33,6,null,$b$Uănh hom, tâm rđĭl đah Brah Ndu gâp nâm bu may lĕ mâu geh êng ôh, Gâp tâm ban lĕ bu njêng luh du tă bơh neh.$b$,true),
('bunong-vn','JOB',33,7,null,$b$Aơ, lơi ta may rnam klach ma gâp ôh; jêh nau dơi gâp ƀư khưm mâu mra n'grŭn mpet may ôh.$b$,true),
('bunong-vn','JOB',33,8,null,$b$“N'hêl nanê̆ gâp hŏ tăng jêh nau may ngơi, tât ma tôr gâp lah pô aơ:$b$,true),
('bunong-vn','JOB',33,9,null,$b$Gâp lĕ kloh ueh mâu geh nau tih ôh.” Gâp jêng rsang, jêh ri tâm nuih n'hâm mâu geh nau tih mhĭk ôh.$b$,false),
('bunong-vn','JOB',33,10,null,$b$Nđâp tơ lah pô nây, Brah Ndu joi nau đah gâp ŭch kơp gâp jêng bunuyh rlăng đah Păng;$b$,true),
('bunong-vn','JOB',33,11,null,$b$Păng nkông lơi jâng gâp jêh ri uănh rmiăng lĕ trong gâp hăn.$b$,false),
('bunong-vn','JOB',33,12,null,$b$Aơ, nau gâp ŭch plơng đah may tâm lĕ nau nây may lah jêng mâu di ôh; yor lah Brah Ndu jêng toyh lơn kon bunuyh.$b$,true),
('bunong-vn','JOB',33,13,null,$b$Mâm ƀư may tâm rlăch đah Păng? Jêh ri lah, Păng mâu ŭch rblang ôh lĕ nau Păng ƀư ma gâp?$b$,true),
('bunong-vn','JOB',33,14,null,$b$Yor lah Brah Ndu ngơi tâm du tơ̆ mâu lah bar tơ̆ , ƀiă lah bunuyh mâu ŭch nklân ôh nau nây kđôi$b$,true),
('bunong-vn','JOB',33,15,null,$b$Păng ngơi tâm nau mbơi, tâm nau tâm saơ dôl măng, dôl khân păng lêt bêch ta klơ sưng bêch khân păng;$b$,false),
('bunong-vn','JOB',33,16,null,$b$rnôk nây Păng pơk trôm tôr kon bunuyh, jêh ri nhhu khân păng ma nau Păng đă njrăng.$b$,false),
('bunong-vn','JOB',33,17,null,$b$Gay ma păng dơi ăn bunuyh der bơh nau khân păng ƀư, jêh ri ngroh lơi nau khân păng sưr rlau.$b$,true),
('bunong-vn','JOB',33,18,null,$b$Gay rklaih huêng khân păng klaih bơh Ntu Jru (ntu môch), jêh ri nau rêh khân păng bơh nau rai yot yor ma đao khĭt.$b$,true),
('bunong-vn','JOB',33,19,null,$b$“Tâm ban lĕ Brah Ndu nkra bunuyh ma nau ji kuet, jêh ri ma nau ji nting mro mrăng.$b$,true),
('bunong-vn','JOB',33,20,null,$b$Pô ri trôm mbung păng tâm rmot ma ndơ sông sa, jêh ri mâu kơnh sa ôh ndơ sa kah.$b$,true),
('bunong-vn','JOB',33,21,null,$b$Nglay săk păng rgay kŏ tât nting dop ntâu mâu hôm saơ đŏng ôh, jêh ri nting păng, sa ơm ri mâu mpơl ôh ƀiă lah aƀaơ knŏng mpơl nting nđăng.$b$,true),
('bunong-vn','JOB',33,22,null,$b$Huêng păng lĕ dăch tât ma Ntu Jru, jêh ri săk jăn păng văch êp ma phung khĭt.$b$,true),
('bunong-vn','JOB',33,23,null,$b$Tơ lah tâm du rbăn Tông mpăr ueh, geh du huê Tông mpăr ueh jêng nơm nti rblang ma bunuyh, gay ntĭm nti păng gĭt nau sŏng srăng ăn păng.$b$,true),
('bunong-vn','JOB',33,24,null,$b$Brah Ndu yô̆ lĕ ma păng jêh ri lah: “Tâm rklaih hom păng gay dơi klaih lơi ăn tŭp tâm Ntu Jru ôh; Gâp hŏ joi jêh trong tâm chuai.”$b$,true),
('bunong-vn','JOB',33,25,null,$b$Păng mra dơi sĭt nse tay ntâu săk nâm bu hôm kon se jê̆ sa ơm.$b$,true),
('bunong-vn','JOB',33,26,null,$b$Păng mbơh sơm ma Brah Ndu, pô ri Brah Ndu mra uănh treng păng, ăn păng răm rhơn saơ muh măt Păng. Jêh ri Brah Ndu mplơ̆ tay nau sŏng srăng ma păng.$b$,true),
('bunong-vn','JOB',33,27,null,$b$Pô nây, bunuyh nây mra mprơ ta năp bunuyh, pô aơ: “Gâp hŏ ƀư tih jêh, ƀư djơh lơi nau sŏng srăng, ƀiă lah mâu geh nau khlay ăn ma gâp ôh.$b$,true),
('bunong-vn','JOB',33,28,null,$b$Brah Ndu tâm rklaih jêh huêng gâp dơi klaih bơh Ntu Jru, jêh ri nau rêh gâp mra saơ nau ang.”$b$,true),
('bunong-vn','JOB',33,29,null,$b$Aơ, Brah Ndu ƀư lĕ nau nây ăn ma kon bunuyh; du tơ̆ mâu lah bar tơ̆ ,$b$,true),
('bunong-vn','JOB',33,30,null,$b$Gay mphâk huêng păng lơi ăn tŭp tâm Ntu Jru ôh, gay ma păng dơi saơ nau ang sol ang ma nau rêh.$b$,false),
('bunong-vn','JOB',33,31,null,$b$Hơi Y-Yôp, may iăt hom nau gâp; gŭ klêm jêh ri iăt nau gâp ngơi.$b$,true),
('bunong-vn','JOB',33,32,null,$b$Tơ lah may geh nau ŭch lah, plơ̆ sĭt lah hom ma gâp; ngơi hom, yor lah gâp ŭch mpơl may jêng sŏng.$b$,true),
('bunong-vn','JOB',33,33,null,$b$Tơ lah mâu di ôh pô nây, iăt hom nau gâp, gŭ klêm hom, pô ri gâp mra nti ma may nau blau mĭn.$b$,true),
('bunong-vn','JOB',34,1,null,$b$Y-Êtihu ngơi lah đŏng:$b$,true),
('bunong-vn','JOB',34,2,null,$b$“Iăt hom nau gâp ngơi, hơi phung bunuyh blau mĭn, jêh ri rkêng tôr iăt hom nau gâp, khân may phung gĭt rbăng;$b$,false),
('bunong-vn','JOB',34,3,null,$b$yor lah trôm tôr yơh sek uănh nau ngơi, nâm bu khay dơ̆ chiăm kah ndơ sa.$b$,false),
('bunong-vn','JOB',34,4,null,$b$Ăn he săch hom ma he nơm nau di, ăn he sek uănh ndrel he moh jêng ueh.$b$,true),
('bunong-vn','JOB',34,5,null,$b$Yor lah Y-Yôp geh lah pô aơ: “Gâp jêng sŏng kđôi, ƀiă lah Brah Ndu hŏ sŏk rhuăt lơi jêh nau gâp jêng di.$b$,true),
('bunong-vn','JOB',34,6,null,$b$Nđâp lah gâp jêng sŏng kđôi lĕ, ăt bu kơp jêh jêng du huê nuyh mƀruh; nđâp tơ lah gâp mâu geh tih ôh, ntŭk têl sôt gâp mâu geh jĭr ôh.”$b$,true),
('bunong-vn','JOB',34,7,null,$b$Mbu moh bunuyh tâm ban nâm Y-Yôp? Bunuyh nhêt nau bu mưch mach nâm bu dak.$b$,true),
('bunong-vn','JOB',34,8,null,$b$Bunuyh sa jiăng đah nơm janh mhĭk, jêh ri hăn ndrel phung ƀư nau djơh?$b$,true),
('bunong-vn','JOB',34,9,null,$b$Yor lah păng geh lah pô aơ: “Mâu geh nau khlay ma bunuyh ôh, tĭng joi nau răm maak ma he nơm tâm ntŭk Brah Ndu.”$b$,true),
('bunong-vn','JOB',34,10,null,$b$Yor nây, hơi phung gĭt rbăng, khân may iăt hom nau gâp; Brah Ndu mâu mâp ƀư nau djơh ôh. Nơm Geh Lĕ Nau Brah mâu lĕ mâp ƀư janh mhĭk.$b$,true),
('bunong-vn','JOB',34,11,null,$b$Păng mra nkhôm ma kon bunuyh, tĭng nâm kan păng hŏ pah. Jêh ri gay ăn ăp nơm dơi joi tay tĭng nâm nuih n'hâm păng ƀư jêh.$b$,true),
('bunong-vn','JOB',34,12,null,$b$N'hêl nanê̆ Brah Ndu mâu mâp ƀư nau djơh ôh. Nơm Geh Lĕ Nau Brah mâu geh nsŭk ƀư tih teng đah nau sŏng ôh.$b$,true),
('bunong-vn','JOB',34,13,null,$b$Mbu nơm ăn Brah Ndu jêng kôranh ma rplay neh? Mbu nơm dơm Păng chiă uănh lam bri neh ntu?$b$,true),
('bunong-vn','JOB',34,14,null,$b$Tơ lah Păng knŏng mĭn rvê êng ma Păng nơm, sŏk sĭt ma păng huêng srêng jêh ri n'hâm nsôr Păng nơm$b$,true),
('bunong-vn','JOB',34,15,null,$b$Pô ri lĕ rngôch phung nglay săk nanê̆ mra khĭt ndrel lĕ ro, jêh ri bunuyh mra plơ̆ sĭt ma ndruyh neh.$b$,false),
('bunong-vn','JOB',34,16,null,$b$“Tơ lah khân may geh nau gĭt rbăng, iăt hom nau aơ, rkêng tôr ma nau gâp ngơi.$b$,true),
('bunong-vn','JOB',34,17,null,$b$Mra geh lĕ du huê nuyh tâm rmot ma nau sŏng jêng Kôranh Chiă uănh? May mra tâm rmal lĕ nơm jêng sŏng jêh ri geh nau dơi,$b$,true),
('bunong-vn','JOB',34,18,null,$b$Dơi lah lĕ ma hađăch pô aơ: “Ndơ dơm dam?” Jêh ri lah ma phung kôranh “Bunuyh djơh mhĭk?”$b$,false),
('bunong-vn','JOB',34,19,null,$b$Ang ma ri Nơm mâu gŭ ôh mpeh ma phung kôranh, kŏ mâu chrê lĕ ma phung ndrŏng âk lơn ma phung o ach. Yor lah lĕ rngôch khân păng jêng kan ti păng ƀư?$b$,true),
('bunong-vn','JOB',34,20,null,$b$Ƀât lât, klong măng khân păng khĭt da dê, Nuih n'hâm râm nsâr jêh ri rai yot, lĕ rngôch phung ktang roh jêh mâu di ôh yor ma ti kon bunuyh ƀư.$b$,true),
('bunong-vn','JOB',34,21,null,$b$“Yor lah măt Brah Ndu uănh treng ma trong kon bunuyh, jêh ri Păng saơ lĕ nhuat khân păng.$b$,true),
('bunong-vn','JOB',34,22,null,$b$Mâu geh ôh ntŭk ngo klĕng vêt vê. Gay ăn ma bunuyh djơh dơi krap.$b$,true),
('bunong-vn','JOB',34,23,null,$b$Tơ lah Brah Ndu phat dôih kon bunuyh mâu kâp gay ăn khân păng văch tât pa năp măt Păng bar tơ̆ ôh gay ôp sek.$b$,true),
('bunong-vn','JOB',34,24,null,$b$Păng ƀư rai phung ktang mâu kâp ôp sek lor ôh, jêh nây njêng bu êng ntrok păng.$b$,true),
('bunong-vn','JOB',34,25,null,$b$Yor lah Kôranh Brah gĭt lĕ kan khân păng. Pô ri Păng n'glưh khân păng dôl bri măng, jêh ri khân păng roh rai.$b$,true),
('bunong-vn','JOB',34,26,null,$b$Kôranh Brah lơh rai khân păng nâm bu bunuyh djơh mhĭk, ăn bu êng saơ khân păng.$b$,true),
('bunong-vn','JOB',34,27,null,$b$Yor lah khân păng cha lơi mâu hôm tĭng Kôranh Brah ôh, jêh ri mâu chrê ôh ma trong Păng.$b$,true),
('bunong-vn','JOB',34,28,null,$b$Khân păng ƀư ăn phung o ach lŭng nter tăng tât ma tôr Păng, jêh ri Kôranh Brah tăng bâr nter bơh phung rêh ni.$b$,true),
('bunong-vn','JOB',34,29,null,$b$Tơ lah Păng ăn nau đăp mpăn, mbu nơm mra ƀư ăn nau uh ah? Tơ lah Păng pôn muh măt păng, mbu nơm mra saơ Păng? Păng ƀư tâm ban pô nây mâu lah mbu ntil mpôl mâu lah mbu bunuyh?$b$,true),
('bunong-vn','JOB',34,30,null,$b$Gay lơi ăn ôh bunuyh mhĭk chiă uănh, jêh ri gay ma nơm nây mâu mra ntŭp phung ƀon lan tâm trôm dăk bu sân.$b$,true),
('bunong-vn','JOB',34,31,null,$b$“Yor lah mâp geh lĕ bunuyh lah ma Brah Ndu pô aơ: “Gâp hŏ dơn jêh nau nduyh nkra ma gâp, gâp mâu mra ƀư mhĭk đŏng ôh;$b$,true),
('bunong-vn','JOB',34,32,null,$b$Sâm nti ma gâp moh nau gâp ê hŏ gĭt rbăng; tơ lah gâp ƀư mhĭk, gâp mâu mra ƀư đŏng ôh? Pô ri,$b$,false),
('bunong-vn','JOB',34,33,null,$b$Brah Ndu mra ăn lĕ nau nkhôm tĭng nâm nau may ŭch, yor lah may lĕ dun jêh nau nkra nây? Yor lah may nơm yơh mra săch, mâu di gâp ôh; pô ri mbơh hom moh nau may gĭt.$b$,false),
('bunong-vn','JOB',34,34,null,$b$Phung bunuyh geh nau gĭt rbăng mra lah ma gâp, jêh ri bunuyh blau mĭn gŭ iăt nau gâp mra lah:$b$,true),
('bunong-vn','JOB',34,35,null,$b$“Y-Yôp ngơi mâu geh ma nau gĭt vât ôh, jêh ri nau păng ngơi mâu geh nau gĭt rbăng lĕ”$b$,false),
('bunong-vn','JOB',34,36,null,$b$Gâp gay ma Y-Yôp dơn nau rlong uănh kŏ tât lôch. Yor lah păng plơ̆ sĭt lah nâm bu phung bunuyh djơh mhĭk.$b$,true),
('bunong-vn','JOB',34,37,null,$b$Yor lah păng ntop tay nau tâm rdâng ndrel ma nau tih păng; păng tap ti păng tra năp hên, jêh ri lơ hâu ntop nau ngơi tâm rdâng đah Brah Ndu.”$b$,true),
('bunong-vn','JOB',35,1,null,$b$Y-Êtihu ngơi tay pô aơ: May hŏ ngơi lah:$b$,true),
('bunong-vn','JOB',35,2,null,$b$“Gâp geh nau sŏng di lơn ma Brah Ndu; may lah tay, ‘Mâm nau gâp ŭch lah? Gay lơi ăn geh nau tih,$b$,false),
('bunong-vn','JOB',35,3,null,$b$Gâp mâu hĕ dơi geh nau khlay? Mâm may mĭn ma nau nây geh khlay lĕ?$b$,false),
('bunong-vn','JOB',35,4,null,$b$Gâp mra plơng nau ngơi may, jêh ri phung mĭt jiăng ndrel ma may đŏng.$b$,true),
('bunong-vn','JOB',35,5,null,$b$N'gơr uănh hom klơ trôk; Uănh hom ma ndâr tŭk, păng prêh lơn ma may.$b$,true),
('bunong-vn','JOB',35,6,null,$b$Tơ lah may hŏ ƀư tih, geh djơh lĕ tât ma Brah Ndu? Tơ lah lĕ nau tih may ƀư jêh ntop lơ hâu âk, moh nau may ƀư ma Păng?$b$,true),
('bunong-vn','JOB',35,7,null,$b$Tơ lah may jêng sŏng, moh may mra ăn ma Păng? Mâu lah moh ntil ndơ Păng mra sŏk dơn tă bơh ti may?$b$,true),
('bunong-vn','JOB',35,8,null,$b$Nau djơh may knŏng ƀư mhĭk ma du mpôl may nơm jêh ri nau sŏng srăng may jêng khlay êng ma du huê kon bunuyh.$b$,true),
('bunong-vn','JOB',35,9,null,$b$“Yor lah geh âk nau tŭn jot, yor ri ƀon lan lŭng nter, yor lah phung ktang ƀư ma khân păng yor ri vơl gay bu kơl an.$b$,true),
('bunong-vn','JOB',35,10,null,$b$Ƀiă lah mâu geh nuyh ôp: “Brah Ndu jêng Nơm Rhăk Njêng gâp, mbah ntŭk gŭ? Păng ăn bu mprơ maak dôl bri măng,$b$,true),
('bunong-vn','JOB',35,11,null,$b$ntĭm nti hên dơi gĭt rbăng lơn lĕ ntil mpô mpa bri ta klơ neh ntu jêh ri njêng he blau mĭn lơn ma sĭm tâm trôk.$b$,false),
('bunong-vn','JOB',35,12,null,$b$Bu lŭng nter, ƀiă lah Brah Ndu mâu plơ̆ sĭt lah ôh, yor nau sưr rlau phung bunuyh djơh mhĭk.$b$,true),
('bunong-vn','JOB',35,13,null,$b$N'hêl nanê̆ Brah Ndu mâu iăt ôh nau vơh vơl n'hi mâu geh nuih n'hâm răp jăp, Nơm Geh Lĕ Nau Brah kŏ mâu chrê lĕ ma nau nây.$b$,true),
('bunong-vn','JOB',35,14,null,$b$Lơ hâu ma nây tơ lah may lah mâu saơ ôh Păng. Nau tâm mpơl hŏ tât jêh ta năp măt Păng, jêh ri may gŭ kâp Păng phat dôih!$b$,true),
('bunong-vn','JOB',35,15,null,$b$Aƀaơ ri, yor lah nau Păng ji nuih mâu hŏ klăp ndăng ôh, jêh ri yor lah Păng mâu klăp ndăng ir ôh nau sưr rlau bu hŏ ƀư nây.$b$,true),
('bunong-vn','JOB',35,16,null,$b$Yor ri Y-Yôp hă trôm mbung păng ngơi dơm dam jêh ri ngơi mâu geh nau gĭt rbăng ôh.”$b$,true),
('bunong-vn','JOB',36,1,null,$b$Y-Êtihu ngơi tay jêh ri lah:$b$,true),
('bunong-vn','JOB',36,2,null,$b$“Srôih hom ndrel ma gâp, jêh ri gâp mra ntĭm ma may: Yor lah gâp ăt hôm geh nau ngơi mpeh ma Brah Ndu.$b$,false),
('bunong-vn','JOB',36,3,null,$b$Gâp mra djôt leo nau gâp gĭt rbăng tă bơh ntŭk ngai, jêh ri gay mpơl mbơh nau sŏng Nơm Rhăk njêng gâp.$b$,true),
('bunong-vn','JOB',36,4,null,$b$N'hêl nanê̆ lĕ nau gâp ngơi mâu jêng mƀruh ôh; geh du huê Nơm gĭt nanê̆ ngăn gŭ ta năp may.$b$,true),
('bunong-vn','JOB',36,5,null,$b$“Aơ, Brah Ndu geh nau brah, mâu geh mưch rmot bu ôh; nau mĭn ueh Păng jru huy ngăn.$b$,true),
('bunong-vn','JOB',36,6,null,$b$Păng mâu prăp ôh nau rêh bunuyh djơh, ƀiă lah mplơ̆ nau di ăn ma nơm geh nau rêh ni.$b$,true),
('bunong-vn','JOB',36,7,null,$b$Păng mâu ndôn kơi ôh ma bunuyh sŏng, ƀiă lah Păng ăn ma khân păng gŭ ndrel ma phung hađăch ta klơ sưng hađăch mro mrăng, jêh ri khân păng geh nau yơk ƀa ƀơ.$b$,true),
('bunong-vn','JOB',36,8,null,$b$Tơ lah khân păng bu kât ma rse rvăk, jêh ri bu klêng khân păng ma rse nglêng nau rêh ni,$b$,true),
('bunong-vn','JOB',36,9,null,$b$rnôk nây Păng ntĭm mbơh ma khân păng nau khân păng hŏ ƀư jêh, jêh ri nau tih jêng nau khân păng sưr.$b$,false),
('bunong-vn','JOB',36,10,null,$b$Păng pơk trôm tôr khân păng gay iăt nau bu nduyh nkra. Ntĭm nti khân păng plơ̆ sĭt cha lơi lĕ nau djơh mhĭk.$b$,true),
('bunong-vn','JOB',36,11,null,$b$Tơ lah khân păng tông iăt nau bu jêh ri pah kan ma Păng, pô ri lôch nar khân păng gŭ rêh dơi geh nau chăt jêng. Jêh ri geh nau răm maak.$b$,true),
('bunong-vn','JOB',36,12,null,$b$Ƀiă lah tơ lah khân păng mâu iăt ôh, nanê̆ đao mra nkhĭt khân păng. Jêh ri khĭt mâu geh nau gĭt rbăng ôh.$b$,true),
('bunong-vn','JOB',36,13,null,$b$“Nuih n'hâm n'hi têm nau ji nuih; tơ lah Brah Ndu kât khân păng, khân păng mâu ŭch nter ôh gay bu kơl an.$b$,true),
('bunong-vn','JOB',36,14,null,$b$Khân păng khĭt dôl hôm mom, nau rêh khân păng rai lôch ndrel tâm phung văng tĭr.$b$,true),
('bunong-vn','JOB',36,15,null,$b$Brah Ndu dŏng nau rêh ni gay rklaih phung geh nau rêh ni, jêh ri yor nau mhĭk tât gay pơk trôm tôr păng.$b$,true),
('bunong-vn','JOB',36,16,null,$b$Păng tâm ban lĕ hŏ ŭch sŭk nsôr may du luh bơh nau rêh ni. Dơm may ta ntŭk gŭ păn thơ mâu hôm geh nau uh nuih ôh; jêh ri ndơ sông sa bu hŏ ndrăp klơ sưng sông may, lĕ ndơ sa kah vah ngi.$b$,true),
('bunong-vn','JOB',36,17,null,$b$Ƀiă lah may bêng ma nau phung mhĭk ŭch ƀư. N'hêl nanê̆ nau phat dôih jêh ri nau tâm rmal mra tât ma may.$b$,true),
('bunong-vn','JOB',36,18,null,$b$Lơi ăn nau ji nuih nsônh may gay ăn may tâm ndăng nau bu nduyh nkra. Jêh ri lơi ăn vĭ yor nau bu nkhôm toyh ir ôh.$b$,true),
('bunong-vn','JOB',36,19,null,$b$Mâu geh nau may ndrŏng ôh mra sâm king may bơh nau uh ah, mâu lah nau ktang may dơi rklaih may bơh nau rêh ni?$b$,true),
('bunong-vn','JOB',36,20,null,$b$Lơi gŭ kâp kêng măng, rnôk nây mơ bu mra ƀư rai phung ƀon lan tă bơh ntŭk khân păng gŭ.$b$,true),
('bunong-vn','JOB',36,21,null,$b$Njrăng hom, lơi n'gĭl plơ̆ ma nau mhĭk ôh, yor lah nây jêng nau may nơm ŭch kơnh âk lơn ma nau rêh ni$b$,true),
('bunong-vn','JOB',36,22,null,$b$Aơ, Brah Ndu geh nau yơk yor nau brah păng toyh ngăn, mbu nơm jêng nơm nti nâm bu Păng?$b$,false),
('bunong-vn','JOB',36,23,null,$b$Mbu nơm sâm nchră an ma Păng dơi gĭt trong Păng? Jêh ri mbu dơi lah: ‘May ƀư tih jêh?’$b$,true),
('bunong-vn','JOB',36,24,null,$b$“Kah gĭt tâm rnê hom ma kan Kôranh Brah, ma kan nây phung kon bunuyh vay mprơ tâm rnê.$b$,false),
('bunong-vn','JOB',36,25,null,$b$Lĕ rngôch bunuyh hŏ n'gơr uănh nau kan nây da dê, jêh ri kon bunuyh uănh nau nây ntơm bơh ngai$b$,true),
('bunong-vn','JOB',36,26,null,$b$Aơ, Brah Ndu jêng toyh lơn, rlau ma he gĭt rbăng; ndah nâm âk năm Păng rêh bu mâu dơi kơp lĕ.$b$,false),
('bunong-vn','JOB',36,27,null,$b$Yor lah Păng bruh n'hao n'hôl dak leo klơ, jêh nây ăn truh dak ngom păng jêng mih.$b$,true),
('bunong-vn','JOB',36,28,null,$b$Jêh ri geh ndâr tŭk tŭp dak mih; păng jêng dak hor ta klơ bunuyh âk ngăn ngên.$b$,true),
('bunong-vn','JOB',36,29,null,$b$Mbu nơm dơi gĭt ndâr tŭk păng ling tâm ban pô nây. Jêh ri nteh nglaih dah tă bơh ntŭk Păng gŭ?$b$,true),
('bunong-vn','JOB',36,30,null,$b$Aơ, Păng ăn lơp nglaih jŭm Păng. Jêh ri nkŭm lĕ tâm dâng săt dak mƀŭt (mbon dak mƀŭt).$b$,true),
('bunong-vn','JOB',36,31,null,$b$Yor lah tă bơh nau nây Păng phat dôih lĕ ntil mpôl bunuyh; Păng ăn ndơ sông sa rmeh rmai.$b$,true),
('bunong-vn','JOB',36,32,null,$b$Păng djôt prăp lơp nglaih tâm ti Păng, Jêh ri mƀăr păng ta ntŭk păng ŭch tâm nal jêh.$b$,true),
('bunong-vn','JOB',36,33,null,$b$Nau nteh nglaih dah jêng nau mbơh ma kan Păng ƀư, jêh ri mpô mpa rong tâm ban lĕ ăt gĭt mbên ma tŭp mih dăch tât nau păng văch ƀư.$b$,true),
('bunong-vn','JOB',37,1,null,$b$Di ngăn, play nuih gâp râm nsâr yor nau nây. Păng mpât tă bơh ntŭk păng.$b$,true),
('bunong-vn','JOB',37,2,null,$b$Iăt hom nteh bâr Păng ma nau nteh nglaih dah ktang jêh ri nteh ktang târ luh bơh trôm mbung Păng.$b$,true),
('bunong-vn','JOB',37,3,null,$b$Păng ăn ndơ nây tŭp tâm dâng trôk, jêh ri nau lơp păng nchrang lam neh ntu,$b$,true),
('bunong-vn','JOB',37,4,null,$b$pa kơi lơp geh târ ƀhing, păng nteh dah nâm bu nau rnam ngăn, jêh ri mâu kơp ôh nau lơp ŭnh nglaih.$b$,false),
('bunong-vn','JOB',37,5,null,$b$Bâr Brah Ndu dah ma nau khlay ngăn ngên; Păng ƀư lĕ kan toyh ngăn ngên yor ri he mâu dơi geh nau gĭt rbăng ôh?$b$,true),
('bunong-vn','JOB',37,6,null,$b$Yor lah Păng lah ma glo dak pler pô aơ: ‘Tŭp hom ta neh ntu’ jêh ri lah ma dak mih tâm ban lĕ, ‘Mih hom ăn ktang’,$b$,true),
('bunong-vn','JOB',37,7,null,$b$Păng ntĭl lơi lĕ rngôch bunuyh gŭ tâm ngih, gay ma lĕ rngôch bunuyh jêng tă bơh Păng hŏ njêng jêr dơi gĭt nau kan Păng.$b$,false),
('bunong-vn','JOB',37,8,null,$b$Jêh ri lĕ rngôch mpô mpa lăp tâm rsuăn păng, jêh ri hôm gŭ tâm trôm khân păng.$b$,true),
('bunong-vn','JOB',37,9,null,$b$Phŭt chuănh luh bơh ntŭk păng, jêh ri sial bơh dor pa lơ tât nau ji kăt ndrêt.$b$,true),
('bunong-vn','JOB',37,10,null,$b$Dak pler hŏ jêng n'hâm rpuh tă bơh Brah Ndu; jêh ri dak toyh jêng kŏt jêh,$b$,true),
('bunong-vn','JOB',37,11,null,$b$Păng krŭng dak tâm tŭk mbâl, jêh ri ling ndâr tŭk hăn bra nau lơp Păng.$b$,false),
('bunong-vn','JOB',37,12,null,$b$Yor tă bơh Păng leo trong, păng mpăr jŭm lam bri neh ntu tĭng nau păng ƀĭt, gay ƀư ăn lôch lĕ nau kan Păng ntăm jêh ma khân păng, ta klơ neh ntu ntŭk bu dơi gŭ.$b$,true),
('bunong-vn','JOB',37,13,null,$b$Păng ăn ndâr tŭk mâu lah jêng nau nduyh nkra mâu lah gay ăn neh dơi jêng, mâu lah gay tâm mpơl nau yô̆ yach ma kon bunuyh.$b$,true),
('bunong-vn','JOB',37,14,null,$b$Hơi Y-Yôp, iăt hom nau aơ, nklân hom, jêh ri mĭn rvê ma kan khlay ngăn ngên Brah Ndu ƀư.$b$,true),
('bunong-vn','JOB',37,15,null,$b$May gĭt lĕ mâm Brah Ndu chiă uănh ndâr tŭk, krĭp dăp lĕ nau kan nây? Mâm dĭng Păng ăn lơp nchrang tă bơh ndâr tŭk?$b$,true),
('bunong-vn','JOB',37,16,null,$b$May gĭt lĕ mâm ndâr tŭk mpăr nâp ta klơ, geh ndơ drơ lĕ? Dơi gĭt rbăng lĕ ma kan khlay bơh Nơm geh nau mĭn gĭt nanê̆ ngăn?$b$,true),
('bunong-vn','JOB',37,17,null,$b$Gĭt lĕ mbah tă bok ao may duh, Tơ lah Păng sŏk sial tă bơh rđŭng ƀư ma rplay neh dơi gŭ srŭng?$b$,true),
('bunong-vn','JOB',37,18,null,$b$May dơi lĕ lăk ling trôk nâm bu Brah Ndu? Păng năp rjăp ngăn nâm bu măt rchŏk bu tŏ.$b$,true),
('bunong-vn','JOB',37,19,null,$b$Nti hom ăn hên gĭt nau hên mra lah ma Păng; yor nau rluk mâl, hên mâu gĭt ôh moh nau ngơi gay nkoch ma Păng.$b$,true),
('bunong-vn','JOB',37,20,null,$b$Bu mra nkoch lĕ ma Brah Ndu nau gâp ŭch ngơi ma Păng? Tơ lah mbu moh ngơi ma Păng, geh lĕ bunuyh mra roh hêng.$b$,true),
('bunong-vn','JOB',37,21,null,$b$Aƀaơ ri, bu mâu dơi saơ nau chrêk lơp nchrat ang, păng lĕ nkâm tâm ndâr tŭk; ƀiă lah sial đô̆ khôm mpruh lơi ndâr tŭk, trôk ang tay rah vah.$b$,true),
('bunong-vn','JOB',37,22,null,$b$Tă bơh dor pa lơ luh du nau chrêk nâm bu mah. Ntŭk Brah Ndu geh nau rnam kir ngăn!$b$,true),
('bunong-vn','JOB',37,23,null,$b$Nkoch tât ma Nơm Geh Lĕ Nau Brah, he mâu dơi saơ Păng ôh; Păng geh nau brah, nau nanê̆ ngăn jêh ri Nau sŏng srăng ngăn ngên, mâu geh nsŭk bu ôh.$b$,true),
('bunong-vn','JOB',37,24,null,$b$Yor nau nây yơh kon bunuyh klach yơk ma Păng; Păng mâu n'gĭl uănh ma mbu moh mĭn ma păng nơm geh nau blau ngăn.$b$,true),
('bunong-vn','JOB',38,1,null,$b$Rnôk nây, tă bơh ta nklang sial vănh blông, Brah Ndu plơ̆ sĭt lah ma Y-Yôp pô aơ:$b$,true),
('bunong-vn','JOB',38,2,null,$b$“Mbu moh nơm aơ nănh dŏng nau ngơi mâu geh nau gĭt vât ôh, nkŭm lơi ăn ngo nau gâp nchră?$b$,false),
('bunong-vn','JOB',38,3,null,$b$Vân rse bŭt may nâm bu du huê bunuyh janh, Gâp mra ôp ma may, jêh ri may mra mbơh ma gâp!$b$,true),
('bunong-vn','JOB',38,4,null,$b$Tơ lah gâp n'gân mbon rplay neh, ta ntŭk may gŭ? Tơ lah may gĭt rbăng, nkoch hom ma gâp.$b$,true),
('bunong-vn','JOB',38,5,null,$b$Mbu tâm nal nau veh rnoh păng, jêh ri nthăng rse dak ôch klơ păng, may dơi gĭt lĕ?$b$,true),
('bunong-vn','JOB',38,6,null,$b$Moh ndơ bu n'gân ta klơ mbon păng? Mbu nơm dơm lŭ ta njônh păng?$b$,true),
