('bunong-vn','JOB',38,8,null,$b$Pô nây, tơ lah dak mƀŭt rlêng ler lip klơ kơh păng. Mbu hŏ sŏk mpông nchăng king lơi păng?$b$,false),
('bunong-vn','JOB',38,9,null,$b$Dôl nây gâp ăn ma păng ndâr tŭk ƀư ao jâr nkŭm păng, jêh ri sŏk nau ngo vêt vê ƀư bok put ma păng.$b$,true),
('bunong-vn','JOB',38,10,null,$b$Gâp tâm nal n'har ma păng, sŏk rnăng mpông jêh ri ntĭl lơi păng.$b$,true),
