('bunong-vn','JOB',38,12,null,$b$Ntơm bơh may deh, may geh lah lĕ ma ang ôi, jêh ri nal ntŭk ăn păng gĭt ntŭk păng gŭ.$b$,true),
('bunong-vn','JOB',38,13,null,$b$Gay ma păng djôt bôl dŭt puăn njônh neh ntu, jêh ri mprơh lơi lĕ phung djơh du luh tă bơh păng?$b$,true),
