('bunong-vn','JOB',38,33,null,$b$May dơi gĭt lĕ nau vay tâm trôk? Dơi njêng kôranh lĕ ma păng Chiă uănh tâm dâng neh aơ?$b$,true),
('bunong-vn','JOB',38,34,null,$b$“Dơi lĕ may ntuh bâr lah ma ndâr tŭk, kŏ tât dak lip nkŭm may?$b$,true),
