('bunong-vn','JOB',38,36,null,$b$Mbu nơm dơm nau blau mĭn tâm nuih n'hâm, mâu lah ăn jêh nau gĭt rbăng ma bôk rngok?$b$,true),
('bunong-vn','JOB',38,37,null,$b$Mbu dơi kơp ndâr tŭk ma nau blau? Mâu lah mbu nơm dơi ăn ndâr tŭk tâm phung trôk ăn tŭp dak mih,$b$,true),
('bunong-vn','JOB',38,38,null,$b$tơ lah ndruyh neh chah rai jêh ri jêng glo krêp nâp ngăn? Mbu nơm rklĭng nkhŭt phung nông dak tă bơh phung trôk?$b$,false),
('bunong-vn','JOB',39,1,null,$b$Tơ lah me yau mŭr kuen kâp dâp tâm trôm, tơ lah moch rmiăt tâm nklang rlô păng,$b$,true),
