('bunong-vn','JOB',39,3,null,$b$Mbu nơm ăn ndơ sa ma nđak, tơ lah kon jê̆ păng nhhiăng ma Brah Ndu jêh ri mpăr ta aơ ta ri mâu geh ndơ sa?$b$,true),
('bunong-vn','JOB',39,4,null,$b$May gĭt lĕ ntŭk be bri deh? May saơ lĕ jun me deh kon?$b$,true),
