('bunong-vn','JOB',39,8,null,$b$Mbu nơm mƀơk seh bri hăn nsong blă blơ? Mbu nơm doh lơi rse kât kon seh bri nchuăl prăl ngăn?$b$,true),
('bunong-vn','JOB',39,9,null,$b$Gâp hŏ ăn jêh ma păng bri neh lâng jêng ntŭk ma khân păng gŭ, jêh ri neh geh boh jêng ntŭk ma khân păng gŭ đŏng?$b$,true),
('bunong-vn','JOB',39,10,null,$b$Păng mưch moh nau ngơi drơu drơu ta nklang ƀon toyh, păng mâu iăt nau phung mât chiăp.$b$,true),
('bunong-vn','JOB',39,11,null,$b$Păng hăn nsong lam yôk jêng ntŭk gơ̆ ndrêch ma păng, păng tĭng joi lĕ rngôch gơ̆ nse$b$,true),
('bunong-vn','JOB',39,12,null,$b$“Mâm ƀư krŭp ŭch pah kan ma may lĕ? Păng ŭch kuen bêch tâm ndrung ndrôk may lĕ?$b$,false),
('bunong-vn','JOB',39,13,null,$b$Dơi lĕ may sŏk rse kât krŭp ta mâng mbăk gay kai mir may? Păng mra ŭch lĕ tĭng pa kơi may chraih mir tâm rlŭng?$b$,true),
('bunong-vn','JOB',39,14,null,$b$May nsing lĕ ma păng yor nau ktang păng toyh, jêh ri may mra jao lĕ ma păng kan jêr may?$b$,true),
('bunong-vn','JOB',39,15,null,$b$May rnơm lĕ ma păng mra leo mplơ̆ sĭt tay ba ma may jêh ri đă păng rdeng tay ba may leo ma ntŭk mprah?$b$,true),
('bunong-vn','JOB',39,16,null,$b$Sĭm ôtrus rtuh nting năr răm rhơn; ƀiă lah nting năr jêh ri rsau nây geh nau tâm rŏng lĕ?$b$,true),
('bunong-vn','JOB',39,17,null,$b$Yor lah păng cha lơi tăp păng tâm neh brôi mpăn tăp nây tâm neh muy,$b$,true),
('bunong-vn','JOB',39,18,null,$b$Jêh ri chuêl du đah jâng chuat geh jot chah lơi tăp nây, mâu lah mpa bri geh jot ta tăp nây.$b$,false),
('bunong-vn','JOB',39,19,null,$b$Păng ƀư janh đah phung kon păng, nâm bu khân păng mâu jêng ôh kon păng nđâp tơ lah păng ƀư pô nây kđôi, păng mâu chrê ôh.$b$,true),
('bunong-vn','JOB',39,20,null,$b$Yor lah Brah Ndu mâu ăn ôh nau blau mĭn ma păng, jêh ri mâu ăn du kô̆ nau gĭt rbăng ôh ma păng.$b$,true),
('bunong-vn','JOB',39,21,null,$b$Tơ lah păng rtuh nting năr dâk mpăr, păng gơm mưch ma seh jêh ri rmăk păng.$b$,true),
('bunong-vn','JOB',39,22,null,$b$Geh lĕ may ăn nau ktang ma seh, jêh ri may ăn hon rsau trô ko rak briu briu lĕ?$b$,true),
('bunong-vn','JOB',39,23,null,$b$Geh lĕ may ăn păng nsăt pak đeh nâm bu krah lĕ? Nau păng krĭ ăn bu klach lĕ?$b$,true),
('bunong-vn','JOB',39,24,null,$b$Păng kuai neh tâm rlŭng, răm rhơn ma nau ktang păng; păng rduh ran pa năp chuă ta han djôt ndơ tâm lơh,$b$,true),
('bunong-vn','JOB',39,25,null,$b$păng gơm mưch yor nau klach, jêh ri mâu rdja nuih ôh; păng mâu plơ̆ rŭch ôh đah mpiăt đao.$b$,false),
('bunong-vn','JOB',39,26,null,$b$Ta klơ săng nglik păng bu tăng nteh dĭng kăm, geh tak jêh ri chrah bu tâm nkrêp.$b$,true),
('bunong-vn','JOB',39,27,null,$b$Ma nau janh jêh ri ji nuih păng nchuăt prăl, păng mâu dơi đăp gŭ ôh tơ lah tăng uh nŭng.$b$,true),
('bunong-vn','JOB',39,28,null,$b$Dôl tăng uh nŭng, păng nter: Hah! Hah! păng n'hôp ƀâu n'hôl tâm lơh ntơm bơh ngai, păng tăng bâr kôranh ta han drơu drơu jêh ri bâr troh nter phung lĭng ta han.$b$,true),
('bunong-vn','JOB',39,29,null,$b$Di lĕ yor nau blau mĭn may klang ntơp mpăr her klơ jêh ri lĭ năr păng mpeh rđŭng?$b$,true),
('bunong-vn','JOB',39,30,null,$b$Di lĕ tĭng nau may ntĭnh ăn klang hao klơ jêh ri, ƀư rsuăn păng ta ntŭk prêh klơ?$b$,true),
('bunong-vn','JOB',39,31,null,$b$Păng gŭ tâm nđa lŭ, ƀư rsuăn ta bôl dŭt lŭ jêh ri ta klơ n'glơn yôk mâu geh bunuyh dơi hao ôh.$b$,true),
('bunong-vn','JOB',39,32,null,$b$Tă bơh nây, păng rmiăt mpa păng kăp. Măt păng uănh ma mpa nây ntơm bơh ngai ri.$b$,true),
('bunong-vn','JOB',39,33,null,$b$Kon jê̆ păng djrêp mham, jêh ri păng gŭ ta ntŭk geh mpa lĕ khĭt jêh.$b$,true),
('bunong-vn','JOB',39,34,null,$b$Yêhôva plơ̆ đah đŏng ma Y-Yôp, lah:$b$,true),
('bunong-vn','JOB',39,35,null,$b$Nơm ngơi ƀrôk mra tâm rlăch đah Nơm Geh Lĕ Nau Brah lĕ? Bunuyh tâm rlăch đah Brah Ndu, plơ̆ sĭt lah hom nau nây?$b$,false),
('bunong-vn','JOB',39,36,null,$b$Y-Yôp plơ̆ sĭt lah ma Yêhôva:$b$,true),
('bunong-vn','JOB',39,37,null,$b$“Gâp jêng du ntil ndơ mâu geh rnoh khlay ôh, moh nau gâp mra plơ̆ sĭt lah ma may? Gâp rdêp lơi trôm mbung gâp mâu hôm ngơi ôh.$b$,false),
('bunong-vn','JOB',39,38,null,$b$Gâp hŏ ngơi jêh du tơ̆ , ƀiă lah mâu mra plơ̆ sĭt lah ôh, gâp hŏ ngơi bar tơ̆ jêh, ƀiă lah mâu hôm ngơi đŏng ôh.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JOB',40,1,null,$b$Tă tâm nklang sial vănh blông, Yêhôva plơ̆ sĭt lah ma Y-Yôp, jêh ri lah:$b$,true),
('bunong-vn','JOB',40,2,null,$b$Rêt hom rse bŭt may nâm bu du huê bunuyh ktang; gâp mra ôp may jêh ri ăn may mra mbơh ma gâp!$b$,false),
('bunong-vn','JOB',40,3,null,$b$May mra ăn nđâp gâp jêng tih lĕ? May mra kơp gâp tih gay may dơi geh nau kơp sŏng lĕ?$b$,true),
('bunong-vn','JOB',40,4,null,$b$May geh lĕ nting tur ktang nâm bu Brah Ndu? Dơi lĕ may ƀư nteh bâr nglaih dah nâm bu Păng?$b$,true),
('bunong-vn','JOB',40,5,null,$b$Pô ri aƀaơ, may nkrơ̆ hom may ma nau rnam jêh ri khưm ro, jêh ri nsoh nau chrêk ma lơp, nchrat ang.$b$,true),
('bunong-vn','JOB',40,6,null,$b$Mbêng ler hom nau may ji nuih, jêh ri uănh hom ma nơm sưr rlau gay ma n'glưh păng.$b$,true),
('bunong-vn','JOB',40,7,null,$b$Uănh ma ăp nơm mbu nơm jêng sưr, jêh ri ntrŭnh păng; jot plên lơi phung djơh ta ntŭk khân păng gŭ.$b$,true),
('bunong-vn','JOB',40,8,null,$b$Tâp brôi lơi lĕ rngôch khân păng ndrel n'grŭp tâm ndruyh neh, put bok ta muh măt khân păng tâm môch.$b$,true),
('bunong-vn','JOB',40,9,null,$b$Rnôk nây lĕ gâp mra dơn ma may geh nau dơi may nơm ma ti ma may.$b$,true),
('bunong-vn','JOB',40,10,null,$b$Aơ, rpu dak gâp hŏ njêng ndrel may; păng sa gơ̆ nâm bu ndrôk.$b$,true),
('bunong-vn','JOB',40,11,null,$b$Uănh hom ma nau ktang pa kơi păng. Nau dăng ktang păng tă tâm jreng n'ho păng.$b$,true),
('bunong-vn','JOB',40,12,null,$b$Păng ƀư đơr chiăng păng nâm bu tơm si sêdar. Suan nglu păng tâm băr ndrel.$b$,true),
('bunong-vn','JOB',40,13,null,$b$Nting păng jêng nâm bu dĭng kông, jâng păng nâm bu loih.$b$,true),
('bunong-vn','JOB',40,14,null,$b$“Păng jêng kan mrô nguay ma Brah Ndu. Nơm rhăk njêng păng sŏk pêih đao kâp ƀư ma păng!$b$,true),
('bunong-vn','JOB',40,15,null,$b$Yor lah yôk hon gơ̆ nse ăn ndơ sa ma păng. Jêng ntŭk phung mpô mpa bri pâl rlưn.$b$,true),
('bunong-vn','JOB',40,16,null,$b$Păng kuen bêch tâm gơ̆ chrăch-chrêl, tâm ntŭk ndâp tâm proh treng jêh ri trâp.$b$,true),
('bunong-vn','JOB',40,17,null,$b$Gơ̆ chrăch-chrêl nkŭm păng ma gui n'hâm păng; tơm yôm ta n'hor dak nchueng jŭm păng$b$,true),
('bunong-vn','JOB',40,18,null,$b$Aơ, dak hao toyh hâu ngăn, ƀiă lah păng mâu klach ôh ăt păng gŭ đăp mpăn. Nđâp tơ lah dak krong Yurdan tap trôm mbung păng, păng ăt gŭ nâp tâm ban lĕ.$b$,false),
('bunong-vn','JOB',40,19,null,$b$Mbu nơm dơi nhŭp păng ta nây ro? Mbu nơm dơi veng păng ma nhuăl, jêh ri sŏk rse chuh muh păng?$b$,true),
('bunong-vn','JOB',40,20,null,$b$“Dơi lĕ may klĕ mphâk rbư ma nglĕ ndar, jêh ri sŏk rse sro mpiăt păng?$b$,true),
('bunong-vn','JOB',40,21,null,$b$Dơi lĕ chuh muh păng n'groi du njăr rse, jêh ri klĕ kang păng ma nglĕ ndar?$b$,true),
('bunong-vn','JOB',40,22,null,$b$Păng mra vơl hâu ngăn lĕ ma may? Păng mra ngơi rdơ̆ lĕ ma may?$b$,true),
('bunong-vn','JOB',40,23,null,$b$Păng mra ƀư nau tâm rnglăp đah may, ăn may sŏk păng jêng oh mon ma may n'ho ro lĕ?$b$,true),
('bunong-vn','JOB',40,24,null,$b$May mra pâl rlưn đah păng nâm bu du mlâm sĭm, mâu lah kât rse têk ta trô ko păng ăn ma phung oh mon bu ur may rlưn pâl lĕ?$b$,true),
('bunong-vn','JOB',40,25,null,$b$Phung tăch rgâl mra tăch păng lĕ? Tâm pă păng ăn ma ndrăng phung tâm tăch lĕ?$b$,true),
('bunong-vn','JOB',40,26,null,$b$Dơi lĕ may sŏk tak ntâp bêng ntâu săk păng, mâu lah ntâp bôk păng ma jôih lĕ?$b$,true),
('bunong-vn','JOB',40,27,null,$b$Lŏng nâl yơr hom ti may ƀư ma păng; kăndơ̆ tơ lah may kah gĭt ma nau mra tât nây lơi hôm ƀư đŏng ôh!$b$,true),
('bunong-vn','JOB',40,28,null,$b$Aơ, nau kâp gân ŭch nhŭp păng lĕ roh jêh; knŏng saơ mpơl săk păng, bu lĕ krit êng jêh.$b$,true),
('bunong-vn','JOB',41,1,null,$b$Mâu geh nuyh dơi janh gay ŭch lôr păng ôh; pô ri, mbu nơm dơi tâm rdâng đah păng?$b$,true),
('bunong-vn','JOB',41,2,null,$b$Mbu nơm ăn lor ma gâp, ri mơ gâp mplơ̆ sĭt tay? Lĕ rngôch ndơ tâm dâng trôk jêng ndơ gâp.$b$,true),
('bunong-vn','JOB',41,3,null,$b$Gâp mra ŭch ngơi tơ lah saơ jâng păng, ma n'hâm suan păng, jêh ri nau ueh săk jăn păng.$b$,true),
('bunong-vn','JOB',41,4,null,$b$Mbu nơm dơi doih ntâu păng? Mbu nơm dơi lăp tâm trôm mơr bar kơn păng?$b$,true),
('bunong-vn','JOB',41,5,null,$b$Mbu nơm dơi nkhak rmlông păng? Nau klach krit gŭ jŭm sêk păng.$b$,true),
('bunong-vn','JOB',41,6,null,$b$Păng geh nau rnam toyh ngăn yor geh âk khêl păng. Păng tâm njĭr nâm bu ndơ bu kŭp rdâl.$b$,true),
('bunong-vn','JOB',41,7,null,$b$Ndơ aơ tâm rđĭl dah ndơ êng. Kŏ tât sial mâu dơi lăp ôh.$b$,true),
('bunong-vn','JOB',41,8,null,$b$Păng tâm lĭr ndrăng khân păng jêh ri krêp nâp ngăn mâu dơi plôk êng êng ôh.$b$,true),
('bunong-vn','JOB',41,9,null,$b$Si đah muh păng nâm bu lơp, Bar đah măt păng nchrang ƀring nâm bu nchrat nar ơm ôi.$b$,true),
('bunong-vn','JOB',41,10,null,$b$Trôm mbung păng hâng ŭnh jêh ri bruh ŭnh hit tă tâm trôm.$b$,true),
('bunong-vn','JOB',41,11,null,$b$Tă tâm trôm muh păng luh thŭl nhhŭk. Nâm bu khuh glah dak jêh ri nâm bu tă ntŭk ŭnh sa proh treng.$b$,true),
('bunong-vn','JOB',41,12,null,$b$Nsôr n'hâm păng nâm bu hâng ŭnh rnga, jêh ri mpiăt ŭnh luh du tă trôm mbung păng.$b$,true),
('bunong-vn','JOB',41,13,null,$b$Tâm trô ko păng geh nau ktang jêh ri bu klach ngăn saơ păng.$b$,true),
('bunong-vn','JOB',41,14,null,$b$Ntŭk mprôn nglay săk păng tâm krêp ndrel ntâu păng nâm bu tŏ nkrêp đah săk păng mâu blau hêk ôh.$b$,true),
('bunong-vn','JOB',41,15,null,$b$Play nuih păng dăng nâm bu lŭ, dăng lơn ma glo mpăl tâm dâng.$b$,true),
('bunong-vn','JOB',41,16,null,$b$Tơ lah păng du dâk, phung janh ktang geh nau klach da dê; Yor lah sŏk nau nkrit yor ri bu du klach.$b$,true),
('bunong-vn','JOB',41,17,null,$b$Tơ lah bu sŏk đao, tak, jêh ri jôih gay ntâp păng kŏ mâu dơi lĕ.$b$,true),
('bunong-vn','JOB',41,18,null,$b$Păng uănh ma loih nâm bu tơm rpho, jêh ri kông nâm bu tơm si ôm.$b$,true),
('bunong-vn','JOB',41,19,null,$b$Chiông hăr mâu dơi ƀư gay ăn păng nchuăt du ôh. Lah bu klŭp ma lŭ păng rlơ̆ jêng rhe.$b$,true),
('bunong-vn','JOB',41,20,null,$b$Nđâp mâng bu dong păng uănh nâm bu rhe, păng gơm mưch tăng nteh brâm tak.$b$,true),
('bunong-vn','JOB',41,21,null,$b$Tâm trôm ndŭl păng geh âk rsong yăng chah, păng nâm du nchraih bu chraih tâm dak bŏk.$b$,true),
('bunong-vn','JOB',41,22,null,$b$Păng ăn dak klŏng jru khuh nâm bu glah dak duh. Păng ƀư ăn dak mƀŭt jêng nâm bu gri bu ăn dak si mhĭng.$b$,true),
('bunong-vn','JOB',41,23,null,$b$Pa kơi păng mpŭnh dak nglang tĭng ndô̆ ; jêh ri klăp lah bu gŭ mĭn pô aơ ntu jru jêng sŏk mra bu ranh.$b$,true),
('bunong-vn','JOB',41,24,null,$b$Ta neh ntu, mâu geh ôh ndơ tâm ban ma păng, bu rhăk njêng păng mâu geh nau klach ôh.$b$,true),
('bunong-vn','JOB',41,25,null,$b$Păng klân treng ma lĕ rngôch ndơ tâm dâng păng da dê, păng ƀư hađăch ăn lĕ rngôch mpô mpa janh ktang.$b$,true),
('bunong-vn','JOB',42,1,null,$b$Y-Yôp plơ̆ sĭt lah ma Yêhôva jêh ri lah:$b$,true),
('bunong-vn','JOB',42,2,null,$b$“Gâp gĭt jêh may dơi ƀư lĕ ntil nau, jêh ri bu mâu dơi der ôh nau may ŭch ƀư.$b$,false),
('bunong-vn','JOB',42,3,null,$b$‘Mbu nơm aơ, mâu geh ôh nau gĭt rbăng janh mo nau nchră. Kôranh Brah?’ Yor nây gâp hŏ ngơi jêh nau gâp ngơi mâu gĭt rbăng ôh, jêng nau khlay ir ngăn ma gâp, kŏ tât gâp mâu dơi rbăng ngăn.$b$,true),
('bunong-vn','JOB',42,4,null,$b$Hơi Kôranh Brah, iăt hom, gâp mra ngơi; gâp mra ôp ma may, may sâm ntĭm nti an ma gâp.$b$,true),
('bunong-vn','JOB',42,5,null,$b$Gâp mâp tăng jêh bu nkoch bri ma may. Ƀiă lah aƀaơ, măt gâp hŏ saơ jêh may;$b$,true),
('bunong-vn','JOB',42,6,null,$b$yor nây, gâp jêng tâm rmot ma gâp nơm. Jêh ri rmal nau tih tâm ndruyh neh.”$b$,false),
('bunong-vn','JOB',42,7,null,$b$Jêh Yêhôva ngơi nau nây ma Y-Yôp, Yêhôva lah ma Y-Êlipas, bunuyh Têman; lah: “Gâp hao ji nuih ngăn ma may jêh ri ma bar hê mĭt jiăng may; yor lah khân may mâu geh ngơi nau di ôh ma gâp, nâm bu Y-Yôp, jêng oh mon Gâp hŏ ngơi.$b$,true),
('bunong-vn','JOB',42,8,null,$b$Pô ri aƀaơ sŏk hom pơh mlâm ndrôk nkuăng, jêh ri pơh mlâm biăp nkuăng, hăn hom ma oh mon Gâp Y-Yôp mra mbơh sơm an ma khân may, jêh ri gâp mra dơn nau păng mbơh sơm dăn ma gâp lơi ƀư ôh ma khân may tĭng nâm nau rluk khân may; yor lah khân may mâu geh ôh nau di ma gâp nâm bu Y-Yôp oh mon Gâp hŏ ngơi jêh.”$b$,false),
('bunong-vn','JOB',42,9,null,$b$Pô ri Y-Êlipas bunuyh Têman, Y-Bildat bunuyh Suah, jêh ri Y-Sôphar bunuyh Naama hăn ƀư tĭng nâm nau Yêhôva dơn jêh nau Y-Yôp mbơh sơm.$b$,true),
('bunong-vn','JOB',42,10,null,$b$Jêh ri Yêhôva mplơ̆ sĭt đŏng nau ueh maak ma Y-Yôp, tơ lah jêh păng mbơh sơm an ma phung mĭt jiăng păng, jêh ri Yêhôva ăn ma Y-Yôp bar tơ̆ âk lơn ma ndơ păng geh jêh ntơm sa ơm.$b$,true),
('bunong-vn','JOB',42,11,null,$b$Lĕ rngôch oh nâu may, oh nur may, jêh ri lĕ rngôch bunuyh tâm bên đah Y-Yôp kăl e, văch tât khâl da dê jêh ri sông sa ndrel ma păng tâm trôm ngih păng. Khân păng tâm mpơl nau yô̆ ma păng jêh ri bonh leng păng yor lĕ rngôch nau mhĭk Yêhôva hŏ tât jêh ma păng. Ăp nơm khân păng ăn da dê ma Y-Yôp du glo prăk jêh ri du mlâm kông mah.$b$,true),
('bunong-vn','JOB',42,12,null,$b$Jêh ri Yêhôva nkhŭt nau ueh uĭn ma Y-Yôp âk lơn tâm rnôk pa kơi ma rnôk sa ơm. Jêh ri păng geh du rmưn puăn rbăn mlâm biăp, prao rbăn ndrôk dui (nđuih) kau kai, jêh ri du rbăn seh bri me.$b$,false),
('bunong-vn','JOB',42,13,null,$b$Păng geh tâm ban lĕ pơh nuyh kon bu klâu jêh ri pe nuyh kon bu ur.$b$,false),
('bunong-vn','JOB',42,14,null,$b$Păng ntơ amoh kon bu ur dak bôk jêng H'Jêmima; amoh kon bu ur rơh bar H'Kêsia; jêh ri ntơ amoh kon bu ur rơh pe H'Karen-Hapuch$b$,false),
('bunong-vn','JOB',42,15,null,$b$Tâm lam n'gor mâu geh ôh bu ur jêng ueh ray nâm bu phung kon bu ur Y-Yôp. Mbơ̆ khân păng ăn ndơn drăp ma khân păng ta nklang oh nâu khân păng.$b$,false),
('bunong-vn','JOB',42,16,null,$b$Jêh nau nây, Y-Yôp hôm e rêh du rhiăng puăn jât năm; păng saơ phung kon bu klâu păng jêh ri sau se păng kŏ tât ma puăn rô̆.$b$,true),
('bunong-vn','JOB',42,17,null,$b$Jêh nây Y-Yôp khĭt ranh jŏk rêh.$b$,true);
